/**
 * 📝 CHANGELOG - 13 janvier 2026
 * 
 * ✨ CORRECTIF : Préservation des propriétés typographiques lors du copier-coller
 * 
 * Problème résolu : Lorsqu'un utilisateur copiait-collait un bloc de texte, la typographie
 * changeait de comportement sur le bloc collé.
 * 
 * Cause : Les propriétés splitByGrapheme, breakWords et styles n'étaient pas incluses
 * dans la liste des propriétés à copier lors du clonage d'objets texte.
 * 
 * Solution implémentée :
 * - Ajout de 'splitByGrapheme' à propsToInclude (préserve le comportement de sélection)
 * - Ajout de 'breakWords' à propsToInclude (préserve le comportement de césure)
 * - Ajout de 'styles' à propsToInclude (préserve les styles inline caractère par caractère)
 * 
 * Fonctions corrigées :
 * 1. altDuplicateSingle() - Duplication Alt+Drag d'un objet unique
 * 2. altDuplicateActiveSelection() - Duplication Alt+Drag de sélection multiple
 * 3. Copier (Ctrl+C) - Copie dans le presse-papier
 * 4. Coller (Ctrl+V) - Collage depuis le presse-papier
 * 5. handleObjectTransfer() - Transfert d'objets entre pages
 * 6. moveObjectToPage() - Déplacement d'objets vers une autre page
 * 
 * Résultat : Le bloc collé conserve maintenant exactement le même comportement
 * typographique que l'original (sélection, césure, styles inline).
 * 
 * ✨ PRÉCÉDENT : Fonctionnalités typographiques opérationnelles
 * 
 * Fonctionnalités confirmées et opérationnelles :
 * 
 * 1. 📊 Affichage des propriétés de sélection de texte
 *    - Taille de police affichée pour le texte sélectionné
 *    - Interlignage affiché en points pour le texte sélectionné
 *    - Graisse, style italique, soulignement visibles
 *    - Indicateur visuel (bordure bleue) quand une sélection partielle est active
 *    - Surveillance en temps réel des changements de sélection (polling 200ms)
 * 
 * 2. 🎨 Application des styles typographiques
 *    - Taille de police : applicable sur bloc complet ou sélection partielle
 *    - Graisse (bold) : fonctionne sur sélection ou texte complet
 *    - Italique : application correcte sur sélection ou texte complet
 *    - Interlignage : modifiable et visible en points
 *    - Espacement des caractères : réglable
 *    - Tous les contrôles typographiques sont fonctionnels
 * 
 * 3. 🔧 Configuration optimale
 *    - splitByGrapheme: false par défaut (mode "par mot")
 *    - splitByGrapheme: true uniquement en mode "par syllabe" avec césure
 *    - Support complet des sélections partielles
 *    - Mise à jour automatique du panneau lors des changements de sélection
 *    - Events: text:selection:changed, text:editing:entered/exited
 * 
 * Note: Le paramètre splitByGrapheme contrôle le mode de césure :
 * - splitByGrapheme: false = mode "par mot" (par défaut)
 * - splitByGrapheme: true = mode "par syllabe" avec tirets automatiques (-)
 * - Les tirets utilisés sont des tirets simples (-)
 */

function isMobileSidebarMode() {
    return window.innerWidth <= 1024 || (window.matchMedia && window.matchMedia('(pointer: coarse)').matches);
}

function ensureMobileSidebarBackdrop() {
    let backdrop = document.getElementById('mobileSidebarBackdrop');
    if (backdrop) return backdrop;

    backdrop = document.createElement('div');
    backdrop.id = 'mobileSidebarBackdrop';
    backdrop.style.cssText = [
        'position:fixed',
        'inset:0',
        'background:rgba(0,0,0,0.18)',
        'backdrop-filter:blur(1px)',
        'z-index:1001',
        'opacity:0',
        'pointer-events:none',
        'transition:opacity 0.18s ease'
    ].join(';');

    backdrop.addEventListener('click', () => {
        const left = document.getElementById('leftSidebar');
        const right = document.getElementById('rightSidebar');
        if (left) left.classList.add('collapsed');
        if (right) right.classList.add('collapsed');
        syncMobileSidebarBackdrop();
    });

    document.body.appendChild(backdrop);
    return backdrop;
}

function syncZoomWidgetWithRightSidebar() {
    const rightSidebar = document.getElementById('rightSidebar');
    const zoomWidget = document.getElementById('zoomWidget');
    if (!rightSidebar || !zoomWidget) return;

    const rightVal = rightSidebar.classList.contains('collapsed')
        ? 'calc(56px + 16px)' : 'calc(280px + 16px)';
    zoomWidget.style.right = rightVal;
}

function syncMobileSidebarBackdrop() {
    const backdrop = ensureMobileSidebarBackdrop();
    const left = document.getElementById('leftSidebar');
    const right = document.getElementById('rightSidebar');
    if (!left || !right || !backdrop) return;

    const mobile = isMobileSidebarMode();
    const leftOpen = !left.classList.contains('collapsed');
    const rightOpen = !right.classList.contains('collapsed');
    const anyOpen = mobile && (leftOpen || rightOpen);

    backdrop.style.opacity = anyOpen ? '1' : '0';
    backdrop.style.pointerEvents = anyOpen ? 'auto' : 'none';

    left.style.zIndex = anyOpen ? '1002' : '';
    right.style.zIndex = anyOpen ? '1002' : '';
}

// Toggle sidebar collapse/expand
function toggleSidebar(side) {
    if (side === 'left') {
        const sidebar = document.getElementById('leftSidebar');
        if (sidebar) {
            sidebar.classList.toggle('collapsed');
            const btn = document.getElementById('toggleLeftSidebar');
            if (btn) {
                btn.innerHTML = sidebar.classList.contains('collapsed') ? '▶' : '◀';
            }

            if (isMobileSidebarMode() && !sidebar.classList.contains('collapsed')) {
                const rightSidebar = document.getElementById('rightSidebar');
                if (rightSidebar) rightSidebar.classList.add('collapsed');
            }
        }
    } else if (side === 'right') {
        const sidebar = document.getElementById('rightSidebar');
        if (sidebar) {
            sidebar.classList.toggle('collapsed');
            const btn = document.getElementById('toggleRightSidebar');
            if (btn) {
                btn.innerHTML = sidebar.classList.contains('collapsed') ? '◀' : '▶';
            }
            
            if (isMobileSidebarMode() && !sidebar.classList.contains('collapsed')) {
                const leftSidebar = document.getElementById('leftSidebar');
                if (leftSidebar) leftSidebar.classList.add('collapsed');
            }

            // Ajuster le positionnement du zoom-widget en fonction de l'etat de la sidebar droite
            syncZoomWidgetWithRightSidebar();
        }
    }

    syncMobileSidebarBackdrop();
}

window.addEventListener('resize', () => {
    syncMobileSidebarBackdrop();
});

document.addEventListener('DOMContentLoaded', () => {
    syncMobileSidebarBackdrop();
});

// Vérification du mot de passe et accès à l'application
function checkPassword() {
    const passwordInput = document.getElementById('passwordInput');
    const loginError = document.getElementById('loginError');
    if (!passwordInput || !loginError) {
        console.warn('Login DOM introuvable, vérifiez index.html');
        return;
    }

    const password = passwordInput.value || '';
    const correctPassword = 'print13';

    if (password.toLowerCase() === correctPassword.toLowerCase()) {
        const userAgent = navigator.userAgent.toLowerCase();
        const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)
            || (window.innerWidth <= 1024 && 'ontouchstart' in window);
        const isSafari = userAgent.includes('safari') && !userAgent.includes('chrome');
        const forceAccess = sessionStorage.getItem('superprint_force_access');

        // Small-screen/mobile alert removed (user request): allow access without blocking.

        // Safari alert removed (user request): allow access without blocking.

        const loginScreen = document.getElementById('loginScreen');
        const mainApp = document.getElementById('mainApp');
        if (loginScreen && mainApp) {
            loginScreen.classList.add('hidden');
            mainApp.style.display = 'flex';
        }

        const remember7 = document.getElementById('remember7days');
        if (remember7 && remember7.checked) {
            const sevenDays = 7 * 24 * 60 * 60 * 1000;
            localStorage.setItem('sp_login_ok', '1');
            localStorage.setItem('sp_login_until', String(Date.now() + sevenDays));
        } else {
            localStorage.setItem('sp_login_ok', '1');
            localStorage.removeItem('sp_login_until');
        }

        startSystemMonitoring();
    } else {
        loginError.classList.add('show');
        setTimeout(() => loginError.classList.remove('show'), 3000);
        passwordInput.value = '';
        passwordInput.focus();
    }
}

// Auto-login si déjà validé récemment
document.addEventListener('DOMContentLoaded', () => {
    try {
        const loginScreen = document.getElementById('loginScreen');
        const mainApp = document.getElementById('mainApp');
        const passwordInput = document.getElementById('passwordInput');

        // Gestion de la touche Entrée sur le champ mot de passe
        if (passwordInput) {
            passwordInput.addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    checkPassword();
                }
            });
            // Ne focus que si l'écran de login est visible
            if (loginScreen && !loginScreen.classList.contains('hidden')) {
                passwordInput.focus();
            }
        }

        // Fermer la modale d'export au chargement si présente
        const exportModal = document.getElementById('exportModal');
        if (exportModal) {
            exportModal.style.display = 'none';
        }

        const loginOk = localStorage.getItem('sp_login_ok') === '1';
        const untilRaw = localStorage.getItem('sp_login_until');
        const now = Date.now();
        let stillValid = false;

        // Force login access (Free Mode)
        if (true) {
            if (loginScreen && mainApp) {
                loginScreen.classList.add('hidden');
                mainApp.style.display = 'flex';
            }
            startSystemMonitoring();
            // Éviter le curseur clignotant sur l'UI (caret actif avant premier clic)
            const clearInitialFocus = () => {
                try {
                    if (mainApp && getComputedStyle(mainApp).display !== 'none') {
                        const ae = document.activeElement;
                        if (ae && typeof ae.blur === 'function') ae.blur();
                        document.querySelectorAll('input, textarea, select, [contenteditable="true"], [contenteditable=""]').forEach(el => {
                            try { el.blur(); } catch (_) {}
                        });
                    }
                } catch (_) {}
            };
            clearInitialFocus();
            setTimeout(clearInitialFocus, 50);
            setTimeout(clearInitialFocus, 200);
            window.addEventListener('focus', clearInitialFocus, { once: true });

            // ✨ Anti-caret UI: si clic hors champs, retirer le focus des inputs (évite curseur clignotant en haut)
            const installFocusGuard = () => {
                if (document._spFocusGuardInstalled) return;
                document._spFocusGuardInstalled = true;
                const blurIfNeeded = (e) => {
                    try {
                        const target = e.target;
                        // Ne pas blur si on clique sur les boutons d'espaces spéciaux (sinon Fabric quitte l'édition)
                        if (target && target.closest && target.closest('#insertThinSpace, #insertNbsp')) return;
                        const keepFocus = target && (target.closest && target.closest('input, textarea, select, [contenteditable="true"], [contenteditable=""]'));
                        if (keepFocus) return;
                        const ae = document.activeElement;
                        if (!ae) return;
                        const tag = (ae.tagName || '').toUpperCase();
                        if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || ae.isContentEditable) {
                            try { ae.blur(); } catch (_) {}
                        }
                    } catch (_) {}
                };
                document.addEventListener('mousedown', blurIfNeeded, true);
                document.addEventListener('touchstart', blurIfNeeded, true);
            };
            installFocusGuard();
            
            // ✨ NOUVEAU : Initialiser le positionnement du zoom-widget selon l'état de la sidebar droite
            setTimeout(() => {
                const rightSidebar = document.getElementById('rightSidebar');
                const zoomWidget = document.getElementById('zoomWidget');
                if (rightSidebar && zoomWidget) {
                    if (rightSidebar.classList.contains('collapsed')) {
                        zoomWidget.style.right = 'calc(56px + 16px)';
                    } else {
                        zoomWidget.style.right = 'calc(280px + 16px)';
                    }
                }
                
                syncZoomWidgetWithRightSidebar();
                
                // ✨ MENU BURGER MOBILE : Initialiser les event listeners
                initMobileBurgerMenu();
            }, 100);
        } else if (untilRaw && !stillValid) {
            localStorage.removeItem('sp_login_ok');
            localStorage.removeItem('sp_login_until');
        }
    } catch (e) {
        console.warn('Auto-login indisponible :', e);
    }
});

// Surveillance continue des exigences système
function startSystemMonitoring() {
    const MIN_SCREEN_WIDTH_PX = 890;
    const MIN_SCREEN_HEIGHT_PX = 700;
    let resizeTimeout = null;

    window.addEventListener('resize', () => {
        const newWidth = window.innerWidth;
        const newHeight = window.innerHeight;

        // Small-screen warning removed (user request)

        // FIX: Ne PAS reconstruire les canvases lors d'un resize navigateur.
        // renderAllPages() détruit et recrée tous les canvases, ce qui provoque
        // des décalages d'objets en mode spread à cause des transformations de
        // coordonnées (bleed, centerX). Le contenu des pages est en coordonnées
        // absolues et n'a pas besoin d'être reconstruit quand la fenêtre change.
        // Seul le scroll/centrage visuel peut être ajusté si nécessaire.
    });

    const refreshOnFullscreen = () => {
        setTimeout(() => {
            if (typeof renderAllPages === 'function') {
                renderAllPages();
            }
        }, 100);
    };

    document.removeEventListener('fullscreenchange', refreshOnFullscreen);
    document.removeEventListener('webkitfullscreenchange', refreshOnFullscreen);
    document.removeEventListener('mozfullscreenchange', refreshOnFullscreen);
    document.removeEventListener('msfullscreenchange', refreshOnFullscreen);
    document.addEventListener('fullscreenchange', refreshOnFullscreen);
    document.addEventListener('webkitfullscreenchange', refreshOnFullscreen);
    document.addEventListener('mozfullscreenchange', refreshOnFullscreen);
    document.addEventListener('msfullscreenchange', refreshOnFullscreen);

    // 🛡️ FIX 2026-05-08 : monitoring mémoire — timer unique (évite empilement
    //   si startSystemMonitoring() est rappelé), check toutes les 5 s au lieu
    //   de 20 s pour réagir avant le jank, et log explicite quand on franchit
    //   un seuil pour aider à diagnostiquer les sessions longues.
    try { if (window._spMemMonitorTimer) clearInterval(window._spMemMonitorTimer); } catch(_e) {}
    window._spMemMonitorTimer = setInterval(() => {
        // 🔋 v1.7.93 : pas de monitoring mémoire en arrière-plan (le navigateur gère déjà le GC,
        //   et les onglets cachés ne génèrent pas de nouvelle pression mémoire utilisateur).
        if (document.hidden) return;
        if (performance && performance.memory && performance.memory.usedJSHeapSize) {
            const usedMB = Math.round(performance.memory.usedJSHeapSize / 1024 / 1024);
            if (usedMB > 500) {
                if (window._spLastMemWarn !== 'high' || (Date.now() - (window._spLastMemWarnAt||0)) > 30000) {
                    console.warn('[SP][Memory] Pression haute :', usedMB, 'MB — release aggressive');
                    window._spLastMemWarn = 'high'; window._spLastMemWarnAt = Date.now();
                }
                try { _spReleaseMemoryPressure(true); } catch(_e) {}
            } else if (usedMB > 300) {
                if (window._spLastMemWarn !== 'mid' || (Date.now() - (window._spLastMemWarnAt||0)) > 60000) {
                    console.info('[SP][Memory] Pression modérée :', usedMB, 'MB — release soft');
                    window._spLastMemWarn = 'mid'; window._spLastMemWarnAt = Date.now();
                }
                try { _spReleaseMemoryPressure(false); } catch(_e) {}
            } else {
                window._spLastMemWarn = null;
            }
        }
    }, 5000);

    // ⚡ SYSTÈME DE LIBÉRATION DE MÉMOIRE
    window._spReleaseMemoryPressure = function(aggressive) {
        // Un rebuild Flatplan recrée images et textes de façon asynchrone. Purger
        // leurs caches pendant cette fenêtre peut laisser Chrome recalculer une
        // géométrie partielle au premier clic, surtout sur les machines lentes.
        if (_isRenderingAllPages || (typeof canvases !== 'undefined' && canvases.some(c => c && (c._isLoading || c._spRenderReady === false)))) {
            return;
        }
        // 1) Réduire l'historique (le plus gros consommateur)
        const maxHistory = aggressive ? 5 : 10;
        while (typeof history !== 'undefined' && history.length > maxHistory) {
            const old = history.shift();
            if (old) { old.pages = null; old.textLinks = null; old.masterPages = null; }
            if (typeof historyStep !== 'undefined') historyStep--;
        }
        if (typeof historyStep !== 'undefined' && historyStep < 0) historyStep = 0;

        // 2) Vider le cache de caractères Fabric (peut devenir énorme avec beaucoup de polices)
        if (typeof fabric !== 'undefined' && fabric.charWidthsCache) {
            fabric.charWidthsCache = {};
        }

        // 3) Libérer les caches d'objets des canvases NON actifs
        if (typeof canvases !== 'undefined' && typeof currentPageIndex !== 'undefined') {
            canvases.forEach((c, idx) => {
                if (!c) return;
                // En mode spread, déterminer si le canvas contient la page active
                const bi = c.bleedInfo || {};
                const isActive = (bi.pageIndex === currentPageIndex) ||
                                 (bi.leftPageIndex === currentPageIndex) ||
                                 (bi.rightPageIndex === currentPageIndex);
                if (isActive) return;
                try {
                    c.getObjects().forEach(obj => {
                        if (obj && obj._cacheCanvas) {
                            obj._cacheCanvas.width = 0;
                            obj._cacheCanvas.height = 0;
                            obj._cacheCanvas = null;
                            obj._cacheContext = null;
                            obj.dirty = true;
                        }
                    });
                } catch(_) {}
            });
        }

        // 4) En mode agressif, forcer un GC hint si disponible
        if (aggressive && window.gc) {
            try { window.gc(); } catch(_) {}
        }

        console.info('[SUPERPRINT] Mémoire libérée (mode ' + (aggressive ? 'AGRESSIF' : 'léger') + ')');
    };

}

// ==================== COLLER (PASTE) : TEXTE BRUT + ZÉRO DÉCALAGE UI ====================
// Objectif: éviter que du contenu HTML (copié depuis Internet) déclenche des sauts de scroll
// ou fasse apparaître des éléments parasites pendant l'édition d'un bloc texte.
function spNormalizePastedText(raw) {
    if (raw == null) return '';
    let text = String(raw);
    // Normaliser les fins de ligne
    text = text.replace(/\r\n?/g, '\n');
    // Nettoyer caractères invisibles fréquents (copie web)
    text = text.replace(/\u00A0/g, ' '); // NBSP
    text = text.replace(/[\u200B-\u200D\uFEFF]/g, ''); // zero-width
    text = text.replace(/[\u2028\u2029]/g, '\n'); // line/paragraph separators
    return text;
}

function spPreserveUiScroll(action) {
    const scroller = document.scrollingElement || document.documentElement;
    const docLeft = scroller ? scroller.scrollLeft : 0;
    const docTop = scroller ? scroller.scrollTop : 0;
    const canvasArea = document.getElementById('canvasScrollArea');
    const areaLeft = canvasArea ? canvasArea.scrollLeft : 0;
    const areaTop = canvasArea ? canvasArea.scrollTop : 0;

    action();

    const restore = () => {
        try {
            if (scroller) {
                scroller.scrollLeft = docLeft;
                scroller.scrollTop = docTop;
            }
        } catch (_) {}
        try {
            if (canvasArea) {
                canvasArea.scrollLeft = areaLeft;
                canvasArea.scrollTop = areaTop;
            }
        } catch (_) {}
    };

    const raf = (typeof requestAnimationFrame === 'function')
        ? requestAnimationFrame
        : (cb) => setTimeout(cb, 0);
    raf(restore);
    setTimeout(restore, 0);
}

function spInsertTextIntoTextarea(textarea, insertText) {
    if (!textarea) return;
    const value = textarea.value || '';
    const start = (typeof textarea.selectionStart === 'number') ? textarea.selectionStart : value.length;
    const end = (typeof textarea.selectionEnd === 'number') ? textarea.selectionEnd : value.length;
    textarea.value = value.slice(0, start) + insertText + value.slice(end);
    const pos = start + insertText.length;
    try {
        if (typeof textarea.setSelectionRange === 'function') {
            textarea.setSelectionRange(pos, pos);
        }
    } catch (_) {}
    try {
        textarea.dispatchEvent(new Event('input', { bubbles: true }));
    } catch (_) {
        try { textarea.dispatchEvent(new Event('input')); } catch (_) {}
    }
}

// ✨ FONCTION DE SYNCHRONISATION: Alignement Textarea / Fabric (anti-décalage \r\n)
function spSyncHiddenTextareaSelection(textObj) {
    if (!textObj || !textObj.hiddenTextarea) return;

    const ta = textObj.hiddenTextarea;
    const oldValue = ta.value || '';

    // ✨ CORRECTIF: Normaliser \r\n -> \n pour éviter le décalage du curseur
    if (oldValue.indexOf('\r') !== -1) {
        const start = (typeof ta.selectionStart === 'number') ? ta.selectionStart : null;
        const end = (typeof ta.selectionEnd === 'number') ? ta.selectionEnd : null;

        const countCR = (str, pos) => {
            let count = 0;
            const limit = Math.min(pos || 0, str.length);
            for (let i = 0; i < limit; i++) {
                if (str.charAt(i) === '\r') count++;
            }
            return count;
        };

        const newValue = oldValue.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
        ta.value = newValue;

        try {
            if (start !== null) ta.selectionStart = Math.max(0, start - countCR(oldValue, start));
            if (end !== null) ta.selectionEnd = Math.max(0, end - countCR(oldValue, end));
        } catch (_) {}
    }
}

// ✨ FONCTION DE SYNCHRONISATION: TextObj bounds update
// (fusionne l'ancienne version globale + la version locale imbriquée qui était
//  dupliquée — voir NOTE dans spForceInlineStyleRewrap. Évite le doublon qui
//  cassait node --check en mode ESM.)
function spSyncTextSelectionBounds(textObj) {
    try {
        if (!textObj) return;
        if (!textObj.canvas) {
            // Cas sans canvas (objet en cours d'édition détaché) : juste setCoords si dispo
            try { if (textObj.type === 'textbox' || textObj.type === 'text') textObj.setCoords && textObj.setCoords(); } catch (_) {}
            return;
        }
        textObj.dirty = true;
        // Synchronisation légère de la sélection / textarea caché (anti-décalage)
        try { if (textObj.type === 'textbox' || textObj.type === 'text') textObj.setCoords && textObj.setCoords(); } catch (_) {}
        try { textObj._updateTextarea && textObj._updateTextarea(); } catch (_) {}
        try { textObj._updateTextareaPosition && textObj._updateTextareaPosition(); } catch (_) {}
        textObj.canvas.requestRenderAll();
    } catch (_) {}
}

function spHardenFabricHiddenTextarea(textObj) {
    try {
        const ta = textObj && textObj.hiddenTextarea;
        if (!ta) return;

        // ✅ PATCH BAS NIVEAU: neutraliser toute réécriture CRLF côté Fabric
        // On force le setter de value du textarea à normaliser \r\n -> \n
        try {
            if (!ta._spValuePatched) {
                const proto = Object.getPrototypeOf(ta);
                const desc = proto && Object.getOwnPropertyDescriptor(proto, 'value');
                if (desc && typeof desc.get === 'function' && typeof desc.set === 'function') {
                    Object.defineProperty(ta, 'value', {
                        configurable: true,
                        get() {
                            return desc.get.call(this);
                        },
                        set(v) {
                            const normalized = String(v).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
                            return desc.set.call(this, normalized);
                        }
                    });
                    ta._spValuePatched = true;

                    // Normaliser la valeur actuelle si besoin
                    if (ta.value && ta.value.indexOf('\r') !== -1) {
                        ta.value = ta.value.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
                    }
                }
            }
        } catch (_) {}
        
        // UNIQUEMENT configurer les styles pour éviter les sauts d'UI
        // NE PAS toucher au contenu ou à la sélection - Fabric.js gère tout
        if (ta.style) {
            ta.style.setProperty('position', 'fixed', 'important');
            ta.style.setProperty('top', '-10000px', 'important');
            ta.style.setProperty('left', '-10000px', 'important');
            ta.style.setProperty('width', '1px', 'important');
            ta.style.setProperty('height', '1px', 'important');
            ta.style.setProperty('opacity', '0', 'important');
            ta.style.setProperty('pointer-events', 'none', 'important');
            ta.style.setProperty('z-index', '-99999', 'important');
            ta.style.setProperty('transform', 'translate3d(0,0,0)', 'important');
            ta.style.setProperty('caret-color', 'transparent', 'important');
            ta.style.setProperty('color', 'transparent', 'important');
            ta.style.setProperty('background', 'transparent', 'important');
            ta.style.setProperty('border', '0', 'important');
            ta.style.setProperty('padding', '0', 'important');
            ta.style.setProperty('margin', '0', 'important');
        }

        // Éviter le scroll automatique
        if (!ta._spScrollBlocked) {
            ta._spScrollBlocked = true;
            ta.addEventListener('scroll', (e) => {
                ta.scrollTop = 0;
                ta.scrollLeft = 0;
            }, { passive: true });
        }

        // 🛡️ FIX 2026-05-11 (mobile "Tout sélectionner") :
        //   Sur iOS/Android, la commande "Tout sélectionner" du menu contextuel
        //   natif opère sur le hiddenTextarea (qui a le focus), PAS sur le canvas.
        //   La sélection apparaît brièvement puis collapse car le tap de
        //   fermeture du menu natif déclenche un mouse:down qui replace le
        //   curseur. On écoute l'event 'select' du textarea : quand toute la
        //   valeur est sélectionnée, on maintient la sélection via une boucle
        //   requestAnimationFrame pendant ~1.5s (durée pendant laquelle le tap
        //   de fermeture du menu peut intervenir).
        if (!ta._spSelectAllListenerAttached) {
            ta._spSelectAllListenerAttached = true;
            ta.addEventListener('select', () => {
                try {
                    if (!textObj || !textObj.isEditing) return;
                    const taLen = ta.value ? ta.value.length : 0;
                    if (taLen <= 0) return;
                    const isFullSelect = (ta.selectionStart === 0 && ta.selectionEnd === taLen);
                    if (!isFullSelect) return;
                    // Synchroniser sur l'objet Fabric
                    const objLen = textObj.text ? textObj.text.length : 0;
                    textObj.selectionStart = 0;
                    textObj.selectionEnd = objLen;
                    textObj.dirty = true;
                    // 🛡️ FIX 2026-05-12 : forcer un selectionColor visible et
                    //   redessiner la sélection explicitement — Fabric ne le fait
                    //   pas via _fireSelectionChanged, et sur mobile l'absence de
                    //   mouseup canvas après le menu natif laisse l'upper-canvas
                    //   vide → la sélection paraît disparue.
                    try {
                        if (!textObj.selectionColor) textObj.selectionColor = 'rgba(13, 153, 255, 0.45)';
                    } catch (_) {}
                    try { if (typeof textObj.abortCursorAnimation === 'function') textObj.abortCursorAnimation(); } catch (_) {}
                    if (textObj.canvas) textObj.canvas.requestRenderAll();
                    try {
                        if (typeof textObj.renderCursorOrSelection === 'function') {
                            requestAnimationFrame(() => { try { textObj.renderCursorOrSelection(); } catch (_) {} });
                            setTimeout(() => { try { textObj.renderCursorOrSelection(); } catch (_) {} }, 120);
                        }
                    } catch (_) {}
                    // Boucle sticky locale (pas d'accès aux helpers de la closure interne)
                    // 🛡️ FIX 2026-05-16 (v1.7.139j bug "letter replaces letter") :
                    //   snapshot du texte initial → la boucle s'auto-arrête dès
                    //   que l'utilisateur tape le 1er caractère (sinon chaque
                    //   frappe re-applique selectAll → la frappe suivante
                    //   remplace au lieu d'insérer).
                    const _stickyInitialText = textObj.text || '';
                    const _stickyInitialLen = _stickyInitialText.length;
                    const startedAt = Date.now();
                    const stickyTick = () => {
                        if (!textObj.isEditing) return;
                        if (Date.now() - startedAt > 1500) return;
                        const len = textObj.text ? textObj.text.length : 0;
                        // Abort si l'utilisateur a tapé / supprimé / modifié le texte.
                        if (len !== _stickyInitialLen || (textObj.text || '') !== _stickyInitialText) return;
                        if (len > 0) {
                            const collapsed = (textObj.selectionEnd === textObj.selectionStart);
                            const partial = !collapsed && (textObj.selectionStart !== 0 || textObj.selectionEnd !== len);
                            if (collapsed || partial) {
                                textObj.selectionStart = 0;
                                textObj.selectionEnd = len;
                                if (textObj.hiddenTextarea) {
                                    try {
                                        textObj.hiddenTextarea.selectionStart = 0;
                                        textObj.hiddenTextarea.selectionEnd = textObj.hiddenTextarea.value.length;
                                    } catch (_) {}
                                }
                                textObj.dirty = true;
                                if (textObj.canvas) textObj.canvas.requestRenderAll();
                            }
                        }
                        requestAnimationFrame(stickyTick);
                    };
                    requestAnimationFrame(stickyTick);
                } catch (_) {}
            });
        }
    } catch (_) {}
}

// ==================== CUSTOM NUMBER SPINNERS ====================
function initNumberSpinners(root = document) {
    try {
        const inputs = root.querySelectorAll('input[type="number"]:not([data-sp-spinner])');
        inputs.forEach((input) => {
            input.setAttribute('data-sp-spinner', '1');

            const wrap = document.createElement('div');
            wrap.className = 'number-spinner-wrap';

            // Preserve flex/width/minWidth from input if set inline
            if (input.style.flex) {
                wrap.style.flex = input.style.flex;
                input.style.flex = '';
            }
            if (input.style.width) {
                wrap.style.width = input.style.width;
                input.style.width = '100%';
            }
            if (input.style.minWidth) {
                wrap.style.minWidth = input.style.minWidth;
                input.style.minWidth = '';
            }

            const parent = input.parentNode;
            if (!parent) return;
            parent.insertBefore(wrap, input);
            wrap.appendChild(input);

            const btnUp = document.createElement('button');
            btnUp.type = 'button';
            btnUp.className = 'number-spinner-btn up';
            btnUp.innerHTML = '▲';
            btnUp.tabIndex = -1;

            const btnDown = document.createElement('button');
            btnDown.type = 'button';
            btnDown.className = 'number-spinner-btn down';
            btnDown.innerHTML = '▼';
            btnDown.tabIndex = -1;

            const stepInput = (direction) => {
                try {
                    if (direction > 0) input.stepUp(); else input.stepDown();
                    input.dispatchEvent(new Event('input', { bubbles: true }));
                    input.dispatchEvent(new Event('change', { bubbles: true }));
                } catch (_) {}
            };

            btnUp.addEventListener('click', () => stepInput(1));
            btnDown.addEventListener('click', () => stepInput(-1));

            wrap.appendChild(btnUp);
            wrap.appendChild(btnDown);
        });
    } catch (_) {}
}

// ✨ Patch au bon endroit: dès la création du hiddenTextarea.
// Objectif: garantir que toute écriture dans textarea.value est normalisée en LF,
// AVANT que Fabric fasse `hiddenTextarea.value = this.text` dans enterEditing().
(function spPatchFabricInitHiddenTextarea() {
    try {
        if (typeof fabric === 'undefined' || !fabric.IText || !fabric.IText.prototype) return;
        const proto = fabric.IText.prototype;
        if (typeof proto.initHiddenTextarea !== 'function') return;
        if (proto.initHiddenTextarea._spHardened) return;
        const _orig = proto.initHiddenTextarea;
        proto.initHiddenTextarea = function() {
            const res = _orig.apply(this, arguments);
            try { spHardenFabricHiddenTextarea(this); } catch (_) {}
            return res;
        };
        proto.initHiddenTextarea._spHardened = true;
    } catch (_) {}
})();

