let canvases = [];
let pages = [];
let currentPageIndex = 0;
let pageFormat = { width: 210, height: 297 };
let margin = 20;
let bleed = 3;
let history = [];
let historyStep = -1;
let _isRestoringState = false;
let currentUnit = 'mm';
let transformLockAspect = true;
let lastTransformField = null;

const DEBUG_MODE = false;
const log = DEBUG_MODE ? console.log.bind(console) : () => {};
const logWarn = DEBUG_MODE ? console.warn.bind(console) : () => {};
const _spClone = typeof structuredClone !== 'undefined' ? structuredClone : (obj) => {
    // 🛡️ FIX 2026-05-08 : fallback robuste si JSON.stringify échoue (refs circulaires,
    //   BigInt, fonctions, DOM nodes…). Évite un throw non capturé qui casserait
    //   tous les undo/redo sur les vieux navigateurs sans structuredClone.
    try { return JSON.parse(JSON.stringify(obj)); }
    catch (e) {
        try { console.warn('[SP] _spClone fallback : non-serializable object, shallow copy used', e); } catch (_) {}
        if (Array.isArray(obj)) return obj.slice();
        if (obj && typeof obj === 'object') return Object.assign({}, obj);
        return obj;
    }
}; // Deep clone performant (structuredClone ou fallback JSON robuste)

// ⚡ PERF UNDO/REDO (2026-06-05) — Snapshot d'historique à PARTAGE STRUCTUREL.
//   Problème : chaque saveState faisait `structuredClone(pages)`, ce qui recopiait
//   des Mo de base64 (images des assets) à chaque action → freeze + 50 états × tailleDoc
//   en mémoire → crashes/instabilité quand on travaille sur les images/assets.
//   Solution : `pages[i].objects` est une chaîne JSON IMMUABLE (toujours RÉASSIGNÉE,
//   jamais mutée en place). On partage donc sa RÉFÉRENCE entre les états d'historique
//   au lieu de la recopier. Seules les méta-données (objets imbriqués éventuels) sont
//   clonées en profondeur. Résultat : plus de copie géante de base64 (fin du freeze) +
//   mémoire d'historique ~plate (1 seule copie de chaque page partagée par tous les
//   états inchangés au lieu de O(nbÉtats × tailleDoc)).
function _clonePagesShared(arr) {
    if (!Array.isArray(arr)) return _spClone(arr);
    const out = new Array(arr.length);
    for (let i = 0; i < arr.length; i++) {
        const p = arr[i];
        if (!p || typeof p !== 'object') { out[i] = p; continue; }
        const copy = {};
        for (const k in p) {
            if (!Object.prototype.hasOwnProperty.call(p, k)) continue;
            const v = p[k];
            // Chaînes (dont 'objects' = base64 lourd) + primitives : partage direct (immuable, sûr).
            if (v === null || typeof v !== 'object') {
                copy[k] = v;
            } else {
                // Structures imbriquées mutables (rare) : clone profond défensif.
                copy[k] = _spClone(v);
            }
        }
        out[i] = copy;
    }
    return out;
}

// ⚡ PERF UNDO/REDO — Préserve l'IDENTITÉ de la chaîne sérialisée d'une page : ne
//   réassigne `pageObj.objects` que si le contenu a réellement changé. Couplé au
//   partage structurel ci-dessus, les pages inchangées gardent la MÊME instance de
//   chaîne d'un saveState au suivant → tous les états d'historique partagent cette
//   unique copie (mémoire ~plate). Aucune perte de données possible : on sérialise
