    if (typeof snap.scaleY === 'number') clone.scaleY = snap.scaleY;
    if (typeof snap.width  === 'number' && snap.width  > 0) clone.width  = snap.width;
    if (typeof snap.height === 'number' && snap.height > 0) clone.height = snap.height;
    if (typeof snap.angle  === 'number') clone.angle  = snap.angle;
    if (typeof snap.skewX  === 'number') clone.skewX  = snap.skewX;
    if (typeof snap.skewY  === 'number') clone.skewY  = snap.skewY;
    clone.flipX = !!snap.flipX;
    clone.flipY = !!snap.flipY;
    if (snap.originX) clone.originX = snap.originX;
    if (snap.originY) clone.originY = snap.originY;
