            tl: { ox: 'right',  oy: 'bottom', dirX: -1, dirY: -1 },
            tr: { ox: 'left',   oy: 'bottom', dirX:  1, dirY: -1 },
            bl: { ox: 'right',  oy: 'top',    dirX: -1, dirY:  1 },
