            const L = transformData._spLocal;
            const axes = _spLocalAxes(L.angle);
            const pointer = target.canvas.getPointer(eventData.e);
            const vx = pointer.x - L.anchorPoint.x;
            const vy = pointer.y - L.anchorPoint.y;
            const localDX = vx * axes.x.x + vy * axes.x.y;
