        // ═══════════════════════════════════════════════════════════════
        // 💾 RESTAURATION DE L'HISTORIQUE PERSISTANT (UNDO + REDO)
        // Priorité 1 : session history complète (history[] + historyStep)
        //   → restaure le stack undo ET redo exactement comme avant le rechargement
        // Priorité 2 (fallback) : snapshots saveHistory (Ctrl+S / auto)
        //   → restaure uniquement l'undo (pas de redo possible)
        // ═══════════════════════════════════════════════════════════════
        function _spRestoreSaveHistory() {
    // ── Priorité 1 : Session History complète (undo + redo) ──
    if (typeof window._spLoadSessionHistory === 'function') {
        window._spLoadSessionHistory().then(sessionData => {
            if (sessionData && sessionData.history && sessionData.history.length > 0) {
                const cloneMethod = _spClone;

                // Marquer tous les états restaurés comme persistants
                const restoredHistory = sessionData.history.map(state => {
                    const s = cloneMethod(state);
                    s._persistent = true;
                    return s;
                });

                // L'état courant (Initialisation) qui vient d'être créé
                const currentState = history.length > 0 ? history[history.length - 1] : null;

                // Reconstruire l'historique complet :
                // [états restaurés AVANT historyStep] + [état courant=position] + [états restaurés APRÈS historyStep = REDO]
                const savedStep = Math.max(0, Math.min(sessionData.historyStep, restoredHistory.length - 1));
                const undoPart = restoredHistory.slice(0, savedStep + 1);
                const redoPart = restoredHistory.slice(savedStep + 1);

                // Combiner : undo persistants + état courant du reload + redo persistants
                history = [...undoPart];
                if (currentState) {
                    history.push(currentState);
                }
                const newCurrentStep = history.length - 1;
                // Ajouter les états redo APRÈS la position courante
                history = [...history, ...redoPart];
                historyStep = newCurrentStep;

                if (typeof updateHistoryPanel === 'function') updateHistoryPanel();
                console.info('[SessionHistory] Stack restauré : ' + undoPart.length + ' undo + ' + redoPart.length + ' redo');
                return;
            }

            // Pas de session history → fallback saveHistory
            _spRestoreSaveHistoryFallback();
        }).catch(err => {
            console.warn('[SessionHistory] Restore error:', err);
            _spRestoreSaveHistoryFallback();
        });
        return;
    }

    // Pas de loadSessionHistory → fallback
    _spRestoreSaveHistoryFallback();
        }

        // ── Fallback : snapshots saveHistory (undo uniquement) ──
        function _spRestoreSaveHistoryFallback() {
    if (typeof window._spLoadSaveHistory !== 'function') return;

    window._spLoadSaveHistory().then(entries => {
        if (!entries || entries.length === 0) return;

        entries.sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));

        if (entries.length > 10) {
            entries = entries.slice(entries.length - 10);
        }

        const cloneMethod = _spClone;

        const persistentStates = [];

        for (let i = 0; i < entries.length; i++) {
            const entry = entries[i];
            if (!entry.pages || entry.pages.length === 0) continue;

            const typeLabel = entry.type === 'ctrl-s' ? '💾 Ctrl+S' : '🔄 Auto-save';
            const state = {
                pages: cloneMethod(entry.pages),
                textLinks: cloneMethod(entry.textLinks || {}),
                masterPages: cloneMethod(entry.masterPages || {}),
                pageMasterAssignments: cloneMethod(entry.pageMasterAssignments || {}),
                pageNumberingSettings: cloneMethod(entry.pageNumberingSettings || {}),
                action: typeLabel,
                timestamp: entry.timeLabel || new Date(entry.timestamp).toLocaleTimeString('fr-FR'),
                _viewMode: entry.viewMode || 'single',
                _pageCount: (entry.pages || []).length,
                _persistent: true
            };
            persistentStates.push(state);
        }

        if (persistentStates.length === 0) return;

        const currentState = history.length > 0 ? history[history.length - 1] : null;

        history = [...persistentStates];
        if (currentState) {
            history.push(currentState);
        }
        historyStep = history.length - 1;

        if (typeof updateHistoryPanel === 'function') updateHistoryPanel();
        console.info('[SaveHistory] ' + persistentStates.length + ' snapshots restaurés (fallback, undo uniquement)');
    }).catch(err => {
        console.warn('[SaveHistory] Restore error:', err);
    });
        }
        
        // ⚡ PERF: Nettoyage profond d'un canvas Fabric avant dispose()
