        // Calculer l'index de page réel depuis bleedInfo
        let currentCanvasPageIndex = -1;
        if (canvas.bleedInfo) {
            if (canvas.bleedInfo.isSpread) {
                if (obj) {
                    const centerX = canvas.bleedInfo.centerX || (canvas.width / 2);
                    currentCanvasPageIndex = obj.left < centerX ? 
                        canvas.bleedInfo.leftPageIndex : 
                        canvas.bleedInfo.rightPageIndex;
                } else {
                    currentCanvasPageIndex = canvas.bleedInfo.leftPageIndex;
                }
            } else {
                currentCanvasPageIndex = canvas.bleedInfo.pageIndex;
            }
        }
        
