    function debouncedSync(target) {
        if (syncTimer) clearTimeout(syncTimer);
        syncTimer = setTimeout(() => {
            if (target && target._hasSpreadMirror) {
                syncMirrorWithSource(target);
            }
            syncTimer = null;
        }, 100); // Délai unifié pour éviter les conflits
    }

