            if (e.target._scaleRecalcTimeout) {
                clearTimeout(e.target._scaleRecalcTimeout);
                delete e.target._scaleRecalcTimeout;
            }

            // 1) Normaliser le scale de la forme pour éviter l'anamorphose accumulée
