                const contentOnly = fabricCanvas.getObjects().filter(obj => 
                    !obj.isMargin && !obj.isBleed && !obj.isGuide && !obj.isManualGuide && !obj.isTrimBox && !obj._isSpreadMirror && !obj.excludeFromExport && !obj._isChainBadge && !obj._isLinkArrow && !obj._isOverflowIndicator && !obj._isMasterRuntime && !obj._isPageNumber
                );
                
