        //   ré-écrit par le post-process pdf-lib (_needsPostProcess !== false).
        //   Remplace l'ancienne garde globale `!window._spSkipRasterImage` qui
        //   était "dernière page gagne" et cassait les docs multi-pages mixtes
        //   (si la dernière page était vectorielle, le post-process global était
        //   sauté → les pages raster perdaient leur texte en collectOnly).
        function _spAnyTextsNeedPostProcess() {
            try {
                const texts = window._spPdfTexts;
                if (!texts || !texts.length) return false;
                for (let i = 0; i < texts.length; i++) {
                    if (texts[i] && texts[i]._needsPostProcess !== false) return true;
                }
            } catch (_) {}
            return false;
        }

        // ========== CRÉATION CANVAS SPREAD UNIFIÉ ==========
        
        function createSpreadCanvas(container, leftIndex, rightIndex, width, height) {
    const spreadWrapper = document.createElement('div');
    spreadWrapper.className = 'spread-wrapper';
    spreadWrapper.style.position = 'relative';
    spreadWrapper.style.display = 'flex';
    spreadWrapper.style.justifyContent = 'center';
    spreadWrapper.style.alignItems = 'center';
    
    // FIX: Ajouter dataset pour la détection de drag & drop
    spreadWrapper.dataset.leftPage = leftIndex;
    spreadWrapper.dataset.rightPage = rightIndex;

    const canvasInner = document.createElement('div');
    canvasInner.className = 'canvas-inner';
    canvasInner.style.position = 'relative';

    // Canvas unique pour la double page
    const canvas = document.createElement('canvas');
    canvas.id = `spread-canvas-${leftIndex}`;
    
    // Largeur = 2 pages + fonds perdus EXTÉRIEURS seulement (pas au centre)
    const bleedPx = mmToPx(bleed);
    const canvasWidth = (width * 2) + (bleedPx * 2); // Bleed gauche + 2 pages + bleed droite
    const canvasHeight = height + (bleedPx * 2); // Bleed haut + page + bleed bas
    
    canvasInner.appendChild(canvas);

    // Ajout des numéros de page
    const pageNumberLeft = document.createElement('div');
    pageNumberLeft.className = 'page-number';
    pageNumberLeft.textContent = `Page  ${leftIndex + 1}`;
    pageNumberLeft.style.position = 'absolute';
    pageNumberLeft.style.left = '0';
    pageNumberLeft.style.bottom = '-24px';
    pageNumberLeft.style.color = '#999';
    pageNumberLeft.style.whiteSpace = 'nowrap';
    pageNumberLeft.style.zIndex = '10'; // 🎨 Au-dessus du canvas Fabric en mode pasteboard

    const pageNumberRight = document.createElement('div');
    pageNumberRight.className = 'page-number';
    pageNumberRight.textContent = rightIndex !== leftIndex ? `Page  ${rightIndex + 1}` : '';
    pageNumberRight.style.position = 'absolute';
    pageNumberRight.style.right = '0';
    pageNumberRight.style.bottom = '-24px';
    pageNumberRight.style.textAlign = 'right';
    pageNumberRight.style.color = '#999';
    pageNumberRight.style.whiteSpace = 'nowrap';
    pageNumberRight.style.zIndex = '10'; // 🎨 Au-dessus du canvas Fabric en mode pasteboard

    spreadWrapper.appendChild(canvasInner);
    // Attacher les numéros de page au canvasInner (pas au wrapper) pour un positionnement correct
    canvasInner.appendChild(pageNumberLeft);
    canvasInner.appendChild(pageNumberRight);

    // Ligne centrale fine pour indiquer la reliure
    const centerLine = document.createElement('div');
    centerLine.className = 'spread-center-line';
    centerLine.style.position = 'absolute';
    // 🛡 .canvas-inner reste page-size même avec pasteboard → pas d'offset à appliquer.
    centerLine.style.left = `${(canvasWidth / 2) - 0.5}px`;
    centerLine.style.top = `${bleedPx}px`;
    centerLine.style.width = '1px';
    centerLine.style.height = `${height}px`;
    centerLine.style.background = 'rgba(0,0,0,0.15)';
    centerLine.style.zIndex = '10';
    centerLine.style.pointerEvents = 'none';
    canvasInner.appendChild(centerLine);

    container.appendChild(spreadWrapper);

    // Initialiser Fabric.js sur ce canvas unique (⚡ PERF: délai minimal, l'échelonnement est géré par enableHighPerformance)
    const delay = 0;
    const _epoch = window._renderEpoch; // Capturer l'époque courante
    setTimeout(() => {
        // FIX ACCUMULATION: Abandonner si une nouvelle passe de rendu a démarré
        if (window._renderEpoch !== _epoch) return;
        
        // 🎨 PASTEBOARD V2: canvas plus large (horizontal) + plus haut (vertical)
        const pbPx = _pasteboardEnabled ? PASTEBOARD_PX : 0;
        const pbVPx = _pasteboardEnabled ? PASTEBOARD_V_PX : 0;
        const actualCanvasWidth = canvasWidth + (pbPx * 2);
        const actualCanvasHeight = canvasHeight + (pbVPx * 2);
        
        const fabricCanvas = new fabric.Canvas(canvas.id, {
            backgroundColor: '#ffffff',
            preserveObjectStacking: true,
            width: actualCanvasWidth,
            height: actualCanvasHeight,
            enableRetinaScaling: true, // ✅ FIX: Réactivé — enableRetinaScaling:false rendait tout flou sur écrans HiDPI
            imageSmoothingEnabled: true,
            selection: true,  // ✅ FIX: Activer explicitement la sélection
            selectionKey: 'shiftKey' // ✅ FIX: comportement standard (Drag=sélection, Shift+Click=multi)
        });
        fabricCanvas._spRenderReady = false;
        fabricCanvas._spRenderEpoch = _epoch;

        // ✅ FIX FOND BLANC: Forcer le background blanc immédiatement après création
        // (Fabric.js peut parfois ignorer backgroundColor passé au constructeur)
        // ⚡ PERF: pas de requestRenderAll ici — loadSpreadContent fera le render final
        fabricCanvas.setBackgroundColor('#ffffff', null);

        // 🎨 PASTEBOARD V2: table de montage grise (horizontal+vertical), zone page blanche
        if (pbPx > 0 || pbVPx > 0) {
            fabricCanvas.viewportTransform = [1, 0, 0, 1, pbPx, pbVPx]; // Décalage X + Y
            canvasInner.classList.add('pasteboard-active');
            fabricCanvas._pbCanvasInner = canvasInner;
            fabricCanvas._pbPx = pbPx;
            fabricCanvas._pbVPx = pbVPx;
            fabricCanvas._pbPageW = canvasWidth;
            fabricCanvas._pbPageH = canvasHeight;
            // 🛡 Garder la PAGE à sa position initiale : .canvas-inner reste page-size,
            // le .canvas-container est positionné en absolu décalé du pasteboard.
            canvasInner.style.width  = canvasWidth  + 'px';
            canvasInner.style.height = canvasHeight + 'px';
            canvasInner.style.overflow = 'visible';
            const _ccS = fabricCanvas.lowerCanvasEl && fabricCanvas.lowerCanvasEl.parentNode;
            if (_ccS) {
                _ccS.style.position = 'absolute';
                _ccS.style.left = (-pbPx) + 'px';
                _ccS.style.top  = (-pbVPx) + 'px';
            }
            // 🎨 Labels de page (relatifs au wrapper page-size → position normale)
            pageNumberLeft.style.left = '0px';
            pageNumberRight.style.right = '0px';
            pageNumberLeft.style.bottom = '-24px';
            pageNumberRight.style.bottom = '-24px';
            // 🎨 Override du fond: bandes grises tout autour, zone page blanche
            fabricCanvas._renderBackground = function(ctx) {
                const r = this.getRetinaScaling ? this.getRetinaScaling() : (fabric.devicePixelRatio || window.devicePixelRatio || 1);
                const _pbH = this._pbPx || 0, _pbV = this._pbVPx || 0;
                const totalW = (this._pbPageW + _pbH * 2) * r;
                const totalH = (this._pbPageH + _pbV * 2) * r;
                ctx.save();
                ctx.setTransform(1, 0, 0, 1, 0, 0);
                // Fond gris complet
                ctx.fillStyle = '#e8e8e8';
                ctx.fillRect(0, 0, totalW, totalH);
                // Zone page blanche
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(_pbH * r, _pbV * r, this._pbPageW * r, this._pbPageH * r);
                ctx.restore();
            };
            // 🎨 Filet bleu APRÈS les objets → 1.5px fin
            fabricCanvas.on('after:render', function() {
                const wrapper = this._pbCanvasInner ? this._pbCanvasInner.closest('.page-wrapper, .spread-wrapper') : null;
                if (!wrapper || !wrapper.classList.contains('active-page')) return;
                const ctx = this.getContext();
                const r = fabric.devicePixelRatio || window.devicePixelRatio || 1;
                const lw = 1.5 * r;
                const _pbH = (this._pbPx || 0) * r, _pbV = (this._pbVPx || 0) * r;
                const _cw = this._pbPageW * r, _ch = this._pbPageH * r;
                ctx.save();
                ctx.setTransform(1, 0, 0, 1, 0, 0);
                ctx.fillStyle = '#00aaff';
                // Haut
                ctx.fillRect(_pbH - lw, _pbV - lw, _cw + lw * 2, lw);
                // Bas
                ctx.fillRect(_pbH - lw, _pbV + _ch, _cw + lw * 2, lw);
                // Gauche
                ctx.fillRect(_pbH - lw, _pbV - lw, lw, _ch + lw * 2);
                // Droite
                ctx.fillRect(_pbH + _cw, _pbV - lw, lw, _ch + lw * 2);
                ctx.restore();
            });
        }

        // Stocker les informations pour ce canvas spread
        fabricCanvas.bleedInfo = {
            left: bleedPx,
            right: bleedPx,
            top: bleedPx,
            bottom: bleedPx,
            isSpread: true,
            leftPageIndex: leftIndex,
            rightPageIndex: rightIndex,
            centerX: canvasWidth / 2,
            centerY: canvasHeight / 2,      // 🎨 Centre Y de la zone page
            pageCanvasWidth: canvasWidth,   // 🎨 Dimensions sans pasteboard
            pageCanvasHeight: canvasHeight, // 🎨 Dimensions sans pasteboard
            pasteboardPx: pbPx,            // 🎨 Taille du pasteboard horizontal
            pasteboardVPx: pbVPx           // 🎨 Taille du pasteboard vertical
        };

        // FIX CRITIQUE: Ajouter à canvases en séquentiel avec push(), pas d'assignment direct
        canvases.push(fabricCanvas);
        
        // Mapper les indices de pages vers l'index du canvas dans le tableau
        if (!window.pageToCanvasMap) {
            window.pageToCanvasMap = {};
        }
        window.pageToCanvasMap[leftIndex] = canvases.length - 1;  // Index du canvas qu'on vient d'ajouter
        window.pageToCanvasMap[rightIndex] = canvases.length - 1; // Même canvas pour les deux pages

        // Charger le contenu existant des pages
        // ⚡ FIX ORDER: addSpreadGuides dans le callback — loadFromJSON efface le canvas
        // en asynchrone via canvas.clear(), les guides ajoutés avant seraient supprimés
        loadSpreadContent(fabricCanvas, leftIndex, rightIndex, () => {
            if (window._renderEpoch !== _epoch) return;
            try { addSpreadGuides(fabricCanvas, width, height, bleedPx, true); } finally {
                fabricCanvas._spRenderReady = true;
            }
        });

        // Event handlers pour le canvas spread
        setupSpreadEventHandlers(fabricCanvas, leftIndex, rightIndex);
        
        // Activer l'édition des groupes au double-clic
        if (typeof setupGroupDoubleClickEdit === 'function') {
            setupGroupDoubleClickEdit(fabricCanvas);
        }

        fabricCanvas.requestRenderAll();
        
        log(`Spread canvas créé pour pages ${leftIndex + 1}-${rightIndex + 1}`);
    }, delay);
        }

        function loadSpreadContent(fabricCanvas, leftIndex, rightIndex, onLoaded) {
    const centerX = fabricCanvas.bleedInfo.centerX;
    let objectsLoaded = 0;
    
    // FIX: Charger les objets de GAUCHE et DROITE indépendamment
    const leftObjects = [];
    const rightObjects = [];
    
    // Page gauche
    if (pages[leftIndex] && pages[leftIndex].objects) {
        try {
            const leftData = JSON.parse(pages[leftIndex].objects);
            if (leftData.objects && Array.isArray(leftData.objects)) {
                // ✅ FIX: Exclure les objets marqués comme overflow de la page droite
                // (ils seront chargés depuis la page droite avec la bonne position)
                leftData.objects.forEach(objData => {
                    if (!objData._isOverflowFromRight) {
                        leftObjects.push(objData);
                    }
                });
            }
        } catch (e) {
            // Erreur silencieuse
        }
    }
    
    // Page droite
    if (rightIndex !== leftIndex && pages[rightIndex] && pages[rightIndex].objects) {
        try {
            const rightData = JSON.parse(pages[rightIndex].objects);
            if (rightData.objects && Array.isArray(rightData.objects)) {
                // Décaler les objets de la page droite vers la droite
                // FIX BLEED OFFSET: Les données sont en référentiel "single" (bleedLeft=bleedPx)
                // Pour le spread, retirer bleedPx et ajouter centerX
                const bleedPx = mmToPx(bleed);
                rightData.objects.forEach(objData => {
                    // ✅ FIX: Exclure les objets marqués comme overflow de la page gauche
                    // (ils sont déjà chargés depuis la page gauche)
                    if (!objData._isOverflowFromLeft) {
                        objData.left = (objData.left || 0) + centerX - bleedPx;
                        rightObjects.push(objData);
                    }
                });
            }
        } catch (e) {
            // Erreur silencieuse
        }
    }
    
    // Combiner tous les objets et charger en UNE FOIS
    const allObjects = [...leftObjects, ...rightObjects];
    
    if (allObjects.length > 0) {
        const spreadData = { objects: allObjects, background: '#ffffff' };
        const _spObjectGeomRestore = _spPrepareGeometryRestore(allObjects);
        fabricCanvas._isLoading = true;
        fabricCanvas.renderOnAddRemove = false; // ⚡ PERF: éviter N renders pendant loadFromJSON
        fabricCanvas.loadFromJSON(spreadData, () => {
            fabricCanvas.renderOnAddRemove = true;
            fabricCanvas._isLoading = false;
            // 🆕 v1.7.131 : réattacher les écouteurs du lien forme↔texte (cf.
            // createPageCanvas).
            try { window._spInstallShapeTextLinkListeners && window._spInstallShapeTextLinkListeners(fabricCanvas); } catch(_) {}
            // 🎨 PASTEBOARD: Re-appliquer le viewport transform après loadFromJSON
            // (Fabric.js peut le réinitialiser lors du clear() interne)
            if (fabricCanvas._pbPx > 0 || fabricCanvas._pbVPx > 0) {
                fabricCanvas.viewportTransform = [1, 0, 0, 1, fabricCanvas._pbPx || 0, fabricCanvas._pbVPx || 0];
            }
            // FORCE WHITE BACKGROUND
            fabricCanvas.setBackgroundColor('#ffffff', () => {});

            // Restaurer la géométrie exacte avant les recalculs texte/clipPath.
            try {
                _spRestoreLoadedGeometry(fabricCanvas, _spObjectGeomRestore);
            } catch(_) {}

            // ✨ Restaurer dimensions fixes + clipPath + initDimensions monkey-patch
            fabricCanvas.getObjects().forEach(obj => {
                if (obj.type === 'textbox' || obj.type === 'text' || obj.type === 'i-text') {
                    restoreTextboxAfterLoad(obj);
                }
                // 📐 GABARITS: Rendre les items master non-sélectionnables
                if (obj._isMasterItem) {
                    obj.set({ selectable: false, evented: false, opacity: obj.opacity || 1 });
                    obj.hoverCursor = 'default';
                    // FIX TYPO GABARIT: Forcer le rendu des textbox master
                    if (obj.type === 'textbox' || obj.type === 'text' || obj.type === 'i-text') {
                        obj.set({ visible: true, dirty: true });
                        if (typeof obj.initDimensions === 'function') {
                            try { obj.initDimensions(); } catch(_) {}
                        }
                        obj.setCoords();
                    }
                }
            });

            // RESTAURER les patterns d'images dans les formes après chargement
            restoreImageMasksAfterLoad(fabricCanvas);
            
            // RÉATTACHER les contrôles crop/replace aux images
            fabricCanvas.getObjects().forEach(obj => {
                if (obj.type === 'image') {
                    try { obj._hasCropControl = false; attachCropControlToImage(obj); } catch (_) {}
                    try { obj._hasReplaceControl = false; attachReplaceControlToImage(obj); } catch (_) {}
                }
            });
            
            // RÉATTACHER les événements double-clic aux tracés plume
            reattachPenPathEvents(fabricCanvas);
            
            // VÉRIFIER les indicateurs de débordement
            setTimeout(() => {
                if (fabricCanvas._spRenderEpoch !== window._renderEpoch) return;
                try { checkTextOverflow(fabricCanvas); } catch (_) {}
            }, 100);
            
            // 🔗 RESTAURER les visuels de chaînage
            setTimeout(() => {
                if (fabricCanvas._spRenderEpoch !== window._renderEpoch) return;
                try { restoreChainVisualsForCanvas(fabricCanvas); } catch (_) {}
            }, 200);
            
            fabricCanvas.requestRenderAll();
            
            // 🔧 FIX TYPO GABARIT + FOLIOS: Créer les textbox master/page numbers
            // directement sur le canvas (contourne le bug Textbox.fromObject)
            setTimeout(() => {
                if (fabricCanvas._spRenderEpoch !== window._renderEpoch) return;
                // Spread canvas = 2 pages: ajouter les objets texte pour CHAQUE page
                try {
                    addSpecialTextObjectsToCanvas(fabricCanvas, leftIndex, 'left');
                    if (rightIndex !== leftIndex) {
                        addSpecialTextObjectsToCanvas(fabricCanvas, rightIndex, 'right');
                    }
                } finally {
                    if (typeof onLoaded === 'function') onLoaded();
                }
            }, 300);
        });
    } else {
        // ✅ Pages vides: forcer le fond blanc + render
        fabricCanvas.setBackgroundColor('#ffffff', () => {});
        fabricCanvas.requestRenderAll();
        if (typeof onLoaded === 'function') onLoaded();
    }
        }

        function setupSpreadEventHandlers(fabricCanvas, leftIndex, rightIndex) {
    const centerX = fabricCanvas.bleedInfo.centerX;
    
    // Fonction pour déterminer sur quelle page se trouve un objet
    function getPageFromPosition(x) {
        return x < centerX ? leftIndex : rightIndex;
    }
    
    // Gestion de la sélection avec détection automatique de page
    fabricCanvas.on('selection:created', (e) => {
        const selectedObj = e.target || e.selected?.[0];
        
        // Ignorer les objets de guide/marge
        if (selectedObj && (selectedObj.isMargin || selectedObj.isBleed || selectedObj.isTrimBox || selectedObj.isPage || selectedObj.isGuide)) {
            return;
        }
        
        if (selectedObj) {
            // Déterminer automatiquement la page active selon la position de l'objet
            const objCenterX = selectedObj.left + (selectedObj.width * selectedObj.scaleX / 2);
            currentPageIndex = getPageFromPosition(objCenterX);
            
            // Mettre à jour la sélection visuelle des pages
            const selectedSide = currentPageIndex === leftIndex ? 'left' : 'right';
            updateSpreadPageSelection(fabricCanvas, selectedSide);
        } else {
            currentPageIndex = leftIndex; // Par défaut, page gauche
        }
        
        updatePageIndicator();
        debouncedUpdateLayersPanel();
        updateTransformPanel();

        // (Nettoyé) Pas de bouton DOM flottant

        // Gérer les outils contextuels (crop / masque) en mode double page
        try { removeAllMaskButtons(); } catch (_) {}
        try { removeMaskPositionPanel(); } catch (_) {}

        if (selectedObj && selectedObj.type === 'image') {
            try { addCropButtonToImage(fabricCanvas, selectedObj); } catch (_) {}
        }
        if (selectedObj && selectedObj._isImageMask) {
            try { attachMaskImageControlsToShape(selectedObj); } catch (_) {}
            try { fabricCanvas && fabricCanvas.requestRenderAll && fabricCanvas.requestRenderAll(); } catch (_) {}
        }
        // 🛡️ FIX BUG 14 (2026-05-04) : ré-affirmer la mise en page pasteboard
        //   après une sélection (cliquer sur une image peut corrompre la CSS
        //   inline du .canvas-container — bord gauche qui disparaît, traits
        //   parasites). Pas de coût si pasteboard désactivé (helper sort tôt).
        try { if (typeof window._spReassertPasteboardLayout === 'function') window._spReassertPasteboardLayout(fabricCanvas); } catch(_) {}
        
        log(`Objet sélectionné sur page ${currentPageIndex + 1}`);
    });
    
    fabricCanvas.on('selection:updated', (e) => {
        const selectedObj = e.target || e.selected?.[0];
        
        if (selectedObj && !selectedObj.isMargin && !selectedObj.isBleed && !selectedObj.isTrimBox && !selectedObj.isPage && !selectedObj.isGuide) {
            // Déterminer la page selon la position de l'objet
            const objCenterX = selectedObj.left + (selectedObj.width * selectedObj.scaleX / 2);
            currentPageIndex = getPageFromPosition(objCenterX);
            
            const selectedSide = currentPageIndex === leftIndex ? 'left' : 'right';
            updateSpreadPageSelection(fabricCanvas, selectedSide);
            
            updatePageIndicator();
            debouncedUpdateLayersPanel();
            updateTransformPanel();

            // Gérer les outils contextuels (crop / masque) en mode double page
            try { removeAllMaskButtons(); } catch (_) {}
            try { removeMaskPositionPanel(); } catch (_) {}

            if (selectedObj && selectedObj.type === 'image') {
                try { addCropButtonToImage(fabricCanvas, selectedObj); } catch (_) {}
            }
            if (selectedObj && selectedObj._isImageMask) {
                try { attachMaskImageControlsToShape(selectedObj); } catch (_) {}
                try { fabricCanvas && fabricCanvas.requestRenderAll && fabricCanvas.requestRenderAll(); } catch (_) {}
            }
            // 🛡️ FIX BUG 14 (2026-05-04) : ré-affirmer la mise en page pasteboard
            //   après changement de sélection (idem selection:created).
            try { if (typeof window._spReassertPasteboardLayout === 'function') window._spReassertPasteboardLayout(fabricCanvas); } catch(_) {}
        }
    });

    fabricCanvas.on('selection:cleared', () => {
        try { removeAllMaskButtons(); } catch (_) {}
        try { removeMaskPositionPanel(); } catch (_) {}
    });
    
    // Clic général sur le canvas pour détecter la page
    fabricCanvas.on('mouse:down', (e) => {
        // AMÉLIORATION : Toujours détecter sur quelle page on clique (fond OU objet)
        const clickX = e.pointer ? e.pointer.x : 0;
        const clickedPageIndex = getPageFromPosition(clickX);
        
        // Mettre à jour la page active (même si on clique sur un objet)
        if (currentPageIndex !== clickedPageIndex) {
            currentPageIndex = clickedPageIndex;
            const selectedSide = currentPageIndex === leftIndex ? 'left' : 'right';
            updateSpreadPageSelection(fabricCanvas, selectedSide);
            updatePageIndicator();
            log(`Spread - Page ${currentPageIndex + 1} sélectionnée (${selectedSide})`);
        }
        
        // Si clic sur fond vide (pas d'objet), forcer la mise à jour
        if (!e.target) {
            const selectedSide = currentPageIndex === leftIndex ? 'left' : 'right';
            updateSpreadPageSelection(fabricCanvas, selectedSide);
            updatePageIndicator();
            log(`Clic sur fond - Page ${currentPageIndex + 1} sélectionnée`);
        }
    });

    // Survol: mettre en évidence la page sous la souris (léger), sans changer la sélection
    function updateSpreadHoverHighlight(fabricCanvas, hoverSide) {
        if (fabricCanvas._hoverSide === hoverSide) return;
        fabricCanvas._hoverSide = hoverSide;
        const isLeftSelected = (currentPageIndex === leftIndex);
        const isRightSelected = (currentPageIndex === rightIndex);

        fabricCanvas.getObjects().forEach(obj => {
            if (!obj.isPage) return;
            // D'abord remettre l'état de base selon la sélection
            obj.set({ fill: 'transparent', stroke: 'transparent', strokeWidth: 0 });
        });

        // Réappliquer la sélection active
        if (isLeftSelected || isRightSelected) {
            const selectedSide = isLeftSelected ? 'left' : 'right';
            updateSpreadPageSelection(fabricCanvas, selectedSide);
        }

        // Appliquer le hover uniquement sur la page non sélectionnée - DÉSACTIVÉ
        /*
        fabricCanvas.getObjects().forEach(obj => {
            if (!obj.isPage) return;
            if (hoverSide === 'left' && obj.pageIndex === leftIndex && !isLeftSelected) {
                obj.set({ fill: 'rgba(0, 100, 255, 0.04)', stroke: 'rgba(0, 100, 255, 0.2)', strokeWidth: 1 });
            } else if (hoverSide === 'right' && obj.pageIndex === rightIndex && !isRightSelected) {
                obj.set({ fill: 'rgba(0, 100, 255, 0.04)', stroke: 'rgba(0, 100, 255, 0.2)', strokeWidth: 1 });
            }
        });
        fabricCanvas.requestRenderAll();
        */
    }

    fabricCanvas.on('mouse:move', (e) => {
        // Désactivé : pas d'effet de survol en mode double page
        /*
        if (!e.pointer) return;
        const hoverX = e.pointer.x;
        const hoverSide = hoverX < centerX ? 'left' : 'right';
        updateSpreadHoverHighlight(fabricCanvas, hoverSide);
        */
    });

    fabricCanvas.on('mouse:out', () => {
        // Désactivé : pas de nettoyage de hover en mode double page
        /*
        delete fabricCanvas._hoverSide;
        // Nettoyer le hover sans toucher à la sélection
        fabricCanvas.getObjects().forEach(obj => {
            if (obj.isPage) {
                obj.set({ stroke: 'transparent' });
                if (currentPageIndex !== obj.pageIndex) {
                    obj.set({ fill: 'transparent' });
                }
            }
        });
        fabricCanvas.requestRenderAll();
        */
    });

    fabricCanvas.on('object:modified', (e) => {
        // Sauvegarder uniquement si ce n'est pas un guide
        if (!e.target || (!e.target.isMargin && !e.target.isBleed && !e.target.isTrimBox && !e.target.isPage && !e.target.isGuide)) {
            saveSpreadContent(fabricCanvas, leftIndex, rightIndex);
            // 🛡️ FIX 2026-08-25 : ne pas créer d'entrée « Objet modifié » pendant un
            //   transfert cross-page (le completeObjectTransfer appelle déjà
            //   saveState('Objet déplacé...') → éviter la double entrée qui cassait
            //   le Ctrl+Z).
            if (fabricCanvas._isTransferring) return;
            // ⚡ PERF: debounce saveState en mode spread
            debouncedSaveState('Objet modifié');
        }
        // Mettre à jour le panneau de transformation
        updateTransformPanel();
    });

    fabricCanvas.on('object:added', (e) => {
        // ✨ FIX DUPLICATION: Ne pas sauvegarder ici car saveAllPages est déjà appelé
        // par le handler global object:added dans attachCanvas()
        // Cela évite le double appel de saveSpreadContent qui causait la duplication des objets
        // DÉSACTIVÉ pour éviter la duplication
        /*
        // Exclure les guides de la sauvegarde
        if (e.target && !e.target.isMargin && !e.target.isBleed && !e.target.isTrimBox && !e.target.isPage && !e.target.isGuide) {
            saveSpreadContent(fabricCanvas, leftIndex, rightIndex);
        }
        */
    });
    
    fabricCanvas.on('object:removed', (e) => {
        // Vérifier si on supprime accidentellement un guide
        if (e.target && (e.target.isMargin || e.target.isBleed || e.target.isTrimBox || e.target.isPage || e.target.isGuide)) {
            console.warn('Guide supprimé accidentellement, restauration...');
            // Petite pause puis restauration
            setTimeout(() => {
                const width = mmToPx(pageFormat.width);
                const height = mmToPx(pageFormat.height);
                const bleedPx = mmToPx(bleed);
                ensureSpreadGuidesExist(fabricCanvas, width, height, bleedPx);
            }, 100);
        } else if (e.target) {
            saveSpreadContent(fabricCanvas, leftIndex, rightIndex);
            // 🔥 BUG03 FIX : nettoyer badges/flèches orphelins en mode spread aussi
            if (typeof cleanOrphanedChainVisuals === 'function') {
                cleanOrphanedChainVisuals(fabricCanvas);
            }
            // 🛡️ FIX 2026-08-25 (doublon fantôme après Ctrl+Z) : ne PLUS créer
            //   d'entrée d'historique ici (même logique que le canvas simple).
            //   La suppression utilisateur (Delete) appelle déjà saveState dans
            //   son handler clavier ; les autres retraits d'objets sont des
            //   opérations INTERNES (transfert cross-page, clear() d'un restore,
            //   recréation de guides) qui ne doivent pas polluer le stack undo/redo.
            //   Sans ce retrait, le clear() de _fastRestoreCanvases/renderAllPages
            //   déclenchait des object:removed en cascade → entrée « Objet supprimé »
            //   parasite qui « mangeait » un step d'undo → Ctrl+Z ne remettait pas le
            //   bloc à sa place et le doublon restait sur la page active.
            //   (saveSpreadContent garde ses propres guards restore/render/loading.)
        }
    });
    
    // DÉSACTIVÉ temporairement : Ajouter une vérification périodique des guides (sécurité)
    /*
    fabricCanvas.on('after:render', () => {
        const guidesCount = fabricCanvas.getObjects().filter(obj => 
            obj.isMargin || obj.isBleed || obj.isTrimBox || obj.isPage || obj.isGuide
        ).length;
        
        // Si moins de 8 guides, il y a un problème
        if (guidesCount < 8) {
            console.warn(`Guides manquants (${guidesCount}/8+), restauration différée...`);
        }
    });
    */
        }

        function saveSpreadContent(fabricCanvas, leftIndex, rightIndex) {
    // 🛡️ FIX 2026-05-08 (v1.7.108) : guards anti-corruption.
    //   1. Canvas en cours de destruction : object:removed flood pendant teardown
    //      → réécrirait pages[] avec un set d'objets qui rétrécit (perte de contenu).
    //   2. Reconstruction globale en cours : pages[] est l'état-cible, ne pas écraser.
    //   3. Restauration undo/redo : pages[] contient l'état historique, idem.
    //   4. Canvas en cours de loadFromJSON : getObjects() partiel → écrasement nuisible.
    if (!fabricCanvas || fabricCanvas._spDisposing) return;
    if (_isRenderingAllPages) return;
    if (_isRestoringState) return;
    if (fabricCanvas._isLoading) return;
    // CORRECTION : Vérifier que les pages existent avant de sauvegarder
    if (!pages[leftIndex] || (rightIndex !== leftIndex && !pages[rightIndex])) {
        console.warn(`Pages inexistantes lors de la sauvegarde spread: ${leftIndex}, ${rightIndex}`);
        return;
    }
    // 🛡️ FIX 2026-09-02 : saveAllPages() a déjà un garde-fou contre les images
    //   encore en décodage async (_spHasPendingAsyncImageLoad) mais saveSpreadContent
    //   (le chemin de sauvegarde RÉEL en mode spread, le mode standard pour les
    //   documents multi-pages) ne l'avait PAS. Juste après une duplication de page
    //   via Flatplan (page dupliquée contenant images/formes/texte), si l'utilisateur
    //   clique/modifie un objet avant que les images aient fini de se recharger,
    //   getObjects() est incomplet → écrasement de pages[leftIndex/rightIndex].objects
    //   par un snapshot partiel (objets perdus, coordonnées incohérentes au reload).
    const _hasPendingAsync = _spHasPendingAsyncImageLoad(fabricCanvas);

    const customProps = SP_CUSTOM_PROPS;

    // Séparer les objets selon leur position (gauche ou droite de la reliure)
    // ✅ FIX EXPORT: Les objets qui chevauchent les deux pages sont sauvegardés sur LES DEUX
    const allObjects = fabricCanvas.getObjects().filter(obj => 
        !obj.isMargin && !obj.isBleed && !obj.isGuide && !obj.isManualGuide && !obj.isTrimBox && !obj.isPage && !obj._isSpreadMirror && !obj.excludeFromExport && !obj._isChainBadge && !obj._isLinkArrow && !obj._isOverflowIndicator && !obj._isMasterRuntime && !obj._isPageNumber
    );
    
    const leftObjects = [];
    const rightObjects = [];
    const centerX = fabricCanvas.bleedInfo.centerX || ((fabricCanvas.bleedInfo.pageCanvasWidth || fabricCanvas.width) / 2);
    const bleedPx = mmToPx(bleed);

    allObjects.forEach(obj => {
        // CORRECTION : Ignorer les objets miroirs lors de la sauvegarde
        if (obj._isSpreadMirror) return;
        
        // FIX: Convertir en objet JSON UNE SEULE FOIS avec propriétés custom
        // 🛡️ FIX 2026-05-01 : strip clipPath pour TOUS les textbox/text
        // (recree au load via applyTextboxClipPath, evite incoherences avec le snap).
        // 🛡️ FIX 2026-05-13 (v1.7.134) : sauf pour `_isShapeClippedText`
        // (texte « dedans une forme » — cf. commentaire identique dans saveAllPages).
        const objData = obj.toObject(customProps);
        if (objData.clipPath && (objData.type === 'textbox' || objData.type === 'text' || objData._fixedHeight || objData.isLinkedTextBlock)) {
            if (!objData._isShapeClippedText) delete objData.clipPath;
        }
        
        // Calculer les bords gauche et droit de l'objet
        const objWidth = (obj.width || 0) * (obj.scaleX || 1);
        let objLeftEdge, objRightEdge;
        
        if (obj.type === 'circle' || obj.type === 'ellipse' || obj.type === 'polygon' || obj.type === 'path') {
            // Pour les formes centrées, obj.left EST le centre
            objLeftEdge = obj.left - objWidth / 2;
            objRightEdge = obj.left + objWidth / 2;
        } else {
            // Pour les rectangles, textbox, images : obj.left = coin supérieur gauche
            objLeftEdge = obj.left;
            objRightEdge = obj.left + objWidth;
        }
        
        // Déterminer si l'objet touche la page gauche et/ou droite
        const touchesLeft = objLeftEdge < centerX;
        const touchesRight = objRightEdge > centerX;
        
        // ✅ FIX: Déterminer la page "principale" par le centre
        let objCenterX;
        if (obj.type === 'circle' || obj.type === 'ellipse' || obj.type === 'polygon' || obj.type === 'path') {
            objCenterX = obj.left;
        } else {
            objCenterX = obj.left + objWidth / 2;
        }
        const primaryPage = objCenterX < centerX ? 'left' : 'right';
        
        if (touchesLeft) {
            // Objet touche la page gauche : sauvegarder avec position originale
            const leftObjData = { ...objData };
            // Marquer si c'est un objet qui chevauche (pas la page principale)
            if (primaryPage === 'right') {
                leftObjData._isOverflowFromRight = true;
            }
            leftObjects.push(leftObjData);
        }
        
        if (touchesRight) {
            // Objet touche la page droite : ajuster la position (retirer centerX)
            // FIX BLEED OFFSET: Ajouter bleedPx pour normaliser vers le référentiel "single"
            // En spread, l'objet au bord gauche de la page droite est à x=centerX
            // Après décalage: left = obj.left - centerX = 0
            // Mais en mode single, il devrait être à x=bleedPx → ajouter bleedPx
            const rightObjData = { ...objData };
            rightObjData.left = obj.left - centerX + bleedPx;
            // Marquer si c'est un objet qui chevauche (pas la page principale)
            if (primaryPage === 'left') {
                rightObjData._isOverflowFromLeft = true;
            }
            rightObjects.push(rightObjData);
        }
    });

    // Sauvegarder les objets dans leurs pages respectives
    // SÉCURITÉ: Ne pas écraser des données existantes par des données vides
    try {
        // 🛡️ FIX 2026-09-02 : compter les objets utilisateur déjà stockés pour CHAQUE
        //   demi-page. Si une image est encore en décodage async ET que le nouveau
        //   snapshot perdrait >1 objet par rapport à l'existant, refuser l'écrasement
        //   (même logique que BUG 20 dans saveAllPages, jamais appliquée ici jusqu'ici).
        let leftExistingUserCount = 0;
        try {
            const exL = typeof pages[leftIndex].objects === 'string' ? JSON.parse(pages[leftIndex].objects) : pages[leftIndex].objects;
            if (exL && exL.objects) leftExistingUserCount = exL.objects.filter(o => o && !o._isMasterItem && !o._isMasterRuntime && !o._isPageNumber).length;
        } catch(_) {}
        const leftJson = JSON.stringify({ objects: leftObjects });
        if (_hasPendingAsync && leftExistingUserCount >= 2 && leftObjects.length < leftExistingUserCount - 1) {
            console.warn(`[saveSpreadContent] Page ${leftIndex} : refus d'ecraser ${leftExistingUserCount} objets par ${leftObjects.length} (image asynchrone en cours)`);
        } else if (leftObjects.length > 0 || !pages[leftIndex].objects) {
            pages[leftIndex].objects = leftJson;
        } else {
            // Vérifier si l'existant avait réellement des données
            let existingHasData = false;
            try {
                const ex = typeof pages[leftIndex].objects === 'string' ? JSON.parse(pages[leftIndex].objects) : pages[leftIndex].objects;
                existingHasData = ex && ex.objects && ex.objects.filter(o => !o._isMasterItem).length > 0;
            } catch(_) {}
            if (!existingHasData) {
                pages[leftIndex].objects = leftJson;
            } else {
                console.warn(`[saveSpreadContent] Page ${leftIndex} : canvas vide mais données existantes — préservation`);
            }
        }
        if (rightIndex !== leftIndex && pages[rightIndex]) {
            let rightExistingUserCount = 0;
            try {
                const exR = typeof pages[rightIndex].objects === 'string' ? JSON.parse(pages[rightIndex].objects) : pages[rightIndex].objects;
                if (exR && exR.objects) rightExistingUserCount = exR.objects.filter(o => o && !o._isMasterItem && !o._isMasterRuntime && !o._isPageNumber).length;
            } catch(_) {}
            const rightJson = JSON.stringify({ objects: rightObjects });
            if (_hasPendingAsync && rightExistingUserCount >= 2 && rightObjects.length < rightExistingUserCount - 1) {
                console.warn(`[saveSpreadContent] Page ${rightIndex} : refus d'ecraser ${rightExistingUserCount} objets par ${rightObjects.length} (image asynchrone en cours)`);
            } else if (rightObjects.length > 0 || !pages[rightIndex].objects) {
                pages[rightIndex].objects = rightJson;
            } else {
                let existingHasData = false;
                try {
                    const ex = typeof pages[rightIndex].objects === 'string' ? JSON.parse(pages[rightIndex].objects) : pages[rightIndex].objects;
                    existingHasData = ex && ex.objects && ex.objects.filter(o => !o._isMasterItem).length > 0;
                } catch(_) {}
                if (!existingHasData) {
                    pages[rightIndex].objects = rightJson;
                } else {
                    console.warn(`[saveSpreadContent] Page ${rightIndex} : canvas vide mais données existantes — préservation`);
                }
            }
        }
    } catch (error) {
        console.error('Erreur lors de la sauvegarde spread:', error);
    }

    // 🔬 DIAG 2026-05-10 (Bug 23 — spread+asset+imposition) :
    // tracer ce qui est effectivement sauvegardé pour chaque demi-page d'un spread.
    if (window.__sp_imp_debug) {
        try {
            console.log('[saveSpreadContent] L=' + leftIndex + ' R=' + rightIndex
                + ' allObj=' + allObjects.length
                + ' leftObj=' + leftObjects.length
                + ' rightObj=' + rightObjects.length
                + ' centerX=' + Math.round(centerX));
        } catch(_) {}
    }
        }

        function attachSpreadPageEvents(fabricCanvas, leftPageRect, rightPageRect) {
    // Events page GAUCHE
    leftPageRect.on('mousedown', () => {
        currentPageIndex = fabricCanvas.bleedInfo.leftPageIndex;
        updatePageIndicator();
        updateSpreadPageSelection(fabricCanvas, 'left');
        log(`Page gauche sélectionnée: ${currentPageIndex + 1}`);
    });
    
    leftPageRect.on('mouseover', () => {
        if (currentPageIndex !== fabricCanvas.bleedInfo.leftPageIndex) {
            leftPageRect.set({
                fill: 'rgba(0, 100, 255, 0.03)',
                stroke: 'rgba(0, 100, 255, 0.2)',
                strokeWidth: 1
            });
            fabricCanvas.requestRenderAll();
        }
    });
    
    leftPageRect.on('mouseout', () => {
        if (currentPageIndex !== fabricCanvas.bleedInfo.leftPageIndex) {
            leftPageRect.set({
                fill: 'transparent',
                stroke: 'transparent',
                strokeWidth: 0
            });
            fabricCanvas.requestRenderAll();
        }
    });
    
    // Events page DROITE
    rightPageRect.on('mousedown', () => {
        currentPageIndex = fabricCanvas.bleedInfo.rightPageIndex;
        updatePageIndicator();
        updateSpreadPageSelection(fabricCanvas, 'right');
        log(`Page droite sélectionnée: ${currentPageIndex + 1}`);
    });
    
    rightPageRect.on('mouseover', () => {
        if (currentPageIndex !== fabricCanvas.bleedInfo.rightPageIndex) {
            rightPageRect.set({
                fill: 'rgba(0, 100, 255, 0.03)',
                stroke: 'rgba(0, 100, 255, 0.2)',
                strokeWidth: 1
            });
            fabricCanvas.requestRenderAll();
        }
    });
    
    rightPageRect.on('mouseout', () => {
        if (currentPageIndex !== fabricCanvas.bleedInfo.rightPageIndex) {
            rightPageRect.set({
                fill: 'transparent',
                stroke: 'transparent',
                strokeWidth: 0
            });
            fabricCanvas.requestRenderAll();
        }
    });
    
    log(`événements de sélection attachés pour pages ${fabricCanvas.bleedInfo.leftPageIndex + 1} et ${fabricCanvas.bleedInfo.rightPageIndex + 1}`);
        }

        function addSpreadGuides(fabricCanvas, width, height, bleedPx, forceRecreate = false) {
    const pageInfo = fabricCanvas.bleedInfo ? 
        `Pages ${fabricCanvas.bleedInfo.leftPageIndex + 1}-${fabricCanvas.bleedInfo.rightPageIndex + 1}` : 
        'Page inconnue';
        
    log(`addSpreadGuides appelé pour ${pageInfo}, forceRecreate: ${forceRecreate}`);
    
    // Vérifier si les guides existent déjà pour éviter les doublons
    const existingGuides = fabricCanvas.getObjects().filter(obj => 
        obj.isMargin || obj.isBleed || obj.isTrimBox || obj.isPage || obj.isGuide
    );
    
    log(`Guides existants: ${existingGuides.length} pour ${pageInfo}`);
    
    // ⚡ PERF: si forceRecreate mais que le format correspond déjà, skip la recréation
    // 🛡️ FIX 2026-05-08 : on ne peut SKIP que si en plus le pairage de pages
    //   (leftPageIndex/rightPageIndex) est identique. Après un drag-drop chemin
    //   de fer, le canvas peut être réutilisé avec MEMES dimensions mais NOUVEAU
    //   pairage → les anciens guides (centerX, bindingLine) doivent être recréés.
    //   Sans cette vérif, des traits verticaux fantômes apparaissent sur la page
    //   droite vide (bug rapporté par utilisateur). On ajoute aussi le check
    //   centerX au cas où il aurait changé (largeur canvas modifiée).
    if (forceRecreate && existingGuides.length > 0) {
        const bi = fabricCanvas.bleedInfo || {};
        const expectedW = (width * 2) + (bleedPx * 2);
        const expectedH = height + (bleedPx * 2);
        const samePairing = (bi._guidesLeftIdx === bi.leftPageIndex && bi._guidesRightIdx === bi.rightPageIndex);
        if (bi._guidesW === expectedW && bi._guidesH === expectedH && bi._guidesM === margin && samePairing) {
            log(`✅ Guides spread inchangés pour ${pageInfo}, recréation ignorée`);
            return;
        }
    }
    
    // Si les guides existent déjà et qu'on ne force pas la recréation, ne pas les recréer
    if (existingGuides.length > 0 && !forceRecreate) {
        log(`ℹ️ Guides spread déjà présents pour ${pageInfo}, pas de recréation nécessaire`);
        return;
    }
    
    // Supprimer les guides existants si on force la recréation
    if (forceRecreate && existingGuides.length > 0) {
        existingGuides.forEach(obj => fabricCanvas.remove(obj));
        log(`Guides spread supprimés pour recréation forcée: ${pageInfo}`);
    }
    
    const centerX = fabricCanvas.bleedInfo.centerX;
    const marginPx = mmToPx(margin);
    // 🎨 PASTEBOARD: utiliser les dimensions de page (sans pasteboard) pour les guides
    const guideCanvasW = fabricCanvas.bleedInfo.pageCanvasWidth || fabricCanvas.width;
    const guideCanvasH = fabricCanvas.bleedInfo.pageCanvasHeight || fabricCanvas.height;
    
    // 1. FOND PERDU (contour pointillé uniquement — PAS de fill gris qui ternit le blanc)
    const fullBleedRect = new fabric.Rect({
        left: 0,
        top: 0,
        width: guideCanvasW,
        height: guideCanvasH,
        fill: 'transparent',
        stroke: '#cccccc',
        strokeWidth: 1,
        strokeDashArray: [5, 5],
        selectable: false,
        evented: false,
        isBleed: true,
        excludeFromExport: true
    });
    
    // 2. TRAITS DE COUPE - Format FINAL (comme pages simples)
    // Page gauche - pas de trait à droite (côté reliure)
    const leftTrimBox = new fabric.Group([
        new fabric.Line([bleedPx, bleedPx, bleedPx + width, bleedPx], { stroke: '#2a2a2a', strokeWidth: 2 }), // haut
        new fabric.Line([bleedPx, bleedPx, bleedPx, bleedPx + height], { stroke: '#2a2a2a', strokeWidth: 2 }), // gauche
        new fabric.Line([bleedPx, bleedPx + height, bleedPx + width, bleedPx + height], { stroke: '#2a2a2a', strokeWidth: 2 }) // bas
    ], {
        selectable: false,
        evented: false,
        excludeFromExport: true,
        isTrimBox: true
    });
    
    // Page droite - pas de trait à gauche (côté reliure)  
    const rightTrimBox = new fabric.Group([
        new fabric.Line([bleedPx + width, bleedPx, bleedPx + width * 2, bleedPx], { stroke: '#2a2a2a', strokeWidth: 2 }), // haut
        new fabric.Line([bleedPx + width * 2, bleedPx, bleedPx + width * 2, bleedPx + height], { stroke: '#2a2a2a', strokeWidth: 2 }), // droite
        new fabric.Line([bleedPx + width, bleedPx + height, bleedPx + width * 2, bleedPx + height], { stroke: '#2a2a2a', strokeWidth: 2 }) // bas
    ], {
        selectable: false,
        evented: false,
        excludeFromExport: true,
        isTrimBox: true
    });
    
    // 3. ZONES DE SÉLECTION DE PAGES (invisibles par défaut, comme pages simples)
    const leftPageRect = new fabric.Rect({
        left: bleedPx,
        top: bleedPx,
        width: width,
        height: height,
        fill: 'transparent',
        stroke: 'transparent',
        strokeWidth: 0,
        selectable: false,
        evented: false, // ✅ FIX: DÉSACTIVER pour laisser passer la sélection rectangle (drag)
        isPage: true,
        pageIndex: fabricCanvas.bleedInfo.leftPageIndex,
        excludeFromExport: true,
        hoverCursor: 'default'
    });
    
    const rightPageRect = new fabric.Rect({
        left: bleedPx + width,
        top: bleedPx,
        width: width,
        height: height,
        fill: 'transparent',
        stroke: 'transparent',
        strokeWidth: 0,
        selectable: false,
        evented: false, // ✅ FIX: DÉSACTIVER pour laisser passer la sélection rectangle (drag)
        isPage: true,
        pageIndex: fabricCanvas.bleedInfo.rightPageIndex,
        excludeFromExport: true,
        hoverCursor: 'default'
    });
    
    // 4. MARGES DE SÉCURITÉ (pointillés rouges comme pages simples)
    const leftMarginRect = new fabric.Rect({
        left: bleedPx + marginPx,
        top: bleedPx + marginPx,
        width: width - (marginPx * 2),
        height: height - (marginPx * 2),
        fill: 'transparent',
        stroke: '#ff0000',
        strokeWidth: 0.5,
        strokeDashArray: [5, 5],
        selectable: false,
        evented: false,
        isMargin: true,
        excludeFromExport: true
    });
    
    const rightMarginRect = new fabric.Rect({
        left: bleedPx + width + marginPx,
        top: bleedPx + marginPx,
        width: width - (marginPx * 2),
        height: height - (marginPx * 2),
        fill: 'transparent',
        stroke: '#ff0000',
        strokeWidth: 0.5,
        strokeDashArray: [5, 5],
        selectable: false,
        evented: false,
        isMargin: true,
        excludeFromExport: true
    });
    
    // 5. LIGNE DE RELIURE (fine au centre)
    // FIX: NE PAS marquer comme isGuide pour éviter le magnétisme automatique
    // L'utilisateur doit pouvoir placer des objets au centre sans être attiré
    const bindingLine = new fabric.Line([centerX, bleedPx, centerX, bleedPx + height], {
        stroke: 'rgba(0,0,0,0.2)',
        strokeWidth: 0.5,
        selectable: false,
        evented: false,
        excludeFromExport: true,
        isBindingLine: true  // Marqueur spécifique (pas de snap)
    });
    
    // Ajouter les éléments: guides en arrière-plan, zones de page au-dessus
    fabricCanvas.insertAt(fullBleedRect, 0, false);
    fabricCanvas.insertAt(leftTrimBox, 1, false);
    fabricCanvas.insertAt(rightTrimBox, 2, false);
    fabricCanvas.insertAt(leftMarginRect, 3, false);
    fabricCanvas.insertAt(rightMarginRect, 4, false);
    fabricCanvas.insertAt(bindingLine, 5, false);
    // Ajouter les zones de page DERRIÈRE tous les autres objets pour ne pas bloquer les interactions
    fabricCanvas.insertAt(leftPageRect, 6, false);
    fabricCanvas.insertAt(rightPageRect, 7, false);
    // NE PAS utiliser bringToFront() car cela bloquerait les interactions avec les objets
    
    // Appliquer les préférences d'affichage
    if (window._spHideMargins) {
        leftMarginRect.visible = false;
        rightMarginRect.visible = false;
    }
    if (window._spHideBleed) {
        fullBleedRect.visible = false;
        // Créer les masques pour cacher la zone de fond perdu (2 pages)
        const contentW = width * 2;
        const trimLeft = bleedPx;
        const trimTop = bleedPx;
        const trimRight = bleedPx + contentW;
        const trimBottom = bleedPx + height;
        const uiMaskColor = '#e8e8e8';
        const maskOverlap = 1;
        const maskProps = {
            selectable: false, evented: false, hoverCursor: 'default',
            hasControls: false, hasBorders: false,
            lockMovementX: true, lockMovementY: true, lockRotation: true,
            lockScalingX: true, lockScalingY: true, lockScaling: true,
            excludeFromExport: true, isBleedMask: true
        };
        const masks = [
            new fabric.Rect({ left: -maskOverlap, top: -maskOverlap, width: guideCanvasW + maskOverlap * 2, height: Math.max(0, trimTop + maskOverlap), fill: uiMaskColor, ...maskProps }),
            new fabric.Rect({ left: -maskOverlap, top: trimBottom, width: guideCanvasW + maskOverlap * 2, height: Math.max(0, guideCanvasH - trimBottom + maskOverlap), fill: uiMaskColor, ...maskProps }),
            new fabric.Rect({ left: -maskOverlap, top: trimTop, width: Math.max(0, trimLeft + maskOverlap), height: Math.max(0, height), fill: uiMaskColor, ...maskProps }),
            new fabric.Rect({ left: trimRight, top: trimTop, width: Math.max(0, guideCanvasW - trimRight + maskOverlap), height: Math.max(0, height), fill: uiMaskColor, ...maskProps })
        ];
        masks.forEach(m => fabricCanvas.add(m));
    }

    // Les zones de page sont non-interactives: la sélection est gérée par selection:created/updated et mouse:down
    
    fabricCanvas.requestRenderAll();
    // ⚡ Mémoriser le format des guides pour éviter les recréations inutiles
    if (fabricCanvas.bleedInfo) {
        fabricCanvas.bleedInfo._guidesW = (width * 2) + (bleedPx * 2);
        fabricCanvas.bleedInfo._guidesH = height + (bleedPx * 2);
        fabricCanvas.bleedInfo._guidesM = margin;
        // 🛡️ FIX 2026-05-08 : mémoriser AUSSI le pairage de pages pour que la
        //   short-circuit d'optimisation puisse détecter un changement de pairage
        //   (ex : drag-drop chemin de fer qui modifie leftPageIndex/rightPageIndex).
        fabricCanvas.bleedInfo._guidesLeftIdx = fabricCanvas.bleedInfo.leftPageIndex;
        fabricCanvas.bleedInfo._guidesRightIdx = fabricCanvas.bleedInfo.rightPageIndex;
    }
    log(`✅ Guides spread complets créés pour ${pageInfo} : fond perdu + traits verts + sélection bleue + marges rouges + reliure`);
        }
        
        function updateSpreadPageSelection(fabricCanvas, selectedSide) {
    // DÉSACTIVÉ : Pas de voile bleu au clic en mode double page
    // Les zones de page restent transparentes, pas besoin de les modifier
    
    // Mettre à jour uniquement l'indicateur de page actif au niveau DOM
    updatePageIndicator();
    
    log(`Spread page sélection : ${selectedSide}`);
        }
        
        // Fonction pour vérifier et restaurer les guides si ils ont disparu
        function ensureSpreadGuidesExist(fabricCanvas, width, height, bleedPx) {
    // 🛡️ FIX 2026-08-26 (perte des guides en production) : garde de sécurité —
    //   cette fonction est appelée depuis un setTimeout(100ms) du handler
    //   object:removed. Si le canvas a été détruit/reconstruit entre-temps
    //   (renderAllPages, undo/redo, duplication), getObjects() lève une erreur
    //   (null 'concat') et la restauration des guides est interrompue → les
    //   traits/marges disparaissent définitivement. On vérifie la validité du
    //   canvas AVANT de toucher à ses objets.
    if (!fabricCanvas || fabricCanvas._spDisposing || fabricCanvas._isLoading || _isRestoringState) return;
    let existingGuides;
    try {
        existingGuides = fabricCanvas.getObjects().filter(obj => 
            obj.isMargin || obj.isBleed || obj.isTrimBox || obj.isPage || obj.isGuide
        );
    } catch (e) {
        console.warn('[ensureSpreadGuidesExist] canvas invalide, restauration ignorée:', e);
        return;
    }
    
    // Si moins de 8 guides (on devrait en avoir plus), les recréer
    if (existingGuides.length < 8) {
        log('Guides manquants détectés, restauration...');
        // Supprimer les guides partiels
        existingGuides.forEach(obj => fabricCanvas.remove(obj));
        // Recréer tous les guides
        try {
            addSpreadGuides(fabricCanvas, width, height, bleedPx);
        } catch (e) {
            console.warn('[ensureSpreadGuidesExist] recréation échouée:', e);
        }
    }
        }

        // Fonction pour convertir un spread en pages simples
        function convertSpreadToSingle() {
    if (viewMode !== 'spread') return;
    
    // SÉCURITÉ: Snapshot des données pages[] AVANT la conversion
    // Si la sauvegarde échoue ou produit des données vides, on restaure le snapshot
    const pagesSnapshot = [];
    pages.forEach((p, i) => {
        pagesSnapshot[i] = p.objects ? p.objects : null;
    });
    
    // Sauvegarder le contenu spread depuis les canvases VIVANTS
    // (saveAllPages() a déjà été appelé par le handler, mais on re-sauvegarde
    //  les spread canvases au cas où — la source de vérité est le canvas)
    canvases.forEach((c) => {
        if (c && c.bleedInfo && c.bleedInfo.isSpread) {
            saveSpreadContent(c, c.bleedInfo.leftPageIndex, c.bleedInfo.rightPageIndex ?? c.bleedInfo.leftPageIndex);
        }
    });
    
    // VALIDATION: Vérifier que les pages n'ont pas été vidées accidentellement
    // Si une page avait des données dans le snapshot mais est maintenant vide,
    // restaurer le snapshot pour cette page
    pages.forEach((p, i) => {
        if (pagesSnapshot[i]) {
            let currentHasObjects = false;
            if (p.objects) {
                try {
                    const parsed = typeof p.objects === 'string' ? JSON.parse(p.objects) : p.objects;
                    currentHasObjects = parsed && parsed.objects && parsed.objects.length > 0;
                } catch(_) {}
            }
            if (!currentHasObjects) {
                let snapshotHasObjects = false;
                try {
                    const parsed = typeof pagesSnapshot[i] === 'string' ? JSON.parse(pagesSnapshot[i]) : pagesSnapshot[i];
                    snapshotHasObjects = parsed && parsed.objects && parsed.objects.length > 0;
                } catch(_) {}
                if (snapshotHasObjects) {
                    console.warn(`[convertSpreadToSingle] Page ${i} vidée — restauration du snapshot`);
                    p.objects = pagesSnapshot[i];
                }
            }
        }
    });
    
    // Changer le mode et re-render
    // (renderAllPages() gère elle-même le deepCleanupCanvas + canvases = [])
    viewMode = 'single';
    document.getElementById('singlePageMode').classList.add('active');
    document.getElementById('spreadMode').classList.remove('active');
    renderAllPages();
        }

        // ========== GESTION DÉBORDEMENT DOUBLE PAGE ==========
        
        // NOUVELLE FONCTION : Nettoyer les objets miroirs orphelins
        function cleanOrphanedMirrors(canvas) {
    if (viewMode !== 'spread') return;
    
    const orphanedMirrors = [];
    canvas.getObjects().forEach(obj => {
        if (obj._isSpreadMirror && obj._sourceObjectId) {
            // Vérifier si l'objet source existe encore
            const sourcePageIndex = obj._sourcePageIndex;
            if (sourcePageIndex !== undefined && canvases[sourcePageIndex]) {
                const sourceCanvas = canvases[sourcePageIndex];
                const sourceExists = sourceCanvas.getObjects().some(sourceObj => 
                    sourceObj._spreadObjectId === obj._sourceObjectId
                );
                
                if (!sourceExists) {
                    orphanedMirrors.push(obj);
                }
            } else {
                orphanedMirrors.push(obj);
            }
        }
    });
    
    // Supprimer les miroirs orphelins silencieusement
    orphanedMirrors.forEach(mirror => {
        canvas.remove(mirror);
    });
        }
        
        // OPTIMISATION: Fonction de debug spread avec logging conditionnel
        function handleSpreadPageOverflow(canvas, pageIndex, obj) {
    // ❌ DÉSACTIVÉ : Les objets texte ne débordent plus automatiquement sur les pages adjacentes
    // L'utilisateur doit créer manuellement des blocs supplémentaires si nécessaire
    return; // Sortie immédiate - fonction désactivée
    
    if (viewMode !== 'spread' || !obj || obj.isMargin || obj.isBleed || obj.isGuide || obj._isSpreadMirror) return;
    
    // FIX: Ne pas traiter pendant un drag actif
    if (isDragging) {
        log(`[SpreadOverflow] Drag en cours, report du traitement`);
        return;
    }
    
    // éviter les appels multiples pendant le déplacement
    if (obj._spreadUpdatePending || obj._mirrorCreationPending) {
        log(`[SpreadOverflow] ? Traitement déjà en cours pour objet ${obj._spreadObjectId || 'sans ID'}`);
        return;
    }
    obj._spreadUpdatePending = true;
    
    // OPTIMISATION : Délai plus court et nettoyage conditionnel seulement
    setTimeout(() => {
        delete obj._spreadUpdatePending;
        
        // Nettoyer SEULEMENT si nécessaire (éviter le scintillement)
        if (obj._hasSpreadMirror) {
            clearSpreadMirrorObjects(obj);
        }
        
        // Calculer les limites de l'objet
        const objBounds = obj.getBoundingRect();
        const canvasWidth = mmToPx(pageFormat.width);
        const bleedWidth = mmToPx(bleed);
        
        log(`[SpreadOverflow] Page ${pageIndex + 1} - Objet bounds:`, objBounds);
        log(`[SpreadOverflow] Canvas width: ${canvasWidth}px, Bleed: ${bleedWidth}px`);
        
        // LOGIQUE CORRIGÉE : Dans SuperPrint, la numérotation est :
        // Page 0 = Page 1 (toujours seule, pas de double page)
        // Page 1 = Page 2 (page droite de la première double page) 
        // Page 2 = Page 3 (page gauche de la deuxième double page)
        // Page 3 = Page 4 (page droite de la deuxième double page)
        // etc.
        
        let adjacentPageIndex = -1;
        let overflowDirection = null; // 'right' ou 'left'
        
        if (pageIndex === 0) {
            // Page 1 seule - peut déborder vers page 2 (index 1) uniquement vers la droite
            const rightEdge = objBounds.left + objBounds.width;
            const pageRightLimit = canvasWidth + bleedWidth;
            
            if (rightEdge > pageRightLimit && canvases.length > 1) {
                adjacentPageIndex = 1;
                overflowDirection = 'right';
            }
        } else {
            // Pages 2+ : logique de double page
            const isRightPage = (pageIndex % 2 === 1); // Pages impaires (1,3,5...) = pages droites 
            
            if (isRightPage) {
                // Page droite - peut déborder vers la page gauche suivante
                const rightEdge = objBounds.left + objBounds.width;
                const pageRightLimit = canvasWidth + bleedWidth;
                
                if (rightEdge > pageRightLimit && pageIndex + 1 < canvases.length) {
                    adjacentPageIndex = pageIndex + 1;
                    overflowDirection = 'right';
                }
            } else {
                // Page gauche - peut déborder vers la page droite précédente  
                const leftEdge = objBounds.left;
                const pageLeftLimit = bleedWidth;
                
                if (leftEdge < pageLeftLimit && pageIndex - 1 >= 0) {
                    adjacentPageIndex = pageIndex - 1;
                    overflowDirection = 'left';
                }
            }
        }
        
        log(`[SpreadOverflow] Adjacent page: ${adjacentPageIndex}, Direction: ${overflowDirection}`);
        
        // Vérifier si la page adjacente existe
        if (adjacentPageIndex < 0 || adjacentPageIndex >= canvases.length || !canvases[adjacentPageIndex]) {
            log(`[SpreadOverflow] Page adjacente non trouvée ou inexistante`);
            return;
        }
        
        const adjacentCanvas = canvases[adjacentPageIndex];
        let overflowAmount = 0;
        
        // Calculer le débordement PRÉCIS selon la direction
        if (overflowDirection === 'right') {
            const rightEdge = objBounds.left + objBounds.width;
            const pageRightLimit = canvasWidth + bleedWidth;
            overflowAmount = Math.max(0, rightEdge - pageRightLimit);
            
            log(`[SpreadOverflow] RIGHT - Objet rightEdge: ${rightEdge}px, Page limit: ${pageRightLimit}px`);
            
        } else if (overflowDirection === 'left') {
            const leftEdge = objBounds.left;
            const pageLeftLimit = bleedWidth;
            overflowAmount = Math.max(0, pageLeftLimit - leftEdge);
            
            log(`[SpreadOverflow] LEFT - Objet leftEdge: ${leftEdge}px, Page limit: ${pageLeftLimit}px`);
        }
        
        log(`[SpreadOverflow] ? Overflow amount calculé: ${overflowAmount}px`);
        
        if (overflowAmount > 5) { // Seuil augmenté pour éviter les créations abusives
            createSpreadMirrorObject(obj, canvas, adjacentCanvas, pageIndex, adjacentPageIndex, overflowAmount, overflowDirection);
        } else if (overflowAmount > 0) {
            log(`[SpreadOverflow] Débordement trop petit (${overflowAmount}px), ignoré`);
        }
    }, 20); // Délai réduit pour une meilleure réactivité
        }
        
        // Copie complète des propriétés visuelles
        function copyAllVisualProperties(source, target) {
    const visualProps = [
        'fill', 'stroke', 'strokeWidth', 'strokeDashArray', 'strokeLineCap', 'strokeLineJoin',
        'strokeMiterLimit', 'shadow', 'opacity', 'angle', 'flipX', 'flipY', 'skewX', 'skewY',
        'rx', 'ry', 'radius', 'fontSize', 'fontFamily', 'fontWeight', 'fontStyle',
        'textAlign', 'lineHeight', 'charSpacing', 'scaleX', 'scaleY', 'filters', 'crossOrigin'
    ];
    
    visualProps.forEach(prop => {
        if (source[prop] !== undefined && source[prop] !== null) {
            target.set(prop, source[prop]);
        }
    });
    
    // Log pour debugging
    log(`Propriétés copiées - Stroke: ${target.stroke}, StrokeWidth: ${target.strokeWidth}, Fill: ${target.fill}`);
        }
        
        function createSpreadMirrorObject(sourceObj, sourceCanvas, targetCanvas, sourcePageIndex, targetPageIndex, overflowAmount, overflowDirection) {
    // Générer un ID unique pour cet objet s'il n'en a pas
    if (!sourceObj._spreadObjectId) {
        sourceObj._spreadObjectId = 'spread_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    }
    
    // VÉRIFICATION RENFORCÉE : Chercher tous les miroirs existants sur TOUTES les pages
    let hasExistingMirror = false;
    canvases.forEach((canvas, pageIdx) => {
        if (!canvas) return;
        const existingMirrors = canvas.getObjects().filter(obj => 
            obj._isSpreadMirror && obj._sourceObjectId === sourceObj._spreadObjectId
        );
        if (existingMirrors.length > 0) {
            hasExistingMirror = true;
            log(`[CreateMirror] Miroir existant trouvé sur page ${pageIdx + 1} pour objet ${sourceObj._spreadObjectId}`);
        }
    });
    
    if (hasExistingMirror) {
        log(`[CreateMirror] ? Abandon création - Miroir déjà existant pour ${sourceObj._spreadObjectId}`);
        return;
    }
    
    // éviter les créations simultanées
    if (sourceObj._mirrorCreationPending) {
        log(`[CreateMirror] ? Création déjà en cours pour ${sourceObj._spreadObjectId}`);
        return;
    }
    sourceObj._mirrorCreationPending = true;
    
    // Marquer l'objet source comme ayant un miroir
    sourceObj._hasSpreadMirror = true;
    sourceObj._mirrorPageIndex = targetPageIndex;
    sourceObj._mirrorDirection = overflowDirection;
    
    log(`[CreateMirror] Création miroir - Source page ${sourcePageIndex + 1} -> Target page ${targetPageIndex + 1}`);
    log(`[CreateMirror] Direction: ${overflowDirection}, Overflow: ${overflowAmount}px`);
    
    // Créer l'objet miroir avec copie complète des propriétés
    sourceObj.clone((mirrorObj) => {
        // Vérifier que le clonage a bien copié les styles essentiels
        if (sourceObj.stroke && !mirrorObj.stroke) {
            console.warn('[CreateMirror] Stroke perdu pendant le clonage, restauration...');
            mirrorObj.set('stroke', sourceObj.stroke);
        }
        if (sourceObj.strokeWidth && !mirrorObj.strokeWidth) {
            console.warn('[CreateMirror] StrokeWidth perdu pendant le clonage, restauration...');
            mirrorObj.set('strokeWidth', sourceObj.strokeWidth);
        }
        
        // Calculer la nouvelle position pour l'objet miroir
        const sourceBounds = sourceObj.getBoundingRect();
        const canvasWidth = mmToPx(pageFormat.width);
        const bleedWidth = mmToPx(bleed);
        
        let newLeft, newTop, newWidth, newHeight;
        
        if (overflowDirection === 'right') {
            // Objet déborde vers la droite - Position précise sans excès
            const pageRightEdge = canvasWidth + bleedWidth;
            const sourceRightEdge = sourceBounds.left + sourceBounds.width;
            const actualOverflow = sourceRightEdge - pageRightEdge;
            
            // Position exacte au bord intérieur
            newLeft = bleedWidth; 
            newWidth = Math.min(actualOverflow, sourceBounds.width);
            newTop = sourceBounds.top;
            newHeight = sourceBounds.height;
            
            log(`[CreateMirror] RIGHT: overflow=${actualOverflow}px, position=${newLeft}px`);
            
        } else if (overflowDirection === 'left') {
            // Objet déborde vers la gauche - Position précise sans excès
            const pageLeftEdge = bleedWidth;
            const sourceLeftEdge = sourceBounds.left;
            const actualOverflow = pageLeftEdge - sourceLeftEdge;
            
            // Position exacte au bord intérieur
            newLeft = canvasWidth + bleedWidth - actualOverflow;
            newWidth = Math.min(actualOverflow, sourceBounds.width);
            newTop = sourceBounds.top;
            newHeight = sourceBounds.height;
            
            log(`[CreateMirror] LEFT: overflow=${actualOverflow}px, position=${newLeft}px`);
        }
        
        log(`[CreateMirror] Nouvelle position miroir: left=${newLeft}, top=${newTop}, width=${newWidth}, height=${newHeight}`);
        
        // Configurer l'objet miroir avec position standard et précise
        mirrorObj.set({
            left: Math.round(newLeft),
            top: Math.round(newTop),
            width: Math.round(newWidth),
            height: Math.round(newHeight),
            selectable: false,      // Empêcher la sélection directe du miroir
            evented: false,         // ✅ FIX: DÉSACTIVER pour ne pas bloquer la sélection rectangle
            opacity: 0.85,          // Légèrement transparent pour montrer que c'est un miroir
            hoverCursor: 'default', // ✅ FIX: Curseur normal
            moveCursor: 'default',
            excludeFromExport: false, // Garder pour l'export PDF (opacité sera restaurée)
            hasControls: false,     // Pas de contrôles de transformation
            hasBorders: false,      // Pas de bordures de sélection
            lockMovementX: true,    // Verrouillage complet du mouvement
            lockMovementY: true,
            lockRotation: true,
            lockScalingX: true,
            lockScalingY: true,
            lockSkewingX: true,
            lockSkewingY: true
        });
        
        // Copier TOUTES les propriétés visuelles de l'objet source
        copyAllVisualProperties(sourceObj, mirrorObj);
        
        // Marquer comme objet miroir avec informations complètes
        mirrorObj._isSpreadMirror = true;
        mirrorObj._sourcePageIndex = sourcePageIndex;
        mirrorObj._sourceObjectId = sourceObj._spreadObjectId;
        mirrorObj._overflowDirection = overflowDirection;
        mirrorObj._overflowAmount = overflowAmount;
        
        // Ajustements spécifiques selon le type d'objet
        if (mirrorObj.type === 'textbox') {
            // Pour le texte, gérer le débordement de manière visuelle
            mirrorObj.set({ 
                // Conserver les propriétés de texte
                fontSize: sourceObj.fontSize,
                fontFamily: sourceObj.fontFamily,
                fontWeight: sourceObj.fontWeight,
                fontStyle: sourceObj.fontStyle,
                textAlign: sourceObj.textAlign,
                lineHeight: sourceObj.lineHeight,
                charSpacing: sourceObj.charSpacing,
                text: sourceObj.text // Même texte
            });
            
            // Appliquer un clipping pour ne montrer que la partie qui déborde
            if (overflowDirection === 'right') {
                // Créer un effet de décalage visuel pour simuler la continuation
                const textOffset = -(sourceBounds.width - overflowAmount);
                mirrorObj.set('textAlign', 'left');
                // Note: L'effet de crop sera géré via CSS clip-path si nécessaire
            }
            
            mirrorObj._clearCache();
            mirrorObj.initDimensions();
            
        } else if (mirrorObj.type === 'image') {
            // Pour les images, créer un crop effect
            const originalScale = sourceObj.scaleX || 1;
            mirrorObj.set({
                scaleX: originalScale,
                scaleY: sourceObj.scaleY || 1,
                filters: sourceObj.filters || [],
                crossOrigin: sourceObj.crossOrigin
            });
            
        } else if (mirrorObj.type === 'rect' || mirrorObj.type === 'circle') {
            mirrorObj.set({ 
                scaleX: 1,
                scaleY: 1,
                // Conserver TOUS les styles de forme
                rx: sourceObj.rx, // Coins arrondis pour rectangles
                ry: sourceObj.ry,
                radius: sourceObj.radius, // Pour les cercles
                // Assurer un rendu net et sans bordure visible
                strokeWidth: sourceObj.strokeWidth || 0,
                stroke: sourceObj.stroke || 'transparent'
            });
            
            // CHEVAUCHEMENT RENFORCé pour les formes géométriques
            if (overflowDirection === 'right') {
                const currentLeft = mirrorObj.left;
                const currentWidth = mirrorObj.width;
                mirrorObj.set({
                    left: currentLeft - 3, // Chevauchement plus important
                    width: currentWidth + 3 // Compenser la largeur
                });
            } else if (overflowDirection === 'left') {
                const currentLeft = mirrorObj.left;
                const currentWidth = mirrorObj.width;
                mirrorObj.set({
                    left: currentLeft + 3, // Chevauchement plus important
                    width: currentWidth + 3 // Compenser la largeur
                });
            }
            
        } else if (mirrorObj.type === 'path') {
            // Pour les formes dessinées à la plume
            mirrorObj.set({
                strokeLineCap: sourceObj.strokeLineCap,
                strokeLineJoin: sourceObj.strokeLineJoin,
                strokeMiterLimit: sourceObj.strokeMiterLimit
            });
        }
        
        // Propriétés communes à TOUS les types d'objets
        mirrorObj.set({
            angle: sourceObj.angle,
            flipX: sourceObj.flipX,
            flipY: sourceObj.flipY,
            skewX: sourceObj.skewX,
            skewY: sourceObj.skewY
        });
        
        // Ajouter à la page adjacente et FORCER à l'arrière-plan
        targetCanvas.add(mirrorObj);
        
        // CRITIQUE : Envoyer l'objet miroir à l'arrière pour ne pas bloquer les interactions
        targetCanvas.sendToBack(mirrorObj);
        
        // Ensuite, envoyer tous les guides encore plus en arrière
        const guides = targetCanvas.getObjects().filter(obj => 
            obj.isMargin || obj.isBleed || obj.isGuide || obj.isTrimBox || obj.isPage
        );
        guides.forEach(guide => targetCanvas.sendToBack(guide));
        
        // GESTIONNAIRE DE CLIC : Rediriger vers l'objet original
        mirrorObj.on('mousedown', (e) => {
            log('[MirrorClick] Clic sur objet miroir, redirection vers original...');
            
            // Trouver l'objet source
            const srcCanvas = canvases[sourcePageIndex];
            if (srcCanvas) {
                const srcObj = srcCanvas.getObjects().find(obj => 
                    obj._spreadObjectId === sourceObj._spreadObjectId
                );
                
                if (srcObj) {
                    // Désélectionner le miroir
                    targetCanvas.discardActiveObject();
                    
                    // Sélectionner l'original
                    srcCanvas.setActiveObject(srcObj);
                    currentPageIndex = sourcePageIndex;
                    
                    updatePageIndicator();
                    debouncedUpdateLayersPanel();
                    updateTransformPanel();
                    
                    setTimeout(() => {
                        srcCanvas.requestRenderAll();
                        targetCanvas.requestRenderAll();
                    }, 5);
                    
                    // Empêcher la propagation de l'événement
                    if (e.e) {
                        e.e.preventDefault();
                        e.e.stopPropagation();
                    }
                }
            }
        });
        
        // OPTIMISATION : Rafraîchissement différé pour éviter le scintillement
        setTimeout(() => {
            targetCanvas.requestRenderAll();
        }, 5);
        
        log(`[CreateMirror] ? Objet miroir créé sur page ${targetPageIndex + 1} (arrière-plan, cliquable):`);
        log(`  - Type: ${mirrorObj.type}`);
        log(`  - Direction: ${overflowDirection}`);
        log(`  - Débordement: ${overflowAmount}px`);
        log(`  - Position: (${mirrorObj.left}, ${mirrorObj.top})`);
        log(`  - Taille: ${mirrorObj.width} x ${mirrorObj.height}`);
        log(`  - Styles: Stroke=${mirrorObj.stroke}, Fill=${mirrorObj.fill}`);
        
        // Notification visuelle temporaire (seulement la première fois)
        if (!sourceObj._notificationShown) {
            showSpreadNotification(`Objet étendu entre pages ${sourcePageIndex + 1}-${targetPageIndex + 1} | Clic ? sélectionne l'original`);
            sourceObj._notificationShown = true;
        }
        
        // Nettoyer le flag de création en cours
        delete sourceObj._mirrorCreationPending;
    });
        }
        
        // ========== GESTION AVANCÉE DES Z-INDEX DOUBLES PAGES ==========
        
        function optimizeSpreadZIndex() {
    if (viewMode !== 'spread') return;
    // ⚡ DEBOUNCE: toutes les invocations dans la même frame JS fusionnent en une seule
    if (window._spreadZIdxTimer) return;
    window._spreadZIdxTimer = setTimeout(() => {
        window._spreadZIdxTimer = null;
        if (viewMode !== 'spread') return;
        // Parcourir toutes les pages par paires (doubles pages)
        for (let i = 0; i < canvases.length; i += 2) {
            const leftCanvas = canvases[i];
            const rightCanvas = canvases[i + 1];
            if (leftCanvas && rightCanvas) {
                optimizePairZIndex(leftCanvas, rightCanvas, i);
            }
        }
    }, 120);
        }
        
        function optimizePairZIndex(leftCanvas, rightCanvas, pageIndex) {
    const leftObjects = leftCanvas.getObjects().filter(obj => 
        !obj.isMargin && !obj.isBleed && !obj.isGuide && !obj.isManualGuide && !obj.isTrimBox
    );
    const rightObjects = rightCanvas.getObjects().filter(obj => 
        !obj.isMargin && !obj.isBleed && !obj.isGuide && !obj.isManualGuide && !obj.isTrimBox
    );
    
    // Créer une liste unifiée avec priorité selon la position
    const allObjects = [];
    
    // Ajouter objets de gauche
    leftObjects.forEach(obj => {
        allObjects.push({
            obj: obj,
            canvas: leftCanvas,
            side: 'left',
            priority: calculateSpreadPriority(obj, 'left')
        });
    });
    
    // Ajouter objets de droite
    rightObjects.forEach(obj => {
        allObjects.push({
            obj: obj,
            canvas: rightCanvas,
            side: 'right',
            priority: calculateSpreadPriority(obj, 'right')
        });
    });
    
    // Trier par priorité (objets qui dépassent au-dessus)
    allObjects.sort((a, b) => b.priority - a.priority);
    
    // Appliquer les z-index optimisés
    allObjects.forEach((item, index) => {
        const newZIndex = index + 100; // Base élevée pour éviter les conflits
        item.canvas.moveTo(item.obj, newZIndex);
    });
    
    // Forcer le rendu
    setTimeout(() => {
        leftCanvas.requestRenderAll();
        rightCanvas.requestRenderAll();
    }, 10);
    
        }
        
        function calculateSpreadPriority(obj, side) {
    let priority = 0;
    
    // Objets qui chevauchent entre pages = priorité maximum
    if (obj._hasSpreadMirror) {
        priority += 1000;
    }
    
    // Objets sélectionnés = priorit• levée
    if (obj === obj.canvas?.getActiveObject()) {
        priority += 500;
    }
    
    // Position verticale (plus haut = plus prioritaire)
    priority += Math.max(0, 1000 - obj.top);
    
    // Taille (plus gros = plus prioritaire dans certains cas)
    if (obj.width * obj.height > 10000) {
        priority += 100;
    }
    
    // Objets de type text = priorité légèrement supérieure
    if (obj.type === 'textbox' || obj.type === 'text') {
        priority += 50;
    }
    
    return priority;
        }
        
        // ========== SYNCHRONISATION OBJETS MIROIRS ==========
        
        function syncMirrorWithSource(sourceObj) {
    if (!sourceObj._hasSpreadMirror || !sourceObj._spreadObjectId) return;
    
    
    // CORRECTION RAFRAICHISSEMENT : Collecter les canvas à rafraîchir pour éviter les rendus multiples
    const canvasesToRender = new Set();
    
    // Trouver tous les miroirs de cet objet sur toutes les pages
    canvases.forEach((canvas, pageIndex) => {
        if (!canvas) return;
        
        canvas.getObjects().forEach(mirrorObj => {
            if (mirrorObj._isSpreadMirror && mirrorObj._sourceObjectId === sourceObj._spreadObjectId) {
                
                // Synchroniser toutes les propriétés visuelles
                copyAllVisualProperties(sourceObj, mirrorObj);
                
                // Synchroniser les propriétés de transformation communes
                mirrorObj.set({
                    angle: sourceObj.angle,
                    flipX: sourceObj.flipX,
                    flipY: sourceObj.flipY,
                    skewX: sourceObj.skewX,
                    skewY: sourceObj.skewY
                });
                
                // Synchronisations spécifiques selon le type
                if (mirrorObj.type === 'textbox') {
                    mirrorObj.set({
                        text: sourceObj.text,
                        fontSize: sourceObj.fontSize,
                        fontFamily: sourceObj.fontFamily,
                        fontWeight: sourceObj.fontWeight,
                        fontStyle: sourceObj.fontStyle,
                        textAlign: sourceObj.textAlign,
                        lineHeight: sourceObj.lineHeight,
                        charSpacing: sourceObj.charSpacing
                    });
                    mirrorObj._clearCache();
                    mirrorObj.initDimensions();
                    
                } else if (mirrorObj.type === 'image') {
                    // Synchroniser les filtres et propriétés d'image
                    mirrorObj.set({
                        filters: sourceObj.filters || [],
                        crossOrigin: sourceObj.crossOrigin
                    });
                    
                } else if (mirrorObj.type === 'rect') {
                    mirrorObj.set({
                        rx: sourceObj.rx,
                        ry: sourceObj.ry
                    });
                    
                } else if (mirrorObj.type === 'circle') {
                    mirrorObj.set({
                        radius: sourceObj.radius
                    });
                    
                } else if (mirrorObj.type === 'path') {
                    mirrorObj.set({
                        strokeLineCap: sourceObj.strokeLineCap,
                        strokeLineJoin: sourceObj.strokeLineJoin,
                        strokeMiterLimit: sourceObj.strokeMiterLimit
                    });
                }
                
                canvasesToRender.add(canvas);
            }
        });
    });
    
    // CORRECTION RAFRAICHISSEMENT : Rendre tous les canvas d'un coup, pas individuellement
    canvasesToRender.forEach(canvas => {
        canvas.requestRenderAll();
    });
        }
        
        function clearSpreadMirrorObjects(sourceObj) {
    if (!sourceObj || !sourceObj._spreadObjectId) return;
    
    // Nettoyer TOUS les objets miroirs de cet objet source sur TOUTES les pages
    canvases.forEach((canvas, index) => {
        if (!canvas) return;
        
        const objectsToRemove = [];
        canvas.getObjects().forEach(obj => {
            if (obj._isSpreadMirror && obj._sourceObjectId === sourceObj._spreadObjectId) {
                objectsToRemove.push(obj);
            }
        });
        
        // Supprimer tous les miroirs trouvés
        objectsToRemove.forEach(mirror => {
            canvas.remove(mirror);
        });
        
        if (objectsToRemove.length > 0) {
            canvas.requestRenderAll();
        }
    });
    
    // Nettoyer TOUS les marqueurs sur l'objet source
    delete sourceObj._hasSpreadMirror;
    delete sourceObj._mirrorPageIndex;
    delete sourceObj._mirrorDirection;
    delete sourceObj._notificationShown;
    delete sourceObj._mirrorCreationPending;
    delete sourceObj._spreadUpdatePending;
        }
        
        // Nettoyer tous les objets miroirs lors du changement de mode
        function clearAllSpreadMirrors() {
    canvases.forEach((canvas, index) => {
        if (!canvas) return;
        
        const objectsToRemove = [];
        canvas.getObjects().forEach(obj => {
            if (obj._isSpreadMirror) {
                objectsToRemove.push(obj);
            }
            // Nettoyer aussi les marqueurs sur les objets sources
            if (obj._hasSpreadMirror || obj._spreadObjectId) {
                delete obj._hasSpreadMirror;
                delete obj._mirrorPageIndex;
                delete obj._mirrorDirection;
                delete obj._notificationShown;
                delete obj._needsSpreadUpdate;
                delete obj._spreadUpdatePending;
                delete obj._mirrorCreationPending;
            }
        });
        
        objectsToRemove.forEach(mirror => canvas.remove(mirror));
        
        if (objectsToRemove.length > 0) {
            canvas.requestRenderAll();
        }
    });
        }
        
        // ========== VÉRIFICATION GLOBALE DES DÉBORDEMENTS ==========
        
        function checkAllObjectsForSpreadOverflow() {
    if (viewMode !== 'spread') return;
    
    
    // D'abord, nettoyer complètement tous les miroirs existants
    clearAllSpreadMirrors();
    
    // Attendre que le nettoyage soit terminé, puis vérifier
    setTimeout(() => {
        let objectCount = 0;
        canvases.forEach((canvas, pageIndex) => {
            if (!canvas) return;
            
            canvas.getObjects().forEach(obj => {
                // Ignorer les marges, repères, fond perdu et objets miroirs
                if (obj.isMargin || obj.isBleed || obj.isGuide || obj._isSpreadMirror) return;
                
                // Ignorer les objets qui ont déjà un miroir ou en cours de traitement
                if (obj._hasSpreadMirror || obj._mirrorCreationPending || obj._spreadUpdatePending) {
                    return;
                }
                
                objectCount++;
                
                // DÉclencher la vérification de débordement avec délai Échelonné
                setTimeout(() => {
                    handleSpreadPageOverflow(canvas, pageIndex, obj);
                }, objectCount * 100); // 100ms d'Écart entre chaque objet
            });
        });
        
    }, 100);
        }
        
        // Notification pour les objets étendus sur double page
        function showSpreadNotification(message) {
    // FIX: Nettoyer les timers précédents pour éviter les conflits
    if (window._spreadNotifShowTimer) { clearTimeout(window._spreadNotifShowTimer); window._spreadNotifShowTimer = null; }
    if (window._spreadNotifDismissTimer) { clearTimeout(window._spreadNotifDismissTimer); window._spreadNotifDismissTimer = null; }
    
    // Créer ou réutiliser l'élément de notification
    let notification = document.getElementById('spreadNotification');
    if (!notification) {
        notification = document.createElement('div');
        notification.id = 'spreadNotification';
        notification.style.cssText = `
            position: fixed;
            bottom: 20px;
            right: 340px;
            transform: translateX(calc(100% + 340px));
            background: #1a1a1a;
            color: white;
            padding: 8px 12px;
            border-radius: 0;
            font-size: 10px;
            font-weight: 500;
            box-shadow: none;
            z-index: 50;
            transition: all 0.3s ease;
            opacity: 0;
            font-family: 'IBM Plex Mono', monospace;
            white-space: nowrap;
        `;
        document.body.appendChild(notification);
    }
    
    notification.textContent = message;
    
    // FIX: Réinitialiser la position de départ AVANT l'animation
    notification.style.transition = 'none'; // Désactiver temporairement la transition
    notification.style.transform = 'translateX(calc(100% + 340px))';
    notification.style.opacity = '0';
    
    // Forcer le reflow pour appliquer le reset
    notification.offsetHeight;
    
    // Réactiver la transition
    notification.style.transition = 'all 0.3s ease';
    
    // Animation d'apparition depuis la droite
    window._spreadNotifShowTimer = setTimeout(() => {
        notification.style.transform = 'translateX(0)';
        notification.style.opacity = '1';
    }, 10);
    
    // Disparition automatique après 3 secondes - sortie vers le bas
    window._spreadNotifDismissTimer = setTimeout(() => {
        notification.style.transform = 'translateY(150px)';
        notification.style.opacity = '0';
        // FIX: Retirer l'élément du DOM après la transition
        setTimeout(() => {
            if (notification && notification.parentNode) {
                notification.parentNode.removeChild(notification);
            }
        }, 400);
    }, 3000);
        }

        function getActiveCanvas() {
    // FIX MODE SPREAD : Trouver le bon canvas selon currentPageIndex
    if (viewMode === 'spread') {
        // En mode spread, un canvas peut contenir 2 pages
        // Il faut trouver le canvas qui contient currentPageIndex
        for (let i = 0; i < canvases.length; i++) {
            const canvas = canvases[i];
            if (!canvas || !canvas.bleedInfo) continue;
            
            if (canvas.bleedInfo.isSpread) {
                // Canvas spread : vérifier si currentPageIndex est dedans
                if (currentPageIndex === canvas.bleedInfo.leftPageIndex || 
                    currentPageIndex === canvas.bleedInfo.rightPageIndex) {
                    return canvas;
                }
            } else {
                // Canvas simple : vérifier l'index de page
                if (currentPageIndex === canvas.bleedInfo.pageIndex) {
                    return canvas;
                }
            }
        }
        
        // Fallback : retourner le premier canvas si rien trouvé
        console.warn(`[getActiveCanvas] Aucun canvas trouvé pour page ${currentPageIndex + 1}, utilisation du premier canvas`);
        return canvases[0];
    } else {
        // Mode single : simple mapping index?canvas
        return canvases[currentPageIndex];
    }
        }

        function createNewPage() {
    pages.push({
        objects: null,
        background: '#ffffff'
    });
        }

        function drawMargins(canvas, pageWidth, pageHeight) {
    if (!canvas) return;
    
    // Supprimer TOUTES les anciennes marges et fonds perdus de manière plus agressive
    const objectsToRemove = [];
    canvas.getObjects().forEach(obj => {
        if (obj.isMargin || obj.isBleed || obj.isTrimBox || obj.isBleedMask) {
            objectsToRemove.push(obj);
        }
    });
    objectsToRemove.forEach(obj => canvas.remove(obj));
    
    // Forcer le rendu avant d'ajouter de nouveaux éléments
    canvas.requestRenderAll();

    // Récupérer les infos de fond perdu pour ce canvas
    const bleedInfo = canvas.bleedInfo || { left: mmToPx(bleed), right: mmToPx(bleed), top: mmToPx(bleed), bottom: mmToPx(bleed), position: 'single' };
    
    // Trait = format FINAL de coupe - CORRECTION DOUBLE PAGE
    let trimBox;
    if (bleedInfo.position === 'left') {
        // Page gauche : pas de trait à droite (côté reliure)
        trimBox = new fabric.Group([
            new fabric.Line([bleedInfo.left, bleedInfo.top, bleedInfo.left + pageWidth, bleedInfo.top], { stroke: '#2a2a2a', strokeWidth: 2 }), // haut
            new fabric.Line([bleedInfo.left, bleedInfo.top, bleedInfo.left, bleedInfo.top + pageHeight], { stroke: '#2a2a2a', strokeWidth: 2 }), // gauche
            new fabric.Line([bleedInfo.left, bleedInfo.top + pageHeight, bleedInfo.left + pageWidth, bleedInfo.top + pageHeight], { stroke: '#2a2a2a', strokeWidth: 2 }) // bas
        ], {
            selectable: false,
            evented: false,
            hoverCursor: 'default',
            hasControls: false,
            hasBorders: false,
            lockMovementX: true,
            lockMovementY: true,
            lockRotation: true,
            lockScalingX: true,
            lockScalingY: true,
            lockScaling: true,
            excludeFromExport: true,
            isTrimBox: true,
            zIndex: 1
        });
    } else if (bleedInfo.position === 'right') {
        // Page droite : pas de trait à gauche (côté reliure)
        trimBox = new fabric.Group([
            new fabric.Line([bleedInfo.left, bleedInfo.top, bleedInfo.left + pageWidth, bleedInfo.top], { stroke: '#2a2a2a', strokeWidth: 2 }), // haut
            new fabric.Line([bleedInfo.left + pageWidth, bleedInfo.top, bleedInfo.left + pageWidth, bleedInfo.top + pageHeight], { stroke: '#2a2a2a', strokeWidth: 2 }), // droite
            new fabric.Line([bleedInfo.left, bleedInfo.top + pageHeight, bleedInfo.left + pageWidth, bleedInfo.top + pageHeight], { stroke: '#2a2a2a', strokeWidth: 2 }) // bas
        ], {
            selectable: false,
            evented: false,
            hoverCursor: 'default',
            hasControls: false,
            hasBorders: false,
            lockMovementX: true,
            lockMovementY: true,
            lockRotation: true,
            lockScalingX: true,
            lockScalingY: true,
            lockScaling: true,
            excludeFromExport: true,
            isTrimBox: true,
            zIndex: 1
        });
    } else {
        // Page simple : trait complet sur les 4 côtés
        trimBox = new fabric.Rect({
            left: bleedInfo.left,
            top: bleedInfo.top,
            width: pageWidth,
            height: pageHeight,
            fill: 'transparent',
            stroke: '#2a2a2a',
            strokeWidth: 2,
            selectable: false,
            evented: false,
            hoverCursor: 'default',
            hasControls: false,
            hasBorders: false,
            lockMovementX: true,
            lockMovementY: true,
            lockRotation: true,
            lockScalingX: true,
            lockScalingY: true,
            lockScaling: true,
            excludeFromExport: true,
            isTrimBox: true,
            zIndex: 1
        });
    }

    // 🎨 PASTEBOARD: utiliser les dimensions de page (sans pasteboard) pour les guides
    const guideCanvasW = bleedInfo.pageCanvasWidth || canvas.width;
    const guideCanvasH = bleedInfo.pageCanvasHeight || canvas.height;

    // Zone de fond perdu (du bord du canvas jusqu'au trait vert)
    const bleedIndicator = new fabric.Rect({
        left: 0,
        top: 0,
        width: guideCanvasW,
        height: guideCanvasH,
        fill: 'transparent', // Fond transparent: la page reste blanc pur
        stroke: '#cccccc',
        strokeWidth: 1,
        strokeDashArray: [5, 5],
        selectable: false,
        evented: false,
        hoverCursor: 'default',
        hasControls: false,
        hasBorders: false,
        lockMovementX: true,
        lockMovementY: true,
        lockRotation: true,
        lockScalingX: true,
        lockScalingY: true,
        lockScaling: true,
        excludeFromExport: true,
        isBleed: true
    });

    // Marges de sécurité en rouge (é l'intérieur du format final)
    const marginPx = mmToPx(margin);
    const marginRect = new fabric.Rect({
        left: bleedInfo.left + marginPx,
        top: bleedInfo.top + marginPx,
        width: pageWidth - (marginPx * 2),
        height: pageHeight - (marginPx * 2),
        fill: 'transparent',
        stroke: '#ff0000',
        strokeWidth: 0.5,
        strokeDashArray: [5, 5],
        selectable: false,
        evented: false,
        hoverCursor: 'default',
        hasControls: false,
        hasBorders: false,
        lockMovementX: true,
        lockMovementY: true,
        lockRotation: true,
        lockScalingX: true,
        lockScalingY: true,
        lockScaling: true,
        excludeFromExport: true,
        isMargin: true
    });
    
    // Appliquer les préférences d'affichage
    if (window._spHideMargins) {
        marginRect.visible = false;
    }
    if (window._spHideBleed) {
        bleedIndicator.visible = false;
    }

    // Masquer visuellement la zone de fond perdu (entre trim et bleed)
    if (window._spHideBleed) {
        // En mode spread, le canvas contient 2 pages côte à côte
        const isSpreadCanvas = bleedInfo.isSpread === true;
        const contentWidth = isSpreadCanvas ? pageWidth * 2 : pageWidth;
        const trimLeft = bleedInfo.left;
        const trimTop = bleedInfo.top;
        const trimRight = bleedInfo.left + contentWidth;
        const trimBottom = bleedInfo.top + pageHeight;

        const uiMaskColor = '#e8e8e8';
        const maskOverlap = 1; // Petit débordement pour éviter les pixels blancs
        const masks = [
            // Haut
            new fabric.Rect({ left: -maskOverlap, top: -maskOverlap, width: guideCanvasW + maskOverlap * 2, height: Math.max(0, trimTop + maskOverlap), fill: uiMaskColor }),
            // Bas
            new fabric.Rect({ left: -maskOverlap, top: trimBottom, width: guideCanvasW + maskOverlap * 2, height: Math.max(0, guideCanvasH - trimBottom + maskOverlap), fill: uiMaskColor }),
            // Gauche
            new fabric.Rect({ left: -maskOverlap, top: trimTop, width: Math.max(0, trimLeft + maskOverlap), height: Math.max(0, pageHeight), fill: uiMaskColor }),
            // Droite
            new fabric.Rect({ left: trimRight, top: trimTop, width: Math.max(0, guideCanvasW - trimRight + maskOverlap), height: Math.max(0, pageHeight), fill: uiMaskColor })
        ];

        masks.forEach(mask => {
            mask.set({
                selectable: false,
                evented: false,
                hoverCursor: 'default',
                hasControls: false,
                hasBorders: false,
                lockMovementX: true,
                lockMovementY: true,
                lockRotation: true,
                lockScalingX: true,
                lockScalingY: true,
                lockScaling: true,
                excludeFromExport: true,
                isBleedMask: true
            });
            canvas.add(mask);
        });
    }

    // Ajouter les éléments de maquette EN HAUT du stack pour qu'ils restent
    // visibles au-dessus des images / textes (repères, fonds perdus, marges,
    // contour de page → toujours en surimpression).
    canvas.add(trimBox);
    canvas.add(bleedIndicator);
    canvas.add(marginRect);
    try {
        canvas.bringToFront(bleedIndicator);
        canvas.bringToFront(marginRect);
        canvas.bringToFront(trimBox);
    } catch(_) {}

    canvas.requestRenderAll();
        }

        // OPTIMISATION: Utilisation de structuredClone pour de meilleures performances
        function saveState(action) {
    // GUARD: Ne pas sauvegarder pendant une restauration (undo/redo)
    if (_isRestoringState) return;
    // GUARD: Ne pas sauvegarder pendant la reconstruction des canvases
    if (_isRenderingAllPages) return;
    // GUARD: Ne pas sauvegarder si un canvas est encore en chargement JSON (positions partielles = état corrompu)
    if (canvases && canvases.some(c => c && c._isLoading)) return;
    
    saveAllPages();
    // ⚡ Tracker le timestamp pour éviter la re-sérialisation dans autoSave
    window._spLastSaveAllPagesTime = Date.now();
    
    if (historyStep < history.length - 1) {
        history = history.slice(0, historyStep + 1);
    }
    
    const cloneMethod = _spClone;
    
    const state = {
        pages: _clonePagesShared(pages),
        textLinks: cloneMethod(textLinks),
        masterPages: cloneMethod(masterPages),
        pageMasterAssignments: cloneMethod(pageMasterAssignments),
        pageNumberingSettings: cloneMethod(pageNumberingSettings),
        action: action,
        timestamp: new Date().toLocaleTimeString('fr-FR'),
        _viewMode: viewMode,
        _pageCount: pages.length,
        // 🆕 v1.7.174 — Sauvegarder la page active pour que undo/redo y revienne
        _currentPageIndex: currentPageIndex
    };
    
    history.push(state);
    historyStep++;
    
    // ⚡ OPTIMISATION: Limiter à 50 états (etait 15 — trop court pour une session de travail)
    if (history.length > 50) {
        const removed = history.shift();
        if (removed) { removed.pages = null; removed.textLinks = null; removed.masterPages = null; }
        historyStep--;
    }
    
    updateHistoryPanel();
    
    // 💾 Marquer dirty + déclencher la sauvegarde automatique (debounced 30s après le dernier saveState)
    // ⚡ FIX FREEZE: requestIdleCallback évite de bloquer le main thread Chrome pendant la sérialisation
    window._spDirtyFlag = true;
    if (typeof window._spAutoSave === 'function') {
        if (window._spAutoSaveDebounce) clearTimeout(window._spAutoSaveDebounce);
        window._spAutoSaveDebounce = setTimeout(() => {
            if (typeof requestIdleCallback === 'function') {
                requestIdleCallback(() => { window._spAutoSave(); }, { timeout: 10000 });
            } else {
                setTimeout(() => { window._spAutoSave(); }, 200);
            }
        }, 30000); // 30s: réduit la pression CPU/disque (le setInterval 5min couvre les cas inactifs)
    }
        }

        // FIX: Variante de saveState qui capture l'état directement depuis pages[]
        // sans appeler saveAllPages() — à utiliser après renderAllPages() car les
        // canvases sont reconstruits de manière asynchrone (setTimeout).
        function saveStateFromPages(action) {
    if (_isRestoringState) return;
    
    if (historyStep < history.length - 1) {
        history = history.slice(0, historyStep + 1);
    }
    
    const cloneMethod = _spClone;
    
    const state = {
        pages: _clonePagesShared(pages),
        textLinks: cloneMethod(textLinks),
        masterPages: cloneMethod(masterPages),
        pageMasterAssignments: cloneMethod(pageMasterAssignments),
        pageNumberingSettings: cloneMethod(pageNumberingSettings),
        action: action,
        timestamp: new Date().toLocaleTimeString('fr-FR'),
        _viewMode: viewMode,
        _pageCount: pages.length,
        _currentPageIndex: currentPageIndex
    };
    
    history.push(state);
    historyStep++;
    
    if (history.length > 50) {
        const removed = history.shift();
        if (removed) { removed.pages = null; removed.textLinks = null; removed.masterPages = null; }
        historyStep--;
    }
    
    updateHistoryPanel();
        }

        function undo() {
    // 💡 FIX UNDO 2026-05-01 (Bug A) : committer toute action en debounce avant
    //   de remonter dans l'historique. Sans ca le Ctrl+Z arrivant pendant les
    //   300ms qui suivent une modif sautait par-dessus cette modif.
    flushPendingSaveState();
    if (historyStep <= 0) return;
    historyStep--;
    restoreState(history[historyStep]);
        }

        function redo() {
    flushPendingSaveState();
    if (historyStep >= history.length - 1) return;
    historyStep++;
    restoreState(history[historyStep]);
        }

        // ⚡ OPTIMISATION: restoreState rapide — recharge le JSON dans les canvases existants
        // au lieu de tout reconstruire (renderAllPages détruit/recrée le DOM = lent + flash)
        let _restoreStateTimerId = null;
        let _restoreDebounceTimer = null;
        let _restoreStateSafetyTimer = null; // Safety: libère _isRestoringState si un restore se bloque indéfiniment
        // 💡 FIX UNDO 2026-05-01 (Bug C) : compteur de generation pour ignorer les
        //   callbacks d'un restore precedent quand un nouveau restore est lance.
        //   Sans ca, un Ctrl+Z arrivant pendant le fast-restore precedent voyait
        //   les loadFromJSON tardifs liberer _isRestoringState a tort.
        let _restoreGeneration = 0;
        
        function restoreState(state) {
    // ⚡ Guard immédiat pour empêcher saveState pendant le debounce
    _isRestoringState = true;
    // Marque immediatement la nouvelle generation : tout callback d'un restore
    // anterieur deviendra orphelin et sera ignore.
    _restoreGeneration++;
    // FIX UNDO CRITIQUE: Annuler tout save débounce en attente pour éviter qu'un
    // saveState planifié n'écrase immédiatement l'état qu'on vient de restaurer
    if (_saveStateTimer) {
        clearTimeout(_saveStateTimer);
        _saveStateTimer = null;
        _lastSaveAction = '';
    }
    // ⚡ DEBOUNCE: Si Ctrl+Z/Y rapide, annuler la restauration précédente
    if (_restoreDebounceTimer) clearTimeout(_restoreDebounceTimer);
    if (_restoreStateTimerId) clearTimeout(_restoreStateTimerId);
    
    // Stocker l'état cible et attendre un court instant avant de restaurer.
    // 30ms : suffit pour absorber les Ctrl+Z rafales sans latence visible.
    _restoreDebounceTimer = setTimeout(() => {
        _restoreDebounceTimer = null;
        _doRestoreState(state);
    }, 30);

    // Safety: reset _isRestoringState si le restore ne se termine jamais (canvas bloqué, JSON corrompu…)
    if (_restoreStateSafetyTimer) clearTimeout(_restoreStateSafetyTimer);
    _restoreStateSafetyTimer = setTimeout(() => {
        _restoreStateSafetyTimer = null;
        if (_isRestoringState) {
            console.warn('[SP] _isRestoringState safety reset — restore bloqué > 10s');
            _isRestoringState = false;
            updateHistoryPanel();
        }
    }, 10000);
        }
        
        function _doRestoreState(state) {
    _isRestoringState = true;
    // FIX UNDO CRITIQUE: Annuler tout save débounce résiduel (en cas de timer planifié
    // entre le déclenchement de restoreState et l'appel réel de _doRestoreState)
    if (_saveStateTimer) {
        clearTimeout(_saveStateTimer);
        _saveStateTimer = null;
        _lastSaveAction = '';
    }
    
    const cloneMethod = _spClone;
    
    // ⚡ PERF UNDO/REDO (2026-06-05) : partage structurel — chaque page devient un
    //   objet neuf (mutations live sûres), mais la chaîne 'objects' (base64 lourd)
    //   est partagée par référence avec le snapshot (immuable, jamais mutée en place,
    //   toujours réassignée). Évite de re-parser/re-stringifier des Mo d'images.
    const newPages = _clonePagesShared(state.pages);
    const newTextLinks = cloneMethod(state.textLinks || {});
    
    // ⚡ FAST PATH: Si même nombre de pages, recharger dans les canvases existants
    // ✨ FIX UNDO SPREAD: Activé aussi en mode spread (utilise loadSpreadContent pour recharger)
    const prevPageCount = pages.length; // avant remplacement
    const canFastRestore = (
        canvases.length > 0 &&
        newPages.length === prevPageCount
    );
    
    pages = newPages;
    textLinks = newTextLinks;
    if (state.masterPages) masterPages = cloneMethod(state.masterPages);
    if (state.pageMasterAssignments) pageMasterAssignments = cloneMethod(state.pageMasterAssignments);
    if (state.pageNumberingSettings) pageNumberingSettings = cloneMethod(state.pageNumberingSettings);
    // 🆕 v1.7.174 — Restaurer la page active sauvegardée dans l'historique
    if (typeof state._currentPageIndex === 'number' && state._currentPageIndex >= 0 && state._currentPageIndex < pages.length) {
        currentPageIndex = state._currentPageIndex;
    }
    
    if (canFastRestore) {
        _fastRestoreCanvases();
    } else {
        // SLOW PATH: reconstruction complète (changement de nombre de pages)
        const pagesContainer = document.getElementById('pagesContainer');
        if (pagesContainer) pagesContainer.style.visibility = 'hidden';
        
        // ✨ Afficher le loader si beaucoup de pages (opération lente)
        if (pages.length > 4) showPageLoader('Restauration en cours…');
        
        try {
            renderAllPages();
        } catch (e) {
            console.error('Erreur restoreState renderAllPages:', e);
            _isRenderingAllPages = false;
        }
        
        const restoreDelay = (viewMode === 'spread' && pages.length > 2)
            ? 200 + pages.length * 60 + 700
            : 800;
        // 💡 FIX UNDO 2026-05-01 (Bug C, slow path) : capture la generation
        //   pour ne pas liberer _isRestoringState si un nouveau Ctrl+Z est passe
        //   par la entre-temps.
        const slowGen = _restoreGeneration;
        _restoreStateTimerId = setTimeout(() => {
            _restoreStateTimerId = null;
            if (slowGen !== _restoreGeneration) return;
            _isRestoringState = false;
            if (_restoreStateSafetyTimer) { clearTimeout(_restoreStateSafetyTimer); _restoreStateSafetyTimer = null; }
            hidePageLoader();
        }, restoreDelay);
        
        let _antiFlashPollCount = 0;
        const _antiFlashPoll = setInterval(() => {
            _antiFlashPollCount++;
            if (!_isRenderingAllPages || _antiFlashPollCount > 60) {
                clearInterval(_antiFlashPoll);
                if (pagesContainer) pagesContainer.style.visibility = '';
            }
        }, 50);
        // ✅ FIX BLANC: Sécurité absolue — si le poll n’a pas restauré la visibilité après 1.5s,
        // on force quoi qu’il arrive (flag bloqué, exception, etc.)
        setTimeout(() => {
            clearInterval(_antiFlashPoll);
            if (pagesContainer) pagesContainer.style.visibility = '';
        }, 1500);
    }
    
    updateHistoryPanel();
        }
        
        // ⚡ FAST RESTORE: Recharge le contenu JSON dans les canvases existants sans reconstruction DOM
        function _fastRestoreCanvases() {
    // 🛡 FIX UNDO 2026-05-01 (Bug C) : capturer la generation au moment ou le
    //   restore commence. Tous les callbacks tardifs (loadFromJSON async)
    //   compareront avec ce numero ; s'il a change, c'est qu'un nouveau Ctrl+Z
    //   a ete declenche entre-temps et il ne faut surtout pas liberer le flag
    //   _isRestoringState ni declencher updatePageIndicator/rebuildGridAll.
    const myGen = _restoreGeneration;
    const isStale = () => myGen !== _restoreGeneration;
    
    // 📐 GABARITS: Ré-injecter les objets master dans les pages avant le rechargement
    Object.keys(pageMasterAssignments).forEach(k => {
        const pageIdx = parseInt(k);
        const masterId = pageMasterAssignments[k];
        if (masterId && masterPages[masterId] && pages[pageIdx]) {
            applyMasterToPage(pageIdx, masterId);
        }
    });

    let pendingLoads = 0;
    const totalCanvases = canvases.length;
    const width = mmToPx(pageFormat.width);
    const height = mmToPx(pageFormat.height);
    const bleedPx = mmToPx(bleed);

    // 🛡️ FIX: Si aucun canvas à charger, libérer immédiatement le verrou
    if (canvases.length === 0) {
        if (!isStale()) {
            _isRestoringState = false;
            if (_restoreStateSafetyTimer) { clearTimeout(_restoreStateSafetyTimer); _restoreStateSafetyTimer = null; }
            updatePageIndicator();
        }
        return;
    }
    
    function onCanvasLoaded() {
        pendingLoads--;
        if (pendingLoads <= 0) {
            if (isStale()) return; // un restore plus recent est en cours, ne pas liberer
            // Tous les canvases sont rechargés
            _isRestoringState = false;
            if (_restoreStateSafetyTimer) { clearTimeout(_restoreStateSafetyTimer); _restoreStateSafetyTimer = null; }
            // Mettre à jour l'indicateur de page et les visuels
            updatePageIndicator();
            if (window._spGridVisible && typeof window.rebuildGridAll === 'function') {
                window.rebuildGridAll();
            }
        }
    }
    
    // ✨ Helper post-chargement commun (évite la duplication)
    function _postLoadCanvas(fabricCanvas, isSpread) {
        // 🔧 FIX: Helper récursif pour traiter les objets dans les groupes
        function _processObject(obj) {
            if (obj.type === 'textbox' || obj.type === 'text' || obj.type === 'i-text') {
                restoreTextboxAfterLoad(obj);
            }
            // 📐 GABARITS: Rendre les items master non-sélectionnables
            if (obj._isMasterItem) {
                obj.set({ selectable: false, evented: false });
                obj.hoverCursor = 'default';
            }
            // 🔧 FIX UNDO/REDO GROUPS: Recurser dans les sous-objets des groupes
            if ((obj.type === 'group' || obj.type === 'Group') && obj._objects) {
                obj._objects.forEach(child => _processObject(child));
            }
        }
        
        // Restaurer les textbox (dimensions fixes, clipPath, monkey-patch) + récurser dans groupes
        fabricCanvas.getObjects().forEach(obj => _processObject(obj));
        
        // Restaurer les patterns d'images dans les formes
        restoreImageMasksAfterLoad(fabricCanvas);
        
        // Réattacher les contrôles crop/replace aux images (y compris dans les groupes)
        function _attachImageControls(obj) {
            if (obj.type === 'image') {
                try { obj._hasCropControl = false; attachCropControlToImage(obj); } catch (_) {}
                try { obj._hasReplaceControl = false; attachReplaceControlToImage(obj); } catch (_) {}
            }
            if ((obj.type === 'group' || obj.type === 'Group') && obj._objects) {
                obj._objects.forEach(child => _attachImageControls(child));
            }
        }
        fabricCanvas.getObjects().forEach(obj => _attachImageControls(obj));
        
        // Réattacher les événements double-clic aux tracés plume
        reattachPenPathEvents(fabricCanvas);
        
        // Redessiner les guides
        if (isSpread) {
            try { addSpreadGuides(fabricCanvas, width, height, bleedPx, true); } catch(_) {}
        } else {
            drawMargins(fabricCanvas, width, height);
        }
        
        // Vérifier les indicateurs de débordement
        setTimeout(() => { checkTextOverflow(fabricCanvas); }, 50);
        
        // Restaurer les visuels de chaînage
        setTimeout(() => { restoreChainVisualsForCanvas(fabricCanvas); }, 100);
        
        // Nettoyer les indicateurs orphelins
        if (typeof cleanOrphanedOverflowIndicators === 'function') {
            cleanOrphanedOverflowIndicators(fabricCanvas);
        }
        
        fabricCanvas.requestRenderAll();
        onCanvasLoaded();
    }
    
    canvases.forEach((fabricCanvas, canvasIdx) => {
        if (!fabricCanvas) return;
        
        const info = fabricCanvas.bleedInfo || {};
        
        pendingLoads++;
        
        // ✨ FIX UNDO SPREAD: Gérer les canvases spread (2 pages par canvas)
        if (info.isSpread) {
            const leftIdx = info.leftPageIndex;
            const rightIdx = info.rightPageIndex;
            
            // Vérifier que les pages existent
            if (!pages[leftIdx]) { onCanvasLoaded(); return; }
            
            // Retirer tous les objets existants
            fabricCanvas.clear();
            fabricCanvas.setBackgroundColor('#ffffff', () => {});
            
            // loadSpreadContent fait son propre loadFromJSON + restaurations internes
            // On n'a besoin que de redessiner les guides et notifier onCanvasLoaded
            try {
                // ⚡ PERF: utiliser le callback onLoaded au lieu d'un setInterval de polling
                loadSpreadContent(fabricCanvas, leftIdx, rightIdx, () => {
                    // Redessiner les guides spread (supprimés par clear())
                    try { addSpreadGuides(fabricCanvas, width, height, bleedPx, true); } catch(_) {}
                    fabricCanvas.requestRenderAll();
                    onCanvasLoaded();
                });
            } catch (e) {
                console.warn('Fast restore spread error:', e);
                fabricCanvas._isLoading = false;
                try { addSpreadGuides(fabricCanvas, width, height, bleedPx, true); } catch(_) {}
                fabricCanvas.requestRenderAll();
                onCanvasLoaded();
            }
        } else {
            // Canvas single-page (mode normal)
            const pageIndex = info.pageIndex !== undefined ? info.pageIndex : canvasIdx;
            
            if (!pages[pageIndex]) { onCanvasLoaded(); return; }
            
            // Retirer tous les objets existants (contenu + guides)
            fabricCanvas.clear();
            fabricCanvas.setBackgroundColor('#ffffff', () => {});
            
            if (pages[pageIndex].objects) {
                // FIX BLEED OFFSET: Ajuster les coordonnées si mode spread + position right
                // Les données sont en référentiel "single" (bleedLeft=bleedPx)
                // En spread position='right', bleedLeft=0 → décaler de -bleedPx
                let loadData = pages[pageIndex].objects;
                if (viewMode === 'spread' && info.position === 'right') {
                    try {
                        const parsed = typeof loadData === 'string' ? JSON.parse(loadData) : loadData;
                        if (parsed && parsed.objects) {
                            parsed.objects.forEach(objData => {
                                objData.left = (objData.left || 0) - bleedPx;
                            });
                            loadData = parsed;
                        }
                    } catch(_) {}
                }
                
                fabricCanvas._isLoading = true;
                fabricCanvas.renderOnAddRemove = false; // ⚡ PERF: éviter N renders pendant loadFromJSON
                const _loadJsonTimer = setTimeout(() => {
                    // ✅ FIX BLANC: si loadFromJSON ne rappelle jamais son callback (JSON corrompu,
                    // bug Fabric.js Textbox silencieux), on force le déblocage après 6s
                    if (fabricCanvas._isLoading) {
                        console.warn('[SP] loadFromJSON timeout (fast restore) — forcé p.', pageIndex);
                        fabricCanvas.renderOnAddRemove = true;
                        fabricCanvas._isLoading = false;
                        try { drawMargins(fabricCanvas, width, height); } catch(_) {}
                        try { fabricCanvas.requestRenderAll(); } catch(_) {}
                        onCanvasLoaded();
                    }
                }, 6000);
                fabricCanvas.loadFromJSON(loadData, () => {
                    clearTimeout(_loadJsonTimer);
                    fabricCanvas.renderOnAddRemove = true;
                    fabricCanvas._isLoading = false;
                    _postLoadCanvas(fabricCanvas, false);
                });
            } else {
                // Page vide — juste redessiner les guides
                drawMargins(fabricCanvas, width, height);
                fabricCanvas.requestRenderAll();
                onCanvasLoaded();
            }
        }
    });
    
    // Sécurité: si aucun canvas n'était à charger
    if (pendingLoads <= 0) {
        _isRestoringState = false;
        if (_restoreStateSafetyTimer) { clearTimeout(_restoreStateSafetyTimer); _restoreStateSafetyTimer = null; }
    }
        }

        function updateHistoryPanel() {
    const panel = document.getElementById('historyPanel');
    if (!panel) return;
    panel.innerHTML = '';

    history.forEach((state, index) => {
        const item = document.createElement('div');
        const isPersistent = state._persistent === true;
        const isRedo = index > historyStep;  // 🔄 État accessible via Ctrl+Y (redo)
        const isUndo = index < historyStep;  // ↩ État accessible via Ctrl+Z (undo)
        item.className = 'history-item' + (index === historyStep ? ' current' : '') + (isPersistent ? ' persistent-save' : '');
        
        // Icône et style différents selon la position dans le stack
        const actionText = state.action || '';
        const displayAction = isRedo && isPersistent ? '⏩ ' + actionText : actionText;
        
        item.innerHTML = `
            <span class="history-item-action">${displayAction}</span>
            <span class="history-item-time">${state.timestamp}</span>
        `;
        
        // Style visuel pour les sauvegardes persistantes (survécu au reload)
        if (isPersistent) {
            // Bleu pour les undo persistants, orange pour les redo persistants
            const borderColor = isRedo ? '#ff9800' : '#00aaff';
            item.style.borderLeft = '3px solid ' + borderColor;
            item.style.paddingLeft = '8px';
        }
        // Redo states en opacité réduite pour indiquer qu'ils sont "en avant"
        if (isRedo) {
            item.style.opacity = '0.6';
        }
        
        item.onclick = () => {
            historyStep = index;
            restoreState(state);
        };
        panel.appendChild(item);
    });

    const currentItem = panel.querySelector('.current');
    if (currentItem) {
        currentItem.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
    // Mettre à jour l'état disabled des boutons ↩ ↪ de la toolbar
    const undoBtn = document.getElementById('undo');
    const redoBtn = document.getElementById('redo');
    if (undoBtn) undoBtn.disabled = (historyStep <= 0);
    if (redoBtn) redoBtn.disabled = (historyStep >= history.length - 1);
        }

        function updateTransformPanel() {
    const activeCanvas = getActiveCanvas();
    if (!activeCanvas) return;
    
    const obj = activeCanvas.getActiveObject();
    if (!obj) {
        document.getElementById('typographySection').style.display = 'none';
        return;
    }

    const factor = getPxToUnitFn();
    const bleedInfo = activeCanvas.bleedInfo || { left: mmToPx(bleed), top: mmToPx(bleed) };
    const pageW = Math.max(1, (bleedInfo.pageCanvasWidth || activeCanvas.width) - (bleedInfo.left * 2));
    const pageH = Math.max(1, (bleedInfo.pageCanvasHeight || activeCanvas.height) - (bleedInfo.top * 2));
    // Affichage X/Y relatif au bord de page (hors fond perdu)
    document.getElementById('transformX').value = factor(obj.left - bleedInfo.left).toFixed(1);
    document.getElementById('transformY').value = factor(obj.top - bleedInfo.top).toFixed(1);
    const displayW = (obj._fixedWidth != null ? obj._fixedWidth : obj.width) * (obj.scaleX || 1);
    const displayH = (obj._fixedHeight != null ? obj._fixedHeight : obj.height) * (obj.scaleY || 1);
    document.getElementById('transformW').value = factor(displayW).toFixed(1);
    document.getElementById('transformH').value = factor(displayH).toFixed(1);
    document.getElementById('transformAngle').value = (obj.angle || 0).toFixed(1);
    const scalePctEl = document.getElementById('transformScalePct');
    if (scalePctEl) scalePctEl.value = '100';
    
    // Mise à jour du fill : gérer transparent / null / gradient
    const blockFillInput = document.getElementById('blockFill');
    const blockFillNoneBtn = document.getElementById('blockFillNone');
    const fillIsGradient = obj.fill && typeof obj.fill === 'object' && obj.fill.type;
    if (fillIsGradient) {
        // Objet avec un dégradé : afficher la première couleur du gradient dans le picker
        const stops = obj.fill.colorStops;
        if (stops && stops.length > 0) {
            try { blockFillInput.value = stops[0].color; } catch(_) {}
        }
        if (blockFillNoneBtn) blockFillNoneBtn.style.borderColor = '#e0e0e0';
        blockFillInput.style.opacity = '1';
        window._blockFillNone = false;
    } else if (obj.fill && obj.fill !== 'transparent' && obj.fill !== '' && obj.fill !== null) {
        try { blockFillInput.value = obj.fill; } catch(_) {}
        if (blockFillNoneBtn) blockFillNoneBtn.style.borderColor = '#e0e0e0';
        blockFillInput.style.opacity = '1';
        window._blockFillNone = false;
    } else {
        // Objet sans fond
        if (blockFillNoneBtn) blockFillNoneBtn.style.borderColor = '#e74c3c';
        blockFillInput.style.opacity = '0.3';
        window._blockFillNone = true;
    }
    // Mise à jour du stroke : gérer transparent / null
    const blockStrokeInput = document.getElementById('blockStroke');
    const blockStrokeNoneBtn = document.getElementById('blockStrokeNone');
    if (obj.stroke && obj.stroke !== 'transparent' && obj.stroke !== '' && obj.stroke !== null) {
        try { blockStrokeInput.value = obj.stroke; } catch(_) {}
        if (blockStrokeNoneBtn) blockStrokeNoneBtn.style.borderColor = '#e0e0e0';
        blockStrokeInput.style.opacity = '1';
        window._blockStrokeNone = false;
    } else {
        if (blockStrokeNoneBtn) blockStrokeNoneBtn.style.borderColor = '#e74c3c';
        blockStrokeInput.style.opacity = '0.3';
        window._blockStrokeNone = true;
    }
    if (obj.strokeWidth !== undefined) {
        document.getElementById('strokeWidth').value = obj.strokeWidth;
        // Sync CMYK stroke width
        const csw = document.getElementById('cmykStrokeWidth');
        if (csw) csw.value = obj.strokeWidth;
    }

    // ✅ Sync CMYK "none" button states
    const cmykFillNB = document.getElementById('cmykFillNoneBtn');
    if (cmykFillNB) cmykFillNB.style.borderColor = window._blockFillNone ? '#E74C3C' : '#e0e0e0';
    const cmykStrokeNB = document.getElementById('cmykStrokeNoneBtn');
    if (cmykStrokeNB) cmykStrokeNB.style.borderColor = window._blockStrokeNone ? '#E74C3C' : '#e0e0e0';

    // Mettre à jour l'affichage des infos couleur (hex ou CMYK)
    if (typeof window.updateColorInfo === 'function') window.updateColorInfo();

    // NOUVEAU : Afficher les contrôles d'image pour les images
    const imageControls = document.getElementById('imageControls');
    const imageMaskControls = document.getElementById('imageMaskControls');
    if (obj.type === 'image') {
        if (obj.lockUniScaling !== true) obj.lockUniScaling = true;
        if (obj.uniformScaling !== true) obj.uniformScaling = true;
        if (obj.lockScalingFlip !== true) obj.lockScalingFlip = true;
        if (imageControls) imageControls.style.display = 'block';
        if (imageMaskControls) imageMaskControls.style.display = 'block';
    } else {
        if (imageControls) imageControls.style.display = 'none';
        if (imageMaskControls) imageMaskControls.style.display = obj._isImageMask ? 'block' : 'none';
    }

    if (obj.type === 'textbox' || obj.type === 'text' || obj.type === 'i-text') {
        document.getElementById('typographySection').style.display = 'block';
        
        // Stabiliser les dimensions avant tout recalcul
        try { spLockTextboxDimensions(obj); } catch (_) {}
        
        // Forcer la mise à jour du cache si nécessaire (sans contracter le bloc)
        const skipAutoRecalc = obj._spSkipAutoRecalc && !obj.isEditing;
        if (obj._clearCache && !skipAutoRecalc) {
            const fixedW = (obj._fixedWidth != null ? obj._fixedWidth : obj.width);
            const fixedH = (obj._fixedHeight != null ? obj._fixedHeight : obj.height);
            obj._clearCache();
            obj.initDimensions();
            // Restaurer les dimensions si le bloc est dimensionné (évite le retrait au clic)
            if (fixedW != null && fixedH != null) {
                obj._fixedWidth = fixedW;
                obj._fixedHeight = fixedH;
                obj.width = fixedW;
                obj.height = fixedH;
                try { applyTextboxClipPath(obj); } catch (_) {}
            }
        }
        
        // ✨ NOUVEAU : Détecter si du texte est sélectionné pour afficher les propriétés de la sélection
        let fontFamily, currentFontSize, lineHeightValue, charSpacingValue, textFill, fontWeight, fontStyle, underlineStyle;
        
        const hasTextSelection = obj.isEditing && obj.selectionStart != null && obj.selectionEnd != null && obj.selectionEnd > obj.selectionStart;
        
        if (hasTextSelection) {
            // 📝 Récupérer les propriétés de la sélection (premier caractère sélectionné)
            const selectionStyles = obj.getSelectionStyles(obj.selectionStart, obj.selectionEnd);
            const firstCharStyle = selectionStyles[0] || {};
            
            // Utiliser les styles de la sélection en priorité, sinon les styles du bloc
            fontFamily = firstCharStyle.fontFamily || obj.fontFamily || 'Open Sans';
            currentFontSize = firstCharStyle.fontSize || obj.fontSize || 14;
            lineHeightValue = firstCharStyle.lineHeight || obj.lineHeight || 1.16;
            charSpacingValue = firstCharStyle.charSpacing !== undefined ? firstCharStyle.charSpacing : (obj.charSpacing || 0);
            textFill = firstCharStyle.fill || obj.fill || '#000000';
            fontWeight = firstCharStyle.fontWeight || obj.fontWeight || '400';
            fontStyle = firstCharStyle.fontStyle || obj.fontStyle || 'normal';
            underlineStyle = firstCharStyle.underline !== undefined ? firstCharStyle.underline : obj.underline;
            
            // 💡 Indiquer visuellement qu'on affiche les propriétés d'une sélection
            const typoSection = document.getElementById('typographySection');
            if (typoSection && !typoSection.dataset.selectionMode) {
                typoSection.classList.add('typo-selection-mode');
                typoSection.dataset.selectionMode = 'true';
            }
        } else {
            // Pas de sélection : utiliser les propriétés globales du bloc
            fontFamily = obj.fontFamily || 'Open Sans';
            currentFontSize = obj.fontSize || 14;
            lineHeightValue = obj.lineHeight || 1.16;
            charSpacingValue = obj.charSpacing || 0;
            textFill = obj.fill || '#000000';
            fontWeight = obj.fontWeight || '400';
            fontStyle = obj.fontStyle || 'normal';
            underlineStyle = obj.underline;
            
            // Retirer l'indicateur visuel de sélection
            const typoSection = document.getElementById('typographySection');
            if (typoSection && typoSection.dataset.selectionMode) {
                typoSection.classList.remove('typo-selection-mode');
                delete typoSection.dataset.selectionMode;
            }
        }
        
        // Mettre à jour les valeurs des contrôles avec les valeurs détectées
        document.getElementById('fontFamily').value = fontFamily;
        document.getElementById('fontSize').value = Math.round(currentFontSize);
        // Convertir l'interligne en points pour l'affichage
        const lineHeightPt = Math.round(lineHeightValue * currentFontSize);
        document.getElementById('lineHeight').value = lineHeightPt;
        document.getElementById('charSpacing').value = Math.round(charSpacingValue);
        document.getElementById('textScaleX').value = Math.round((obj.scaleX || 1) * 100);
        document.getElementById('textFill').value = textFill;
        
        // 📐 Retraits de paragraphe
        const ilEl = document.getElementById('indentLeft');
        const irEl = document.getElementById('indentRight');
        const iflEl = document.getElementById('indentFirstLine');
        if (ilEl) ilEl.value = Math.round(obj._spIndentLeft || 0);
        if (irEl) irEl.value = Math.round(obj._spIndentRight || 0);
        if (iflEl) iflEl.value = Math.round(obj._spFirstLineIndent || 0);
        
        // Mettre à jour les graisses disponibles et sélectionner la graisse actuelle
        updateFontWeightOptions(fontFamily);
        document.getElementById('fontWeight').value = fontWeight;
        
        // Mettre à jour les boutons de style
        document.getElementById('textItalic').classList.toggle('active', fontStyle === 'italic');
        document.getElementById('textUnderline').classList.toggle('active', underlineStyle === true);

        // ✅ Sync de TOUS les boutons "Options avancées" / "Formats" sur la sélection ou le bloc actif
        try { spSyncAdvancedFormatButtons(obj); } catch (_) {}
        
        // Mettre à jour les boutons d'alignement
        document.querySelectorAll('[data-text-align]').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.textAlign === (obj.textAlign || 'left'));
        });
        
        // Mettre à jour les réglages de justification
        const js = obj._justSettings || {};
        const justWMin = document.getElementById('justWordSpaceMin');
        if (justWMin) {
            document.getElementById('justWordSpaceMin').value = js.wordSpaceMin || 80;
            document.getElementById('justWordSpaceOpt').value = js.wordSpaceOpt || 100;
            document.getElementById('justWordSpaceMax').value = js.wordSpaceMax || 133;
            document.getElementById('justLetterSpaceMin').value = js.letterSpaceMin || 0;
            document.getElementById('justLetterSpaceOpt').value = js.letterSpaceOpt || 0;
            document.getElementById('justLetterSpaceMax').value = js.letterSpaceMax || 0;
            document.getElementById('justGlyphScaleMin').value = js.glyphScaleMin || 100;
            document.getElementById('justGlyphScaleOpt').value = js.glyphScaleOpt || 100;
            document.getElementById('justGlyphScaleMax').value = js.glyphScaleMax || 100;
        }
    } else {
        document.getElementById('typographySection').style.display = 'none';
    }

    // 🍏 v1.7.231 : Afficher/masquer le panneau coins arrondis pour les rect
    var cornerPanel = document.getElementById('shapeCornerRadius');
    if (cornerPanel) {
        if (obj.type === 'rect' || (obj._spCornerRadii && obj.type === 'path')) {
            cornerPanel.style.display = 'block';
            // 🍏 v1.7.231 : Lire les coins (liés ou individuels)
            var corners = _spReadCorners(obj);
            // Le mode lié/délié est stocké sur l'objet (pas en variable globale)
            var linked = (obj._spCornersLinked !== false) && (corners.tl === corners.tr && corners.tl === corners.bl && corners.tl === corners.br);
            var linkBtn = document.getElementById('cornerLinkToggle');
            var linkedMode = document.getElementById('cornerLinkedMode');
            var unlinkedMode = document.getElementById('cornerUnlinkedMode');
            if (linkBtn) linkBtn.textContent = linked ? '🔗' : '🔓';
            if (linkedMode) linkedMode.style.display = linked ? '' : 'none';
            if (unlinkedMode) unlinkedMode.style.display = linked ? 'none' : '';
            var maxR = Math.max(200, Math.round(Math.min(obj.width * (obj.scaleX || 1), obj.height * (obj.scaleY || 1)) / 2));
            // 🎨 FIX 2026-08-26 : mettre à jour la piste remplie du slider (look CMYK)
            var fillTrack = function(sl, val) {
                if (!sl || !sl.max) return;
                var pct = Math.max(0, Math.min(100, (val / sl.max) * 100));
                sl.style.backgroundSize = pct + '% 100%';
            };
            if (linked) {
                var slider = document.getElementById('cornerRadiusSlider');
                var input = document.getElementById('cornerRadiusInput');
                if (slider) { slider.value = Math.round(corners.tl); slider.max = maxR; fillTrack(slider, Math.round(corners.tl)); }
                if (input) input.value = Math.round(corners.tl);
            } else {
                ['tl','tr','bl','br'].forEach(function(c) {
                    var sl = document.querySelector('.corner-slider[data-corner="' + c + '"]');
                    var inp = document.querySelector('.corner-input[data-corner="' + c + '"]');
                    if (sl) { sl.value = Math.round(corners[c]); sl.max = maxR; fillTrack(sl, Math.round(corners[c])); }
                    if (inp) inp.value = Math.round(corners[c]);
                });
            }
        } else {
            cornerPanel.style.display = 'none';
        }
    }
        }

        // 🍏 v1.7.231 : Lire les 4 coins d'un rect ou path
        function _spReadCorners(obj) {
            if (obj._spCornerRadii) return obj._spCornerRadii;
            var r = (typeof obj.rx === 'number') ? obj.rx : 0;
            return { tl: r, tr: r, bl: r, br: r };
        }

        // 🍏 v1.7.231 : Convertit un fabric.Rect en fabric.Path avec coins individuels
        function _spApplyPerCornerPath(obj, radii) {
            if (!obj || !obj.canvas) return;
            var w = obj.width * (obj.scaleX || 1);
            var h = obj.height * (obj.scaleY || 1);
            var tl = Math.max(0, Math.min(radii.tl, w/2, h/2));
            var tr = Math.max(0, Math.min(radii.tr, w/2, h/2));
            var bl = Math.max(0, Math.min(radii.bl, w/2, h/2));
            var br = Math.max(0, Math.min(radii.br, w/2, h/2));
            // Construire le path SVG
            var d = 'M ' + tl.toFixed(2) + ' 0 ' +
                'L ' + (w - tr).toFixed(2) + ' 0 ' +
                'Q ' + w.toFixed(2) + ' 0 ' + w.toFixed(2) + ' ' + tr.toFixed(2) + ' ' +
                'L ' + w.toFixed(2) + ' ' + (h - br).toFixed(2) + ' ' +
                'Q ' + w.toFixed(2) + ' ' + h.toFixed(2) + ' ' + (w - br).toFixed(2) + ' ' + h.toFixed(2) + ' ' +
                'L ' + bl.toFixed(2) + ' ' + h.toFixed(2) + ' ' +
                'Q 0 ' + h.toFixed(2) + ' 0 ' + (h - bl).toFixed(2) + ' ' +
                'L 0 ' + tl.toFixed(2) + ' ' +
                'Q 0 0 ' + tl.toFixed(2) + ' 0 Z';
            var wasPath = (obj.type === 'path' && obj._spCornerRadii);
            var oldLeft = obj.left, oldTop = obj.top, oldAngle = obj.angle || 0;
            var oldFill = obj.fill, oldStroke = obj.stroke, oldStrokeWidth = obj.strokeWidth || 0;
            var oldOpacity = obj.opacity != null ? obj.opacity : 1;
            var oldIndex = obj.canvas.getObjects().indexOf(obj);
            var canvas = obj.canvas;
            // 🍏 v1.7.231 : Préserver les propriétés de masque image
            var wasImageMask = obj._isImageMask;
            var maskImage = obj._maskImage;
            var maskImageSourceURL = obj._maskImageSourceURL;
            var maskMode = obj._maskMode;
            var maskPositionRatioX = obj._maskPositionRatioX;
            var maskPositionRatioY = obj._maskPositionRatioY;
            var maskUserZoom = obj._maskUserZoom;
            var maskBackgroundColor = obj._maskBackgroundColor;
            var maskPatternCanvas = obj._maskPatternCanvas;
            var maskScale = obj._maskScale;
            var maskOffsetX = obj._maskOffsetX;
            var maskOffsetY = obj._maskOffsetY;
            var originalFill = obj._originalFill;
            var originalStroke = obj._originalStroke;
            var originalStrokeWidth = obj._originalStrokeWidth;
            var previousSize = obj._previousSize;
            canvas.remove(obj);
            var path = new fabric.Path(d, {
                left: oldLeft, top: oldTop, angle: oldAngle,
                fill: oldFill, stroke: oldStroke, strokeWidth: oldStrokeWidth,
                opacity: oldOpacity, originX: 'left', originY: 'top',
                objectCaching: false
            });
            path._spCornerRadii = { tl: tl, tr: tr, bl: bl, br: br };
            path._spCornersLinked = false; // mode délié
            path._spOrigWidth = w; path._spOrigHeight = h;
            // 🍏 v1.7.231 : Restaurer les propriétés de masque image
            if (wasImageMask) {
                path._isImageMask = true;
                path._maskImage = maskImage;
                path._maskImageSourceURL = maskImageSourceURL;
                path._maskMode = maskMode;
                path._maskPositionRatioX = maskPositionRatioX;
                path._maskPositionRatioY = maskPositionRatioY;
                path._maskUserZoom = maskUserZoom;
                path._maskBackgroundColor = maskBackgroundColor;
                path._maskPatternCanvas = maskPatternCanvas;
                path._maskScale = maskScale;
                path._maskOffsetX = maskOffsetX;
                path._maskOffsetY = maskOffsetY;
                path._originalFill = originalFill;
                path._originalStroke = originalStroke;
                path._originalStrokeWidth = originalStrokeWidth;
                path._previousSize = previousSize;
                path.objectCaching = false;
                path.statefullCache = false;
                path.noScaleCache = true;
                path.needsItsOwnCache = function() { return false; };
            }
            if (oldIndex >= 0) canvas.insertAt(path, Math.min(oldIndex, canvas.getObjects().length));
            else canvas.add(path);
            path.setCoords();
            canvas.setActiveObject(path);
            canvas.requestRenderAll();
            return path;
        }

        // 🍏 v1.7.231 : Convertit un fabric.Path (coins individuels) en fabric.Rect
        function _spApplyUniformCorners(obj, radius) {
            if (!obj || !obj.canvas) return;
            var w = obj._spOrigWidth || (obj.width * (obj.scaleX || 1));
            var h = obj._spOrigHeight || (obj.height * (obj.scaleY || 1));
            var r = Math.max(0, Math.min(radius, w/2, h/2));
            var oldLeft = obj.left, oldTop = obj.top, oldAngle = obj.angle || 0;
            var oldFill = obj.fill, oldStroke = obj.stroke, oldStrokeWidth = obj.strokeWidth || 0;
            var oldOpacity = obj.opacity != null ? obj.opacity : 1;
            var oldIndex = obj.canvas.getObjects().indexOf(obj);
            var canvas = obj.canvas;
            // 🍏 v1.7.231 : Préserver les propriétés de masque image
            var wasImageMask = obj._isImageMask;
            var maskImage = obj._maskImage;
            var maskImageSourceURL = obj._maskImageSourceURL;
            var maskMode = obj._maskMode;
            var maskPositionRatioX = obj._maskPositionRatioX;
            var maskPositionRatioY = obj._maskPositionRatioY;
            var maskUserZoom = obj._maskUserZoom;
            var maskBackgroundColor = obj._maskBackgroundColor;
            var maskPatternCanvas = obj._maskPatternCanvas;
            var maskScale = obj._maskScale;
            var maskOffsetX = obj._maskOffsetX;
            var maskOffsetY = obj._maskOffsetY;
            var originalFill = obj._originalFill;
            var originalStroke = obj._originalStroke;
            var originalStrokeWidth = obj._originalStrokeWidth;
            var previousSize = obj._previousSize;
            canvas.remove(obj);
            var rect = new fabric.Rect({
                left: oldLeft, top: oldTop, angle: oldAngle,
                width: w, height: h, rx: r, ry: r,
                fill: oldFill, stroke: oldStroke, strokeWidth: oldStrokeWidth,
                opacity: oldOpacity, originX: 'left', originY: 'top',
                objectCaching: false
            });
            rect._spCornersLinked = true; // mode lié
            // 🍏 v1.7.231 : Restaurer les propriétés de masque image
            if (wasImageMask) {
                rect._isImageMask = true;
                rect._maskImage = maskImage;
                rect._maskImageSourceURL = maskImageSourceURL;
                rect._maskMode = maskMode;
                rect._maskPositionRatioX = maskPositionRatioX;
                rect._maskPositionRatioY = maskPositionRatioY;
                rect._maskUserZoom = maskUserZoom;
                rect._maskBackgroundColor = maskBackgroundColor;
                rect._maskPatternCanvas = maskPatternCanvas;
                rect._maskScale = maskScale;
                rect._maskOffsetX = maskOffsetX;
                rect._maskOffsetY = maskOffsetY;
                rect._originalFill = originalFill;
                rect._originalStroke = originalStroke;
                rect._originalStrokeWidth = originalStrokeWidth;
                rect._previousSize = previousSize;
                rect.objectCaching = false;
                rect.statefullCache = false;
                rect.noScaleCache = true;
                rect.needsItsOwnCache = function() { return false; };
            }
            if (oldIndex >= 0) canvas.insertAt(rect, Math.min(oldIndex, canvas.getObjects().length));
            else canvas.add(rect);
            rect.setCoords();
            canvas.setActiveObject(rect);
            canvas.requestRenderAll();
            return rect;
        }

        function applyTransform() {
    const activeCanvas = getActiveCanvas();
    if (!activeCanvas) return;
    
    const obj = activeCanvas.getActiveObject();
    if (!obj) return;

    const converter = getUnitToPxFn();
    const factor = getPxToUnitFn();
    const bleedInfo = activeCanvas.bleedInfo || { left: mmToPx(bleed), top: mmToPx(bleed) };
    const pageW = Math.max(1, (bleedInfo.pageCanvasWidth || activeCanvas.width) - (bleedInfo.left * 2));
    const pageH = Math.max(1, (bleedInfo.pageCanvasHeight || activeCanvas.height) - (bleedInfo.top * 2));
    let newLeft;
    let newTop;
    let newWidth;
    let newHeight;

    newLeft = bleedInfo.left + converter(parseFloat(document.getElementById('transformX').value));
    newTop = bleedInfo.top + converter(parseFloat(document.getElementById('transformY').value));
    newWidth = converter(parseFloat(document.getElementById('transformW').value));
    newHeight = converter(parseFloat(document.getElementById('transformH').value));

    if (transformLockAspect && (lastTransformField === 'transformW' || lastTransformField === 'transformH')) {
        const currentWidth = (obj.width || 0) * (obj.scaleX || 1);
        const currentHeight = (obj.height || 0) * (obj.scaleY || 1);
        if (currentWidth > 0 && currentHeight > 0) {
            const ratio = currentWidth / currentHeight;
            if (lastTransformField === 'transformW') {
                newHeight = newWidth / ratio;
                document.getElementById('transformH').value = factor(newHeight).toFixed(1);
            } else {
                newWidth = newHeight * ratio;
                document.getElementById('transformW').value = factor(newWidth).toFixed(1);
            }
        }
    }

    obj.set({
        // Application X/Y relatif au bord de page (ajoute le fond perdu)
        left: newLeft,
        top: newTop,
        angle: parseFloat(document.getElementById('transformAngle').value)
    });
    
    // Comportement PAO : pour les textbox, modifier width/height directement sans scaling
    if (obj.type === 'textbox' || obj.type === 'text') {
        const fixedW = Math.max(1, newWidth);
        const fixedH = Math.max(1, newHeight);

        obj.set({
            width: fixedW,
            height: fixedH,
            scaleX: 1,
            scaleY: 1
        });

        // Verrouiller les dimensions pour éviter les resets de hauteur
        obj._fixedWidth = fixedW;
        obj._fixedHeight = fixedH;

        // Recalculer sans perdre les dimensions
        try { forceTextRecalc(obj); } catch (_) {
            if (typeof obj._clearCache === 'function') obj._clearCache();
            if (typeof obj.initDimensions === 'function') obj.initDimensions();
            obj.width = fixedW;
            obj.height = fixedH;
        }

        checkTextOverflow(activeCanvas);
    } else {
        // Pour les autres objets, calculer les scales nécessaires pour atteindre les dimensions
        const currentWidth = obj.width * obj.scaleX;
        const currentHeight = obj.height * obj.scaleY;
        const newScaleX = (currentWidth > 0) ? (newWidth / obj.width) : 1;
        const newScaleY = (currentHeight > 0) ? (newHeight / obj.height) : 1;
        
        obj.set({
            scaleX: newScaleX,
            scaleY: newScaleY
        });
    }

    obj.setCoords();
    activeCanvas.requestRenderAll();
    saveState('Transformation');
        }

        // État interne : sans fond / sans contour
        // Utiliser window.* pour rester synchronisé avec updateTransformPanel()
        if (window._blockFillNone === undefined) window._blockFillNone = false;
        if (window._blockStrokeNone === undefined) window._blockStrokeNone = false;

        function applyColors(skipSave) {
    const activeCanvas = getActiveCanvas();
    if (!activeCanvas) return;
    
    let obj = activeCanvas.getActiveObject();
    if (!obj) return;

    // FIX: Si c'est un miroir, rediriger vers l'objet original
    if (obj._isSpreadMirror && obj._sourcePageIndex !== undefined && obj._sourceObjectId) {
        const sourceCanvas = canvases[obj._sourcePageIndex];
        const sourceObj = sourceCanvas?.getObjects().find(o => o._spreadObjectId === obj._sourceObjectId);
        
        if (sourceObj && sourceCanvas) {
            obj = sourceObj;
            activeCanvas.discardActiveObject();
            sourceCanvas.setActiveObject(sourceObj);
            currentPageIndex = obj._sourcePageIndex;
        }
    }

    const fillValue = window._blockFillNone ? 'transparent' : document.getElementById('blockFill').value;
    const strokeValue = window._blockStrokeNone ? 'transparent' : document.getElementById('blockStroke').value;

    obj.set({
        fill: fillValue,
        stroke: strokeValue,
        strokeWidth: window._blockStrokeNone ? 0 : parseFloat(document.getElementById('strokeWidth').value)
    });
    
    // Rendre à la fois le canvas source et le canvas actuel
    if (obj.canvas) {
        obj.canvas.requestRenderAll();
    }
    if (activeCanvas !== obj.canvas) {
        activeCanvas.requestRenderAll();
    }
    
    if (!skipSave) saveState('Couleurs');
        }

        // Bouton "Sans fond"
        document.getElementById('blockFillNone')?.addEventListener('click', () => {
            window._blockFillNone = !window._blockFillNone;
            const btn = document.getElementById('blockFillNone');
            const fillInput = document.getElementById('blockFill');
            if (window._blockFillNone) {
                btn.style.borderColor = '#e74c3c';
                fillInput.style.opacity = '0.3';
            } else {
                btn.style.borderColor = '#e0e0e0';
                fillInput.style.opacity = '1';
            }
            applyColors();
            updateColorInfo();
        });

        // Bouton "Sans contour"
        document.getElementById('blockStrokeNone')?.addEventListener('click', () => {
            window._blockStrokeNone = !window._blockStrokeNone;
            const btn = document.getElementById('blockStrokeNone');
            const strokeInput = document.getElementById('blockStroke');
            if (window._blockStrokeNone) {
                btn.style.borderColor = '#e74c3c';
                strokeInput.style.opacity = '0.3';
            } else {
                btn.style.borderColor = '#e0e0e0';
                strokeInput.style.opacity = '1';
            }
            applyColors();
            updateColorInfo();
        });

        // ── Panneau Transparence : applique l'opacité aux objets sélectionnés
        // (textes, formes, images). Synchronise le slider à la sélection.
        const _opacitySlider = document.getElementById('opacitySlider');
        const _opacityValue = document.getElementById('opacityValue');
        if (_opacitySlider && _opacityValue) {
            function _applyOpacityToSelection(val, save) {
                const activeCanvas = getActiveCanvas();
                if (!activeCanvas) return;
                const obj = activeCanvas.getActiveObject();
                if (!obj) return;
                const opacity = Math.max(0, Math.min(1, val / 100));
                // Éviter de toucher aux objets de repères / système
                if (obj.isMargin || obj.isBleed || obj.isTrimBox || obj.isGuide || obj.isManualGuide) return;
                obj.set({ opacity: opacity, dirty: true });
                activeCanvas.requestRenderAll();
                if (save !== false) saveState('Transparence');
            }
            _opacitySlider.addEventListener('input', function() {
                const v = parseInt(this.value, 10);
                if (_opacityValue) _opacityValue.value = v;
                _applyOpacityToSelection(v, false); // live, sans saveState
            });
            _opacitySlider.addEventListener('change', function() {
                const v = parseInt(this.value, 10);
                if (_opacityValue) _opacityValue.value = v;
                _applyOpacityToSelection(v, true);
            });
            _opacityValue.addEventListener('change', function() {
                let v = parseInt(this.value, 10);
                if (isNaN(v)) v = 100;
                v = Math.max(0, Math.min(100, v));
                this.value = v;
                if (_opacitySlider) _opacitySlider.value = v;
                _applyOpacityToSelection(v, true);
            });
        }
        // Synchronise le slider quand un objet est sélectionné
        window.updateOpacityUI = function() {
            const activeCanvas = getActiveCanvas();
            if (!_opacitySlider || !activeCanvas) return;
            const obj = activeCanvas.getActiveObject();
            if (obj && !(obj.isMargin || obj.isBleed || obj.isTrimBox || obj.isGuide || obj.isManualGuide)) {
                const pct = Math.round((obj.opacity != null ? obj.opacity : 1) * 100);
                _opacitySlider.value = pct;
                if (_opacityValue) _opacityValue.value = pct;
            } else {
                _opacitySlider.value = 100;
                if (_opacityValue) _opacityValue.value = 100;
            }
        };

        function nudgeObject(dx, dy) {
    const activeCanvas = getActiveCanvas();
    if (!activeCanvas) return;
    
    const obj = activeCanvas.getActiveObject();
    if (!obj) return;

    let stepX;
    let stepY;
    const step = currentUnit === 'cm'
        ? cmToPx(0.1)
        : currentUnit === 'in'
            ? inToPx(0.05)
            : currentUnit === 'px'
                ? 1
                : mmToPx(1);
    stepX = step;
    stepY = step;
    obj.left += dx * stepX;
    obj.top += dy * stepY;
    obj.setCoords();
    activeCanvas.requestRenderAll();
    updateTransformPanel();
        }

        function addRect() {
    // FIX: Désélectionner tous les objets avant d'en créer un nouveau
    canvases.forEach(c => {
        if (c && c.getActiveObject()) {
            c.discardActiveObject();
        }
    });
    
    const activeCanvas = getActiveCanvas();
    if (!activeCanvas) return;
    
    const bleedInfo = activeCanvas.bleedInfo || { left: mmToPx(bleed), top: mmToPx(bleed) };
    
    const rect = new fabric.Rect({
        left: bleedInfo.left + 100,
        top: bleedInfo.top + 100,
        width: mmToPx(50),
        height: mmToPx(30),
        fill: '#b3b3b3',
        stroke: 'transparent',
        strokeWidth: 0
    });
    activeCanvas.add(rect);
    activeCanvas.requestRenderAll();
    
    // ? Auto-dèsélection après création (comportement PAO professionnel)
    setTimeout(() => {
        activeCanvas.discardActiveObject();
        activeCanvas.requestRenderAll();
    }, 50);
    
    debouncedUpdateLayersPanel();
        }

        function addCircle() {
    // FIX: Désélectionner tous les objets avant d'en créer un nouveau
    canvases.forEach(c => {
        if (c && c.getActiveObject()) {
            c.discardActiveObject();
        }
    });
    
    const activeCanvas = getActiveCanvas();
    if (!activeCanvas) return;
    
    const bleedInfo = activeCanvas.bleedInfo || { left: mmToPx(bleed), top: mmToPx(bleed) };
    
    // CALCUL POSITION INITIALE INTELLIGENTE EN MODE SPREAD
    let initialLeft = bleedInfo.left + 100;
    let initialTop = bleedInfo.top + 100;
    
    if (viewMode === 'spread' && bleedInfo.isSpread) {
        const centerX = bleedInfo.centerX || (activeCanvas.width / 2);
        if (currentPageIndex === bleedInfo.rightPageIndex) {
            initialLeft = centerX + 100; // Page droite
        }
    }
    
    const circle = new fabric.Circle({
        left: initialLeft,
        top: initialTop,
        radius: mmToPx(25),
        fill: '#b3b3b3',
        stroke: 'transparent',
        strokeWidth: 0
    });
    activeCanvas.add(circle);
    activeCanvas.requestRenderAll();
    
    // ? Auto-dèsélection après création (comportement PAO professionnel)
    setTimeout(() => {
        activeCanvas.discardActiveObject();
        activeCanvas.requestRenderAll();
    }, 50);
    
    debouncedUpdateLayersPanel();
        }

        function addStar() {
    const activeCanvas = getActiveCanvas();
    if (!activeCanvas) return;
    
    const bleedInfo = activeCanvas.bleedInfo || { left: mmToPx(bleed), top: mmToPx(bleed) };
    
    // CALCUL POSITION INITIALE INTELLIGENTE EN MODE SPREAD
    let initialLeft = bleedInfo.left + 100;
    let initialTop = bleedInfo.top + 100;
    
    if (viewMode === 'spread' && bleedInfo.isSpread) {
        const centerX = bleedInfo.centerX || (activeCanvas.width / 2);
        if (currentPageIndex === bleedInfo.rightPageIndex) {
            initialLeft = centerX + 100; // Page droite
        }
    }
    
    // Créer une étoile à 5 branches
    const points = 5;
    const outerRadius = mmToPx(30);
    const innerRadius = mmToPx(15);
    const starPoints = [];
    
    for (let i = 0; i < points * 2; i++) {
        const radius = i % 2 === 0 ? outerRadius : innerRadius;
        const angle = (Math.PI * i) / points - Math.PI / 2;
        starPoints.push({
            x: radius * Math.cos(angle),
            y: radius * Math.sin(angle)
        });
    }
    
    const star = new fabric.Polygon(starPoints, {
        left: initialLeft,
        top: initialTop,
        fill: '#b3b3b3',
        stroke: 'transparent',
        strokeWidth: 0,
        objectCaching: true
    });
    
    activeCanvas.add(star);
    activeCanvas.requestRenderAll();
    
    // ? Auto-dèsélection après création (comportement PAO professionnel)
    setTimeout(() => {
        activeCanvas.discardActiveObject();
        activeCanvas.requestRenderAll();
    }, 50);
    
    debouncedUpdateLayersPanel();
        }

