        function setupShapesDropdown() {
    const toggle = document.getElementById('shapesToggle');
    const menu = document.getElementById('shapesMenu');
    const dropdown = document.getElementById('shapesDropdown');
    
    if (!toggle || !menu) return;
    
    // Toggle menu on click
    toggle.addEventListener('click', (e) => {
        e.stopPropagation();
        menu.classList.toggle('open');
    });
    
    // Close menu when clicking outside
    document.addEventListener('click', (e) => {
        if (!dropdown.contains(e.target)) {
            menu.classList.remove('open');
        }
    });
    
    // Update icon and close menu when selecting a shape
    const shapeButtons = menu.querySelectorAll('.dropdown-item');
    shapeButtons.forEach(btn => {
        btn.addEventListener('click', (e) => {
            const icon = btn.querySelector('.tool-icon');
            if (icon) {
                const mainIcon = document.getElementById('shapesIcon');
                if (mainIcon) {
                    mainIcon.src = icon.src;
                    mainIcon.alt = icon.alt;
                }
            }
            menu.classList.remove('open');
        });
    });
        }

        // ==================== PEN + PENCIL DROPDOWN ====================
        function setupPenDropdown() {
    const toggle = document.getElementById('penTool');
    const menu = document.getElementById('penMenu');
    const dropdown = document.getElementById('penDropdown');
    if (!toggle || !menu || !dropdown) {
        const legacy = document.getElementById('penTool');
        if (legacy) legacy.addEventListener('click', activatePenTool);
        return;
    }
    toggle.addEventListener('click', (e) => {
        e.stopPropagation();
        menu.classList.toggle('open');
    });
    document.addEventListener('click', (e) => {
        if (!dropdown.contains(e.target)) menu.classList.remove('open');
    });
    const penItem = document.getElementById('penToolItem');
    const PEN_ICON_SVG = {
        select: '<svg class="tool-icon" id="penIcon" viewBox="0 0 24 24" fill="currentColor" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 3 L5 18 L9 14 L11.5 19.5 L13.5 18.7 L11 13.2 L17 13 Z"/></svg>',
        pen:    '<img src="icons/pen.svg" alt="Plume" class="tool-icon" id="penIcon">',
        pencil: '<img src="icons/freeform-pen.svg" alt="Crayon" class="tool-icon" id="penIcon">'
    };
    const setPenToolbarIcon = (mode) => {
        const cur = document.getElementById('penIcon');
        if (!cur || !PEN_ICON_SVG[mode]) return;
        const tmp = document.createElement('div');
        tmp.innerHTML = PEN_ICON_SVG[mode];
        const newIcon = tmp.firstElementChild;
        cur.parentNode.replaceChild(newIcon, cur);
        const labels = { select: 'Sélection', pen: 'Plume', pencil: 'Crayon' };
        const titles = { select: 'Sélection / Plume / Crayon', pen: 'Plume / Crayon', pencil: 'Crayon / Plume' };
        toggle.setAttribute('aria-label', labels[mode]);
        toggle.setAttribute('title', titles[mode]);
    };
    const selectItem = document.getElementById('selectToolItem');
    if (selectItem) {
        selectItem.addEventListener('click', (e) => {
            e.stopPropagation();
            menu.classList.remove('open');
            try { if (typeof window.__spActivateSelectTool === 'function') window.__spActivateSelectTool(); } catch(_) {}
            setPenToolbarIcon('select');
        });
    }
    if (penItem) {
        penItem.addEventListener('click', (e) => {
            e.stopPropagation();
            menu.classList.remove('open');
            if (window.simplePenTool && window.simplePenTool.isPencilActive && window.simplePenTool.isPencilActive()) {
                try { window.simplePenTool.deactivatePencil(); } catch(_) {}
            }
            setPenToolbarIcon('pen');
            activatePenTool();
        });
    }
    const pencilItem = document.getElementById('pencilTool');
    if (pencilItem) {
        pencilItem.addEventListener('click', (e) => {
            e.stopPropagation();
            menu.classList.remove('open');
            const canvas = (typeof getActiveCanvas === 'function') ? getActiveCanvas() : null;
            if (!canvas) { console.error('❌ Pas de canvas actif'); return; }
            if (!window.simplePenTool) { console.error('❌ simplePenTool non chargé'); return; }
            if (window.simplePenTool.isPencilActive && window.simplePenTool.isPencilActive()) {
                window.simplePenTool.deactivatePencil();
                setPenToolbarIcon('select');
                try { if (typeof window.__spActivateSelectTool === 'function') window.__spActivateSelectTool(); } catch(_) {}
                return;
            }
            if (window.simplePenTool.active) {
                try { window.simplePenTool.deactivate(); } catch(_) {}
            }
            window.simplePenTool.activatePencil(canvas);
            setPenToolbarIcon('pencil');
        });
    }
        }

