        function applyFixedHeightProtection(textbox) {
    if (!textbox || (textbox.type !== 'textbox' && textbox.type !== 'text')) {
        return;
    }
    
    // 🔒 BLOQUER le recalcul automatique de la hauteur
    const originalInitDimensions = textbox.initDimensions.bind(textbox);
    textbox.initDimensions = function() {
        originalInitDimensions();
        // Toujours restaurer la hauteur fixe après recalcul
        if (this._fixedHeight !== undefined) {
            this.height = this._fixedHeight;
        }
    };
    
    // 🔒 Event 'modified' : restaurer la hauteur si elle change
    textbox.on('modified', function() {
        if (this._fixedHeight !== undefined && this.height !== this._fixedHeight) {
            this.height = this._fixedHeight;
            this.setCoords();
        }
    });
    
    // 🔒 Event 'scaling' : convertir le scaling en redimensionnement de la hauteur fixe
    textbox.on('scaling', function() {
        const newHeight = this.height * (this.scaleY || 1);
        const newWidth = this.width * (this.scaleX || 1);
        
        // Mettre à jour la hauteur fixe
        this._fixedHeight = newHeight;
        this.height = newHeight;
        this.width = newWidth;
        
        // Réinitialiser les scales
        this.scaleX = 1;
        this.scaleY = 1;
        this.setCoords();
    });
    
        }
        
