        // Helper: ensure crisp rendering for big text boxes
        function ensureCrispText(tb) {
    if (!tb) return;
    tb.objectCaching = false; // force live render, avoids blurry cache at zoom
    tb.noScaleCache = true;
    tb.statefullCache = false;
    // pixel snap to avoid half-pixel blur
            if (typeof tb.left === 'number') tb.left = Math.round(tb.left);
            if (typeof tb.top === 'number') tb.top = Math.round(tb.top);
    if (typeof tb.width === 'number') tb.width = Math.round(tb.width);
    if (typeof tb.height === 'number') tb.height = Math.round(tb.height);
        }

        // ===== TXT Auto-pagination utilities =====
        function getFittingTextIndex(textbox, fullText) {
    // Binary search the last index that fits in textbox height
    // ✅ FIX: Priorité _fixedHeight pour les blocs chaînés, puis _maxTextHeight, puis height
    const maxHeight = (typeof textbox._fixedHeight === 'number') ? (textbox._fixedHeight * (textbox.scaleY || 1)) :
                      (typeof textbox._maxTextHeight === 'number') ? textbox._maxTextHeight : 
                      (textbox.height * (textbox.scaleY || 1));
    const original = textbox.text;
    const originalWidth = textbox.width;
    const originalHeight = textbox.height;
    let low = 0;
    let high = fullText.length;
    let best = 0;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        textbox.text = fullText.slice(0, mid);
        // ✅ Restore fixed width before initDimensions to prevent dimension drift
        if (typeof textbox._fixedWidth === 'number') textbox.width = textbox._fixedWidth;
        if (typeof textbox.initDimensions === 'function') textbox.initDimensions();
        const h = textbox.calcTextHeight();
        if (h <= maxHeight + 0.5) {
            best = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    // ✅ FIX InDesign-style: Snap to word boundary (never split mid-word)
    if (best > 0 && best < fullText.length) {
        const charAtBest = fullText[best];
        const charBefore = fullText[best - 1];
        // If split point is inside a word (neither side is whitespace), backtrack
        if (charAtBest && !/\s/.test(charAtBest) && charBefore && !/\s/.test(charBefore)) {
            let breakPos = best;
            while (breakPos > 0 && !/\s/.test(fullText[breakPos - 1])) {
                breakPos--;
            }
            // Use word boundary if found (don't go all the way to 0 — that means the
            // single word doesn't fit at all, so keep the character-level split)
            if (breakPos > 0) {
                best = breakPos;
            }
        }
    }
    textbox.text = original;
    textbox.width = originalWidth;
    textbox.height = originalHeight;
    return best;
        }

        // splitTextToFit: voir implémentation unique plus bas (~l.13903)

        function ensureNextPageCanvas(currentPageIndex) {
    const nextIndex = currentPageIndex + 1;
    if (nextIndex >= pages.length) {
        // Sauvegarder l'état actuel avant de re-rendre toutes les pages
        try { saveAllPages(); } catch(e) { console.warn('saveAllPages before new page failed', e); }
        createNewPage();
        renderAllPages();
    }
    return new Promise(resolve => {
        const start = Date.now();
        const tryGet = () => {
            const cv = canvases[nextIndex];
            if (cv && cv.lowerCanvasEl) {
                cv.requestRenderAll();
                resolve(cv);
                return;
            }
            if (Date.now() - start > 3000) { // 3s timeout safeguard
                resolve(cv || null);
                return;
            }
            setTimeout(tryGet, 120);
        };
        setTimeout(tryGet, 120);
    });
        }

        function createTextBoxLike(sourceObj, targetCanvas) {
    const marginPx = mmToPx(margin);
    const bleedPx = mmToPx(bleed);
    const newBlock = new fabric.Textbox('', {
        left: Math.round(bleedPx + marginPx) + 0.5,
        top: Math.round(bleedPx + marginPx) + 0.5,
        width: Math.round(sourceObj.width),
        height: Math.round(sourceObj.height),
        fontSize: sourceObj.fontSize,
        fontFamily: sourceObj.fontFamily,
        fontWeight: sourceObj.fontWeight,
        fontStyle: sourceObj.fontStyle,
        fill: sourceObj.fill,
        stroke: sourceObj.stroke,
        strokeWidth: sourceObj.strokeWidth,
        textAlign: sourceObj.textAlign,
        lineHeight: sourceObj.lineHeight,
        charSpacing: sourceObj.charSpacing,
        splitByGrapheme: sourceObj.splitByGrapheme,
        breakWords: sourceObj.breakWords,
        objectCaching: false,
        noScaleCache: true,
        statefullCache: false
    });
    newBlock._maxTextHeight = sourceObj._maxTextHeight || (sourceObj.height * (sourceObj.scaleY || 1));
    newBlock.textLinkId = 'autoflow_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    targetCanvas.add(newBlock);
    ensureCrispText(newBlock);
    return newBlock;
        }

        function linkTextBoxes(sourceObj, targetObj, targetPageIndex) {
    if (!textLinks) textLinks = {};
    textLinks[sourceObj.textLinkId] = {
        targetId: targetObj.textLinkId,
        targetPageIndex
    };
        }

        async function flowTailAcrossPages(tailText, sourceObj, sourceCanvas, pageIndex) {
    if (!tailText || tailText.length === 0) return;
    const nextPageIndex = pageIndex + 1;
    const nextCanvas = await ensureNextPageCanvas(pageIndex);
    if (!nextCanvas) return;
    const newBlock = createTextBoxLike(sourceObj, nextCanvas);
    linkTextBoxes(sourceObj, newBlock, nextPageIndex);
    // Determine how much of tailText fits in this new block
    const idx = getFittingTextIndex(newBlock, tailText);
    let head = tailText.slice(0, idx);
    let rest = tailText.slice(idx);
    // Safety: ensure progress if idx == 0
    if (idx === 0 && tailText.length > 0) {
        head = tailText.slice(0, 1);
        rest = tailText.slice(1);
    }
    newBlock.text = head;
    nextCanvas.requestRenderAll();
    saveAllPages();
    saveState('Texte coulé automatiquement vers page ' + (nextPageIndex + 1));
    // Notify and continue if needed
    const sourcePageIndex = canvases.indexOf(sourceCanvas);
    showAutoFlowNotification(sourcePageIndex + 1, nextPageIndex + 1);
    if (rest && rest.length > 0) {
        // small delay to allow dimension settle, then continue
        await new Promise(r => setTimeout(r, 80));
        checkTextOverflow(nextCanvas);
        await flowTailAcrossPages(rest, newBlock, nextCanvas, nextPageIndex);
    }
        }

        // Nouveau: pagination directe itérative sans dépendre des événements d'overflow
        async function paginateTextFromBox(textObj, canvas, pageIndex) {
    if (!textObj || !canvas) return;
    let full = textObj.text || '';
    if (!full) return;
    // Caler la première page
    // Assurer les dimensions de référence
    if (typeof textObj._maxTextHeight !== 'number') {
        textObj._maxTextHeight = (textObj.height * (textObj.scaleY || 1));
    }
    const idx0 = getFittingTextIndex(textObj, full);
    let head0 = idx0 > 0 ? full.slice(0, idx0) : full.slice(0, 1);
    let rest = idx0 > 0 ? full.slice(idx0) : full.slice(1);
    textObj.text = head0;
    ensureCrispText(textObj);
    canvas.requestRenderAll();
    debouncedUpdateLayersPanel();
    // Sauvegarder la page 1 avant de créer la page suivante pour éviter toute perte au renderAllPages
    try { saveAllPages(); saveState('Texte calé page 1'); } catch(e) { console.warn('saveAllPages after first head failed', e); }
    // Boucle pour les pages suivantes
    let current = textObj;
    let curCanvas = canvas;
    let curPage = pageIndex;
    while (rest && rest.length > 0) {
        const nextCanvas = await ensureNextPageCanvas(curPage);
        if (!nextCanvas) break;
        const newBlock = createTextBoxLike(current, nextCanvas);
        const idx = getFittingTextIndex(newBlock, rest);
        let head = idx > 0 ? rest.slice(0, idx) : rest.slice(0, 1);
        rest = idx > 0 ? rest.slice(idx) : rest.slice(1);
        newBlock.text = head;
        ensureCrispText(newBlock);
        nextCanvas.requestRenderAll();
        debouncedUpdateLayersPanel();
        saveState('Texte coulé vers page ' + (curPage + 2));
        curCanvas = nextCanvas;
        current = newBlock;
        curPage += 1;
        // Petite pause pour laisser les mesures s'établir si nécessaire
        await new Promise(r => setTimeout(r, 40));
    }
        }

        // NOUVELLE FONCTION: Chaînage automatique de texte
        function autoFlowTextToNextPage(textObj, canvas, pageIndex) {
    
    // LOGIQUE SIMPLIFIÉE: Si le bloc déborde, créer une nouvelle page automatiquement
    if (!textObj.hasOverflow) {
        return;
    }
    
    
    // Si le texte déborde, découper précisément ce qui tient ici et pousser le reste
    const { head, tail } = splitTextToFit(textObj);
    if (head === textObj.text && !tail) {
        // Aucun découpage possible (cas limite)
        return;
    }
    textObj.text = head;
    canvas.requestRenderAll();
    
    
    // Re-check soon to keep flow going even if fonts/layout shift slightly
    const continueFlow = () => flowTailAcrossPages(tail.trimStart(), textObj, canvas, pageIndex);
    setTimeout(() => {
        checkTextOverflow(canvas);
        continueFlow();
    }, 50);
        }        // Fonction helper pour créer le bloc lié
        function createLinkedTextBlock(sourceObj, sourceCanvas, targetCanvas, targetPageIndex) {
    const marginPx = mmToPx(margin);
    const bleedPx = mmToPx(bleed);
    
    // Position en haut à gauche (avec marges)
    const newX = bleedPx + marginPx;
    const newY = bleedPx + marginPx;
    
    
    // Créer le nouveau bloc avec les mêmes propriétés
    const newBlock = new fabric.Textbox('', {
        left: newX,
        top: newY,
        width: sourceObj.width,
        height: sourceObj.height,
        fontSize: sourceObj.fontSize,
        fontFamily: sourceObj.fontFamily,
        fontWeight: sourceObj.fontWeight,
        fontStyle: sourceObj.fontStyle,
        fill: sourceObj.fill,
        stroke: sourceObj.stroke,
        strokeWidth: sourceObj.strokeWidth,
        textAlign: sourceObj.textAlign,
        lineHeight: sourceObj.lineHeight,
        charSpacing: sourceObj.charSpacing
    });
    
    // Générer un ID unique pour le nouveau bloc
    newBlock.textLinkId = 'autoflow_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    
    // Ajouter le nouveau bloc au canvas
    targetCanvas.add(newBlock);
    
    // Créer le lien entre les deux blocs
    if (!textLinks) textLinks = {};
    textLinks[sourceObj.textLinkId] = {
        targetId: newBlock.textLinkId,
        targetPageIndex: targetPageIndex
    };
    
    
    // Vers ancien flux (compat): découpe et transfert
    const { tail } = splitTextToFit(sourceObj);
    newBlock.text = tail.trimStart();
    sourceCanvas.requestRenderAll();
    targetCanvas.requestRenderAll();
    
    // Notification visuelle
    const sourcePageIndex = canvases.indexOf(sourceCanvas);
    showAutoFlowNotification(sourcePageIndex + 1, targetPageIndex + 1);
    
    // Sauvegarder
    saveAllPages();
    saveState('Texte coulé automatiquement vers page ' + (targetPageIndex + 1));
    
    // Recheck overflow sur le nouveau bloc (récursif)
    setTimeout(() => {
        checkTextOverflow(targetCanvas);
    }, 100);
        }
        
        function showAutoFlowNotification(fromPage, toPage) {
    const notification = document.createElement('div');
    notification.style.position = 'fixed';
    notification.style.top = '80px';
    notification.style.right = '20px';
    notification.style.background = '#4CAF50';
    notification.style.color = 'white';
    notification.style.padding = '15px 20px';
    notification.style.borderRadius = '5px';
    notification.style.boxShadow = '0 4px 10px rgba(0,0,0,0.3)';
    notification.style.zIndex = '10000';
    notification.style.fontFamily = 'IBM Plex Mono, monospace';
    notification.style.fontSize = '12px';
    notification.textContent = `✅ Texte coulé automatiquement: Page ${fromPage} → Page ${toPage}`;
    document.body.appendChild(notification);
    
    setTimeout(() => {
        notification.style.transition = 'opacity 0.5s';
        notification.style.opacity = '0';
        setTimeout(() => notification.remove(), 500);
    }, 3000);
        }

