        // Appliquer les paramètres de qualité maximale
        freshImg.objectCaching = false;
        freshImg.statefullCache = false;
        freshImg.needsItsOwnCache = () => false;
        freshImg.imageSmoothing = true;
        freshImg.imageSmoothingQuality = 'high';
        
