        let displayWidth = img.width;
        let displayHeight = img.height;
        
        const ratio = Math.min(maxWidth / img.width, maxHeight / img.height, 1);
        displayWidth = Math.floor(img.width * ratio);
        displayHeight = Math.floor(img.height * ratio);
        
