        // createLinkedTextBlocks supprimé

        
        function calculateFittingText(textObj, fullText) {
    // Sauvegarder le texte original
    const originalText = textObj.text;
    
    // Protection : texte trop long, utiliser approximation rapide
    if (fullText.length > 5000) {
        console.warn('⚠️ Texte très long, calcul approximatif');
        // Estimation rapide basée sur la taille moyenne des caractères
        const avgCharHeight = textObj.fontSize * 1.2;
        const availableHeight = textObj.height * (textObj.scaleY || 1);
        const estimatedChars = Math.floor((availableHeight / avgCharHeight) * (textObj.width / (textObj.fontSize * 0.6)));
        return fullText.substring(0, Math.min(estimatedChars, fullText.length));
    }
    
    // Test binaire pour trouver la quantité optimale de texte
    let low = 0;
    let high = fullText.length;
    let bestFit = '';
    let iterations = 0;
    const MAX_ITERATIONS = 30; // Protection contre boucle infinie
    
    while (low <= high && iterations < MAX_ITERATIONS) {
        iterations++;
        const mid = Math.floor((low + high) / 2);
        const testText = fullText.substring(0, mid);
        
        textObj.text = testText;
        textObj._clearCache();
        textObj.initDimensions();
        
        if (!hasTextOverflow(textObj)) {
            bestFit = testText;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    
    // Restaurer le texte original temporairement
    textObj.text = originalText;
    textObj._clearCache();
    textObj.initDimensions();
    
    return bestFit;
        }
        
        function createNextTextBlock(sourceObj, currentCanvas, pageIndex) {
    const blockWidth = sourceObj.width;
    const blockHeight = sourceObj.height;
    
    // Calculer la position pour le nouveau bloc
    let newX = sourceObj.left;
    let newY = sourceObj.top + sourceObj.height * (sourceObj.scaleY || 1) + mmToPx(10); // 10mm d'espacement
    
    // Vérifier si le nouveau bloc sort de la page
    const pageHeight = mmToPx(pageFormat.height);
    const bleedInfo = currentCanvas.bleedInfo || { left: mmToPx(bleed), top: mmToPx(bleed) };
    
    if (newY + blockHeight + bleedInfo.top > pageHeight) {
        // Le bloc ne rentre pas sur cette page
        return { canvas: null, block: null };
    }
    
    // Créer le nouveau bloc de texte
    const newBlock = new fabric.Textbox('', {
        left: newX,
        top: newY,
        width: blockWidth,
        height: blockHeight,
        fontSize: sourceObj.fontSize,
        fontFamily: sourceObj.fontFamily,
        fontWeight: sourceObj.fontWeight,
        fill: sourceObj.fill,
        textAlign: sourceObj.textAlign,
        lineHeight: sourceObj.lineHeight,
        charSpacing: sourceObj.charSpacing,
        stroke: '#0088ff', // Bordure bleue pour blocs liés
        strokeWidth: 0.5,
        strokeDashArray: [5, 3] // Pointillés
    });
    
    // Figer les dimensions du nouveau bloc
    newBlock._fixedWidth = Math.round(blockWidth);
    newBlock._fixedHeight = Math.round(blockHeight);
    
    // Générer un ID de liaison unique
    newBlock.textLinkId = 'autolink_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    
    // Marquer le bloc source aussi avec une bordure
    if (!sourceObj.stroke) {
        sourceObj.stroke = '#0088ff';
        sourceObj.strokeWidth = 0.5;
        sourceObj.strokeDashArray = [5, 3];
    }
    
    currentCanvas.add(newBlock);
    currentCanvas.requestRenderAll();
    
    return { canvas: currentCanvas, block: newBlock };
        }
        
        function linkTextBlocks(sourceId, targetObj) {
    if (!targetObj.textLinkId) {
        targetObj.textLinkId = 'autolink_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    }
    
    // Enregistrer la liaison
    if (!textLinks) textLinks = {};
    textLinks[sourceId] = {
        targetId: targetObj.textLinkId,
        targetPageIndex: currentPageIndex
    };
        }
        
        function unlinkTextBlocks() {
    const activeCanvas = getActiveCanvas();
    if (!activeCanvas) return;
    
    const obj = activeCanvas.getActiveObject();
    if (!obj || obj.type !== 'textbox') {
        showChainToast('Sélectionnez un bloc texte chaîné', 2000);
        return;
    }
    
    if (!obj.textLinkId) {
        showChainToast('Ce bloc n\'est pas chaîné', 2000);
        return;
    }

    // Trouver toute la chaîne
    const first = findFirstBlockInChain(obj);
    if (!first) { showChainToast('Ce bloc n\'est pas chaîné', 2000); return; }
    const chain = buildLinkedChain(first);
    if (chain.length < 2) { showChainToast('Ce bloc n\'est pas chaîné', 2000); return; }

    // 🔗 Collecter tout le texte + styles AVANT de casser les liens
    let fullText = '';
    let fullStyles = [];
    const headBlock = chain[0].obj;
    try {
        for (let i = 0; i < chain.length; i++) {
            const tb = chain[i].obj;
            const partStart = fullText.length;
            fullText += (tb.text || '');
            const styles = _collectCharStyles(tb);
            for (const cs of styles) {
                fullStyles.push({ charIdx: partStart + cs.charIdx, style: cs.style });
            }
        }
    } catch (_) {}

    // Nettoyer tous les liens de la chaîne
    chain.forEach(b => {
        const tb = b.obj;
        // Supprimer le lien sortant
        if (textLinks[tb.textLinkId]) {
            delete textLinks[tb.textLinkId];
        }
        // Retirer les bordures de chaînage
        tb.set({ stroke: null, strokeWidth: 0, strokeDashArray: null });
        // Supprimer le badge
        removeChainBadge(tb);
        // Supprimer la flèche
        if (tb._linkArrow && tb._linkArrow.canvas) {
            try { tb._linkArrow.canvas.remove(tb._linkArrow); } catch(_) {}
        }
        tb._linkArrow = null;
        // Réinitialiser les propriétés de chaîne
        delete tb._linkOrder;
        delete tb._chainTotal;
        delete tb.isLinkedTextBlock;
        delete tb._hasAutoFlowListener;
    });

    // 🔗 Refluer tout le texte dans le 1er bloc et vider les autres
    try {
        // Mettre tout le texte dans le head block
        headBlock.text = fullText;
        _applyMergedStyles(headBlock, fullStyles);
        headBlock._clearCache();
        headBlock.initDimensions();
        if (typeof headBlock._fixedHeight === 'number') headBlock.height = headBlock._fixedHeight;
        if (typeof headBlock._fixedWidth === 'number') headBlock.width = headBlock._fixedWidth;
        applyTextboxClipPath(headBlock);
        headBlock.setCoords();
        if (headBlock.canvas) {
            updateOverflowIndicator(headBlock, headBlock.canvas);
            headBlock.canvas.requestRenderAll();
        }

        // Vider les blocs suivants
        for (let i = 1; i < chain.length; i++) {
            const tb = chain[i].obj;
            tb.text = '';
            tb.styles = {};
            tb._clearCache();
            tb.initDimensions();
            if (typeof tb._fixedHeight === 'number') tb.height = tb._fixedHeight;
            if (typeof tb._fixedWidth === 'number') tb.width = tb._fixedWidth;
            applyTextboxClipPath(tb);
            tb.setCoords();
            if (tb.canvas) {
                updateOverflowIndicator(tb, tb.canvas);
                tb.canvas.requestRenderAll();
            }
        }
    } catch (err) {
        console.warn('[unlinkTextBlocks] reflow error:', err);
    }

    // Nettoyer aussi les flèches/badges orphelins sur tous les canvas
    canvases.forEach(c => {
        const toRemove = c.getObjects().filter(o => o._isLinkArrow || o._isChainBadge);
        toRemove.forEach(o => { try { c.remove(o); } catch(_) {} });
    });
    
    activeCanvas.requestRenderAll();
    debouncedUpdateLayersPanel();
    saveState('Chaînage texte supprimé — texte replacé dans le 1er bloc');
        }
        
        function findAllLinkedBlocks(linkId) {
    const linkedBlocks = [];
    const baseId = linkId.split('_')[0] + '_' + linkId.split('_')[1];
    
    canvases.forEach((canvas, pageIndex) => {
        canvas.getObjects().forEach(obj => {
            if (obj.textLinkId && obj.textLinkId.startsWith(baseId)) {
                linkedBlocks.push({
                    blockId: obj.textLinkId,
                    pageIndex: pageIndex,
                    obj: obj
                });
            }
        });
    });
    
    return linkedBlocks;
        }
        
        function gatherAllLinkedText(linkId) {
    const linkedBlocks = findAllLinkedBlocks(linkId);
    return linkedBlocks
        .sort((a, b) => a.blockId.localeCompare(b.blockId))
        .map(block => block.obj.text)
        .join(' ');
        }
        
