                setTimeout(() => _spForceSelectAllWhenReady(activeObj, 15), 0);
                setTimeout(() => _spForceSelectAllWhenReady(activeObj, 15), 30);
                setTimeout(() => _spForceSelectAllWhenReady(activeObj, 15), 80);
                setTimeout(() => _spForceSelectAllWhenReady(activeObj, 15), 150);
