        // ¡ BUG02 FIX 2026-05-01 : Avant un changement de format, repositionner les
        // objets pour qu'ils restent visibles dans la nouvelle page. Sans ce clamp,
        // un objet place vers le bord droit/bas d'un A4 disparait visuellement quand
        // on passe en A5 (il est toujours dans le JSON, mais clippe par le canvas).
        // 🛡️ FIX 2026-06-02 (copier-coller hors page) : recadre un groupe d'objets
        //   fraîchement collés pour qu'ils restent dans la zone page+bleed de leur
        //   canvas de destination. On applique un MÊME décalage (dx,dy) à tous les
        //   objets pour préserver leur disposition relative (collage multi-objets).
        //   Corrige le bug "parfois les éléments sortent du canvas" quand on colle
        //   d'une page vers une autre (page plus petite ou position source décalée).
        function _spClampPastedObjectsToPage(objs, canvas) {
            if (!Array.isArray(objs) || !objs.length || !canvas) return;
            const pageWpx = mmToPx(pageFormat.width);
            const pageHpx = mmToPx(pageFormat.height);
            if (!isFinite(pageWpx) || !isFinite(pageHpx) || pageWpx <= 0 || pageHpx <= 0) return;
            const bleedPx = mmToPx(typeof bleed === 'number' ? bleed : 0);
            const info = canvas.bleedInfo || { left: 0, top: 0 };
            const baseLeft = info.left || 0;
            const baseTop = info.top || 0;
            // Bornes de la zone autorisée (page + fond perdu), en coords monde.
            const minX = baseLeft - bleedPx;
            let maxX = baseLeft + pageWpx + bleedPx;
            if (info.isSpread) {
                // En spread, autoriser toute la largeur des deux pages.
                maxX = baseLeft + pageWpx * 2 + bleedPx;
            }
            const minY = baseTop - bleedPx;
            const maxY = baseTop + pageHpx + bleedPx;
            // Bounding-box courante du groupe collé (coords absolues).
            let bx0 = Infinity, by0 = Infinity, bx1 = -Infinity, by1 = -Infinity;
            objs.forEach(o => {
                if (!o || typeof o.getBoundingRect !== 'function') return;
                const r = o.getBoundingRect(true, true);
                bx0 = Math.min(bx0, r.left);
                by0 = Math.min(by0, r.top);
                bx1 = Math.max(bx1, r.left + r.width);
                by1 = Math.max(by1, r.top + r.height);
            });
            if (!isFinite(bx0)) return;
            let dx = 0, dy = 0;
            // Ramener d'abord le bord qui dépasse le plus loin (droite/bas), puis
            // garantir que le bord opposé (gauche/haut) ne sort pas non plus.
            if (bx1 > maxX) dx = maxX - bx1;
            if (bx0 + dx < minX) dx = minX - bx0;
            if (by1 > maxY) dy = maxY - by1;
            if (by0 + dy < minY) dy = minY - by0;
            if (dx === 0 && dy === 0) return;
            objs.forEach(o => {
                if (!o) return;
                o.set({ left: (o.left || 0) + dx, top: (o.top || 0) + dy });
                if (typeof o.setCoords === 'function') o.setCoords();
            });
        }

        function clampObjectsToCurrentFormat() {
    if (!Array.isArray(canvases) || canvases.length === 0) return 0;
    const newPageWpx = mmToPx(pageFormat.width);
    const newPageHpx = mmToPx(pageFormat.height);
    if (!isFinite(newPageWpx) || !isFinite(newPageHpx) || newPageWpx <= 0 || newPageHpx <= 0) return 0;
    let moved = 0;
    canvases.forEach(canvas => {
        if (!canvas || typeof canvas.getObjects !== 'function') return;
        const info = canvas.bleedInfo || { left: 0, top: 0 };
        const isSpread = !!info.isSpread;
        const baseLeft = info.left || 0;
        const baseTop = info.top || 0;
        const centerX = isSpread ? (typeof info.centerX === 'number' ? info.centerX : (baseLeft + newPageWpx)) : null;
        canvas.getObjects().forEach(obj => {
            if (!obj) return;
            if (obj.isMargin || obj.isBleed || obj.isGuide || obj.isManualGuide || obj.isTrimBox || obj.isPage || obj._isSpreadMirror || obj._isMasterRuntime || obj._isMasterGuide || obj._isChainBadge || obj._isLinkArrow || obj._isOverflowIndicator || obj._isPageNumber || obj.excludeFromExport) return;
            const w = (obj.width || 0) * (obj.scaleX || 1);
            const h = (obj.height || 0) * (obj.scaleY || 1);
            const isCentered = (obj.type === 'circle' || obj.type === 'ellipse' || obj.type === 'polygon' || obj.type === 'path');
            // Determiner la page d'appartenance (gauche/droite en spread, sinon page unique)
            let minLeft, maxLeft;
            if (isSpread) {
                const objCenter = isCentered ? obj.left : obj.left + w / 2;
                if (objCenter < centerX) {
                    minLeft = baseLeft;
                    maxLeft = centerX - (isCentered ? w / 2 : w);
                } else {
                    minLeft = centerX + (isCentered ? w / 2 : 0);
                    maxLeft = centerX + newPageWpx - (isCentered ? w / 2 : w);
                }
            } else {
                minLeft = baseLeft + (isCentered ? w / 2 : 0);
                maxLeft = baseLeft + newPageWpx - (isCentered ? w / 2 : w);
            }
            const minTop = baseTop + (isCentered ? h / 2 : 0);
            const maxTop = baseTop + newPageHpx - (isCentered ? h / 2 : h);
            let newLeft = obj.left;
            let newTop = obj.top;
            if (typeof newLeft === 'number') {
                if (maxLeft >= minLeft) newLeft = Math.max(minLeft, Math.min(maxLeft, newLeft));
                else newLeft = minLeft;
            }
            if (typeof newTop === 'number') {
                if (maxTop >= minTop) newTop = Math.max(minTop, Math.min(maxTop, newTop));
                else newTop = minTop;
            }
            if (newLeft !== obj.left || newTop !== obj.top) {
                obj.set({ left: newLeft, top: newTop });
                if (typeof obj.setCoords === 'function') obj.setCoords();
                moved++;
            }
        });
    });
    if (moved > 0) {
        try { canvases.forEach(c => c && c.requestRenderAll && c.requestRenderAll()); } catch (_) {}
    }
    return moved;
        }

        // 🛡️ FIX 2026-05-01 v2 (Bug 02 retour test) : clamper DIRECTEMENT dans pages[]
        // car renderAllPages() reconstruit les canvases depuis pages[] - si saveAllPages()
        // est silencieusement bypass par ses guards (_isRenderingAllPages, _isRestoringState,
        // canvas en chargement), la version clampee sur les canvases live est PERDUE et
        // les anciennes positions hors-bornes sont restaurees -> objets disparaissent.
        function clampPagesDataToCurrentFormat() {
            if (!Array.isArray(pages)) return 0;
            const newPageWpx = mmToPx(pageFormat.width);
            const newPageHpx = mmToPx(pageFormat.height);
            if (!isFinite(newPageWpx) || !isFinite(newPageHpx) || newPageWpx <= 0 || newPageHpx <= 0) return 0;
            // Marge securitaire : 20% de la page pour autoriser un debord acceptable
            // (un objet partiellement hors page reste cliquable et editable)
            const safetyW = newPageWpx * 0.2;
            const safetyH = newPageHpx * 0.2;
            let moved = 0;
            pages.forEach(page => {
                if (!page) return;
                const objs = (page.objects && Array.isArray(page.objects)) ? page.objects
                            : (Array.isArray(page) ? page : null);
                if (!Array.isArray(objs)) return;
                objs.forEach(data => {
                    if (!data || typeof data !== 'object') return;
                    if (data.isMargin || data.isBleed || data.isGuide || data.isManualGuide || data.isTrimBox || data.isPage || data._isSpreadMirror || data._isMasterRuntime || data._isMasterGuide || data._isChainBadge || data._isLinkArrow || data._isOverflowIndicator || data._isPageNumber || data.excludeFromExport) return;
                    const w = (data.width || 0) * (data.scaleX || 1);
                    const h = (data.height || 0) * (data.scaleY || 1);
                    const isCentered = (data.originX === 'center')
                        || (data.type === 'circle' || data.type === 'ellipse' || data.type === 'polygon' || data.type === 'path');
                    const halfW = isCentered ? w / 2 : 0;
                    const halfH = isCentered ? h / 2 : 0;
                    // Borne large : page entiere + bleed (~bleedPx) + tolerance safetyW/H
                    // pour ne PAS deplacer des objets qui sont juste sur le bord du fond perdu.
                    const bleedPx = mmToPx(typeof bleed === 'number' ? bleed : 3);
                    const minLeft = -safetyW + halfW;
                    const maxLeft = newPageWpx + bleedPx + safetyW - (isCentered ? halfW : w);
                    const minTop = -safetyH + halfH;
                    const maxTop = newPageHpx + bleedPx + safetyH - (isCentered ? halfH : h);
                    let nl = (typeof data.left === 'number') ? data.left : null;
                    let nt = (typeof data.top === 'number') ? data.top : null;
                    if (nl != null) {
                        if (maxLeft >= minLeft) nl = Math.max(minLeft, Math.min(maxLeft, nl));
                        else nl = minLeft;
                    }
                    if (nt != null) {
                        if (maxTop >= minTop) nt = Math.max(minTop, Math.min(maxTop, nt));
                        else nt = minTop;
                    }
                    if (nl !== data.left || nt !== data.top) {
                        if (nl !== null) data.left = nl;
                        if (nt !== null) data.top = nt;
                        moved++;
                    }
                });
            });
            return moved;
        }

        // Aide: forcer le rafraîchissement des métriques de police
        // SYSTÈME PERFORMANCE ULTIME POUR TYPOGRAPHIE
        let fontRefreshTimeout = null;
        let isRefreshing = false;
