        function forceFontRefresh(obj, canvas) {
    if (!obj || !canvas || isRefreshing) return;
    
    if (fontRefreshTimeout) {
        clearTimeout(fontRefreshTimeout);
    }
    
    fontRefreshTimeout = setTimeout(() => {
        isRefreshing = true;
        
        obj.dirty = true;
        if (typeof obj._clearCache === 'function') obj._clearCache();
        if (obj.type === 'textbox' || obj.type === 'text') {
            // ✨ CORRECTIF STABILITÉ: Purger l'état runtime de césure AVANT initDimensions
            // pour que _wrapLine redémarre avec un compteur à zéro (évite les indices décalés
            // dans __spHyphenFlags qui causaient des sauts de texte après changement de taille).
            obj.__spHyphenFlags = [];
            obj.__spWrapLineCounter = 0;
            obj.__spMissingOffsets = [];
            obj.__spMissingOffsetCounter = 0;
            obj._styleMap = null;
            obj._textLines = null;
            obj.__lineWidths = null;
            obj.__lineHeights = null;
            if (typeof obj.initDimensions === 'function') obj.initDimensions();
            // Restaurer dimensions fixes après initDimensions
            if (obj._fixedWidth !== undefined) { obj.width = obj._fixedWidth; }
            if (obj._fixedHeight !== undefined) { obj.height = obj._fixedHeight; }
            if (typeof obj.setCoords === 'function') obj.setCoords();
            applyTextboxClipPath(obj);
            updateOverflowIndicator(obj, canvas);

            if (obj.isEditing) {
                try {
                    if (typeof obj._updateTextarea === 'function') obj._updateTextarea();
                    if (typeof obj._updateTextareaPosition === 'function') obj._updateTextareaPosition();
                    if (obj.hiddenTextarea && obj.hiddenTextarea.style) {
                        const fontSize = (obj.fontSize || 14);
                        const lineHeight = (obj.lineHeight || 1.16);
                        const charSpacing = Number(obj.charSpacing || 0);
                        const letterSpacingPx = (isFinite(charSpacing) ? (charSpacing / 1000) * fontSize : 0);
                        obj.hiddenTextarea.style.fontSize = fontSize + 'px';
                        obj.hiddenTextarea.style.lineHeight = String(Math.round(fontSize * lineHeight)) + 'px';
                        obj.hiddenTextarea.style.fontFamily = (obj.fontFamily || 'sans-serif');
                        obj.hiddenTextarea.style.fontWeight = (obj.fontWeight || 'normal');
                        obj.hiddenTextarea.style.fontStyle = (obj.fontStyle || 'normal');
                        obj.hiddenTextarea.style.letterSpacing = (isFinite(letterSpacingPx) ? (letterSpacingPx + 'px') : '0px');
                    }
                } catch (_) {}
            }
        }
        scheduleRender(canvas);
        
        isRefreshing = false;
    }, performanceMode ? 8 : 16);
        }

        // Nettoyer uniquement les tailles inline pour éviter les mélanges (conserve gras/italique/etc.)
