        // Nettoyer les soft hyphens (U+00AD) pour permettre un reflow propre
        function stripSoftHyphens(textObj, selection) {
    try {
        if (!textObj || typeof textObj.text !== 'string') return selection || null;
        if (textObj.text.indexOf('\u00AD') === -1) return selection || null;
        const oldText = textObj.text;
        const re = /\u00AD/g;
        const newText = oldText.replace(re, '');
        if (newText === oldText) return selection || null;

        let newStart = selection && typeof selection.start === 'number' ? selection.start : null;
        let newEnd = selection && typeof selection.end === 'number' ? selection.end : null;
        if (newStart != null && newEnd != null) {
            const beforeStart = oldText.slice(0, newStart);
            const beforeEnd = oldText.slice(0, newEnd);
            const removedBeforeStart = (beforeStart.match(re) || []).length;
            const removedBeforeEnd = (beforeEnd.match(re) || []).length;
            newStart = Math.max(0, newStart - removedBeforeStart);
            newEnd = Math.max(newStart, newEnd - removedBeforeEnd);
        }

        textObj.text = newText;
        return { start: newStart, end: newEnd, changed: true };
    } catch (_) {
        return selection || null;
    }
        }

        // Nettoyer soft hyphens + invalider les caches de layout
