    // ===== 🚀 v1.7.323 (perf 2026-09-03) : chargement à la demande des vendors export/import =====
    // Avant : jspdf/svg2pdf/opentype/wawoff2/fontkit/pdf-lib/jszip/pdf.min/paper-full
    // étaient des <script> BLOQUANTS dans index.html (~2,95 Mo de JS synchrone au
    // démarrage, sur TOUTES les machines, même quand aucune de ces features n'est
    // utilisée). Pénalisant surtout sur les machines lentes (ex. vieux Mac Intel).
    // jspdf/svg2pdf/opentype/wawoff2/fontkit/pdf-lib/jszip/pdf.min/paper-full ne sont
    // plus des <script> bloquants dans index.html (~2,95 Mo). Ils sont injectés ici,
    // une seule fois (promesse mise en cache), juste avant le code qui en a besoin.
    function spEnsureLibs(specs, callback) {
        const needed = specs.filter(s => !s.check());
        if (needed.length === 0) { callback(); return; }
        let loaded = 0;
        needed.forEach(spec => {
            if (spec.inline) { try { spec.inline(); } catch(e) { console.error('[SP] init vendor', spec.src, e); } }
            const s = document.createElement('script');
            s.src = spec.src;
            // 🛡️ async=false : préserve l'ordre d'exécution (ex. svg2pdf DOIT s'exécuter
            //   après jspdf, même si son fichier finit de télécharger avant), comme les
            //   <script> classiques parser-insérés qu'ils remplacent.
            s.async = false;
            s.onload = () => { loaded++; if (loaded === needed.length) callback(); };
            s.onerror = () => {
                // 100% local — aucun fallback CDN. Si le fichier est manquant on log et on continue.
                console.error('[SP] Impossible de charger le vendor local :', spec.src, '— verifier que le fichier existe dans JS/.');
                loaded++; if (loaded === needed.length) callback();
            };
            document.head.appendChild(s);
        });
    }

    // wawoff2.js exige que window.Module.onRuntimeInitialized soit posé AVANT son
    // exécution (le wasm Emscripten s'auto-lance dès le chargement du script).
    function _spInitWawoff2Module() {
        if (window.SP_Wawoff2Module) return; // déjà initialisé (ou en cours)
        window.SP_Wawoff2Module = { _ready: null };
        window.Module = window.Module || {};
        let resolveReady = null;
        window.SP_Wawoff2Module._ready = new Promise((res) => { resolveReady = res; });
        window.Module.onRuntimeInitialized = function () {
            window.SP_Wawoff2Module.instance = window.Module;
            if (resolveReady) resolveReady(window.Module);
        };
        window.wawoff2_decompress = function (buffer) {
            return window.SP_Wawoff2Module._ready.then((M) => {
                if (!M || typeof M.decompress !== 'function') {
                    throw new Error('wawoff2: decompress() not available');
                }
                const u8 = (buffer instanceof Uint8Array) ? buffer : new Uint8Array(buffer);
                const out = M.decompress(u8);
                return out instanceof Uint8Array ? out : new Uint8Array(out);
            });
        };
        // Timeout de sécurité : si wawoff2 n'est pas prêt en 8 sec, le texte restera raster.
        setTimeout(() => {
            if (!window.SP_Wawoff2Module.instance) {
                console.warn('[SuperPrint] wawoff2 init timeout (8s) → texte restera raster');
                if (resolveReady) resolveReady(null);
            }
        }, 8000);
    }

    // Bundle export PDF/imposition (jspdf, svg2pdf, opentype, wawoff2, fontkit, pdf-lib, jszip).
    let _spExportLibsPromise = null;
    function ensureExportLibs() {
        if (_spExportLibsPromise) return _spExportLibsPromise;
        _spExportLibsPromise = new Promise((resolve) => {
            spEnsureLibs([
                { check: () => !!window.jspdf, src: 'JS/jspdf.umd.min.js' },
                { check: () => !!window.svg2pdf, src: 'JS/svg2pdf.umd.min.js' },
                { check: () => !!window.opentype, src: 'JS/opentype.min.js' },
                { check: () => !!(window.Module && window.Module.run), src: 'JS/wawoff2.js', inline: _spInitWawoff2Module },
                { check: () => !!window.fontkit, src: 'JS/fontkit.min.js' },
                { check: () => !!window.PDFLib, src: 'JS/pdf-lib.min.js' },
                { check: () => !!window.JSZip, src: 'JS/jszip.min.js' },
            ], resolve);
        });
        return _spExportLibsPromise;
    }

    // JSZip seul (export D4/image multi-pages) — sous-ensemble léger d'ensureExportLibs.
    let _spZipLibPromise = null;
    function ensureZipLib() {
        if (_spZipLibPromise) return _spZipLibPromise;
        _spZipLibPromise = new Promise((resolve) => {
            spEnsureLibs([{ check: () => !!window.JSZip, src: 'JS/jszip.min.js' }], resolve);
        });
        return _spZipLibPromise;
    }

    // PDF.js (import PDF) + reconfiguration du worker local à chaque (re)chargement.
    let _spPdfImportLibPromise = null;
    function ensurePdfImportLib() {
        if (_spPdfImportLibPromise) return _spPdfImportLibPromise;
        _spPdfImportLibPromise = new Promise((resolve) => {
            spEnsureLibs([{ check: () => typeof pdfjsLib !== 'undefined', src: 'JS/pdf.min.js' }], () => {
                try {
                    if (window.pdfjsLib && window.pdfjsLib.GlobalWorkerOptions) {
                        window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'JS/pdf.worker.min.js';
                    }
                } catch(_) {}
                resolve();
            });
        });
        return _spPdfImportLibPromise;
    }
    // 🛡️ Exposées sur window : main.js est un monolithe multi-closures — confirmExport/
    //   exportImposedPDF/confirmD4Export/showPDFImportModal/exportPagesAsImages vivent
    //   dans d'autres portées que ce bloc et ne verraient pas ces fonctions autrement.
    window.ensureExportLibs = ensureExportLibs;
    window.ensureZipLib = ensureZipLib;
    window.ensurePdfImportLib = ensurePdfImportLib;

    // ===== DOCX IMPORT =====
    // Charge mammoth.js et JSZip si absent (pour conversion basique DOCX -> HTML -> texte structuré)
    function ensureDocxLibs(callback) {
        const needed = [];
        if (!window.mammoth) needed.push('JS/mammoth.min.js');
        if (!window.JSZip) needed.push('JS/jszip.min.js');
        if (needed.length === 0) { callback(); return; }
        let loaded = 0;
        needed.forEach(src => {
            const s = document.createElement('script');
            s.src = src;
            s.onload = () => { loaded++; if (loaded === needed.length) callback(); };
            s.onerror = () => {
                // 100% local — aucun fallback CDN. Si le fichier est manquant on log et on continue.
                console.error('[SP] Impossible de charger le vendor local :', src, '— verifier que le fichier existe dans JS/.');
                loaded++; if (loaded === needed.length) callback();
            };
            document.head.appendChild(s);
        });
    }

    // ── Dialog réutilisable : choisir la page d'insertion ──
    function askInsertAtPage() {
        return new Promise((resolve) => {
            const totalPages = pages.length || 1;
            const currentP = (typeof currentPageIndex === 'number' ? currentPageIndex : 0) + 1;
            const overlay = document.createElement('div');
            overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:100010;display:flex;align-items:center;justify-content:center;';
            const card = document.createElement('div');
            card.style.cssText = 'background:#fff;border-radius:12px;padding:28px 32px;min-width:340px;max-width:90vw;box-shadow:0 8px 32px rgba(0,0,0,0.3);font-family:system-ui,sans-serif;';
            card.innerHTML = '<div style="font-size:18px;font-weight:700;margin-bottom:16px;">' + translate('docxInsertPageTitle') + '</div>'
                + '<div style="font-size:13px;color:#555;margin-bottom:14px;">' + translate('docxInsertPageQuestion') + '</div>'
                + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:18px;">'
                + '<label style="font-size:13px;font-weight:600;">' + translate('docxInsertPageLabel') + '</label>'
                + '<input type="number" id="_askInsertPageNum" min="1" max="' + (totalPages + 1) + '" value="' + currentP + '" style="width:70px;padding:6px 10px;border:1px solid #ccc;border-radius:6px;font-size:14px;text-align:center;">'
                + '<span style="font-size:12px;color:#888;">/ ' + totalPages + ' (max ' + (totalPages + 1) + ')</span>'
                + '</div>'
                + '<div style="font-size:11px;color:#666;margin-bottom:18px;background:#f0f7ff;padding:8px 12px;border-radius:6px;">' + translatef('docxInsertPageHint', totalPages + 1) + '</div>'
                + '<div style="display:flex;gap:10px;">'
                + '<button id="_askInsertCancel" style="flex:1;padding:10px;border:1px solid #ddd;background:#f5f5f5;border-radius:8px;cursor:pointer;font-size:13px;">' + translate('cancel') + '</button>'
                + '<button id="_askInsertOk" style="flex:2;padding:10px;border:none;background:#4361ee;color:#fff;border-radius:8px;cursor:pointer;font-size:13px;font-weight:600;">' + translate('docxInsertOkBtn') + '</button>'
                + '</div>';
            overlay.appendChild(card);
            document.body.appendChild(overlay);
            const inp = document.getElementById('_askInsertPageNum');
            inp.focus();
            inp.select();
            function cleanup() { document.body.removeChild(overlay); }
            document.getElementById('_askInsertOk').addEventListener('click', () => {
                const v = Math.max(1, Math.min(totalPages + 1, parseInt(inp.value) || 1));
                cleanup();
                resolve(v - 1); // 0-based
            });
            document.getElementById('_askInsertCancel').addEventListener('click', () => {
                cleanup();
                resolve(null); // null = annulé
            });
            overlay.addEventListener('click', (ev) => { if (ev.target === overlay) { cleanup(); resolve(null); } });
            inp.addEventListener('keydown', (ev) => {
                if (ev.key === 'Enter') { document.getElementById('_askInsertOk').click(); }
                if (ev.key === 'Escape') { document.getElementById('_askInsertCancel').click(); }
            });
        });
    }

    async function flowHtmlIntoPages(html, startPageIndex) {
        // Parse HTML (avec images, listes, titres, tableaux basiques)
        const tmp = document.createElement('div');
        tmp.innerHTML = html;

        // Collecte en ORDRE des blocs pertinents
        const blocks = [];
        const walker = document.createTreeWalker(tmp, NodeFilter.SHOW_ELEMENT, null);
        while (walker.nextNode()) {
            const el = walker.currentNode;
            const tag = el.tagName ? el.tagName.toLowerCase() : '';
            if (tag === 'h1' || tag === 'h2' || tag === 'h3' || tag === 'p') {
                const text = el.textContent.trim().replace(/\s+/g, ' ');
                if (text) blocks.push({ kind: 'text', tag, text, isBold: !!el.querySelector('b,strong'), isItalic: !!el.querySelector('i,em') });
            } else if (tag === 'ul' || tag === 'ol') {
                const items = Array.from(el.querySelectorAll(':scope > li'));
                items.forEach((li, idx) => {
                    const text = li.textContent.trim().replace(/\s+/g, ' ');
                    if (!text) return;
                    const bullet = (tag === 'ol') ? (String(idx + 1) + '. ') : '• ';
                    blocks.push({ kind: 'list-item', text: bullet + text, isBold: !!li.querySelector('b,strong'), isItalic: !!li.querySelector('i,em') });
                });
            } else if (tag === 'img') {
                const src = el.getAttribute('src');
                if (src) blocks.push({ kind: 'image', src });
            } else if (tag === 'table') {
                const rows = Array.from(el.querySelectorAll('tr')).map(tr =>
                    Array.from(tr.querySelectorAll('th,td')).map(td => td.textContent.trim()).join(' | ')
                );
                const text = rows.join('\n');
                if (text) blocks.push({ kind: 'table', text });
            }
        }
        if (blocks.length === 0) { alert(translate('alertNoContentDetected')); return; }
        logAI && logAI('\uD83D\uDCE6 Import: ' + blocks.length + ' blocs');

        // ── Dimensions de page (reference single-page, sans bleed offset) ──
        // On calcule la zone de travail sur la base du format physique du document
        const bleedPx = mmToPx(bleed);
        const refPageW = mmToPx(pageFormat.width);
        const refPageH = mmToPx(pageFormat.height);
        const safe = {
            left: bleedPx + 40,
            top: bleedPx + 40,
            right: bleedPx + refPageW - 40,
            bottom: bleedPx + refPageH - 40
        };
        const safeW = Math.max(60, safe.right - safe.left);
        const safeH = Math.max(60, safe.bottom - safe.top);
        const gap = 20;
        const autoColumns = blocks.filter(b => b.kind === 'text' || b.kind === 'list-item').length > 40 ? 2 : 1;
        const columns = autoColumns;
        const colWidth = Math.floor((safeW - (columns > 1 ? gap : 0)) / columns);
        let colIndex = 0;
        let cursorY = safe.top;
        let pageIdx = (typeof startPageIndex === 'number') ? startPageIndex : currentPageIndex;

        // S'assurer que la page de départ existe
        while (pages.length <= pageIdx) { createNewPage(); }
        currentPageIndex = pageIdx;

        // ── Stockage direct dans pages[] (pas de canvas intermédiaire) ──
        // On accumule les objets sérialisés par page, puis on écrit dans pages[] à la fin
        const pageObjects = {}; // { pageIndex: [ serializedObj, ... ] }
        function getPageObjs() {
            if (!pageObjects[pageIdx]) pageObjects[pageIdx] = [];
            return pageObjects[pageIdx];
        }

        function gotoNextColumn() {
            if (columns <= 1) return false;
            colIndex++;
            if (colIndex >= columns) { colIndex = 0; return false; }
            cursorY = safe.top; return true;
        }
        function newPage() {
            if (pageIdx >= pages.length - 1) {
                createNewPage();
            }
            pageIdx++; currentPageIndex = pageIdx;
            cursorY = safe.top; colIndex = 0;
        }
        function currentX() { return safe.left + colIndex * (colWidth + gap); }

        // ── Sérialiser un objet Fabric en JSON pour stockage dans pages[] ──
        function serializeAndStore(fabricObj) {
            const data = fabricObj.toObject([
                'selectable', 'evented', 'hasControls', 'lockMovementX', 'lockMovementY',
                'splitByGrapheme', 'breakWords'
            ]);
            getPageObjs().push(data);
        }

        function measureTextHeight(text, fontSize, isBold, width) {
            const tb = new fabric.Textbox(text, {
                left: 0, top: 0, width: width, fontSize,
                fontFamily: 'IBM Plex Sans', fontWeight: isBold ? 'bold' : 'normal',
                splitByGrapheme: false, breakWords: true
            });
            return tb.height || Math.ceil(fontSize * 1.35);
        }
        function softHyphenateWord(word) {
            if (!word || word.length < 10) return word;
            const vowels = 'aeiouyàâäéèêëïîôùûüæœAEIOUY';
            const consonants = 'bcdfghjklmnpqrstvwxzçBCDFGHJKLMNPQRSTVWXZÇ';
            const pieces = [];
            let start = 0;
            for (let i = 1; i < word.length - 2; i++) {
                const a = word[i - 1], b = word[i];
                if (vowels.includes(a) && consonants.includes(b)) {
                    if (i - start >= 3) { pieces.push(word.slice(start, i)); start = i; }
                }
            }
            if (start < word.length) pieces.push(word.slice(start));
            return pieces.join('\u00AD');
        }
        function applySoftHyphenation(text) {
            return String(text).replace(/([A-Za-zÀ-ÖØ-öø-ÿ]{10,})/g, (m) => softHyphenateWord(m));
        }
        function splitTextToFit(text, fontSize, isBold, width, remainingH) {
            const words = text.split(' ');
            let lo = 1, hi = words.length, fit = 0;
            while (lo <= hi) {
                const mid = Math.floor((lo + hi) / 2);
                const part = applySoftHyphenation(words.slice(0, mid).join(' '));
                const h = measureTextHeight(part, fontSize, isBold, width);
                if (h <= remainingH) { fit = mid; lo = mid + 1; } else { hi = mid - 1; }
            }
            const first = applySoftHyphenation(words.slice(0, Math.max(1, fit)).join(' '));
            const rest = words.slice(Math.max(1, fit)).join(' ');
            return { first, rest };
        }

        for (const block of blocks) {
            if (block.kind === 'image') {
                // Image: charger pour connaître les dimensions, puis sérialiser
                await new Promise((resolve) => {
                    fabric.Image.fromURL(block.src, (img) => {
                        try {
                            const maxW = colWidth;
                            const scale = Math.min(1, maxW / img.width);
                            const h = img.height * scale;
                            const remaining = safe.bottom - cursorY;
                            if (h > remaining) {
                                if (!gotoNextColumn()) { newPage(); }
                            }
                            img.set({ left: currentX(), top: cursorY, scaleX: scale, scaleY: scale, selectable: true });
                            serializeAndStore(img);
                            cursorY += h + 10;
                            resolve();
                        } catch (e) { console.error('IMG place error', e); resolve(); }
                    }, { crossOrigin: 'anonymous' });
                });
                continue;
            }
            let fontSize = 14, isBold = false, isItalic = false, textAlign = 'left';
            if (block.kind === 'text') {
                if (block.tag === 'h1') { fontSize = 42; isBold = true; }
                else if (block.tag === 'h2') { fontSize = 32; isBold = true; }
                else if (block.tag === 'h3') { fontSize = 24; isBold = true; }
                else { fontSize = 14; isBold = !!block.isBold; isItalic = !!block.isItalic; textAlign = 'justify'; }
            } else if (block.kind === 'list-item') {
                fontSize = 14; isItalic = !!block.isItalic; textAlign = 'left';
            } else if (block.kind === 'table') {
                fontSize = 12; textAlign = 'left';
            }
            const fontStyleVal = isItalic ? 'italic' : '';
            let remaining = safe.bottom - cursorY;
            let text = block.text || '';
            // Scinder si nécessaire pour tenir dans la colonne
            if (text) {
                const h = measureTextHeight(applySoftHyphenation(text), fontSize, isBold, colWidth);
                if (h > remaining) {
                    const parts = splitTextToFit(text, fontSize, isBold, colWidth, remaining);
                    // première partie
                    const tb1 = new fabric.Textbox(parts.first, {
                        left: currentX(), top: cursorY, width: colWidth,
                        fontSize, fontFamily: 'IBM Plex Sans', fontWeight: isBold ? 'bold' : 'normal',
                        fontStyle: fontStyleVal,
                        fill: '#000', splitByGrapheme: false, breakWords: true, textAlign
                    });
                    serializeAndStore(tb1);
                    cursorY += tb1.height + (isBold ? Math.round(fontSize * 0.5) : 10);
                    // reste sur nouvelles colonnes/pages
                    let rest = parts.rest;
                    while (rest && rest.length > 0) {
                        if (!gotoNextColumn()) { newPage(); }
                        remaining = safe.bottom - cursorY;
                        const more = splitTextToFit(rest, fontSize, isBold, colWidth, remaining);
                        const tb = new fabric.Textbox(more.first, {
                            left: currentX(), top: cursorY, width: colWidth,
                            fontSize, fontFamily: 'IBM Plex Sans', fontWeight: isBold ? 'bold' : 'normal',
                            fontStyle: fontStyleVal,
                            fill: '#000', splitByGrapheme: false, breakWords: true, textAlign
                        });
                        serializeAndStore(tb);
                        cursorY += tb.height + 10;
                        rest = more.rest;
                    }
                    continue;
                }
            }
            // Si ça tient tel quel
            if (cursorY + (text ? measureTextHeight(text, fontSize, isBold, colWidth) : 0) > safe.bottom) {
                if (!gotoNextColumn()) { newPage(); }
            }
            if (text) {
                const tb = new fabric.Textbox(applySoftHyphenation(text), {
                    left: currentX(), top: cursorY, width: colWidth,
                    fontSize, fontFamily: 'IBM Plex Sans', fontWeight: isBold ? 'bold' : 'normal',
                    fontStyle: fontStyleVal,
                    fill: '#000', splitByGrapheme: false, breakWords: true, textAlign
                });
                serializeAndStore(tb);
                cursorY += tb.height + (isBold ? Math.round(fontSize * 0.5) : 10);
            }
        }

        // ── Écrire directement dans pages[] (bypass saveAllPages qui ne marche pas en spread) ──
        for (const [pidx, objArr] of Object.entries(pageObjects)) {
            const pi = parseInt(pidx);
            if (!pages[pi]) continue;
            // Fusionner avec les objets existants de la page (si on import sur une page déjà remplie)
            let existingObjs = [];
            if (pages[pi].objects) {
                try {
                    const parsed = typeof pages[pi].objects === 'string' ? JSON.parse(pages[pi].objects) : pages[pi].objects;
                    if (parsed && parsed.objects) existingObjs = parsed.objects;
                } catch (_) {}
            }
            const merged = existingObjs.concat(objArr);
            pages[pi].objects = JSON.stringify({ objects: merged });
        }

        // Reconstruire l'affichage depuis pages[]
        renderAllPages();
        saveStateFromPages('Import DOCX/ODT (texte+images)');
        alert(translatef('alertImportComplete', blocks.length, Object.keys(pageObjects).length));
    }

    if (importDocxBtn && importDocxInput) {
        importDocxBtn.addEventListener('click', () => importDocxInput.click());
        importDocxInput.addEventListener('change', (e) => {
            const file = e.target.files && e.target.files[0];
            if (!file) return;
            importModal.style.display = 'none';
            askInsertAtPage().then(startPage => {
                if (startPage === null) return; // annulé
                ensureDocxLibs(() => {
                    if (!window.mammoth) { alert(translate('alertMammothNotAvailable')); return; }
                    const reader = new FileReader();
                    reader.onload = function(ev) {
                        const arrayBuffer = ev.target.result;
                        const options = {
                            convertImage: window.mammoth.images.inline(function(element) {
                                return element.read("base64").then(function(imageBuffer) {
                                    return { src: "data:" + element.contentType + ";base64," + imageBuffer };
                                });
                            })
                        };
                        mammoth.convertToHtml({ arrayBuffer }, options)
                            .then(result => flowHtmlIntoPages(result.value, startPage))
                            .catch(err => { console.error('DOCX import error', err); alert(translatef('alertDocxImportError', err.message || err)); });
                    };
                    reader.readAsArrayBuffer(file);
                });
            });
            e.target.value = '';
        });
    }

    // ===== XLSX IMPORT (Excel) =====
    function ensureXlsxLibs(callback) {
        if (window.XLSX) { callback(); return; }
        // SheetJS — chargé en lazy uniquement lors d'un import Excel
        const s = document.createElement('script');
        s.src = 'https://cdn.sheetjs.com/xlsx-0.20.2/package/dist/xlsx.full.min.js';
        s.onload = callback;
        s.onerror = function () {
            // Fallback : le fichier local s'il existe
            const l = document.createElement('script');
            l.src = 'JS/xlsx.full.min.js';
            l.onload = callback;
            l.onerror = function () { alert(translate('alertXlsxNotAvailable')); };
            document.head.appendChild(l);
        };
        document.head.appendChild(s);
    }
    if (importXlsxBtn && importXlsxInput) {
        importXlsxBtn.addEventListener('click', () => importXlsxInput.click());
        importXlsxInput.addEventListener('change', (e) => {
            const file = e.target.files && e.target.files[0];
            if (!file) return;
            importModal.style.display = 'none';
            askInsertAtPage().then(startPage => {
                if (startPage === null) return; // annulé
                ensureXlsxLibs(() => {
                    if (!window.XLSX) return;
                    const reader = new FileReader();
                    reader.onload = function(ev) {
                        try {
                            const wb = window.XLSX.read(ev.target.result, { type: 'array' });
                            const html = [];
                            wb.SheetNames.forEach(function(sheetName) {
                                const ws = wb.Sheets[sheetName];
                                if (!ws) return;
                                const aoa = window.XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
                                html.push('<h2>' + sheetName.replace(/</g, '&lt;') + '</h2>');
                                html.push('<table>');
                                aoa.forEach(function(row) {
                                    html.push('<tr>');
                                    (row || []).forEach(function(cell) {
                                        const txt = (cell === null || cell === undefined) ? '' : String(cell);
                                        html.push('<td>' + txt.replace(/</g, '&lt;') + '</td>');
                                    });
                                    html.push('</tr>');
                                });
                                html.push('</table>');
                            });
                            if (html.length === 0) { alert(translate('alertXlsxEmpty')); return; }
                            flowHtmlIntoPages(html.join(''), startPage);
                        } catch (err) {
                            console.error('XLSX import error', err);
                            alert(translatef('alertXlsxImportError', err.message || err));
                        }
                    };
                    reader.readAsArrayBuffer(file);
                });
            });
            e.target.value = '';
        });
    }

    // ===== ODT IMPORT =====
    function extractOdtHtml(arrayBuffer) {
        return new Promise((resolve, reject) => {
            if (!window.JSZip) { reject(new Error('JSZip absent')); return; }
            JSZip.loadAsync(arrayBuffer).then(zip => {
                const entry = zip.file('content.xml');
                if (!entry) { reject(new Error('content.xml introuvable')); return; }
                entry.async('text').then(async (xmlStr) => {
                    try {
                        const parser = new DOMParser();
                        const doc = parser.parseFromString(xmlStr, 'application/xml');
                        // Chercher le body via namespace ou localName
                        const bodyNodes = doc.getElementsByTagNameNS('urn:oasis:names:tc:opendocument:xmlns:office:1.0', 'body');
                        let bodyEl = bodyNodes.length > 0 ? bodyNodes[0] : null;
                        if (!bodyEl) {
                            // Fallback: chercher par localName
                            const all = doc.getElementsByTagName('*');
                            for (let i = 0; i < all.length; i++) {
                                if (all[i].localName === 'body') { bodyEl = all[i]; break; }
                            }
                        }
                        if (!bodyEl) { resolve(''); return; }
                        // Chercher le text element (office:text) dedans
                        let textRoot = null;
                        for (let i = 0; i < bodyEl.children.length; i++) {
                            if (bodyEl.children[i].localName === 'text') { textRoot = bodyEl.children[i]; break; }
                        }
                        if (!textRoot) textRoot = bodyEl;

                        // Préparer extraction images : collecter tous les draw:image / image dans le doc
                        const allElems = Array.from(doc.getElementsByTagName('*'));
                        const imgNodes = allElems.filter(n => n.localName === 'image');
                        const hrefs = [];
                        imgNodes.forEach(n => {
                            // xlink:href — essayer getAttributeNS et fallback getAttribute
                            let href = n.getAttributeNS('http://www.w3.org/1999/xlink', 'href');
                            if (!href) href = n.getAttribute('xlink:href');
                            if (!href) href = n.getAttribute('href');
                            if (href) hrefs.push(href);
                        });
                        const uniqueHrefs = Array.from(new Set(hrefs)).filter(Boolean);
                        const hrefMap = {};
                        await Promise.all(uniqueHrefs.map(async (href) => {
                            const path = href.replace(/^\//, '');
                            const file = zip.file(path);
                            if (!file) return;
                            const b64 = await file.async('base64');
                            let mime = 'image/png';
                            if (/\.jpe?g$/i.test(path)) mime = 'image/jpeg';
                            else if (/\.gif$/i.test(path)) mime = 'image/gif';
                            else if (/\.svg$/i.test(path)) mime = 'image/svg+xml';
                            else if (/\.webp$/i.test(path)) mime = 'image/webp';
                            hrefMap[href] = `data:${mime};base64,${b64}`;
                        }));

                        // Fonction pour extraire les images d'un nœud (draw:frame / draw:image)
                        function extractImagesFromNode(node) {
                            const parts = [];
                            const frames = Array.from(node.children).filter(c => c.localName === 'frame' || c.localName === 'image');
                            frames.forEach(f => {
                                // frame contient image, ou c'est directement image
                                const targets = f.localName === 'image' ? [f] : Array.from(f.getElementsByTagName('*')).filter(x => x.localName === 'image');
                                targets.forEach(img => {
                                    let href = img.getAttributeNS('http://www.w3.org/1999/xlink', 'href');
                                    if (!href) href = img.getAttribute('xlink:href');
                                    if (!href) href = img.getAttribute('href');
                                    const src = hrefMap[href];
                                    if (src) parts.push(`<img src="${src}" />`);
                                });
                            });
                            return parts;
                        }

                        // Fonction pour collecter le texte propre d'un nœud (sans descendre dans frame/image)
                        function getCleanText(node) {
                            let result = '';
                            node.childNodes.forEach(child => {
                                if (child.nodeType === 3) { // TEXT_NODE
                                    result += child.textContent;
                                } else if (child.nodeType === 1) { // ELEMENT_NODE
                                    const ln = child.localName;
                                    if (ln === 'frame' || ln === 'image') return; // skip images
                                    if (ln === 's') { // text:s = espaces
                                        const count = parseInt(child.getAttribute('text:c') || child.getAttribute('c') || '1');
                                        result += ' '.repeat(count);
                                    } else if (ln === 'tab') {
                                        result += '\t';
                                    } else if (ln === 'line-break') {
                                        result += '\n';
                                    } else {
                                        result += getCleanText(child); // span, etc.
                                    }
                                }
                            });
                            return result;
                        }

                        // Fonction qui collecte le texte d'un nœud EN PRÉSERVANT le gras/italique.
                        // Les <text:span text:style-name="…"> sont rendus en <b>/<i>/<b><i> selon
                        // le style référencé (détecté par le nom OU en parsant office:automatic-styles).
                        const charStyleMap = (function () {
                            const map = {};
                            try {
                                // Lire les styles de caractères automatiques (gras/italique) + styles nommés
                                const docRef = doc;
                                ['office:automatic-styles', 'office:styles'].forEach(function (rootName) {
                                    const root = docRef.getElementsByTagNameNS ? docRef.getElementsByTagName(rootName)[0] : null;
                                    if (!root) return;
                                    Array.from(root.children).forEach(function (st) {
                                        if (!st || !/style$/.test(st.localName)) return;
                                        const name = st.getAttribute('style:name');
                                        if (!name) return;
                                        let bold = false, italic = false;
                                        const props = Array.from(st.children).find(function (c) {
                                            return /^text-properties$/.test(c.localName);
                                        });
                                        if (props) {
                                            bold = /bold/i.test(props.getAttribute('fo:font-weight') || '') ||
                                                   Number(props.getAttribute('fo:font-weight')) >= 700;
                                            italic = /italic|oblique/i.test(props.getAttribute('fo:font-style') || '');
                                        }
                                        if (bold || italic) map[name] = { bold: !!bold, italic: !!italic };
                                    });
                                });
                            } catch (_) {}
                            return map;
                        })();

                        function getCleanTextHtml(node) {
                            const esc = function (s) {
                                return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
                            };
                            let result = '';
                            node.childNodes.forEach(child => {
                                if (child.nodeType === 3) { // TEXT_NODE
                                    result += esc(child.textContent);
                                } else if (child.nodeType === 1) {
                                    const ln = child.localName;
                                    if (ln === 'frame' || ln === 'image') return;
                                    if (ln === 's') {
                                        const count = parseInt(child.getAttribute('text:c') || child.getAttribute('c') || '1');
                                        result += ' '.repeat(count);
                                    } else if (ln === 'tab') {
                                        result += '\t';
                                    } else if (ln === 'line-break') {
                                        result += '\n';
                                    } else if (ln === 'span') {
                                        // text:span → gras/italique via le style
                                        const stName = child.getAttribute('text:style-name') || child.getAttributeNS('urn:oasis:names:tc:opendocument:xmlns:text:1.0', 'style-name') || '';
                                        let inner = getCleanTextHtml(child);
                                        const st = charStyleMap[stName];
                                        if (st) {
                                            if (st.bold && st.italic) inner = '<b><i>' + inner + '</i></b>';
                                            else if (st.bold) inner = '<b>' + inner + '</b>';
                                            else if (st.italic) inner = '<i>' + inner + '</i>';
                                        } else {
                                            // Heuristique sur le nom du style
                                            const n = stName.toLowerCase();
                                            const isB = /bold|gras|b\d|gra/i.test(n);
                                            const isI = /italic|ital|oblique|pench/i.test(n);
                                            if (isB && isI) inner = '<b><i>' + inner + '</i></b>';
                                            else if (isB) inner = '<b>' + inner + '</b>';
                                            else if (isI) inner = '<i>' + inner + '</i>';
                                        }
                                        result += inner;
                                    } else {
                                        result += getCleanTextHtml(child);
                                    }
                                }
                            });
                            return result;
                        }

                        // Parcourir les enfants directs du textRoot (pas getElementsByTagName pour éviter doublons)
                        let htmlParts = [];
                        function processChildren(parent) {
                            for (let i = 0; i < parent.children.length; i++) {
                                const n = parent.children[i];
                                const ln = n.localName;
                                if (ln === 'h') {
                                    const level = n.getAttribute('text:outline-level') || n.getAttributeNS('urn:oasis:names:tc:opendocument:xmlns:text:1.0', 'outline-level') || '1';
                                    const tag = (level === '1') ? 'h1' : (level === '2' ? 'h2' : 'h3');
                                    const txt = getCleanText(n).trim();
                                    if (txt) htmlParts.push(`<${tag}>${txt.replace(/</g,'&lt;')}</${tag}>`);
                                    // Images dans le heading
                                    htmlParts.push(...extractImagesFromNode(n));
                                } else if (ln === 'p') {
                                    const txt = getCleanTextHtml(n).trim();
                                    if (txt) htmlParts.push(`<p>${txt}</p>`);
                                    // Images dans le paragraphe
                                    htmlParts.push(...extractImagesFromNode(n));
                                } else if (ln === 'list') {
                                    // text:list — parcourir les list-item
                                    const items = Array.from(n.children).filter(c => c.localName === 'list-item');
                                    if (items.length > 0) {
                                        let listHtml = '<ul>';
                                        items.forEach(item => {
                                            // list-item contient des <text:p>
                                            const ps = Array.from(item.children).filter(c => c.localName === 'p');
                                            const txt = ps.map(p => getCleanTextHtml(p).trim()).filter(Boolean).join(' ');
                                            if (txt) listHtml += `<li>${txt}</li>`;
                                        });
                                        listHtml += '</ul>';
                                        htmlParts.push(listHtml);
                                    }
                                } else if (ln === 'table') {
                                    // table:table — extraire lignes/cellules
                                    const rows = Array.from(n.getElementsByTagName('*')).filter(x => x.localName === 'table-row');
                                    if (rows.length > 0) {
                                        let tableHtml = '<table>';
                                        rows.forEach(row => {
                                            tableHtml += '<tr>';
                                            const cells = Array.from(row.children).filter(c => c.localName === 'table-cell');
                                            cells.forEach(cell => {
                                                const ps = Array.from(cell.children).filter(c => c.localName === 'p');
                                                const txt = ps.map(p => getCleanTextHtml(p).trim()).filter(Boolean).join(' ');
                                                tableHtml += `<td>${txt}</td>`;
                                            });
                                            tableHtml += '</tr>';
                                        });
                                        tableHtml += '</table>';
                                        htmlParts.push(tableHtml);
                                    }
                                } else if (ln === 'section') {
                                    // text:section — recurse into children
                                    processChildren(n);
                                }
                            }
                        }
                        processChildren(textRoot);

                        resolve(htmlParts.join('\n'));
                    } catch(err) { reject(err); }
                });
            }).catch(reject);
        });
    }

    if (importOdtBtn && importOdtInput) {
        importOdtBtn.addEventListener('click', () => importOdtInput.click());
        importOdtInput.addEventListener('change', (e) => {
            const file = e.target.files && e.target.files[0];
            if (!file) return;
            importModal.style.display = 'none';
            askInsertAtPage().then(startPage => {
                if (startPage === null) return; // annulé
                ensureDocxLibs(() => { // JSZip will be loaded here
                    const reader = new FileReader();
                    reader.onload = function(ev) {
                        extractOdtHtml(ev.target.result)
                            .then(html => flowHtmlIntoPages(html, startPage))
                            .catch(err => { console.error('ODT import error', err); alert(translatef('alertOdtImportError', err.message || err)); });
                    };
                    reader.readAsArrayBuffer(file);
                });
            });
            e.target.value = '';
        });
    }

