    function importScribusFile(xmlStr) {
        const parser = new DOMParser();
        const doc = parser.parseFromString(xmlStr, 'application/xml');
        const parserError = doc.querySelector('parsererror');
        if (parserError) { alert(translate('alertSlaInvalidXml')); return; }

        // Trouver le DOCUMENT
        const docEl = doc.querySelector('DOCUMENT');
        if (!docEl) { alert(translate('alertSlaNoDocument')); return; }

        // Lire les propriétés du document
        const docPageW = parseFloat(docEl.getAttribute('PAGEWIDTH') || '595');
        const docPageH = parseFloat(docEl.getAttribute('PAGEHEIGHT') || '842');

        // Lire les pages
        const pageEls = doc.querySelectorAll('PAGE');
        const pageObjs = doc.querySelectorAll('PAGEOBJECT');



        // Calculer le ratio de conversion vers notre canvas
        const canvasRef = getActiveCanvas();
        if (!canvasRef) { alert(translate('alertNoActiveCanvas')); return; }
        const scaleX = (canvasRef.width - 2 * bleedPx) / docPageW;
        const scaleY = (canvasRef.height - 2 * bleedPx) / docPageH;
        const scale = Math.min(scaleX, scaleY);

        // Grouper les objets par page (attribut OwnPage)
        const objsByPage = {};
        pageObjs.forEach(obj => {
            const pageNum = parseInt(obj.getAttribute('OwnPage') || '0');
            if (!objsByPage[pageNum]) objsByPage[pageNum] = [];
            objsByPage[pageNum].push(obj);
        });

        // Compter combien de pages on doit créer
        const maxPage = Math.max(0, ...Object.keys(objsByPage).map(Number));
        while (pages.length <= maxPage) { createNewPage(); }
        renderAllPages();

        let totalImported = 0;

        // Traiter chaque page
        for (const [pageStr, objs] of Object.entries(objsByPage)) {
            const pageIdx = parseInt(pageStr);
            if (pageIdx < 0 || pageIdx >= canvases.length) continue;
            const cvs = canvases[pageIdx];
            if (!cvs) continue;

            objs.forEach(obj => {
                const ptype = parseInt(obj.getAttribute('PTYPE') || '0');
                // Scribus PTYPE: 2=Image, 4=Text, 6=Shape/Rect, 7=Polygon, 8=Polyline
                const xpos = parseFloat(obj.getAttribute('XPOS') || '0');
                const ypos = parseFloat(obj.getAttribute('YPOS') || '0');
                const width = parseFloat(obj.getAttribute('WIDTH') || '100');
                const height = parseFloat(obj.getAttribute('HEIGHT') || '50');

                // Calculer la page d'origine pour offset
                let pageOriginX = 0;
                if (pageEls.length > pageIdx) {
                    pageOriginX = parseFloat(pageEls[pageIdx].getAttribute('PAGEXPOS') || '0');
                }
                const localX = (xpos - pageOriginX) * scale + bleedPx;
                const localY = ypos * scale + bleedPx;
                const localW = width * scale;
                const localH = height * scale;

                // Lire la couleur de remplissage
                const fillColorName = obj.getAttribute('PCOLOR') || 'None';
                const fillShade = parseFloat(obj.getAttribute('SHADE') || '100') / 100;
                const lineColorName = obj.getAttribute('PCOLOR2') || 'None';
                const lineWidth = parseFloat(obj.getAttribute('PWIDTH') || '1') * scale;

                function scribusColorToHex(name, shade) {
                    if (!name || name === 'None') return 'transparent';
                    // Couleurs Scribus standard
                    const map = {
                        'Black': '#000000', 'White': '#ffffff',
                        'Blue': '#0000ff', 'Cyan': '#00ffff',
                        'Green': '#00ff00', 'Magenta': '#ff00ff',
                        'Red': '#ff0000', 'Yellow': '#ffff00',
                        'Registration': '#000000'
                    };
                    let hex = map[name] || '#cccccc';
                    if (shade < 1 && hex !== 'transparent') {
                        // Appliquer shade (éclaircir)
                        const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
                        const sr = Math.round(r * shade + 255 * (1 - shade));
                        const sg = Math.round(g * shade + 255 * (1 - shade));
                        const sb = Math.round(b * shade + 255 * (1 - shade));
                        hex = '#' + [sr,sg,sb].map(v => Math.min(255,v).toString(16).padStart(2,'0')).join('');
                    }
                    return hex;
                }

                const fill = scribusColorToHex(fillColorName, fillShade);
                const stroke = scribusColorToHex(lineColorName, 1);

                if (ptype === 4) {
                    // TEXT FRAME — extraire le texte des sous-éléments ITEXT / para
                    let textParts = [];
                    const itexts = obj.querySelectorAll('ITEXT');
                    itexts.forEach(it => {
                        const ch = it.getAttribute('CH') || '';
                        if (ch) textParts.push(ch);
                    });
                    // Aussi chercher le texte dans les StoryText / DefaultStyle / trail
                    if (textParts.length === 0) {
                        const storyText = obj.querySelector('StoryText');
                        if (storyText) {
                            storyText.querySelectorAll('ITEXT, chars').forEach(it => {
                                const ch = it.getAttribute('CH') || it.textContent || '';
                                if (ch.trim()) textParts.push(ch);
                            });
                        }
                    }
                    const fullText = textParts.join('').replace(/\r/g, '\n');
                    if (!fullText.trim()) return; // Skip empty text frames

                    // Déterminer la taille de police
                    const firstItext = obj.querySelector('ITEXT');
                    let fontSize = 12;
                    if (firstItext) {
                        const fs = firstItext.getAttribute('FONTSIZE') || firstItext.getAttribute('FSIZE');
                        if (fs) fontSize = parseFloat(fs);
                    }
                    fontSize = Math.max(8, Math.round(fontSize * scale));

                    const isBold = firstItext && (firstItext.getAttribute('FONT') || '').toLowerCase().includes('bold');

                    const tb = new fabric.Textbox(fullText, {
                        left: localX, top: localY,
                        width: localW,
                        fontSize: fontSize,
                        fontFamily: 'IBM Plex Sans',
                        fontWeight: isBold ? 'bold' : 'normal',
                        fill: fill !== 'transparent' ? fill : '#000',
                        splitByGrapheme: false, breakWords: true,
                        _scribusImport: true
                    });
                    cvs.add(tb);
                    totalImported++;

                } else if (ptype === 2) {
                    // IMAGE FRAME — juste créer un rectangle placeholder
                    const rect = new fabric.Rect({
                        left: localX, top: localY,
                        width: localW, height: localH,
                        fill: fill !== 'transparent' ? fill : '#f0f0f0',
                        stroke: stroke !== 'transparent' ? stroke : '#ccc',
                        strokeWidth: Math.max(0.5, lineWidth),
                        rx: 0, ry: 0,
                        _scribusImport: true,
                        _scribusType: 'imageFrame'
                    });
                    cvs.add(rect);
                    // Ajouter un petit texte "Image" au centre
                    const label = new fabric.Text('🖼', {
                        left: localX + localW / 2,
                        top: localY + localH / 2,
                        fontSize: Math.min(24, localH * 0.4),
                        originX: 'center', originY: 'center',
                        fill: '#999',
                        selectable: false, evented: false,
                        _scribusImport: true,
                        _scribusPlaceholder: true
                    });
                    cvs.add(label);
                    totalImported++;

                } else if (ptype === 6 || ptype === 7) {
                    // SHAPE / POLYGON — créer un rectangle (simplification)
                    const rect = new fabric.Rect({
                        left: localX, top: localY,
                        width: localW, height: localH,
                        fill: fill !== 'transparent' ? fill : 'transparent',
                        stroke: stroke !== 'transparent' ? stroke : '#333',
                        strokeWidth: Math.max(0.5, lineWidth),
                        rx: 0, ry: 0,
                        _scribusImport: true
                    });
                    cvs.add(rect);
                    totalImported++;

                } else if (ptype === 8) {
                    // POLYLINE — créer une ligne simple
                    const line = new fabric.Line([localX, localY, localX + localW, localY + localH], {
                        stroke: stroke !== 'transparent' ? stroke : '#333',
                        strokeWidth: Math.max(0.5, lineWidth),
                        _scribusImport: true
                    });
                    cvs.add(line);
                    totalImported++;
                }
            });
            cvs.requestRenderAll();
        }

        // Retourner à la première page
        currentPageIndex = 0;
        renderAllPages();
        saveAllPages();
        saveState('Import Scribus (.sla)');
        alert(translatef('alertScribusImportComplete', totalImported, maxPage + 1));
    }

    // ===== IDML Import =====
    (function initIdmlImport() {
        const idmlBtn = document.getElementById('importIdmlBtn');
        const idmlModal = document.getElementById('idmlImportModal');
        const closeIdmlModal = document.getElementById('closeIdmlImportModal');
        const dropZone = document.getElementById('idmlDropZone');
        const fileInput = document.getElementById('idmlZipFileInput');
        const progressDiv = document.getElementById('idmlImportProgress');
        const progressText = document.getElementById('idmlProgressText');
        const progressBar = document.getElementById('idmlProgressBar');
        const logDiv = document.getElementById('idmlImportLog');
        let idmlFileName = '';

        if (!idmlBtn || !idmlModal) return;

        function logMsg(msg) {
            if (!logDiv) return;
            logDiv.style.display = 'block';
            const _line = document.createElement('span');
            _line.textContent = msg;
            logDiv.appendChild(_line);
            logDiv.appendChild(document.createElement('br'));
            logDiv.scrollTop = logDiv.scrollHeight;
        }
        function setProgress(pct, text) {
            if (progressDiv) progressDiv.style.display = 'block';
            if (progressBar) progressBar.style.width = pct + '%';
            if (progressText) progressText.textContent = text;
        }
        function resetModal() {
            if (progressDiv) progressDiv.style.display = 'none';
            if (progressBar) progressBar.style.width = '0%';
            if (logDiv) { logDiv.style.display = 'none'; logDiv.innerHTML = ''; }
        }

        // Open IDML modal from import modal button
        idmlBtn.addEventListener('click', function() {
            importModal.style.display = 'none';
            resetModal();
            idmlModal.style.display = 'block';
        });

        // Close
        closeIdmlModal.addEventListener('click', function() {
            idmlModal.style.display = 'none';
            resetModal();
        });

        // Drop zone drag events
        ['dragenter', 'dragover'].forEach(function(evt) {
            dropZone.addEventListener(evt, function(e) { e.preventDefault(); e.stopPropagation(); dropZone.classList.add('drag-over'); });
        });
        ['dragleave', 'drop'].forEach(function(evt) {
            dropZone.addEventListener(evt, function(e) { e.preventDefault(); e.stopPropagation(); dropZone.classList.remove('drag-over'); });
        });

        // Click to select file
        dropZone.addEventListener('click', function() { fileInput.click(); });
        fileInput.addEventListener('change', function(e) {
            var file = e.target.files && e.target.files[0];
            if (file) processIdmlZip(file);
            e.target.value = '';
        });

        // Drop file
        dropZone.addEventListener('drop', function(e) {
            var file = e.dataTransfer.files && e.dataTransfer.files[0];
            if (file) processIdmlZip(file);
        });

        // ===================== MAIN IDML PROCESSING =====================
        async function processIdmlZip(file) {
            const MAX_IDML_FILE_BYTES = 100 * 1024 * 1024;
            const MAX_IDML_ENTRIES = 5000;
            const MAX_IDML_UNCOMPRESSED_BYTES = 250 * 1024 * 1024;
            var name = file.name.toLowerCase();
            if (!name.endsWith('.zip') && !name.endsWith('.idml')) {
                alert(translate('alertProvideZipOrIdml'));
                return;
            }
            if (file.size > MAX_IDML_FILE_BYTES) {
                alert(translatef('alertIdmlImportError', 'Fichier trop volumineux (maximum 100 Mo).'));
                return;
            }
            setProgress(5, 'Lecture du fichier\u2026');
            logMsg('\uD83D\uDCC2 Fichier : ' + file.name + ' (' + (file.size / 1024).toFixed(0) + ' Ko)');

            try {
                var arrayBuffer = await file.arrayBuffer();
                setProgress(15, 'D\u00e9compression ZIP\u2026');
                var zip = await JSZip.loadAsync(arrayBuffer);

                function assertSafeArchive(archive, label) {
                    var entries = Object.keys(archive.files || {});
                    if (entries.length > MAX_IDML_ENTRIES) {
                        throw new Error(label + ' contient trop de fichiers (maximum ' + MAX_IDML_ENTRIES + ').');
                    }
                    var uncompressedBytes = entries.reduce(function(total, entryPath) {
                        var data = archive.files[entryPath] && archive.files[entryPath]._data;
                        return total + (data && Number(data.uncompressedSize) || 0);
                    }, 0);
                    if (uncompressedBytes > MAX_IDML_UNCOMPRESSED_BYTES) {
                        throw new Error(label + ' est trop volumineux après décompression (maximum 250 Mo).');
                    }
                }

                assertSafeArchive(zip, 'Le ZIP');

                var idmlZip = null;
                idmlFileName = '';
                var fontsFound = {};
                var imagesFound = {};

                if (name.endsWith('.idml')) {
                    idmlZip = zip;
                    idmlFileName = file.name;
                } else {
                    // Search for .idml inside the zip
                    for (var path of Object.keys(zip.files)) {
                        if (path.toLowerCase().endsWith('.idml') && !zip.files[path].dir) {
                            setProgress(20, 'Extraction IDML\u2026');
                            logMsg('\uD83D\uDCC4 IDML trouv\u00e9 : ' + path);
                            var idmlData = await zip.files[path].async('arraybuffer');
                            idmlZip = await JSZip.loadAsync(idmlData);
                            assertSafeArchive(idmlZip, 'Le fichier IDML');
                            idmlFileName = path.split('/').pop();
                            break;
                        }
                    }

                    // Extract fonts
                    for (var fpath of Object.keys(zip.files)) {
                        var lp = fpath.toLowerCase();
                        if ((lp.includes('font') || lp.includes('police')) && !zip.files[fpath].dir) {
                            if (lp.endsWith('.ttf') || lp.endsWith('.otf') || lp.endsWith('.woff') || lp.endsWith('.woff2')) {
                                fontsFound[fpath.split('/').pop()] = await zip.files[fpath].async('blob');
                            }
                        }
                    }

                    // Extract images
                    for (var ipath of Object.keys(zip.files)) {
                        var lpi = ipath.toLowerCase();
                        if ((lpi.includes('link') || lpi.includes('image') || lpi.includes('img') || lpi.includes('media')) && !zip.files[ipath].dir) {
                            if (/\.(jpe?g|png|gif|svg|bmp|webp|tiff?)$/i.test(lpi)) {
                                var imgBlob = await zip.files[ipath].async('blob');
                                var imgName = ipath.split('/').pop();
                                var ext = imgName.split('.').pop().toLowerCase();
                                var mimeMap = { jpg:'image/jpeg', jpeg:'image/jpeg', png:'image/png', gif:'image/gif', svg:'image/svg+xml', bmp:'image/bmp', webp:'image/webp', tif:'image/tiff', tiff:'image/tiff' };
                                imagesFound[imgName] = URL.createObjectURL(new Blob([imgBlob], { type: mimeMap[ext] || 'application/octet-stream' }));
                            }
                        }
                    }
                }

                if (!idmlZip) {
                    alert(translate('alertNoIdmlInZip'));
                    resetModal();
                    return;
                }

                // Also extract images embedded inside the IDML itself
                for (var rpath of Object.keys(idmlZip.files)) {
                    var lpr = rpath.toLowerCase();
                    if (!idmlZip.files[rpath].dir && /\.(jpe?g|png|gif|svg|bmp|webp)$/i.test(lpr)) {
                        var rBlob = await idmlZip.files[rpath].async('blob');
                        var rName = rpath.split('/').pop();
                        if (!imagesFound[rName]) {
                            var rExt = rName.split('.').pop().toLowerCase();
                            var rMime = { jpg:'image/jpeg', jpeg:'image/jpeg', png:'image/png', gif:'image/gif', svg:'image/svg+xml', bmp:'image/bmp', webp:'image/webp' };
                            imagesFound[rName] = URL.createObjectURL(new Blob([rBlob], { type: rMime[rExt] || 'application/octet-stream' }));
                        }
                    }
                }

                setProgress(25, 'Chargement des polices\u2026');
                var fontCount = Object.keys(fontsFound).length;
                if (fontCount > 0) {
                    logMsg('\uD83D\uDD24 ' + fontCount + ' police(s) trouv\u00e9e(s)');
                    for (var fontFileName of Object.keys(fontsFound)) {
                        var fontUrl = null; // 💧 v1.7.92 : hors try pour pouvoir revoke en cas d'erreur
                        try {
                            var baseName = fontFileName.replace(/\.(ttf|otf|woff2?)/i, '');
                            fontUrl = URL.createObjectURL(fontsFound[fontFileName]);
                            var fontFace = new FontFace(baseName, 'url(' + fontUrl + ')');
                            await fontFace.load();
                            document.fonts.add(fontFace);
                            // 💧 v1.7.91 : la police est parsée et copiée par le navigateur ;
                            //   le blob URL n'est plus nécessaire (libère le Blob source).
                            try { URL.revokeObjectURL(fontUrl); fontUrl = null; } catch(_) {}
                            logMsg('  \u2705 ' + baseName);
                        } catch (err) {
                            // 💧 v1.7.92 : en cas d'échec FontFace.load (format invalide / corrompu),
                            //   il faut quand même libérer le blob URL déjà créé.
                            if (fontUrl) { try { URL.revokeObjectURL(fontUrl); } catch(_) {} }
                            logMsg('  \u26A0\uFE0F Police ignor\u00e9e : ' + fontFileName);
                        }
                    }
                }

                var imgCount = Object.keys(imagesFound).length;
                if (imgCount > 0) logMsg('\uD83D\uDDBC\uFE0F ' + imgCount + ' image(s) trouv\u00e9e(s)');

                setProgress(35, 'Analyse IDML\u2026');
                await parseIdmlAndBuild(idmlZip, fontsFound, imagesFound);

                // 💧 v1.7.92 : libère les blob URLs des images IDML.
                //   parseIdmlAndBuild les a déjà transformées en dataURL via
                //   loadImgAsync(...).toDataURL() (cf. L24923) — les blob URLs
                //   ne sont donc plus référencées nulle part. Sans revoke,
                //   chaque IDML import laisse N images en mémoire jusqu'au
                //   reload du navigateur.
                try {
                    for (var _imgKey of Object.keys(imagesFound)) {
                        var _imgUrl = imagesFound[_imgKey];
                        if (typeof _imgUrl === 'string' && _imgUrl.indexOf('blob:') === 0) {
                            try { URL.revokeObjectURL(_imgUrl); } catch(_) {}
                        }
                    }
                } catch(_) {}

                setProgress(100, 'Import termin\u00e9 !');
                logMsg('\u2705 Import IDML termin\u00e9');
                logMsg('\u26A0\uFE0F Import BETA — certains effets avanc\u00e9s peuvent \u00eatre absents.');

                setTimeout(function() {
                    idmlModal.style.display = 'none';
                    resetModal();
                    window.spShowToast('Import BETA \u2014 les mises en page simples (texte, images, formes) sont bien support\u00e9es. Les effets avanc\u00e9s et transformations complexes peuvent \u00eatre perdus.', { kind: 'warning', duration: 6000 });
                }, 1200);

            } catch (err) {
                console.error('IDML import error', err);
                logMsg('\u274C Erreur : ' + err.message);
                setProgress(0, 'Erreur');
                // 💧 v1.7.92 : libère aussi les blob URLs sur le chemin d'erreur
                //   (sinon une exception au milieu de parseIdmlAndBuild laisse
                //   toutes les images en mémoire).
                try {
                    if (typeof imagesFound === 'object' && imagesFound) {
                        for (var _eImgKey of Object.keys(imagesFound)) {
                            var _eImgUrl = imagesFound[_eImgKey];
                            if (typeof _eImgUrl === 'string' && _eImgUrl.indexOf('blob:') === 0) {
                                try { URL.revokeObjectURL(_eImgUrl); } catch(_) {}
                            }
                        }
                    }
                } catch(_) {}
                alert(translatef('alertIdmlImportError', err.message));
            }
        }

        // ===================== PARSE IDML XML =====================
        async function parseIdmlAndBuild(zip, fontsMap, imagesMap) {
            // --- Read designmap.xml (master entry) ---
            var designmapXml = await readXmlFile(zip, 'designmap.xml');
            if (!designmapXml) throw new Error('designmap.xml introuvable dans le IDML');

            // --- Read Preferences for page dimensions ---
            var docPageW = 210, docPageH = 297;
            var prefsFile = await readXmlFile(zip, 'Resources/Preferences.xml');
            if (prefsFile) {
                var dpEl = prefsFile.querySelector('DocumentPreference');
                if (dpEl) {
                    var pw = parseFloat(dpEl.getAttribute('PageWidth'));
                    var ph = parseFloat(dpEl.getAttribute('PageHeight'));
                    if (pw && ph) {
                        // IDML uses points (1pt = 1/72 inch)
                        docPageW = pw * 25.4 / 72;
                        docPageH = ph * 25.4 / 72;
                    }
                }
            }
            logMsg('\uD83D\uDCD0 Format : ' + docPageW.toFixed(1) + ' \u00d7 ' + docPageH.toFixed(1) + ' mm');

            pageFormat.width = Math.round(docPageW);
            pageFormat.height = Math.round(docPageH);

            // Update UI inputs
            var formatSel = document.getElementById('pageFormat');
            if (formatSel) formatSel.value = 'custom';
            var cwEl = document.getElementById('customWidth');
            var chEl = document.getElementById('customHeight');
            if (cwEl) cwEl.value = pageFormat.width;
            if (chEl) chEl.value = pageFormat.height;

            // --- Collect Styles ---
            var stylesMap = {};
            var stylesXml = await readXmlFile(zip, 'Resources/Styles.xml');
            if (stylesXml) {
                stylesXml.querySelectorAll('ParagraphStyle, CharacterStyle').forEach(function(s) {
                    var selfAttr = s.getAttribute('Self');
                    if (!selfAttr) return;
                    var props = {};
                    var fontEl = s.querySelector('Properties > AppliedFont');
                    if (fontEl) props.fontFamily = fontEl.textContent.trim();
                    if (s.getAttribute('PointSize')) props.fontSize = parseFloat(s.getAttribute('PointSize'));
                    if (s.getAttribute('FontStyle')) props.fontStyle = s.getAttribute('FontStyle');
                    if (s.getAttribute('FillColor')) props.fillColor = s.getAttribute('FillColor');
                    if (s.getAttribute('Justification')) props.justification = s.getAttribute('Justification');
                    if (s.getAttribute('Leading')) props.leading = parseFloat(s.getAttribute('Leading'));
                    if (s.getAttribute('Tracking')) props.tracking = parseFloat(s.getAttribute('Tracking'));
                    stylesMap[selfAttr] = props;
                });
            }

            // --- Collect Colors ---
            var colorsMap = { 'Color/Black': '#000000', 'Color/Paper': '#FFFFFF', 'Color/Registration': '#000000' };
            var graphicXml = await readXmlFile(zip, 'Resources/Graphic.xml');
            if (graphicXml) {
                graphicXml.querySelectorAll('Color').forEach(function(c) {
                    var selfAttr = c.getAttribute('Self');
                    var space = c.getAttribute('Space') || 'CMYK';
                    var values = (c.getAttribute('ColorValue') || '').split(' ').map(Number);
                    if (space === 'CMYK' && values.length >= 4) {
                        colorsMap[selfAttr] = cmykHex(values[0], values[1], values[2], values[3]);
                    } else if (space === 'RGB' && values.length >= 3) {
                        colorsMap[selfAttr] = rgbHex(values[0], values[1], values[2]);
                    }
                });
            }

            // --- Read Spreads ---
            setProgress(45, 'Lecture des pages\u2026');
            var spreadPaths = [];
            // FIX IDML: Essayer plusieurs méthodes pour trouver les spreads
            // (le namespace idPkg: peut ne pas fonctionner avec querySelectorAll selon le navigateur)
            try { designmapXml.querySelectorAll('idPkg\\:Spread, Spread').forEach(function(s) {
                var src = s.getAttribute('src');
                if (src) spreadPaths.push(src);
            }); } catch(_) {}
            if (spreadPaths.length === 0) {
                // Fallback: chercher par getElementsByTagName (gère les namespaces)
                var allEls = designmapXml.getElementsByTagName('*');
                for (var ei = 0; ei < allEls.length; ei++) {
                    if (allEls[ei].localName === 'Spread' || allEls[ei].tagName.endsWith(':Spread')) {
                        var src = allEls[ei].getAttribute('src');
                        if (src) spreadPaths.push(src);
                    }
                }
            }
            if (spreadPaths.length === 0) {
                for (var sp of Object.keys(zip.files)) {
                    if (/^Spreads\/Spread_.*\.xml$/i.test(sp)) spreadPaths.push(sp);
                }
                spreadPaths.sort();
            }
            logMsg('\uD83D\uDCD1 ' + spreadPaths.length + ' spread(s) trouv\u00e9(s)');

            // --- Collect all Stories (text content) ---
            setProgress(50, 'Lecture des textes\u2026');
            var storiesMap = {};
            for (var stPath of Object.keys(zip.files)) {
                if (/^Stories\/Story_.*\.xml$/i.test(stPath)) {
                    var storyXml = await readXmlFile(zip, stPath);
                    if (!storyXml) continue;
                    var storyEl = storyXml.querySelector('Story');
                    // FIX IDML: Fallback si querySelector ne trouve pas Story
                    if (!storyEl) {
                        var allStEls = storyXml.getElementsByTagName('*');
                        for (var sti = 0; sti < allStEls.length; sti++) {
                            if (allStEls[sti].localName === 'Story') { storyEl = allStEls[sti]; break; }
                        }
                    }
                    if (!storyEl) continue;
                    var storyId = storyEl.getAttribute('Self');
                    if (!storyId) continue;
                    storiesMap[storyId] = extractStoryText(storyEl, stylesMap, colorsMap);
                }
            }
            logMsg('\uD83D\uDCDD ' + Object.keys(storiesMap).length + ' bloc(s) de texte');

            // --- Process each spread into pages ---
            setProgress(60, 'Construction des pages\u2026');
            pages.length = 0;
            currentPageIndex = 0;
            textLinks = {};
            var totalObjCount = 0;
            var importedStoryChains = {};
            var importedStoryHeadIds = [];
            var importedFrameSequence = 0;

            function orderImportedStoryFrames(frames) {
                if (!frames || frames.length < 2) return frames || [];
                var bySelf = {};
                var targeted = {};
                frames.forEach(function(frame) {
                    if (frame.self) bySelf[frame.self] = frame;
                    if (frame.next) targeted[frame.next] = true;
                });
                var ordered = [];
                var current = frames.find(function(frame) { return frame.self && !targeted[frame.self]; }) || frames[0];
                while (current && ordered.indexOf(current) === -1) {
                    ordered.push(current);
                    current = current.next ? bySelf[current.next] : null;
                }
                frames.forEach(function(frame) {
                    if (ordered.indexOf(frame) === -1) ordered.push(frame);
                });
                return ordered;
            }

            for (var si = 0; si < spreadPaths.length; si++) {
                var spreadXml = await readXmlFile(zip, spreadPaths[si]);
                if (!spreadXml) continue;
                var spreadEl = spreadXml.querySelector('Spread');
                // FIX IDML: Fallback si querySelector ne trouve pas Spread (namespace)
                if (!spreadEl) {
                    var allSpreadEls = spreadXml.getElementsByTagName('*');
                    for (var sei = 0; sei < allSpreadEls.length; sei++) {
                        if (allSpreadEls[sei].localName === 'Spread' && allSpreadEls[sei] !== spreadXml.documentElement) {
                            spreadEl = allSpreadEls[sei]; break;
                        }
                    }
                }
                if (!spreadEl) continue;

                var pageEls = spreadEl.querySelectorAll('Page');
                var allItems = spreadEl.querySelectorAll('TextFrame, Rectangle, Oval, Polygon, GraphicLine, Group');

                var pageBoundsArr = [];
                pageEls.forEach(function(pgEl) {
                    var gbArr = (pgEl.getAttribute('GeometricBounds') || '').split(' ').map(Number);
                    if (gbArr.length === 4) pageBoundsArr.push({ top: gbArr[0], left: gbArr[1], bottom: gbArr[2], right: gbArr[3] });
                });
                if (pageBoundsArr.length === 0) {
                    var defW = docPageW * 72 / 25.4;
                    var defH = docPageH * 72 / 25.4;
                    pageBoundsArr.push({ top: 0, left: 0, bottom: defH, right: defW });
                }

                for (var pi = 0; pi < pageBoundsArr.length; pi++) {
                    var pgB = pageBoundsArr[pi];
                    var pageIdx = pages.length;
                    createNewPage();

                    var pctVal = 60 + Math.round(35 * (pageIdx / Math.max(1, spreadPaths.length * pageBoundsArr.length)));
                    setProgress(pctVal, 'Page ' + (pageIdx + 1) + '\u2026');

                    var itemsForPage = [];
                    allItems.forEach(function(itm) {
                        var itmBounds = getItemGeoBounds(itm);
                        if (!itmBounds) return;
                        var centerX = (itmBounds.left + itmBounds.right) / 2;
                        if (centerX >= pgB.left && centerX <= pgB.right) {
                            itemsForPage.push({ el: itm, bounds: itmBounds });
                        }
                    });

                    var fabricObjs = [];
                    for (var ii = 0; ii < itemsForPage.length; ii++) {
                        var itemEl = itemsForPage[ii].el;
                        var fObj = await convertToFabricObj(itemsForPage[ii].el, itemsForPage[ii].bounds, pgB, storiesMap, stylesMap, colorsMap, imagesMap);
                        if (!fObj) continue;

                        if (itemEl.tagName === 'TextFrame') {
                            var itemStoryId = itemEl.getAttribute('ParentStory');
                            if (itemStoryId) {
                                var linkId = 'idml_' + Date.now() + '_' + (++importedFrameSequence);
                                fObj.textLinkId = linkId;
                                fObj.isLinkedTextBlock = true;
                                fObj._fixedWidth = fObj.width;
                                fObj._fixedHeight = fObj._fixedHeight || (itemsForPage[ii].bounds.bottom - itemsForPage[ii].bounds.top);

                                var frameInfo = {
                                    linkId: linkId,
                                    pageIndex: pageIdx,
                                    self: itemEl.getAttribute('Self'),
                                    next: itemEl.getAttribute('NextTextFrame') || ''
                                };

                                if (importedStoryChains[itemStoryId]) {
                                    importedStoryChains[itemStoryId].frames.push(frameInfo);
                                    // The complete story remains in the head frame until the
                                    // native chain reflow distributes it after Fabric renders.
                                    fObj.text = '';
                                    fObj.styles = {};
                                } else {
                                    importedStoryChains[itemStoryId] = { frames: [frameInfo] };
                                }
                            }
                        }
                        fabricObjs.push(fObj);
                        totalObjCount++;
                    }
                    pages[pageIdx].objects = JSON.stringify({ objects: fabricObjs });
                }
            }

            if (pages.length === 0) createNewPage();
            function findImportedTextbox(linkId) {
                for (var importedPageIndex = 0; importedPageIndex < pages.length; importedPageIndex++) {
                    var importedPage = pages[importedPageIndex];
                    if (!importedPage || !importedPage.objects) continue;
                    try {
                        var importedData = typeof importedPage.objects === 'string' ? JSON.parse(importedPage.objects) : importedPage.objects;
                        var importedObject = (importedData.objects || []).find(function(object) { return object.textLinkId === linkId; });
                        if (importedObject) {
                            return {
                                object: importedObject,
                                page: importedPage,
                                data: importedData
                            };
                        }
                    } catch (_) {}
                }
                return null;
            }
            Object.keys(importedStoryChains).forEach(function(storyId) {
                var orderedFrames = orderImportedStoryFrames(importedStoryChains[storyId].frames);
                if (!orderedFrames.length) return;
                var headTextboxEntry = findImportedTextbox(orderedFrames[0].linkId);
                var populatedTextboxEntry = null;
                orderedFrames.forEach(function(frame) {
                    var textboxEntry = findImportedTextbox(frame.linkId);
                    if (!populatedTextboxEntry && textboxEntry && textboxEntry.object.text) populatedTextboxEntry = textboxEntry;
                });
                if (headTextboxEntry && populatedTextboxEntry && headTextboxEntry.object.textLinkId !== populatedTextboxEntry.object.textLinkId) {
                    headTextboxEntry.object.text = populatedTextboxEntry.object.text;
                    headTextboxEntry.object.styles = populatedTextboxEntry.object.styles;
                    populatedTextboxEntry.object.text = '';
                    populatedTextboxEntry.object.styles = {};
                    headTextboxEntry.page.objects = JSON.stringify(headTextboxEntry.data);
                    populatedTextboxEntry.page.objects = JSON.stringify(populatedTextboxEntry.data);
                }
                importedStoryHeadIds.push(orderedFrames[0].linkId);
                for (var frameIndex = 0; frameIndex < orderedFrames.length - 1; frameIndex++) {
                    textLinks[orderedFrames[frameIndex].linkId] = {
                        targetId: orderedFrames[frameIndex + 1].linkId,
                        targetPageIndex: orderedFrames[frameIndex + 1].pageIndex
                    };
                }
            });
            logMsg('\uD83E\uDDF1 ' + totalObjCount + ' objet(s) cr\u00e9\u00e9s sur ' + pages.length + ' page(s)');

            setProgress(95, 'Rendu\u2026');
            currentPageIndex = 0;
            renderAllPages();

            setTimeout(function() {
                // FIX: Forcer la désactivation du guard avant de sauvegarder
                _isRenderingAllPages = false;
                if (window._renderAllPagesTimerId) { clearTimeout(window._renderAllPagesTimerId); window._renderAllPagesTimerId = null; }
                importedStoryHeadIds.forEach(function(headId) {
                    var head = findBlockById(headId);
                    if (head) redistributeLinkedTextChain(head.obj);
                });
                saveStateFromPages('Import IDML : ' + (idmlFileName || 'document'));
            }, 800);
        }

        // ===================== HELPER FUNCTIONS =====================

        async function readXmlFile(zip, path) {
            var f = zip.files[path];
            if (!f) return null;
            var txt = await f.async('string');
            return new DOMParser().parseFromString(txt, 'application/xml');
        }

        function cmykHex(c, m, y, k) {
            var r = Math.round(255 * (1 - c / 100) * (1 - k / 100));
            var g = Math.round(255 * (1 - m / 100) * (1 - k / 100));
            var b = Math.round(255 * (1 - y / 100) * (1 - k / 100));
            return '#' + [r, g, b].map(function(v) { return Math.max(0, Math.min(255, v)).toString(16).padStart(2, '0'); }).join('');
        }

        function rgbHex(r, g, b) {
            return '#' + [r, g, b].map(function(v) { return Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0'); }).join('');
        }

        function resolveColorRef(ref, cMap) {
            if (!ref) return null;
            if (ref === 'Color/Paper') return '#FFFFFF';
            if (ref === 'Color/Black' || ref === 'Color/Registration') return '#000000';
            if (cMap[ref]) return cMap[ref];
            var m = ref.match(/C=(\d+)\s*M=(\d+)\s*Y=(\d+)\s*K=(\d+)/);
            if (m) return cmykHex(+m[1], +m[2], +m[3], +m[4]);
            return null;
        }

        function getItemGeoBounds(item) {
            var gbAttr = item.getAttribute('GeometricBounds');
            if (gbAttr) {
                var gb = gbAttr.split(' ').map(Number);
                if (gb.length === 4) return { top: gb[0], left: gb[1], bottom: gb[2], right: gb[3] };
            }
            var pts = item.querySelectorAll('PathPointArray PathPointType');
            if (pts.length > 0) {
                var mnX = Infinity, mnY = Infinity, mxX = -Infinity, mxY = -Infinity;
                pts.forEach(function(pp) {
                    var anc = (pp.getAttribute('Anchor') || '').split(' ').map(Number);
                    if (anc.length >= 2) { mnX = Math.min(mnX, anc[0]); mnY = Math.min(mnY, anc[1]); mxX = Math.max(mxX, anc[0]); mxY = Math.max(mxY, anc[1]); }
                });
                if (isFinite(mnX)) return { top: mnY, left: mnX, bottom: mxY, right: mxX };
            }
            return null;
        }

        function extractStoryText(storyEl, sMap, cMap) {
            var result = { paragraphs: [] };
            storyEl.querySelectorAll('ParagraphStyleRange').forEach(function(psr) {
                var pStyleRef = psr.getAttribute('AppliedParagraphStyle') || '';
                var pStyle = sMap[pStyleRef] || {};
                var runs = [];
                psr.querySelectorAll('CharacterStyleRange').forEach(function(csr) {
                    var cStyleRef = csr.getAttribute('AppliedCharacterStyle') || '';
                    var cStyle = sMap[cStyleRef] || {};
                    var text = '';
                    csr.querySelectorAll('Content').forEach(function(c) { text += c.textContent; });
                    csr.querySelectorAll('Br').forEach(function() { text += '\n'; });
                    if (!text) return;
                    var run = { text: text };
                    var fEl = csr.querySelector('Properties > AppliedFont');
                    run.fontFamily = (fEl && fEl.textContent.trim()) || cStyle.fontFamily || pStyle.fontFamily || 'Open Sans';
                    run.fontSize = parseFloat(csr.getAttribute('PointSize')) || cStyle.fontSize || pStyle.fontSize || 12;
                    var fsAttr = csr.getAttribute('FontStyle') || cStyle.fontStyle || pStyle.fontStyle || '';
                    run.fontWeight = fsAttr.toLowerCase().includes('bold') ? 'bold' : 'normal';
                    run.fontStyleCSS = (fsAttr.toLowerCase().includes('italic') || fsAttr.toLowerCase().includes('oblique')) ? 'italic' : 'normal';
                    run.underline = csr.getAttribute('Underline') === 'true';
                    run.linethrough = csr.getAttribute('StrikeThru') === 'true';
                    var fillRef = csr.getAttribute('FillColor') || cStyle.fillColor || pStyle.fillColor;
                    run.fill = resolveColorRef(fillRef, cMap) || '#000000';
                    run.tracking = parseFloat(csr.getAttribute('Tracking')) || cStyle.tracking || pStyle.tracking || 0;
                    runs.push(run);
                });
                if (runs.length === 0) return;
                result.paragraphs.push({
                    runs: runs,
                    justification: psr.getAttribute('Justification') || pStyle.justification || 'LeftAlign',
                    leading: parseFloat(psr.getAttribute('Leading')) || pStyle.leading || 0,
                    spaceAfter: parseFloat(psr.getAttribute('SpaceAfter')) || 0,
                });
            });
            return result;
        }

        function justToFabricAlign(just) {
            var m = { 'LeftAlign':'left', 'CenterAlign':'center', 'RightAlign':'right', 'LeftJustified':'justify-left', 'RightJustified':'justify-right', 'CenterJustified':'justify-left', 'FullyJustified':'justify' };
            return m[just] || 'left';
        }

        // pt → px : In this app, canvas uses 72dpi, so 1pt = 1px
        function ptPx(pt) { return pt; }

        async function convertToFabricObj(item, gb, pgB, storiesMap, sMap, cMap, imgMap) {
            var tag = item.tagName;
            var bPx = mmToPx(bleed);
            // Convert from spread-points to page-relative px
            var x = ptPx(gb.left - pgB.left) + bPx;
            var y = ptPx(gb.top - pgB.top) + bPx;
            var w = ptPx(gb.right - gb.left);
            var h = ptPx(gb.bottom - gb.top);
            if (w < 1 || h < 1) return null;

            // --- Apply ItemTransform if present ---
            // In IDML, GeometricBounds is in local coords; ItemTransform maps local→spread
            // For items directly on a spread (not nested), GeometricBounds is often already in spread coords
            // We check: if bounds seem to be near origin, apply transform translation
            var txAttr = item.getAttribute('ItemTransform');
            if (txAttr) {
                var txVals = txAttr.split(' ').map(Number);
                if (txVals.length === 6) {
                    var a = txVals[0], b = txVals[1], c = txVals[2], d = txVals[3], tx = txVals[4], ty = txVals[5];
                    // If the matrix has significant translation and bounds are near local origin, apply transform
                    if ((Math.abs(tx) > 1 || Math.abs(ty) > 1) && Math.abs(gb.left) < 1 && Math.abs(gb.top) < 1) {
                        x = ptPx(tx) - ptPx(pgB.left) + bPx;
                        y = ptPx(ty) - ptPx(pgB.top) + bPx;
                    }
                }
            }

            // --- TextFrame ---
            if (tag === 'TextFrame') {
                var storyRef = item.getAttribute('ParentStory');
                var story = storyRef ? storiesMap[storyRef] : null;
                if (!story || story.paragraphs.length === 0) {
                    return { type:'textbox', left:x, top:y, width:w, text:'', fontSize:12, fontFamily:'Open Sans', fill:'#000000', _fixedWidth:w, _fixedHeight:h };
                }
                var fullText = '';
                var fabricStyles = {};
                var domFontSize = 12, domFontFamily = 'Open Sans', domFontWeight = 'normal', domFontStyle = 'normal', domFill = '#000000', domTracking = 0, domUnderline = false, domLinethrough = false, domAlign = 'left', domLeading = 0;
                var hasBaseStyle = false;
                var chIdx = 0;

                story.paragraphs.forEach(function(para, paraIdx) {
                    if (paraIdx === 0) domAlign = justToFabricAlign(para.justification);
                    para.runs.forEach(function(run) {
                        if (!hasBaseStyle) {
                            domFontSize = run.fontSize || domFontSize;
                            domFontFamily = run.fontFamily || domFontFamily;
                            domFontWeight = run.fontWeight || domFontWeight;
                            domFontStyle = run.fontStyleCSS || domFontStyle;
                            domFill = run.fill || domFill;
                            domTracking = run.tracking || 0;
                            domUnderline = run.underline;
                            domLinethrough = run.linethrough;
                            hasBaseStyle = true;
                        }
                        for (var ci = 0; ci < run.text.length; ci++) {
                            var lineIdx = fullText.split('\n').length - 1;
                            if (!fabricStyles[lineIdx]) fabricStyles[lineIdx] = {};
                            fabricStyles[lineIdx][chIdx] = {};
                            if (run.fontFamily && run.fontFamily !== domFontFamily) fabricStyles[lineIdx][chIdx].fontFamily = run.fontFamily;
                            if (run.fontSize && run.fontSize !== domFontSize) fabricStyles[lineIdx][chIdx].fontSize = run.fontSize;
                            if (run.fontWeight !== domFontWeight) fabricStyles[lineIdx][chIdx].fontWeight = run.fontWeight;
                            if (run.fontStyleCSS !== domFontStyle) fabricStyles[lineIdx][chIdx].fontStyle = run.fontStyleCSS;
                            if (run.fill && run.fill !== domFill) fabricStyles[lineIdx][chIdx].fill = run.fill;
                            if (run.tracking !== domTracking) fabricStyles[lineIdx][chIdx].charSpacing = run.tracking;
                            if (run.underline !== domUnderline) fabricStyles[lineIdx][chIdx].underline = run.underline;
                            if (run.linethrough !== domLinethrough) fabricStyles[lineIdx][chIdx].linethrough = run.linethrough;
                            chIdx++;
                            fullText += run.text[ci];
                            if (run.text[ci] === '\n') chIdx = 0;
                        }
                    });
                    if (para.leading > domLeading) domLeading = para.leading;
                    if (paraIdx < story.paragraphs.length - 1) { fullText += '\n'; chIdx = 0; }
                });

                // Clean empty style entries
                for (var ln in fabricStyles) {
                    for (var ch in fabricStyles[ln]) {
                        if (Object.keys(fabricStyles[ln][ch]).length === 0) delete fabricStyles[ln][ch];
                    }
                    if (Object.keys(fabricStyles[ln]).length === 0) delete fabricStyles[ln];
                }

                var lhVal = domLeading > 0 ? domLeading / domFontSize : 1.35;
                return {
                    type:'textbox', left:x, top:y, width:w,
                    text: fullText.replace(/\r/g, ''),
                    fontSize: domFontSize, fontFamily: domFontFamily, fill: domFill,
                    fontWeight: domFontWeight, fontStyle: domFontStyle, charSpacing: domTracking, underline: domUnderline, linethrough: domLinethrough,
                    textAlign: domAlign,
                    lineHeight: Math.max(1, Math.min(3, lhVal)),
                    styles: fabricStyles,
                    _fixedWidth: w, _fixedHeight: h,
                    splitByGrapheme: false, breakWords: true,
                };
            }

            // --- Rectangle / Oval / Polygon ---
            if (tag === 'Rectangle' || tag === 'Oval' || tag === 'Polygon') {
                var fillRef = item.getAttribute('FillColor');
                var strokeRef = item.getAttribute('StrokeColor');
                var strokeW = parseFloat(item.getAttribute('StrokeWeight')) || 0;
                var fillC = resolveColorRef(fillRef, cMap) || 'transparent';
                var strokeC = resolveColorRef(strokeRef, cMap) || 'transparent';

                // Check for embedded image
                var imageEl = item.querySelector('Image');
                var linkEl = imageEl ? imageEl.querySelector('Link') : null;
                var linkPath = linkEl ? (linkEl.getAttribute('LinkResourceURI') || '') : '';
                var linkName = decodeURIComponent(linkPath.split('/').pop().split('\\').pop());

                if (linkName && imgMap[linkName]) {
                    try {
                        var loadedImg = await loadImgAsync(imgMap[linkName]);
                        if (loadedImg) {
                            var scX = w / loadedImg.width;
                            var scY = h / loadedImg.height;
                            var sc = Math.max(scX, scY);
                            return { type:'image', src: loadedImg.toDataURL(), left:x, top:y, scaleX: sc, scaleY: sc };
                        }
                    } catch (e) { logMsg('  \u26A0\uFE0F Image ignor\u00e9e : ' + linkName); }
                }

                if (tag === 'Oval') {
                    return { type:'ellipse', left: x + w/2, top: y + h/2, rx: w/2, ry: h/2, fill: fillC === 'transparent' ? '' : fillC, stroke: strokeC === 'transparent' ? '' : strokeC, strokeWidth: ptPx(strokeW), originX:'center', originY:'center' };
                }
                return { type:'rect', left:x, top:y, width:w, height:h, fill: fillC === 'transparent' ? '' : fillC, stroke: strokeC === 'transparent' ? '' : strokeC, strokeWidth: ptPx(strokeW) };
            }

            // --- GraphicLine ---
            if (tag === 'GraphicLine') {
                var lStrokeRef = item.getAttribute('StrokeColor');
                var lStrokeW = parseFloat(item.getAttribute('StrokeWeight')) || 1;
                var lStroke = resolveColorRef(lStrokeRef, cMap) || '#000000';
                return { type:'line', x1:x, y1:y, x2: x+w, y2: y+h, stroke: lStroke, strokeWidth: ptPx(lStrokeW) };
            }

            // --- Group ---
            if (tag === 'Group') {
                var children = item.querySelectorAll(':scope > TextFrame, :scope > Rectangle, :scope > Oval, :scope > Polygon, :scope > GraphicLine');
                var grpObjs = [];
                for (var gi = 0; gi < children.length; gi++) {
                    var cBounds = getItemGeoBounds(children[gi]);
                    if (!cBounds) continue;
                    var cObj = await convertToFabricObj(children[gi], cBounds, pgB, storiesMap, sMap, cMap, imgMap);
                    if (cObj) grpObjs.push(cObj);
                }
                if (grpObjs.length === 1) return grpObjs[0];
                if (grpObjs.length > 1) return { type:'group', left:x, top:y, objects: grpObjs };
            }

            return null;
        }

        function loadImgAsync(src) {
            return new Promise(function(resolve, reject) {
                fabric.Image.fromURL(src, function(img) {
                    if (img) resolve(img); else reject(new Error('Image load failed'));
                }, { crossOrigin: 'anonymous' });
            });
        }
    })();

