        // FIX: Nettoyer la notification spread si présente
        if (window._spreadNotifShowTimer) { clearTimeout(window._spreadNotifShowTimer); window._spreadNotifShowTimer = null; }
        if (window._spreadNotifDismissTimer) { clearTimeout(window._spreadNotifDismissTimer); window._spreadNotifDismissTimer = null; }
        const notif = document.getElementById('spreadNotification');
        if (notif && notif.parentNode) notif.parentNode.removeChild(notif);
        
