        loader.remove();
        
        const now = new Date();
        const dateStr = now.toISOString().slice(0, 16).replace(/[-:]/g, '').replace('T', '-');
        
        const imposedColorMode = (
            document.querySelector('input[name="imposedColorMode"]:checked')?.value
            || document.querySelector('input[name="colorMode"]:checked')?.value
            || 'rgb'
        );
        const imposedColorLabel = imposedColorMode === 'cmyk' ? 'cmyk' : (imposedColorMode === 'bw' ? 'bw' : 'rgb');
        const filename = `superprint-imposed-${imposedColorLabel}-${dateStr}.pdf`;
