                                var tgtH = sheetH * mmToPt;
                                // On dessine la page PDF d'origine centrée, mise à l'échelle
                                var scale = Math.min(tgtW / srcW, tgtH / srcH);
                                var dw = srcW * scale, dh = srcH * scale;
