                var shPt = sheetH * mmToPt;
                var page = doc.addPage([swPt, shPt]);

                // Fond blanc si bleed
                if (incBleed) {
                    page.drawRectangle({
                        x: 0, y: 0, width: swPt, height: shPt,
                        color: PDFLib.rgb(1, 1, 1)
                    });
                }

                // 🧩 RÉ-EMBARQUEMENT DES PDF VECTORIELS IMPORTÉS (imposition) :
                // Identique à l'export simple : si la feuille contient des PDF importés
                // avec contenu vectoriel/transparent et que l'archive source est
                // disponible, on remplace l'image raster par la page PDF D'ORIGINE
                // (copiée telle quelle → typo + objets vectoriels conservés, pas d'image).
                // On dessine d'abord la page PDF d'origine, puis on marque l'objet
                // _spPdfReplaced pour qu'il soit ignoré dans la boucle de rendu raster.
