            var dateStr = now.toISOString().slice(0, 16).replace(/[-:]/g, '').replace('T', '-');
            var filename = 'superprint-imposed-vector-' + dateStr + '.pdf';
            var blob = new Blob([pdfBytes], { type: 'application/pdf' });
            var url = URL.createObjectURL(blob);
