        // 🆕 Studio SP213 : ouvre l'interface dédiée de conversation (Groq ou WLLM).
        // L'URL est construite depuis location.origin + le répertoire de l'index
        // (robuste même si l'app est servie depuis une sous-route), et on propose
        // un lien de secours si le popup est bloqué par le navigateur.
        function openSp213Studio() {
            try { window._aiSp213Enabled = true; localStorage.setItem('sp_ai_sp213', '1'); } catch(e) {}
            const _sp213Toggle = document.getElementById('aiSp213Toggle');
            if (_sp213Toggle) _sp213Toggle.checked = true;
            logAI('SP213 activé — ouverture du studio…');
            const base = window.location.origin + window.location.pathname.replace(/[^\/]*$/, '');
            // Le studio est à la racine, l'app dans /app/ → remonter d'un niveau
            const url = base + '../sp213-studio.html';
            const win = window.open(url, '_blank', 'noopener');
            if (!win) {
                // Popup bloqué → fallback par lien cliquable
                const a = document.createElement('a');
                a.href = url;
                a.target = '_blank';
                a.rel = 'noopener';
                document.body.appendChild(a);
                a.click();
                a.remove();
                logAI('Popup bloqué ? Si rien ne s\'ouvre, ouvrez manuellement : ' + url);
            }
        }
        window.openSp213Studio = openSp213Studio;

