    // est AUTORITAIRE quand il est présent. Cela rend la compréhension non ambiguë → résultats plus probants.
    const _aiDocType = window._aiDocType || 'auto';
    if (_aiDocType === 'multi') {
        const _uiCount = parseInt((document.getElementById('aiPageCount') || {}).value, 10);
        _requestedPages = (!isNaN(_uiCount) && _uiCount > 1) ? _uiCount : (_requestedPages > 1 ? _requestedPages : 8);
        _isMultiPageRequest = true;
    } else if (_aiDocType === 'single' || _aiDocType === 'spread') {
        _requestedPages = 0;
        _isMultiPageRequest = false;
    }

