        function updateUnitsForLanguage() {
    const units = unitsPerLanguage[currentLanguage] || ['mm', 'cm'];
    const unitToggle = document.querySelector('.unit-toggle');
    
    if (unitToggle) {
        unitToggle.innerHTML = '';
        const toggleUnits = units.slice();
        const preferredUnit = toggleUnits.includes(currentUnit) ? currentUnit : toggleUnits[0];

        toggleUnits.forEach((unit) => {
            const btn = document.createElement('div');
            btn.className = `unit-btn ${unit === preferredUnit ? 'active' : ''}`;
            btn.dataset.unit = unit;
            btn.textContent = unit;
            // Localized titles for units
            if (currentLanguage === 'ja') {
                btn.title = unit === 'mm' ? 'ミリメートル' : unit === 'cm' ? 'センチメートル' : unit === 'px' ? 'ピクセル' : 'インチ';
            } else if (currentLanguage === 'en') {
                btn.title = unit === 'mm' ? 'Millimeters' : unit === 'cm' ? 'Centimeters' : unit === 'px' ? 'Pixels' : 'Inches';
            } else {
                btn.title = unit === 'mm' ? 'Millimêtres' : unit === 'cm' ? 'Centimêtres' : unit === 'px' ? 'Pixels' : 'Pouces';
            }
            unitToggle.appendChild(btn);

            // Ajouter l'event listener
            btn.addEventListener('click', () => {
                document.querySelectorAll('.unit-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                if (typeof currentUnit !== 'undefined') {
                    currentUnit = unit;
                    // Adapter steps des inputs de transformation selon l'unité
                    const step = currentUnit === 'cm' ? 0.01 : currentUnit === 'in' ? 0.01 : currentUnit === 'px' ? 1 : 0.1;
                    ['transformX','transformY','transformW','transformH'].forEach(id => {
                        const el = document.getElementById(id);
                        if (el) el.step = step;
                    });
                }
            });
        });
        // Mettre currentUnit par défaut selon la langue (première unité)
        if (typeof currentUnit !== 'undefined') {
            currentUnit = preferredUnit;
            // Adapter steps au défaut
            const step = currentUnit === 'cm' ? 0.01 : currentUnit === 'in' ? 0.01 : currentUnit === 'px' ? 1 : 0.1;
            ['transformX','transformY','transformW','transformH'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.step = step;
            });
        }
    }

    // Mettre à jour aussi les unités dans les réglages
    const settingsUnits = document.getElementById('settingsUnits');
    if (settingsUnits) {
        settingsUnits.innerHTML = '';
        units.forEach((unit, index) => {
            const btn = document.createElement('button');
            btn.className = `btn btn-secondary ${index === 0 ? 'active' : ''}`;
            btn.dataset.unit = unit;
            if (currentLanguage === 'en' || currentLanguage === 'ja') {
                btn.textContent = unit === 'mm' ? 'Millimeters (mm)' : unit === 'cm' ? 'Centimeters (cm)' : 'Pixels (px)';
            } else {
                // FR ou autres
                btn.textContent = unit === 'mm' ? 'Millimêtres (mm)' : unit === 'cm' ? 'Centimêtres (cm)' : 'Pixels (px)';
            }
            settingsUnits.appendChild(btn);
        });
    }
        }

        function setLanguage(lang) {
    currentLanguage = lang;
    localStorage.setItem('sp_lang', lang);
    document.documentElement.lang = lang;
    updateInterface();
    // Adapter unités et suffixes pour les labels de dimensions de page
    const wLabel = document.getElementById('labelPageW');
    const hLabel = document.getElementById('labelPageH');
    if (wLabel && hLabel) {
        const suffix = (currentLanguage === 'en') ? 'in' : 'mm';
        if (currentLanguage === 'fr') {
            wLabel.textContent = `L (${suffix})`;
            hLabel.textContent = `H (${suffix})`;
        } else if (currentLanguage === 'ja') {
            wLabel.textContent = `W (${suffix})`;
            hLabel.textContent = `H (${suffix})`;
        } else {
            wLabel.textContent = `W (${suffix})`;
            hLabel.textContent = `H (${suffix})`;
        }
    }
    // Conversion des valeurs de page et marges si langue EN => inches, sinon mm
    try {
        if (currentLanguage === 'en') {
            // Convertir mm -> in pour affichage
            document.getElementById('pageWidth').value = mmToIn(pageFormat.width).toFixed(2);
            document.getElementById('pageHeight').value = mmToIn(pageFormat.height).toFixed(2);
            document.getElementById('margin').value = mmToIn(margin).toFixed(2);
            document.getElementById('bleed').value = mmToIn(bleed).toFixed(2);
        } else {
            // Afficher mm
            document.getElementById('pageWidth').value = pageFormat.width;
            document.getElementById('pageHeight').value = pageFormat.height;
            document.getElementById('margin').value = margin;
            document.getElementById('bleed').value = bleed;
        }
    } catch {}
        }

        // ========== TYPOGRAPHY STYLES (Widget + Modal) ==========
        let typographyStyles = [];

        function defaultTypographyStyles() {
    return [
        { id: 'title', name: 'Titre', fontFamily: 'Open Sans', fontSize: 28, fontWeight: '700', lineHeight: 1.15, charSpacing: 0, fill: '#000000', textAlign: 'left' },
        { id: 'subtitle', name: 'Sous-titre', fontFamily: 'Open Sans', fontSize: 18, fontWeight: '600', lineHeight: 1.2, charSpacing: 0, fill: '#111111', textAlign: 'left' },
        { id: 'body', name: 'Corps', fontFamily: 'Open Sans', fontSize: 12, fontWeight: '400', lineHeight: 1.4, charSpacing: 0, fill: '#222222', textAlign: 'left' },
        { id: 'caption', name: 'Légende', fontFamily: 'Open Sans', fontSize: 10, fontWeight: '400', lineHeight: 1.2, charSpacing: 50, fill: '#333333', textAlign: 'left' }
    ];
        }

        function loadTypographyStyles() {
    try {
        const raw = localStorage.getItem('sp_typo_styles');
        typographyStyles = raw ? JSON.parse(raw) : defaultTypographyStyles();
    } catch {
        typographyStyles = defaultTypographyStyles();
    }
        }

        function saveTypographyStyles() {
    try { localStorage.setItem('sp_typo_styles', JSON.stringify(typographyStyles)); } catch {}
        }

        function renderTypographyStylesList() {
    const list = document.getElementById('typoStylesList');
    if (!list) return;
    // Preserve the add button
    const addBtn = document.getElementById('typoStyleAddBtn');
    list.innerHTML = '';
    typographyStyles.forEach((st, idx) => {
        const item = document.createElement('div');
        item.className = 'typo-style-item';
        item.dataset.index = String(idx);
        item.innerHTML = `
            <span>${st.name}</span>
            <div style="display:flex; gap:3px; align-items:center;">
                <small>${st.fontFamily || ''} à ${st.fontSize || ''}</small>
                <button class="icon-btn" title="Mettre à jour partout" data-action="updateAll" style="background:none; border:none; cursor:pointer; padding:2px; color:#0066cc;">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"></polyline><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"></path></svg>
                </button>
                <button class="icon-btn" title="Edit" data-translate-title="edit" data-action="edit" style="background:none; border:none; cursor:pointer; padding:2px; color:#666;">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>
                </button>
                <button class="icon-btn" title="Delete" data-translate-title="delete" data-action="delete" style="background:none; border:none; cursor:pointer; padding:2px; color:#666;">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>
                </button>
            </div>`;
        // Apply on click on main label area only
        item.addEventListener('click', (e) => {
            const actionBtn = e.target.closest('button');
            if (actionBtn) return; // handled separately
            e.stopPropagation();
            applyTypographyStyle(st);
        });
        // Edit / Delete handlers
        item.querySelector('[data-action="updateAll"]').addEventListener('click', (e) => {
            e.stopPropagation();
            updateAllStyleInstances(st.id);
        });
        item.querySelector('[data-action="edit"]').addEventListener('click', (e) => {
            e.stopPropagation();
            openEditStyleModal(idx);
        });
        item.querySelector('[data-action="delete"]').addEventListener('click', (e) => {
            e.stopPropagation();
            deleteTypographyStyle(idx);
        });
        list.appendChild(item);
    });
    if (addBtn) list.appendChild(addBtn);
    // Update i18n header/labels
    const hdr = document.querySelector('#typoStylesWidget [data-translate="stylesHeader"]');
    if (hdr) hdr.textContent = translate('stylesHeader');
    const addLbl = document.getElementById('typoStyleAddBtn');
    if (addLbl) addLbl.textContent = translate('addStyle');
        }

        // Fonction pour amener un widget au premier plan
        let widgetZIndexCounter = 100;
        function bringWidgetToFront(widgetElement) {
    widgetZIndexCounter++;
    widgetElement.style.zIndex = widgetZIndexCounter;
        }

        function applyTypographyStyle(style) {
    const activeCanvas = getActiveCanvas();
    if (!activeCanvas) return;

    const target = activeCanvas.getActiveObject();
    const applyToText = (obj) => {
        if (obj && obj.type === 'textbox') {
            // 🎯 v1.7.122 : si l'utilisateur édite le bloc avec une sélection partielle
            //    (du texte surligné), appliquer le style UNIQUEMENT à cette sélection
            //    (caractère-par-caractère via setSelectionStyles), sans toucher au bloc.
            const _selStart = (typeof obj.selectionStart === 'number') ? obj.selectionStart : 0;
            const _selEnd = (typeof obj.selectionEnd === 'number') ? obj.selectionEnd : _selStart;
            const _isEditing = !!obj.isEditing;
            const _hasPartialSel = _isEditing && _selEnd > _selStart;
            if (_hasPartialSel) {
                const inlineStyle = {};
                if (style.fontFamily) inlineStyle.fontFamily = style.fontFamily;
                if (style.fontSize) inlineStyle.fontSize = style.fontSize;
                if (style.fontWeight) inlineStyle.fontWeight = style.fontWeight;
                if (typeof style.charSpacing === 'number') inlineStyle.charSpacing = style.charSpacing;
                if (style.fill) inlineStyle.fill = style.fill;
                // NB: lineHeight et textAlign sont des propriétés bloc/paragraphe,
                //     pas appliquées à une sélection partielle.
                try { obj.setSelectionStyles(inlineStyle, _selStart, _selEnd); } catch (_) {}
                try { obj._clearCache && obj._clearCache(); } catch (_) {}
                try { obj.initDimensions && obj.initDimensions(); } catch (_) {}
                obj.setCoords && obj.setCoords();
                return; // ne pas écraser le bloc entier
            }

            const fixedW = obj._fixedWidth ?? obj.width;
            const fixedH = obj._fixedHeight ?? obj.height;

            obj.set({
                fontFamily: style.fontFamily || obj.fontFamily,
                fontSize: style.fontSize || obj.fontSize,
                fontWeight: style.fontWeight || obj.fontWeight,
                lineHeight: style.lineHeight || obj.lineHeight,
                charSpacing: (typeof style.charSpacing === 'number') ? style.charSpacing : obj.charSpacing,
                fill: style.fill || obj.fill,
                textAlign: style.textAlign || obj.textAlign
            });
            // Tag pour "mettre à jour partout"
            if (style.id) obj._appliedStyleId = style.id;

            // 🔒 Restaurer dimensions fixes puis rewrap (éviter dépassement)
            try {
                obj._fixedWidth = fixedW;
                obj._fixedHeight = fixedH;
                obj.width = fixedW;
                obj.height = fixedH;
            } catch (_) {}

            try { obj._clearCache && obj._clearCache(); } catch (_) {}
            try { obj._styleMap = null; } catch (_) {}
            try { obj.initDimensions && obj.initDimensions(); } catch (_) {}
            try { spForceTextboxRewrap(obj); } catch (_) {}
            try { spEnsureTextboxWrapWithinWidth(obj); } catch (_) {}
            try { applyTextboxClipPath(obj); } catch (_) {}
            obj.setCoords();

            // ✨ Rewrap après chargement effectif des polices
            if (document.fonts && document.fonts.ready) {
                document.fonts.ready.then(() => {
                    try {
                        obj._fixedWidth = fixedW;
                        obj._fixedHeight = fixedH;
                        obj.width = fixedW;
                        obj.height = fixedH;
                    } catch (_) {}
                    try { spForceTextboxRewrap(obj); } catch (_) {}
                    try { spEnsureTextboxWrapWithinWidth(obj); } catch (_) {}
                    try { applyTextboxClipPath(obj); } catch (_) {}
                    obj.setCoords();
                    activeCanvas.requestRenderAll();
                }).catch(() => {});
            }
        }
    };

    // 🎯 v1.7.122 : si l'utilisateur édite un textbox avec une sélection partielle,
    //    ne pas discardActiveObject (sinon on quitte l'édition et on perd la sélection).
    const _keepEditing = !!(target && target.type === 'textbox' && target.isEditing
        && typeof target.selectionStart === 'number' && typeof target.selectionEnd === 'number'
        && target.selectionEnd > target.selectionStart);

    if (target && target.type === 'activeSelection') {
        target._objects.forEach(applyToText);
    } else {
        applyToText(target);
    }
    if (!_keepEditing) {
        activeCanvas.discardActiveObject();
    }
    activeCanvas.requestRenderAll();
    updateTransformPanel(); // Mettre à jour l'affichage après application du style
    saveState('Style typographique appliqué');
        }

        function openCreateStyleModal() {
    const ov = document.getElementById('createStyleModal');
    if (ov) {
        // Populate font families dropdown
        try {
            const select = document.getElementById('styleFontFamily');
            if (select) {
                select.innerHTML = '';
                const fonts = getAllAvailableFontFamilies();
                fonts.forEach(f => {
                    const opt = document.createElement('option');
                    opt.value = f;
                    opt.textContent = f + (isCustomFont(f) ? ' (Custom)' : '');
                    select.appendChild(opt);
                });
                // Hook change to update weight list
                select.addEventListener('change', updateStyleWeightsOptions);
                updateStyleWeightsOptions();
                // Hook preview listeners
                const previewInputs = ['styleFontFamily','styleFontSize','styleFontWeight','styleLineHeight','styleLetterSpacing','styleColor','styleAlign'];
                previewInputs.forEach(id => {
                    const el = document.getElementById(id);
                    if (el) el.addEventListener('input', updateStylePreviewBox);
                    if (el) el.addEventListener('change', updateStylePreviewBox);
                });
                updateStylePreviewBox();
            }
        } catch {}
        ov.classList.add('active');
    }
        }
        function closeCreateStyleModal() {
    const ov = document.getElementById('createStyleModal');
    if (ov) ov.classList.remove('active');
        }
        function saveNewTypographyStyle() {
    const name = (document.getElementById('styleName')?.value || '').trim();
    if (!name) { closeCreateStyleModal(); return; }
    const fontFamily = (document.getElementById('styleFontFamily')?.value || 'Open Sans').trim();
    const fontSize = parseFloat(document.getElementById('styleFontSize')?.value || '14');
    const fontWeight = (document.getElementById('styleFontWeight')?.value || '400');
    // 🎯 v1.7.123 : interlignage saisi en pt, converti en multiplicateur Fabric
    const lineHeightPt = parseFloat(document.getElementById('styleLineHeight')?.value || String(fontSize * 1.2));
    const lineHeight = (fontSize > 0) ? (lineHeightPt / fontSize) : 1.2;
    const charSpacing = parseInt(document.getElementById('styleLetterSpacing')?.value || '0', 10);
    const fill = document.getElementById('styleColor')?.value || '#000000';
    const textAlign = document.getElementById('styleAlign')?.value || 'left';
    const id = `${name.toLowerCase().replace(/\s+/g,'-')}-${Date.now()}`;

    const style = { id, name, fontFamily, fontSize, fontWeight, lineHeight, charSpacing, fill, textAlign };
    typographyStyles.push(style);
    saveTypographyStyles();
    renderTypographyStylesList();
    closeCreateStyleModal();
        }

        function openEditStyleModal(index) {
    const st = typographyStyles[index];
    if (!st) return;
    openCreateStyleModal();
    // Prefill
    const setVal = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };
    setVal('styleName', st.name);
    setVal('styleFontFamily', st.fontFamily || 'Open Sans');
    updateStyleWeightsOptions();
    setVal('styleFontWeight', st.fontWeight || '400');
    setVal('styleFontSize', st.fontSize || 14);
    // 🎯 v1.7.123 : afficher l'interlignage en pt (multiplier × fontSize)
    {
        const _fs = parseFloat(st.fontSize) || 14;
        const _lhMult = (typeof st.lineHeight === 'number' && st.lineHeight > 0) ? st.lineHeight : 1.2;
        setVal('styleLineHeight', Math.round((_lhMult * _fs) * 10) / 10);
    }
    setVal('styleLetterSpacing', st.charSpacing || 0);
    setVal('styleColor', st.fill || '#000000');
    setVal('styleAlign', st.textAlign || 'left');
    updateStylePreviewBox();
    // Overwrite save to update existing
    const saveBtn = document.querySelector('#createStyleModal .modal-footer .btn:not(.btn-secondary)');
    if (saveBtn) {
        const originalHandler = saveNewTypographyStyle;
        saveBtn.onclick = () => {
            const name = (document.getElementById('styleName')?.value || '').trim();
            if (!name) { closeCreateStyleModal(); return; }
            const _fs = parseFloat(document.getElementById('styleFontSize')?.value || '14');
            const _lhPt = parseFloat(document.getElementById('styleLineHeight')?.value || String(_fs * 1.2));
            const _lhMult = (_fs > 0) ? (_lhPt / _fs) : 1.2;
            const style = {
                ...st,
                name,
                fontFamily: (document.getElementById('styleFontFamily')?.value || 'Open Sans').trim(),
                fontSize: _fs,
                fontWeight: (document.getElementById('styleFontWeight')?.value || '400'),
                lineHeight: _lhMult,
                charSpacing: parseInt(document.getElementById('styleLetterSpacing')?.value || '0', 10),
                fill: document.getElementById('styleColor')?.value || '#000000',
                textAlign: document.getElementById('styleAlign')?.value || 'left'
            };
            typographyStyles[index] = style;
            saveTypographyStyles();
            renderTypographyStylesList();
            closeCreateStyleModal();
        };
    }
        }

        function deleteTypographyStyle(index) {
    const st = typographyStyles[index];
    if (!st) return;
    const msg = translate('confirmDeleteStyle') || 'Delete this style?';
    if (!confirm(msg + `\n\n${st.name}`)) return;
    typographyStyles.splice(index,1);
    saveTypographyStyles();
    renderTypographyStylesList();
        }

        // ── Mettre à jour tous les blocs qui utilisent ce style ──
        function updateAllStyleInstances(styleId) {
    const style = typographyStyles.find(s => s.id === styleId);
    if (!style) return;
    let count = 0;
    canvases.forEach(c => {
        if (!c) return;
        let changed = false;
        c.getObjects().filter(o => o.type === 'textbox' && o._appliedStyleId === styleId).forEach(obj => {
            const fixedW = obj._fixedWidth ?? obj.width;
            const fixedH = obj._fixedHeight ?? obj.height;
            obj.set({
                fontFamily: style.fontFamily || obj.fontFamily,
                fontSize: style.fontSize || obj.fontSize,
                fontWeight: style.fontWeight || obj.fontWeight,
                lineHeight: style.lineHeight || obj.lineHeight,
                charSpacing: (typeof style.charSpacing === 'number') ? style.charSpacing : obj.charSpacing,
                fill: style.fill || obj.fill,
                textAlign: style.textAlign || obj.textAlign
            });
            try { obj._fixedWidth = fixedW; obj._fixedHeight = fixedH; obj.width = fixedW; obj.height = fixedH; } catch (_) {}
            try { spForceTextboxRewrap(obj); } catch (_) {}
            try { obj.setCoords(); } catch (_) {}
            changed = true; count++;
        });
        if (changed) c.requestRenderAll();
    });
    if (count > 0) saveState(`Style "${style.name}" mis à jour`);
    const msg = count > 0 ? `${count} bloc${count > 1 ? 's' : ''} mis à jour` : 'Aucun bloc avec ce style';
    if (typeof showToast === 'function') showToast(msg, count > 0 ? 'success' : 'info');
        }

        // ── Find & Replace ──
        let _frMatches = [];
        let _frCurrentIdx = 0;

        function openFindReplace(showReplace) {
    const panel = document.getElementById('findReplacePanel');
    if (!panel) return;
    panel.style.display = 'block';
    const inp = document.getElementById('findInput');
    if (inp) { inp.value = ''; inp.focus(); }
    const cnt = document.getElementById('findMatchCount'); if (cnt) cnt.textContent = '';
    const st = document.getElementById('findReplaceStatus'); if (st) st.textContent = '';
    const ri = document.getElementById('replaceInput'); if (ri) ri.value = '';
    _frMatches = []; _frCurrentIdx = 0;
        }

        function closeFindReplace() {
    const panel = document.getElementById('findReplacePanel');
    if (panel) panel.style.display = 'none';
    canvases.forEach(c => {
        const active = c && c.getActiveObject();
        if (active && active.isEditing) { try { active.exitEditing(); } catch (_) {} }
    });
    _frMatches = []; _frCurrentIdx = 0;
        }

        function findInDocument() {
    const query = document.getElementById('findInput')?.value || '';
    _frMatches = []; _frCurrentIdx = 0;
    const cnt = document.getElementById('findMatchCount');
    const st = document.getElementById('findReplaceStatus');
    if (!query) { if (cnt) cnt.textContent = ''; if (st) st.textContent = ''; return; }
    const lower = query.toLowerCase();
    canvases.forEach((c, ci) => {
        if (!c) return;
        c.getObjects().filter(o => (o.type === 'textbox' || o.type === 'text') && !o.excludeFromExport && !o.isMargin).forEach(obj => {
            const text = obj.text || '';
            let pos = 0;
            while ((pos = text.toLowerCase().indexOf(lower, pos)) !== -1) {
                _frMatches.push({ ci, obj, start: pos });
                pos += lower.length;
            }
        });
    });
    if (cnt) cnt.textContent = _frMatches.length ? `${_frMatches.length} rés.` : '∅';
    if (_frMatches.length > 0) { _frCurrentIdx = 0; _frHighlight(_frCurrentIdx); }
        }

        function _frHighlight(idx) {
    const match = _frMatches[idx];
    if (!match) return;
    const canvas = canvases[match.ci];
    if (!canvas) return;
    try { canvas.lowerCanvasEl?.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (_) {}
    canvas.setActiveObject(match.obj);
    try {
        match.obj.enterEditing();
        const q = document.getElementById('findInput')?.value || '';
        match.obj.setSelectionStart(match.start);
        match.obj.setSelectionEnd(match.start + q.length);
    } catch (_) {}
    canvas.requestRenderAll();
    const cnt = document.getElementById('findMatchCount');
    if (cnt) cnt.textContent = `${idx + 1}/${_frMatches.length}`;
        }

        function findNext() {
    if (!_frMatches.length) return;
    _frCurrentIdx = (_frCurrentIdx + 1) % _frMatches.length;
    _frHighlight(_frCurrentIdx);
        }

        function findPrev() {
    if (!_frMatches.length) return;
    _frCurrentIdx = (_frCurrentIdx - 1 + _frMatches.length) % _frMatches.length;
    _frHighlight(_frCurrentIdx);
        }

        function replaceOne() {
    if (!_frMatches.length) return;
    const match = _frMatches[_frCurrentIdx];
    if (!match) return;
    const q = document.getElementById('findInput')?.value || '';
    const rep = document.getElementById('replaceInput')?.value || '';
    const obj = match.obj;
    obj.text = obj.text.substring(0, match.start) + rep + obj.text.substring(match.start + q.length);
    obj.dirty = true;
    if (canvases[match.ci]) canvases[match.ci].requestRenderAll();
    saveState('Remplacement');
    findInDocument();
        }

        function _spReplaceAll() {
    const q = document.getElementById('findInput')?.value || '';
    const rep = document.getElementById('replaceInput')?.value || '';
    if (!q || !_frMatches.length) return;
    const re = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
    const touched = new Set(_frMatches.map(m => m.obj));
    let count = 0;
    touched.forEach(obj => {
        const before = obj.text;
        obj.text = obj.text.replace(re, rep);
        if (obj.text !== before) { count++; obj.dirty = true; }
    });
    canvases.forEach(c => { if (c) c.requestRenderAll(); });
    const status = document.getElementById('findReplaceStatus');
    if (status) status.textContent = count ? `${count} remplacement${count > 1 ? 's' : ''} effectué${count > 1 ? 's' : ''}` : 'Aucun remplacement';
    if (count > 0) saveState('Remplacer tout');
    findInDocument();
        }

        // ── Export PNG / JPG ──
        function _spRenderCanvasForImageExport(c, format, multiplier, opts) {
            opts = opts || {};
            const transparent = !!opts.transparent && format === 'png';
            // Exporter la PAGE ENTIÈRE (incluant les fonds perdus / bleed), comme le PDF.
            // On exclut uniquement la zone pasteboard autour, ainsi que les repères visuels
            // (filets de marge, filet bleed, guides, traits de coupe, etc.).
            const bi = c.bleedInfo || {};
            const pbPx  = bi.pasteboardPx  || 0;
            const pbVPx = bi.pasteboardVPx || 0;
            const pageCW = bi.pageCanvasWidth  || c.getWidth();
            const pageCH = bi.pageCanvasHeight || c.getHeight();
            const cropLeft = pbPx;
            const cropTop  = pbVPx;
            const cropW    = Math.max(1, pageCW);
            const cropH    = Math.max(1, pageCH);

            // Masquer marges, filets de fonds perdus, repères, guides, traits de coupe,
            // ET tous les indicateurs d'édition (badges/flèches de chaînage, indicateurs
            // de débordement). Liste alignée avec celle du PDF (saveAllPages + confirmExport).
            // (le contenu graphique placé dans la zone bleed reste exporté)
            const hidden = [];
            c.getObjects().forEach(o => {
                if (!o) return;
                const isMark = o.isMargin || o.isBleed || o.isGuide || o.isManualGuide
                    || o.isTrimBox || o.excludeFromExport
                    || o._isChainBadge || o._isLinkArrow || o._isOverflowIndicator;
                if (isMark && o.visible !== false) {
                    hidden.push(o);
                    o.visible = false;
                }
            });

            // 🎯 v1.7.125 : pour PNG transparent, neutraliser le backgroundColor du canvas
            //   le temps de l'export, puis restaurer. JPG est ignoré (pas de transparence).
            const _prevBg = c.backgroundColor;
            if (transparent) {
                try { c.backgroundColor = null; } catch (_) {}
            }

            let dataUrl;
            try {
                dataUrl = c.toDataURL({
                    format,
                    multiplier,
                    quality: 0.92,
                    left: cropLeft,
                    top: cropTop,
                    width: cropW,
                    height: cropH
                });
            } finally {
                if (transparent) {
                    try { c.backgroundColor = _prevBg; } catch (_) {}
                }
                hidden.forEach(o => { o.visible = true; });
                c.requestRenderAll();
            }
            return dataUrl;
        }

        function exportPagesAsImages(format) {
    const quality = document.querySelector('input[name="exportQuality"]:checked')?.value || 'standard';
    const multiplierMap = { standard: 1, medium: 2, hd: 4 };
    const multiplier = multiplierMap[quality] || 1;
    const ext = format === 'jpeg' ? 'jpg' : 'png';
    const isBW = !!document.getElementById('colorBW')?.checked;
    // 🎯 v1.7.125 : option fond transparent (PNG uniquement)
    const pngBg = document.querySelector('input[name="pngBg"]:checked')?.value || 'white';
    const wantTransparent = (format === 'png' && pngBg === 'transparent');
    if (typeof saveAllPages === 'function') saveAllPages();
    const exportCvs = canvases.filter(Boolean);
    if (exportCvs.length === 0) return;

    const maybeBW = async (dataUrl) => {
        if (!isBW) return dataUrl;
        const fmt = format === 'jpeg' ? 'jpeg' : 'png';
        return await convertToGrayscale(dataUrl, fmt, 0.92);
    };

    (async () => {
        const pageData = [];
        for (let i = 0; i < exportCvs.length; i++) {
            let d = _spRenderCanvasForImageExport(exportCvs[i], format, multiplier, { transparent: wantTransparent });
            d = await maybeBW(d);
            pageData.push(d);
        }

        if (pageData.length === 1) {
            _spDownloadDataUrl(pageData[0], `page-1.${ext}`);
            closeExportModal();
            return;
        }
        await ensureZipLib(); // 🚀 Perf : JSZip chargé à la demande (voir ensureZipLib)
        if (typeof JSZip !== 'undefined') {
            const zip = new JSZip();
            pageData.forEach((dataUrl, i) => {
                zip.file(`page-${i + 1}.${ext}`, dataUrl.split(',')[1], { base64: true });
            });
            zip.generateAsync({ type: 'blob' }).then(blob => {
                const url = URL.createObjectURL(blob);
                _spDownloadDataUrl(url, `superprint-${ext}.zip`);
                setTimeout(() => URL.revokeObjectURL(url), 3000);
            });
        } else {
            pageData.forEach((dataUrl, i) => {
                _spDownloadDataUrl(dataUrl, `page-${i + 1}.${ext}`);
            });
        }
        closeExportModal();
    })();
        }

        function _spDownloadDataUrl(url, filename) {
    const a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click();
    document.body.removeChild(a);
        }

        function updateStylePreviewBox() {
    const box = document.getElementById('stylePreviewBox');
    if (!box) return;
    const fam = document.getElementById('styleFontFamily')?.value || 'Open Sans';
    const size = parseFloat(document.getElementById('styleFontSize')?.value || '14');
    const weight = document.getElementById('styleFontWeight')?.value || '400';
    // 🎯 v1.7.123 : interlignage saisi en pt → multiplicateur pour le rendu CSS
    const lhPt = parseFloat(document.getElementById('styleLineHeight')?.value || String(size * 1.2));
    const lh = (size > 0) ? (lhPt / size) : 1.2;
    const cs = parseInt(document.getElementById('styleLetterSpacing')?.value || '0', 10);
    const color = document.getElementById('styleColor')?.value || '#000000';
    const align = document.getElementById('styleAlign')?.value || 'left';
    box.style.fontFamily = fam;
    box.style.fontSize = `${size}px`;
    box.style.fontWeight = weight;
    box.style.lineHeight = String(lh);
    box.style.letterSpacing = `${cs/1000}em`;
    box.style.color = color;
    // CSS ne gère pas 'justify-left' nativement — on retombe sur 'justify' pour l'aperçu
    box.style.textAlign = (align === 'justify' || align === 'justify-left') ? 'justify' : align;
        }

        function setupDraggableStylesWidget() {
    const widget = document.getElementById('typoStylesWidget');
    const header = document.getElementById('typoStylesToggle');
    const container = document.getElementById('widgetsOverlay') || document.getElementById('canvasScrollArea');
    if (!widget || !header || !container) return;

    // Restore saved position (ou positionner en bas à gauche par défaut)
    setTimeout(() => {
        try {
            const saved = JSON.parse(localStorage.getItem('sp_styles_widget_pos') || 'null');
            if (saved && typeof saved.x === 'number' && typeof saved.y === 'number') {
                widget.style.left = saved.x + 'px';
                widget.style.top = saved.y + 'px';
                widget.style.bottom = 'auto';
                widget.style.right = 'auto';
            } else {
                // Position par défaut : en bas à gauche (troisième position)
                widget.style.left = '16px';
                widget.style.top = 'auto';
                widget.style.bottom = '144px';
                widget.style.right = 'auto';
            }
        } catch {}
    }, 100);

    let isDown = false;
    let startX = 0, startY = 0, originLeft = 0, originTop = 0;

    header.addEventListener('mousedown', (e) => {
        isDown = true;
        widget.dataset.dragging = '0';
        const rect = widget.getBoundingClientRect();
        const containerRect = container.getBoundingClientRect();
        startX = e.clientX;
        startY = e.clientY;
        originLeft = rect.left - containerRect.left;
        originTop = rect.top - containerRect.top;
        document.body.style.userSelect = 'none';
    });
    document.addEventListener('mousemove', (e) => {
        if (!isDown) return;
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        // Threshold to consider it a drag
        if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
            if (widget.dataset.dragging !== '1') widget.dataset.dragging = '1';
            let x = originLeft + dx;
            let y = originTop + dy;
            // Constrain within container bounds
            const contRect = container.getBoundingClientRect();
            const wRect = widget.getBoundingClientRect();
            const maxX = contRect.width - wRect.width;
            const maxY = contRect.height - wRect.height;
            x = Math.max(0, Math.min(x, maxX));
            y = Math.max(0, Math.min(y, maxY));
            widget.style.left = x + 'px';
            widget.style.top = y + 'px';
            widget.style.bottom = 'auto';
        }
    });
    document.addEventListener('mouseup', () => {
        if (!isDown) return;
        isDown = false;
        const wasDragging = widget.dataset.dragging === '1';
        setTimeout(() => { widget.dataset.dragging = '0'; }, 50);
        document.body.style.userSelect = '';
        // Save position
        if (wasDragging) {
            const left = parseInt(widget.style.left || '16', 10) || 0;
            const top = parseInt(widget.style.top || '16', 10) || 0;
            try { localStorage.setItem('sp_styles_widget_pos', JSON.stringify({ x: left, y: top })); } catch {}
        }
    });
        }

