        // Fonction de conversion RGB vers CMYK (pour l'affichage print professionnel)
        // Délègue à l'utilitaire unifié _spCmykConvert.
        function rgbToCMYK(r, g, b) {
            const conv = (typeof window._spCmykConvert === 'function')
                ? window._spCmykConvert(r, g, b)
                : (function(){
                    const rn=r/255, gn=g/255, bn=b/255;
                    const k = 1 - Math.max(rn,gn,bn);
                    if (k>=1) return {c:0,m:0,y:0,k:1};
                    return { c:(1-rn-k)/(1-k), m:(1-gn-k)/(1-k), y:(1-bn-k)/(1-k), k };
                })();
            return {
                c: Math.round(conv.c * 100),
                m: Math.round(conv.m * 100),
                y: Math.round(conv.y * 100),
                k: Math.round(conv.k * 100)
            };
        }

        // Extraire RGB depuis différents formats de couleur
        function extractRGB(color) {
    if (!color) return null;

    // Format hex (#RRGGBB ou #RGB)
    if (color.startsWith('#')) {
        const hex = color.slice(1);
        let r, g, b;
        if (hex.length === 3) {
            r = parseInt(hex[0] + hex[0], 16);
            g = parseInt(hex[1] + hex[1], 16);
            b = parseInt(hex[2] + hex[2], 16);
        } else if (hex.length === 6) {
            r = parseInt(hex.slice(0, 2), 16);
            g = parseInt(hex.slice(2, 4), 16);
            b = parseInt(hex.slice(4, 6), 16);
        }
        return { r, g, b };
    }

    // Format rgba(r, g, b, a)
    const rgbaMatch = color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    if (rgbaMatch) {
        return {
            r: parseInt(rgbaMatch[1]),
            g: parseInt(rgbaMatch[2]),
            b: parseInt(rgbaMatch[3])
        };
    }

    // Pour les dégradés, extraire la première couleur
    if (color.includes('gradient')) {
        const hexMatch = color.match(/#[0-9A-Fa-f]{6}/);
        if (hexMatch) {
            return extractRGB(hexMatch[0]);
        }
    }

    return null;
        }

        // Formater CMYK pour l'affichage
        function formatCMYK(color) {
    const rgb = extractRGB(color);
    if (!rgb) return null;

    const cmyk = rgbToCMYK(rgb.r, rgb.g, rgb.b);
    return `C${cmyk.c} M${cmyk.m} Y${cmyk.y} K${cmyk.k}`;
        }

