    // Styles widget events
    const widget = document.getElementById('typoStylesWidget');
    const toggle = document.getElementById('typoStylesToggle');
    const addBtn = document.getElementById('typoStyleAddBtn');
    const arrow = toggle ? toggle.querySelector('.typo-toggle-arrow') : null;
    
    // Toggle expand on click unless a drag actually occurred
    if (toggle) toggle.addEventListener('click', () => {
        if (widget.dataset.dragging === '1') return;
        widget.classList.toggle('expanded');
        
        // Amener le widget au premier plan
        bringWidgetToFront(widget);
        
        // Inverser la flèche
        if (arrow) {
            arrow.textContent = widget.classList.contains('expanded') ? '▸' : '▾';
        }
    });
    if (addBtn) addBtn.addEventListener('click', (e) => { e.stopPropagation(); openCreateStyleModal(); });

    // Initialize styles from storage and render
    loadTypographyStyles();
