    // Layouts exemple - Collection professionnelle enrichie
    // Helper pour créer un groupe éditable (double-clic pour entrer dans le groupe)
    const addAssetObjects = (canvas, objs, assetName) => {
        // Stabiliser dimensions des blocs texte + marquer types de blocs
        try {
            objs.forEach(o => {
                if (!o) return;
                if (o.type === 'textbox' || o.type === 'text') {
                    o.isTextBlock = true;
                    // FIX: Empêcher la contraction automatique et assurer la stabilité
                    // On force une largeur fixe pour éviter l'effet "snap to word"
                    if (o.width != null) {
                        o._fixedWidth = o.width;
                        o.width = o.width; // Force update
                    }
                    if (o.height != null) o._fixedHeight = o.height;
                    
                    // Désactiver le comportement "fit to text" par défaut de Fabric si présent
                    o.splitByGrapheme = false;
                    
                    if (typeof spLockTextboxDimensions === 'function') {
                        spLockTextboxDimensions(o);
                    }
                    
                    o.scaleX = 1;
                    o.scaleY = 1;
                } else if (['rect', 'circle', 'ellipse', 'polygon', 'path'].includes(o.type)) {
                    o.isShapeBlock = true;
                }
            });
        } catch (_) {}

        // FIX IMAGES + ÉLÉMENTS MANQUANTS: Ajouter chaque objet individuellement (pas de groupe).
        // Regrouper des objets avec fabric.Group translate les coordonnées en coordonnées relatives
        // au centre du groupe, ce qui casse applyImagePatternToRect (masque positionné au mauvais
        // endroit) et peut faire "disparaître" des éléments hors viewport.
        const validObjs = objs.filter(Boolean);
        validObjs.forEach(o => canvas.add(o));
        if (validObjs.length > 0) {
            canvas.setActiveObject(validObjs[validObjs.length - 1]);
        }
        canvas.requestRenderAll();
        debouncedUpdateLayersPanel();
        // FIX RAM/PERF: Pas de saveState pendant la construction multi-pages.
        // buildBrochureMulti / comp.buildMulti sauvegardent une seule fois à la fin.
        if (!window._buildingMultiPage) {
            saveState(assetName);
        }
    };
    
    // Gérer le double-clic pour entrer dans un groupe et éditer les sous-éléments
    function setupGroupDoubleClickEdit(canvas) {
        canvas.on('mouse:dblclick', function(opt) {
            const target = opt.target;
            if (!target) return;
            
            // Si c'est un groupe, entrer dedans pour éditer sans déplacement
            if (target.type === 'group' || target.type === 'Group') {
                try {
                    const selection = target.toActiveSelection();
                    canvas.setActiveObject(selection);
                    canvas.requestRenderAll();
                    debouncedUpdateLayersPanel();
                    saveState('Groupe éclaté pour édition');
                } catch (e) {
                    console.warn('Double-clic groupe: fallback', e);
                }
            }
            // Si c'est un Textbox, entrer en mode édition (sans sélectionner tout)
            else if (target.type === 'textbox' || target.type === 'text' || target.type === 'i-text') {
                try { target.enterEditing(); } catch (_) {}
            }
        });
    }
    
