        // Résout un seed picsum ou des keywords unsplash en URL Unsplash réelle
        function resolveAssetImageUrl(url) {
            if (!url) return url;
            // 🆕 v1.7.173 : les URLs locales (img/auto/...) sont retournées telles quelles
            if (url.indexOf('img/auto/') === 0 || url.indexOf('/img/auto/') >= 0 || url.indexOf('data:') === 0) {
                return url;
            }
            var keywords = [];
            // picsum.photos/seed/xxx-yyy/
            var picsumMatch = url.match(/picsum\.photos\/seed\/([^/]+)\//);
            if (picsumMatch) {
                keywords = picsumMatch[1].toLowerCase().replace(/\d+/g, '').split('-').filter(Boolean);
            }
            // source.unsplash.com/.../?kw1,kw2,kw3
            var unsplashMatch = url.match(/source\.unsplash\.com\/[^?]*\?(.+)/);
            if (unsplashMatch) {
                keywords = unsplashMatch[1].toLowerCase().split(',').map(function(s) { return s.trim(); }).filter(Boolean);
            }
            if (keywords.length === 0) return url;

            // Dimensions from URL
            var w = 1200, h = 800;
            var dimMatch = url.match(/\/(\d{3,4})x(\d{3,4})/);
            if (dimMatch) { w = parseInt(dimMatch[1]); h = parseInt(dimMatch[2]); }

            // Trouver un photo ID qui correspond à un keyword
            var photoId = null;
            var hashBase = keywords.join('');
            for (var i = 0; i < keywords.length; i++) {
                var kw = keywords[i];
                if (_themePhotos[kw]) {
                    var arr = _themePhotos[kw];
                    // hash simple pour varier les photos (basé sur les keywords)
                    var idx = 0;
                    for (var c = 0; c < hashBase.length; c++) idx += hashBase.charCodeAt(c);
                    photoId = arr[idx % arr.length];
                    break;
                }
            }
            if (!photoId) {
                // Fallback : chercher une correspondance partielle
                var allKeys = Object.keys(_themePhotos);
                for (var j = 0; j < keywords.length; j++) {
                    for (var k = 0; k < allKeys.length; k++) {
                        if (keywords[j].includes(allKeys[k]) || allKeys[k].includes(keywords[j])) {
                            var arr2 = _themePhotos[allKeys[k]];
                            photoId = arr2[0];
                            break;
                        }
                    }
                    if (photoId) break;
                }
            }
            if (!photoId) return url; // fallback: return original URL
            return 'https://images.unsplash.com/photo-' + photoId + '?w=' + w + '&h=' + h + '&fit=crop&auto=format&q=80';
        }

        function applyImagePatternToRect(rect, url, canvas) {
    if (!rect || !canvas || !url) return;
    var resolvedUrl = resolveAssetImageUrl(url);
    // ✏️ v1.7.175 : pour les images locales, ne pas utiliser crossOrigin
    //   (sinon le navigateur bloque les chemins relatifs avec CORS)
    var isLocal = (resolvedUrl.indexOf('img/auto/') === 0 || resolvedUrl.indexOf('/img/auto/') >= 0 || resolvedUrl.indexOf('data:') === 0);
    var fromUrlOpts = isLocal ? {} : { crossOrigin: 'anonymous' };
    fabric.Image.fromURL(resolvedUrl, (img) => {
        try {
            if (!img) return;
            // Configurer l'image pour le masque
            img.objectCaching = false;
            img.statefullCache = false;
            img.imageSmoothing = true;
            img.imageSmoothingQuality = 'high';

            // Sauvegarder l'URL source pour remplacement ultérieur
            rect._maskImageSourceURL = resolvedUrl;

            // Sauvegarder le fill original
            if (!rect._originalFill) {
                rect._originalFill = rect.fill;
            }

            // Activer le système de masque d'image (crop/replace controls)
            rect._isImageMask = true;
            rect._maskImage = img;
            rect.objectCaching = false;
            rect.statefullCache = false;
            rect.noScaleCache = true;
            rect.needsItsOwnCache = () => false;
            rect.dirty = true;

            // Configuration initiale : COVER (remplit le cadre, pas de bandes blanches)
            rect._maskMode = 'cover';
            rect._maskPosition = 'center';
            rect._maskPositionRatioX = 0.5;
            rect._maskPositionRatioY = 0.5;
            rect._maskUserZoom = 1;
            rect._maskBackgroundColor = 'transparent';
            rect._maskFixedScale = null;
            rect.lockUniScaling = true;

            // Initialiser _previousSize pour le suivi du redimensionnement
            if (typeof getMaskShapeDisplaySize === 'function') {
                const displaySize = getMaskShapeDisplaySize(rect);
                rect._previousSize = displaySize.width;
            }

            // Générer le pattern de masque via la fonction centralisée
            if (typeof recalculateMaskPattern === 'function') {
                recalculateMaskPattern(rect, canvas);
            }

            rect.dirty = true;
            // FIX PERFS: requestRenderAll groupé par canvas pour éviter 40+ appels async
            if (!canvas._spImgRenderTimer) {
                canvas._spImgRenderTimer = setTimeout(() => {
                    canvas._spImgRenderTimer = null;
                    canvas.requestRenderAll();
                }, 80);
            }
        } catch (e) {
            console.warn('Image pattern error:', e);
        }
    }, fromUrlOpts);
}

