        const contactInfo = new fabric.Textbox('mode@magazine.com · @modemagazine · www.modemagazine.com', { left: x + 24, top: y + pageH - 50, width: pageW - 48, fontSize: 7.5, fontFamily: 'Open Sans', fill: '#444', textAlign: 'center', charSpacing: 50 });
