        const issueTag = new fabric.Textbox('N°31 — SUMMER 2026', { left: x + 28, top: y + 44, width: pageW - 56, fontSize: 7, fontFamily: 'Open Sans', fill: '#666', charSpacing: 300, textAlign: 'center' });
