        const mainSub = new fabric.Textbox('Rencontres, festivals & vinyles :\nla scène musicale en pleine renaissance', { left: x + 28, top: y + pageH - 80, width: pageW - 56, fontSize: 9.5, fontFamily: 'Open Sans', fill: '#999', lineHeight: 1.4 });
        const accentLine = new fabric.Rect({ left: x + 28, top: y + pageH * 0.53, width: 45, height: 3, fill: accent });
        objs.push(heroImg, overlay, accentLine, logoBar, issueTag, mainTitle, mainSub);
