        const entries = new fabric.Textbox('01 ─ Le son de demain\n02 ─ Portrait : artiste révélation\n03 ─ Vinyles & analogique\n04 ─ Festivals d\'été\n05 ─ Playlist exclusive\n06 ─ Studio : en coulisses\n07 ─ Chroniques albums', { left: x + 24, top: y + 60, width: leftCol - 48, fontSize: 10, fontFamily: 'Open Sans', fill: '#bbb', lineHeight: 2.0 });
        const playlistTitle = new fabric.Textbox('PLAYLIST', { left: x + leftCol + 24, top: y + 30, width: pageW - leftCol - 48, fontSize: 9, fontWeight: '800', fontFamily: 'Open Sans', fill: accent, charSpacing: 400 });
        const playlistItems = new fabric.Textbox('♪ Daft Punk — Random Access Memories\n♪ Aya Nakamura — Mélodie\n♪ Stromae — Multitude\n♪ Christine and the Queens — Chris\n♪ Justice — Audio, Video, Disco\n♪ Phoenix — Bankrupt!\n♪ Polo & Pan — Caravelle\n♪ Ibeyi — Spell 31', { left: x + leftCol + 24, top: y + 55, width: pageW - leftCol - 48, fontSize: 9, fontFamily: 'Open Sans', fill: '#aaa', lineHeight: 1.8 });
