        const overlay = new fabric.Rect({ left: bx, top: by, width: bW, height: pageH * 0.30 + bp, fill: dark, opacity: 0.6 });
        const overlayBtm = new fabric.Rect({ left: bx, top: y + pageH * 0.65, width: bW, height: pageH * 0.35 + bp, fill: dark, opacity: 0.7 });
