        const badge = new fabric.Textbox('NON-PROFIT ORGANIZATION', { left: x + 25, top: y + pageH * 0.44, width: pageW - 50, fontSize: 7, fontWeight: '700', fontFamily: 'Open Sans', fill: accent, charSpacing: 450, textAlign: 'center' });
