        const desc = new fabric.Textbox('Providing education, clean water, and healthcare\nto communities in need across 24 countries.\nYour generosity changes lives.', { left: x + 30, top: y + pageH * 0.70, width: pageW - 60, fontSize: 10, fontFamily: 'Open Sans', fill: '#a7f3d0', lineHeight: 1.7, textAlign: 'center' });
