        const ctaText = new fabric.Textbox('DONATE NOW', { left: x + pageW * 0.24, top: y + pageH * 0.84 + 10, width: pageW * 0.52, fontSize: 14, fontWeight: '800', fontFamily: 'Open Sans', fill: dark, textAlign: 'center' });
