        objs.push(new fabric.Circle({ left: x - 20, top: y - 20, radius: 60, fill: '#fecaca', opacity: 0.5 }));
        objs.push(new fabric.Circle({ left: x + pageW - 60, top: y + pageH - 80, radius: 50, fill: '#c4b5fd', opacity: 0.4 }));
        objs.push(new fabric.Circle({ left: x + pageW * 0.6, top: y + 10, radius: 35, fill: '#a7f3d0', opacity: 0.5 }));
        // Emoji
        const emoji = new fabric.Textbox('🎉🎈🎂', { left: x + pageW/2 - 60, top: y + 25, width: 120, fontSize: 32, textAlign: 'center' });
