        const sub = new fabric.Textbox('HANATSUKI', { left: x + M, top: y + heroH * 0.25 + 56, width: CW, fontSize: 9, fontFamily: F3, fill: gold, charSpacing: 500, textAlign: 'center' });
        const tagline = new fabric.Textbox('天然温泉  ·  懐石料理  ·  庭園露天風呂', { left: x + M, top: y + heroH * 0.25 + 74, width: CW, fontSize: 8, fontFamily: F, fill: '#ddd', textAlign: 'center', charSpacing: 100 });
        // Main body
