        const introT = new fabric.Textbox('箱根の隠れ宿', { left: x + M, top: bodyY + 10, width: CW, fontSize: 16, fontWeight: '700', fontFamily: F2, fill: '#fff', textAlign: 'center' });
        const introB = new fabric.Textbox('箱根湯本の静寂な森の中に佇む「花月」は、\n全8室の隠れ家温泉旅館です。\n\n源泉かけ流しの天然温泉と、\n旬の食材を活かした月替わりの懐石料理で、\n心と体をほぐすひとときをお過ごしください。', { left: x + M, top: bodyY + 34, width: CW, fontSize: 9, fontFamily: F, fill: '#ccc', lineHeight: 1.8, textAlign: 'center' });
