        const title = new fabric.Textbox('ご宿泊プラン', { left: x + M, top: y + MT + 10, width: CW, fontSize: 18, fontWeight: '700', fontFamily: F2, fill: '#fff', textAlign: 'center' });
        const titleEn = new fabric.Textbox('ACCOMMODATION PLANS', { left: x + M, top: y + MT + 34, width: CW, fontSize: 7, fontFamily: F3, fill: gold, charSpacing: 300, textAlign: 'center' });
        // Plans
        const plans = [
            ['椿の間','TSUBAKI','和室10畳+広縁\n庭園露天風呂付き\n\n季節の懐石料理（全12品）\nチェックイン 15:00 / アウト 11:00\n\nお一人様　¥38,000〜（税込）\n※ 2名1室利用時', gold],
            ['桜の間','SAKURA','和洋室 ツインベッド+畳\n展望檜内風呂付き\n\n懐石料理（全10品）\nチェックイン 15:00 / アウト 10:30\n\nお一人様　¥28,000〜（税込）\n※ 2名1室利用時', r],
            ['藤の間','FUJI','和室8畳\n大浴場・露天風呂利用\n\n季節の会席料理（全8品）\nチェックイン 15:00 / アウト 10:00\n\nお一人様　¥19,800〜（税込）\n※ 2名1室利用時', '#5a6a6a']
        ];
        const planW = (CW - 10 * 2) / 3;
