        const accRule = new fabric.Rect({ left: x + (pageW - 50) / 2, top: accY, width: 50, height: 1, fill: gold });
        const accTitle = new fabric.Textbox('アクセス · ACCESS', { left: x + M, top: accY + 8, width: CW, fontSize: 10, fontWeight: '700', fontFamily: F2, fill: '#fff', textAlign: 'center' });
        const accBody = new fabric.Textbox('【電車】箱根登山鉄道「箱根湯本」駅より送迎車5分（要予約）\n【お車】小田原厚木道路「箱根口IC」より国道1号線経由 約10分  ·  駐車場8台（無料）\n【高速バス】新宿バスタより小田急高速バス約100分「箱根湯本」下車', { left: x + M, top: accY + 26, width: CW, fontSize: 7, fontFamily: F, fill: '#aaa', lineHeight: 1.55, textAlign: 'center' });
        // Bottom
