        const phone = new fabric.Textbox('☎ 0460-85-1234', { left: x + M, top: y + pageH - MB - 22, width: CW, fontSize: 12, fontWeight: '700', fontFamily: F3, fill: '#fff', textAlign: 'center' });
        const hours = new fabric.Textbox('受付時間 9:00〜21:00（年中無休）  ·  www.hanatsuki-hakone.jp', { left: x + M, top: y + pageH - MB - 8, width: CW, fontSize: 7, fontFamily: F, fill: '#888', textAlign: 'center' });
