        const ccD = new fabric.Textbox('Enregistré en prises live, ce deuxième album respire la liberté. Une production organique, une voix lumineuse et dix titres taillés pour durer. Le disque de l\u2019année, sans hésitation.', { left: x + 42, top: ccY + 80, width: pageW - 84, fontSize: 10, fontFamily: F, fill: '#fbe6ef', lineHeight: 1.55 });
        objs.push(bar, bt, cc, ccK, ccT, ccD, folio);
