        const k = new fabric.Textbox('LA PLAYLIST', { left: x + pageW * 0.4 + 22, top: y + 32, width: pageW * 0.58 - 44, fontSize: 9, fontWeight: '800', fontFamily: F, fill: accent, charSpacing: 260 });
        const ti = new fabric.Textbox('10 titres\npour l\u2019hiver', { left: x + pageW * 0.4 + 22, top: y + 50, width: pageW * 0.58 - 44, fontSize: 30, fontFamily: F2, fill: ink, lineHeight: 1.05 });
        const tracks = ['01  Nova Ray — Lumen', '02  Kaito — Neon Drift', '03  Marlow — Pinewood', '04  Sève — Racines', '05  Ada Vine — Ghost FM', '06  Joon — Slow Tide', '07  Bloc Nord — Mistral', '08  Elia — Verre Cassé', '09  Ravel Jr — Aube', '10  Polaris — Dernier Train'];
        objs.push(new fabric.Textbox(tracks.join('\n'), { left: x + pageW * 0.4 + 22, top: y + 130, width: pageW * 0.58 - 44, fontSize: 10.5, fontFamily: FM, fill: '#cfc9bf', lineHeight: 1.9 }));
