    const info = new fabric.Textbox('12 rue des Lilas · 75011 Paris\n01 23 45 67 89\nwww.lamaisondoree.fr', { left: x + M, top: y + pageH * 0.52 + 56, width: pageW - 2 * M, fontSize: 11, fontFamily: F, fill: '#a89c89', textAlign: 'center', lineHeight: 1.7 });
    const hours = new fabric.Textbox('Ouvert du mardi au samedi · 12h–14h30 / 19h–22h30', { left: x + M, top: y + pageH * 0.52 + 130, width: pageW - 2 * M, fontSize: 9, fontStyle: 'italic', fontFamily: F2, fill: gold, textAlign: 'center' });
    objs.push(topImg, orn, name, info, hours);
