        const mainTitle = new fabric.Textbox('L\'excellence\nà table', { left: x + 28, top: y + pageH * 0.58, width: pageW - 56, fontSize: 40, fontWeight: '300', fontFamily: 'Playfair Display', fill: '#fff', lineHeight: 1.05 });
