        document.getElementById('importWord')?.addEventListener('click', () => {
            document.getElementById('wordFileInput').click();
        });
        
        document.getElementById('wordFileInput')?.addEventListener('change', async (e) => {
            const file = e.target.files[0];
            if (!file) return;
            
            if (!file.name.endsWith('.docx')) {
                alert(translate('alertDocxOnlySupported'));
                return;
            }
            
            const startPage = await askInsertAtPage();
            if (startPage === null) { e.target.value = ''; return; } // annulé
            
            try {
                await importWordDocument(file, startPage);
            } catch (error) {
                console.error('Erreur import Word:', error);
                alert(translatef('alertWordImportError', error.message));
            }
            
            e.target.value = '';
        });
        
        async function importWordDocument(file, startPageIndex) {
            if (!window.mammoth) {
                alert(translate('alertMammothNotLoaded'));
                return;
            }
            
            // Naviguer vers la page d'insertion demandée
            if (typeof startPageIndex === 'number' && startPageIndex >= 0) {
                // Créer les pages nécessaires si startPageIndex dépasse le nombre actuel
                while (pages.length <= startPageIndex) { createNewPage(); }
                currentPageIndex = startPageIndex;
                renderAllPages();
            }
            
            const progressMsg = document.createElement('div');
            progressMsg.style.cssText = 'position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); background: rgba(0,0,0,0.9); color: white; padding: 30px 40px; border-radius: 12px; z-index: 100000; font-size: 16px; text-align: center;';
            progressMsg.innerHTML = '<div style="font-size: 48px; margin-bottom: 16px;">📝</div><div>Import Word en cours...</div>';
            document.body.appendChild(progressMsg);
            
            try {
                // Lire le fichier
                const arrayBuffer = await file.arrayBuffer();
                
                // Convertir avec Mammoth.js
                const result = await mammoth.convertToHtml({ arrayBuffer: arrayBuffer });
                const htmlContent = result.value;
                
                // Créer une nouvelle page pour le contenu
                const canvas = getActiveCanvas();
                if (!canvas) {
                    document.body.removeChild(progressMsg);
                    return;
                }
                
                // Parser le HTML et créer des objets texte
                const tempDiv = document.createElement('div');
                tempDiv.innerHTML = htmlContent;
                
                let yPosition = 50;
                const xPosition = 50;
                // 🎨 PASTEBOARD: utiliser pageCanvasWidth
                const _biWord = canvas.bleedInfo || {};
                const maxWidth = (_biWord.pageCanvasWidth || canvas.width) - 100;
                
                // Parcourir les paragraphes
                const paragraphs = tempDiv.querySelectorAll('p, h1, h2, h3, h4, h5, h6');
                
                for (const para of paragraphs) {
                    const text = para.textContent.trim();
                    if (!text) continue;
                    
                    // Déterminer le style selon le tag
                    let fontSize = 12;
                    let fontWeight = 'normal';
                    
                    if (para.tagName === 'H1') {
                        fontSize = 24;
                        fontWeight = 'bold';
                    } else if (para.tagName === 'H2') {
                        fontSize = 20;
                        fontWeight = 'bold';
                    } else if (para.tagName === 'H3') {
                        fontSize = 16;
                        fontWeight = 'bold';
                    } else if (para.tagName.startsWith('H')) {
                        fontSize = 14;
                        fontWeight = 'bold';
                    }
                    
                    // Créer le bloc texte
                    const textBox = new fabric.Textbox(text, {
                        left: xPosition,
                        top: yPosition,
                        width: maxWidth,
                        fontSize: fontSize,
                        fontFamily: 'Arial',
                        fontWeight: fontWeight,
                        fill: '#000000',
                        lineHeight: 1.3
                    });
                    
                    canvas.add(textBox);
                    
                    // Calculer la hauteur réelle du texte
                    const textHeight = textBox.height;
                    yPosition += textHeight + 20; // Espacement entre paragraphes
                }
                
                canvas.requestRenderAll();
                saveAllPages();
                debouncedUpdateLayersPanel();
                
                document.body.removeChild(progressMsg);
                
                alert(translatef('alertWordImportSuccess', paragraphs.length));
                
            } catch (error) {
                document.body.removeChild(progressMsg);
                throw error;
            }
        }
        
        // Importer les pages PDF sélectionnées
        // Importer les pages PDF sélectionnées
        async function importPDFPages(pageNumbers, recadrageMode = 'support') {
            if (!currentPDFDocument || pageNumbers.length === 0) return;
            
            const progressMsg = document.createElement('div');
            progressMsg.style.cssText = 'position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); background: rgba(0,0,0,0.9); color: white; padding: 30px 40px; border-radius: 12px; z-index: 100000; font-size: 16px; text-align: center;';
            progressMsg.innerHTML = '<div style="font-size: 48px; margin-bottom: 16px;">📄</div><div>Import PDF en cours...</div><div id="pdfProgressText" style="margin-top: 12px; font-size: 14px; opacity: 0.8;">0 / ' + pageNumbers.length + '</div>';
            document.body.appendChild(progressMsg);
            
            try {
                // 🎯 DÉTECTION DU FORMAT PDF - Récupérer les dimensions de la première page
                const firstPage = await currentPDFDocument.getPage(pageNumbers[0]);
                const firstViewport = firstPage.getViewport({ scale: 1.0 });
                
                // Convertir les dimensions PDF (points) en mm (1 point = 0.352778 mm)
                const pdfWidthMM = firstViewport.width * 0.352778;
                const pdfHeightMM = firstViewport.height * 0.352778;
                const pdfOrientation = pdfWidthMM > pdfHeightMM ? 'landscape' : 'portrait';
                
                // Sauvegarder le format actuel de SUPERPRINT
                const originalFormat = { ...pageFormat };
                
                // Détecter le format PDF et ajuster SUPERPRINT
                let detectedFormat = detectPDFFormat(pdfWidthMM, pdfHeightMM);
                
                if (detectedFormat) {
                    // Appliquer le format détecté
                    if (confirm(translatef('confirmAdjustFormat', detectedFormat.name, Math.round(pdfWidthMM), Math.round(pdfHeightMM), pageFormat.name))) {
                        
                        // Mettre à jour le format de page
                        pageFormat = {
                            name: detectedFormat.name,
                            width: Math.round(pdfWidthMM),
                            height: Math.round(pdfHeightMM),
                            orientation: pdfOrientation
                        };
                        
                        // Mettre à jour l'interface
                        const formatSelect = document.getElementById('pageFormat');
                        if (formatSelect) {
                            formatSelect.value = 'custom';
                        }
                        
                        document.getElementById('customWidth').value = pageFormat.width;
                        document.getElementById('customHeight').value = pageFormat.height;
                    }
                }
                
                for (let i = 0; i < pageNumbers.length; i++) {
                    const pageNum = pageNumbers[i];
                    document.getElementById('pdfProgressText').textContent = `${i + 1} / ${pageNumbers.length}`;
                    
                    // Créer une nouvelle page pour chaque page PDF
                    addPageFromChemin('simple');
                    
                    // Mettre à jour l'index de page pour cibler la nouvelle page
                    currentPageIndex = pages.length - 1;
                    updatePageIndicator();
                    
                    await new Promise(resolve => setTimeout(resolve, 150)); // Attendre que la page soit créée
                    
                    // Rendre la page PDF en image
                    const page = await currentPDFDocument.getPage(pageNum);
                    const viewport = page.getViewport({ scale: 6.0 }); // Très haute résolution (600 DPI)
                    
                    const canvas = document.createElement('canvas');
                    const context = canvas.getContext('2d');
                    canvas.width = viewport.width;
                    canvas.height = viewport.height;
                    
                    await page.render({
                        canvasContext: context,
                        viewport: viewport
                    }).promise;
                    
                    // Convertir en image et ajouter au canvas Fabric
                    const imgDataUrl = canvas.toDataURL('image/png');
                    
                    // ✅ CORRECTIF: Capturer le canvas AVANT le callback
                    const targetCanvas = getActiveCanvas();
                    
                    if (targetCanvas) {
                        // ✅ Attendre que l'image soit chargée avec une Promise
                        await new Promise((resolve) => {
                            fabric.Image.fromURL(imgDataUrl, (img) => {
                                // Récupérer les infos de bleed pour positionnement correct
                                const bleedInfo = targetCanvas.bleedInfo || { left: mmToPx(bleed), top: mmToPx(bleed) };
                                
                                // Dimensions de la zone de travail (sans fond perdu)
                                const workAreaWidth = mmToPx(pageFormat.width);
                                const workAreaHeight = mmToPx(pageFormat.height);
                                
                                // Calculer le scale pour ajuster l'image à la zone de travail
                                const scaleX = workAreaWidth / img.width;
                                const scaleY = workAreaHeight / img.height;
                                let scale = Math.min(scaleX, scaleY);
                                
                                // Mode recadrage
                                if (recadrageMode === 'fill') {
                                    scale = Math.max(scaleX, scaleY);
                                }
                                
                                // Positionner l'image au centre de la zone de travail (après le fond perdu)
                                img.set({
                                    left: bleedInfo.left + (workAreaWidth - img.width * scale) / 2,
                                    top: bleedInfo.top + (workAreaHeight - img.height * scale) / 2,
                                    scaleX: scale,
                                    scaleY: scale,
                                    selectable: true,
                                    hasControls: true,
                                    hasBorders: true,
                                    lockRotation: false,
                                    lockScalingX: false,
                                    lockScalingY: false,
                                    cornerSize: 8,
                                    transparentCorners: false
                                });
                                
                                targetCanvas.add(img);
                                targetCanvas.requestRenderAll();
                                resolve(); // ✅ Résoudre la Promise une fois l'image ajoutée
                            });
                        });
                    }
                }
                
                await new Promise(resolve => setTimeout(resolve, 300));
                
                if (progressMsg && progressMsg.parentNode) {
                    progressMsg.parentNode.removeChild(progressMsg);
                }
                
                alert(translatef('alertPdfPagesImported', pageNumbers.length));
                debouncedUpdateLayersPanel();
                
            } catch (error) {
                if (progressMsg && progressMsg.parentNode) {
                    progressMsg.parentNode.removeChild(progressMsg);
                }
                console.error('Erreur lors de l\'import des pages PDF:', error);
                alert(translatef('alertPdfPagesImportError', error.message));
            }
        }

        // ==================== ?? PATHFINDER WIDGET ====================
        function setupPathfinderWidget() {
    const widget = document.getElementById('pathfinderWidget');
    const header = document.getElementById('pathfinderToggle');
    
    if (!widget || !header) return;

    // Helper to bring widget to front
    const bringToFront = () => {
        const widgets = document.querySelectorAll('.pathfinder-widget, .typo-styles-widget, .swatches-widget');
        let maxZ = 100;
        widgets.forEach(w => {
            const z = parseInt(window.getComputedStyle(w).zIndex) || 0;
            if (z > maxZ) maxZ = z;
        });
        widget.style.zIndex = maxZ + 1;
    };
    
    // Toggle expand/collapse
    header.addEventListener('click', (e) => {
        if (e.target.closest('.pathfinder-toggle-arrow') || e.target === header) {
            widget.classList.toggle('expanded');
            bringToFront();
        }
    });

    // Bring to front on interaction
    widget.addEventListener('mousedown', bringToFront);
    
    // Make widget draggable
    setupDraggablePathfinderWidget();
    
    // Attach operation handlers
    document.querySelectorAll('.pathfinder-item').forEach(btn => {
        btn.addEventListener('click', () => {
            const operation = btn.dataset.operation;
            applyPathfinderOperation(operation);
        });
    });
        }
        
        function setupDraggablePathfinderWidget() {
    const widget = document.getElementById('pathfinderWidget');
    const header = document.getElementById('pathfinderToggle');
    const container = document.getElementById('widgetsOverlay') || document.getElementById('canvasScrollArea');
    
    if (!widget || !header || !container) return;
    
    // Load saved position
    setTimeout(() => {
        try {
            const saved = JSON.parse(localStorage.getItem('sp_pathfinder_widget_pos') || 'null');
            if (saved && typeof saved.x === 'number' && typeof saved.y === 'number') {
                widget.style.left = saved.x + 'px';
                widget.style.top = saved.y + 'px';
                widget.style.bottom = 'auto';
                widget.style.right = 'auto';
            }
        } catch {}
    }, 100);
    
    let isDragging = false;
    let startX = 0, startY = 0, originLeft = 0, originTop = 0;
    
    header.addEventListener('mousedown', (e) => {
        if (e.target.closest('.pathfinder-toggle-arrow')) return;
        isDragging = true;
        
        const rect = widget.getBoundingClientRect();
        const containerRect = container.getBoundingClientRect();
        startX = e.clientX;
        startY = e.clientY;
        originLeft = rect.left - containerRect.left;
        originTop = rect.top - containerRect.top;
        
        header.style.cursor = 'grabbing';
        document.body.style.userSelect = 'none';
        e.preventDefault();
    });
    
    document.addEventListener('mousemove', (e) => {
        if (!isDragging) return;
        
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        
        let newLeft = originLeft + dx;
        let newTop = originTop + dy;
        
        // Limites dans le container
        const containerRect = container.getBoundingClientRect();
        const maxLeft = containerRect.width - widget.offsetWidth;
        const maxTop = containerRect.height - widget.offsetHeight;
        
        newLeft = Math.max(0, Math.min(newLeft, maxLeft));
        newTop = Math.max(0, Math.min(newTop, maxTop));
        
        widget.style.left = newLeft + 'px';
        widget.style.top = newTop + 'px';
        widget.style.bottom = 'auto';
    });
    
    document.addEventListener('mouseup', () => {
        if (!isDragging) return;
        isDragging = false;
        header.style.cursor = 'grab';
        document.body.style.userSelect = '';
        
        // Save position
        localStorage.setItem('sp_pathfinder_widget_pos', JSON.stringify({
            x: parseInt(widget.style.left),
            y: parseInt(widget.style.top)
        }));
    });
        }
        
// ==========================================
// PATHFINDER ENGINE (Paper.js Integration)
// ==========================================

async function applyPathfinderOperation(operation) {
    const canvas = getActiveCanvas();
    if (!canvas) return;
    
    const selection = canvas.getActiveObject();
    if (!selection || selection.type !== 'activeSelection' || selection._objects.length < 2) {
        alert(translate('alertPathfinderNeedsTwoShapes'));
        return;
    }
    
    const objects = selection._objects.filter(obj => 
        obj.type === 'rect' || obj.type === 'circle' || obj.type === 'triangle' || obj.type === 'polygon' || obj.type === 'path'
    );
    
    if (objects.length < 2) {
        alert(translate('alertPathfinderUnsupportedFormat'));
        return;
    }
    
    // CRUCIAL: Désélectionner AVANT de récupérer les positions
    // Cela force Fabric à recalculer les coordonnées absolues
    canvas.discardActiveObject();
    canvas.requestRenderAll();
    
    // Forcer la mise à jour des coordonnées de chaque objet
    objects.forEach(obj => obj.setCoords());
    
    // Sort objects by stacking order (top-most first)
    objects.sort((a, b) => canvas.getObjects().indexOf(b) - canvas.getObjects().indexOf(a));
    
    try {
        let resultPath = null;
        
        // Show loading state
        document.body.style.cursor = 'wait';
        
        switch(operation) {
            case 'unite':
                resultPath = await uniteShapes(objects);
                break;
            case 'subtract':
                resultPath = await subtractShapes(objects);
                break;
            case 'intersect':
                resultPath = await intersectShapes(objects);
                break;
            case 'exclude':
                resultPath = await excludeShapes(objects);
                break;
        }
        
        document.body.style.cursor = 'default';
        
        if (resultPath) {
            // Remove original objects
            objects.forEach(obj => canvas.remove(obj));
            
            // Add result
            canvas.add(resultPath);
            canvas.setActiveObject(resultPath);
            canvas.requestRenderAll();
            
            saveAllPages();
            saveState(`Pathfinder: ${operation}`);
            debouncedUpdateLayersPanel();
        }
    } catch (error) {
        document.body.style.cursor = 'default';
        console.error('Erreur Pathfinder:', error);
        alert(translatef('alertPathfinderError', error.message));
    }
}

async function performPaperOperation(objects, operation) {
    // Filet de sécurité : certains contextes (extensions, blocages SW, cache obsolète)
    // peuvent empêcher l'auto-exposition de `var paper` en globale.
    if (!window.paper && typeof paper !== 'undefined') {
        try { window.paper = paper; } catch(_) {}
    }
    // Auto-réparation : si Paper.js n'est pas dispo, on tente un chargement à la
    // volée (cache-busting fort + mode classique). Ça couvre les cas où le SW a
    // servi une version corrompue ou où le 1er <script> a été bloqué.
    if (!window.paper) {
        console.warn('[Pathfinder] window.paper introuvable → chargement dynamique de paper-full.min.js…');
        await new Promise((resolve, reject) => {
            // Nettoie un éventuel script déjà en place pour forcer la réinjection.
            const old = document.querySelector('script[data-sp-paper-fallback]');
            if (old) old.remove();
            const s = document.createElement('script');
            s.src = 'JS/paper-full.min.js?_sp_reload=' + Date.now();
            s.async = false;
            s.dataset.spPaperFallback = '1';
            s.onload = () => {
                if (!window.paper && typeof paper !== 'undefined') {
                    try { window.paper = paper; } catch(_) {}
                }
                resolve();
            };
            s.onerror = () => reject(new Error('Échec du chargement de JS/paper-full.min.js'));
            document.head.appendChild(s);
            // Garde-fou 8 s
            setTimeout(() => resolve(), 8000);
        }).catch(err => { console.error('[Pathfinder]', err); });
    }
    if (!window.paper) {
        console.error('[Pathfinder] window.paper toujours introuvable après tentative de rechargement.');
        throw new Error('Paper.js n\'a pas pu être chargé. Vérifie ta connexion puis Ctrl+Shift+R. Si le problème persiste, vide le cache du navigateur (DevTools → Application → Clear storage).');
    }
    
    return new Promise((resolve, reject) => {
        try {
            // Setup Paper.js project if needed
            if (!paper.project) {
                const canvas = document.createElement('canvas');
                paper.setup(canvas);
            } else {
                paper.project.activeLayer.removeChildren();
            }
            
            // Convert Fabric objects to Paper.js paths using ABSOLUTE coordinates
            const paperPaths = [];
            
            for (const obj of objects) {
                let paperPath = null;
                
                // Utiliser calcTransformMatrix pour obtenir les coordonnées absolues
                const matrix = obj.calcTransformMatrix();
                
                if (obj.type === 'rect') {
                    const w = obj.width;
                    const h = obj.height;
                    // Points locaux (centrés sur 0,0)
                    const pts = [
                        fabric.util.transformPoint({ x: -w/2, y: -h/2 }, matrix),
                        fabric.util.transformPoint({ x: w/2, y: -h/2 }, matrix),
                        fabric.util.transformPoint({ x: w/2, y: h/2 }, matrix),
                        fabric.util.transformPoint({ x: -w/2, y: h/2 }, matrix)
                    ];
                    paperPath = new paper.Path({
                        segments: pts.map(p => [p.x, p.y]),
                        closed: true
                    });
                    
                } else if (obj.type === 'circle') {
                    const center = fabric.util.transformPoint({ x: 0, y: 0 }, matrix);
                    const radius = obj.radius * (obj.scaleX || 1);
                    paperPath = new paper.Path.Circle({
                        center: [center.x, center.y],
                        radius: radius
                    });
                    
                } else if (obj.type === 'triangle') {
                    const w = obj.width;
                    const h = obj.height;
                    const pts = [
                        fabric.util.transformPoint({ x: 0, y: -h/2 }, matrix),
                        fabric.util.transformPoint({ x: w/2, y: h/2 }, matrix),
                        fabric.util.transformPoint({ x: -w/2, y: h/2 }, matrix)
                    ];
                    paperPath = new paper.Path({
                        segments: pts.map(p => [p.x, p.y]),
                        closed: true
                    });
                    
                } else if (obj.type === 'polygon' && obj.points) {
                    const pts = obj.points.map(p => {
                        const local = { 
                            x: p.x - obj.pathOffset.x, 
                            y: p.y - obj.pathOffset.y 
                        };
                        return fabric.util.transformPoint(local, matrix);
                    });
                    paperPath = new paper.Path({
                        segments: pts.map(p => [p.x, p.y]),
                        closed: true
                    });
                    
                } else if (obj.type === 'path') {
                    // Pour les paths SVG complexes
                    if (obj.path) {
                        const segments = [];
                        for (const cmd of obj.path) {
                            const letter = cmd[0];
                            if (letter === 'M' || letter === 'L') {
                                const local = { 
                                    x: cmd[1] - (obj.pathOffset ? obj.pathOffset.x : 0), 
                                    y: cmd[2] - (obj.pathOffset ? obj.pathOffset.y : 0) 
                                };
                                const abs = fabric.util.transformPoint(local, matrix);
                                segments.push([abs.x, abs.y]);
                            }
                        }
                        if (segments.length >= 3) {
                            paperPath = new paper.Path({
                                segments: segments,
                                closed: true
                            });
                        }
                    }
                    
                    // Fallback: utiliser le bounding box
                    if (!paperPath) {
                        const bounds = obj.getBoundingRect(true, true);
                        paperPath = new paper.Path.Rectangle({
                            point: [bounds.left, bounds.top],
                            size: [bounds.width, bounds.height]
                        });
                    }
                }
                
                if (paperPath) {
                    paperPaths.push(paperPath);
                }
            }
            
            if (paperPaths.length < 2) {
                reject(new Error('Impossible de convertir les formes (besoin de 2 formes minimum)'));
                return;
            }
            
            // Perform boolean operation
            let result = paperPaths[0];
            
            if (operation === 'subtract') {
                // Subtract all other shapes from the base (bottom-most)
                result = paperPaths[paperPaths.length - 1];
                for (let i = 0; i < paperPaths.length - 1; i++) {
                    if (result && paperPaths[i]) {
                        result = result.subtract(paperPaths[i]);
                    }
                }
            } else {
                // Union, intersect, or exclude
                for (let i = 1; i < paperPaths.length; i++) {
                    if (!result || !paperPaths[i]) continue;
                    
                    switch(operation) {
                        case 'unite':
                            result = result.unite(paperPaths[i]);
                            break;
                        case 'intersect':
                            result = result.intersect(paperPaths[i]);
                            break;
                        case 'exclude':
                            result = result.exclude(paperPaths[i]);
                            break;
                    }
                }
            }
            
            if (!result) {
                reject(new Error('Opération impossible - les formes ne se chevauchent peut-être pas'));
                return;
            }
            
            // Récupérer les bounds du résultat Paper.js (coordonnées absolues)
            const paperBounds = result.bounds;
            const paperCenterX = paperBounds.x + paperBounds.width / 2;
            const paperCenterY = paperBounds.y + paperBounds.height / 2;
            
            
            // Convert Paper.js path to SVG path data string directly
            const pathData = result.pathData;
            
            // Clean up Paper project
            paper.project.activeLayer.removeChildren();
            
            // Create Fabric path directly from path data
            const fabricPath = new fabric.Path(pathData);
            
            // Copy style from the bottom-most original object
            const baseObj = objects[objects.length - 1];
            
            fabricPath.set({
                fill: baseObj.fill || '#cccccc',
                stroke: baseObj.stroke || null,
                strokeWidth: baseObj.strokeWidth || 0,
                opacity: baseObj.opacity || 1,
                selectable: true,
                evented: true,
                objectCaching: false
            });
            
            // Force Fabric to recalculate the path dimensions
            fabricPath.setCoords();
            
            // Récupérer le centre actuel de Fabric
            const fabricCenter = fabricPath.getCenterPoint();
            
            // Calculer le décalage nécessaire pour aligner sur Paper.js
            const offsetX = paperCenterX - fabricCenter.x;
            const offsetY = paperCenterY - fabricCenter.y;
            
            
            // Appliquer le décalage
            fabricPath.set({
                left: fabricPath.left + offsetX,
                top: fabricPath.top + offsetY
            });
            
            fabricPath.setCoords();
            
            
            resolve(fabricPath);
            
        } catch (error) {
            reject(error);
        }
    });
}

function uniteShapes(objects) {
    return performPaperOperation(objects, 'unite');
}

function subtractShapes(objects) {
    return performPaperOperation(objects, 'subtract');
}

function intersectShapes(objects) {
    return performPaperOperation(objects, 'intersect');
}

function excludeShapes(objects) {
    return performPaperOperation(objects, 'exclude');
}

// ========================================
// 🌐 WEB3 / IPFS (Pinata) BACKUP
// ========================================

const WEB3_SETTINGS_KEY = 'superprint.web3.settings.v1';
const WEB3_SAVES_KEY = 'superprint.web3.saves.v1';

function loadWeb3Settings() {
    try {
        const raw = localStorage.getItem(WEB3_SETTINGS_KEY);
        if (!raw) return { apiKey: '' };
        const parsed = JSON.parse(raw);
        return { apiKey: typeof parsed?.apiKey === 'string' ? parsed.apiKey : '' };
    } catch {
        return { apiKey: '' };
    }
}

function saveWeb3Settings(next) {
    try {
        localStorage.setItem(WEB3_SETTINGS_KEY, JSON.stringify(next));
    } catch {}
}

function loadWeb3Saves() {
    try {
        const raw = localStorage.getItem(WEB3_SAVES_KEY);
        if (!raw) return [];
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
    } catch {
        return [];
    }
}

function saveWeb3Saves(list) {
    try {
        localStorage.setItem(WEB3_SAVES_KEY, JSON.stringify(list));
    } catch {}
}

function refreshWeb3UploadButton() {
    const uploadBtn = document.getElementById('web3Upload');
    if (!uploadBtn) return;
    const settings = loadWeb3Settings();
    const hasKey = String(settings.apiKey || '').trim().length > 0;
    uploadBtn.disabled = !hasKey;
}

function refreshWeb3SavesList() {
    const listEl = document.getElementById('web3SavesList');
    if (!listEl) return;

    const saves = loadWeb3Saves();
    
    // Apply sorting
    const sortFilter = document.getElementById('web3SortFilter');
    if (sortFilter && saves.length > 0) {
        const sortMode = sortFilter.value;
        saves.sort((a, b) => {
            switch (sortMode) {
                case 'date-asc':
                    return (a.timestamp || 0) - (b.timestamp || 0);
                case 'date-desc':
                    return (b.timestamp || 0) - (a.timestamp || 0);
                case 'name-asc':
                    return (a.hash || '').localeCompare(b.hash || '');
                case 'name-desc':
                    return (b.hash || '').localeCompare(a.hash || '');
                default:
                    return (b.timestamp || 0) - (a.timestamp || 0);
            }
        });
    }

    if (!saves || saves.length === 0) {
        listEl.innerHTML = '<p style="font-size: 11px; color: #999; text-align: center; padding: 20px;">Aucune sauvegarde Web3 pour le moment.</p>';
        return;
    }

    listEl.innerHTML = '';
    for (let i = 0; i < saves.length; i++) {
        const s = saves[i];
        const item = document.createElement('div');
        item.style.cssText = 'display: flex; align-items: start; justify-content: space-between; gap: 12px; padding: 10px; border: 1px solid #e0e0e0; border-radius: 6px; background: white;';

        const infoDiv = document.createElement('div');
        infoDiv.style.cssText = 'flex: 1; min-width: 0;';

        const dateDiv = document.createElement('div');
        dateDiv.style.cssText = 'font-size: 11px; font-weight: 600; color: #333; margin-bottom: 4px;';
        dateDiv.textContent = s.date || 'Date inconnue';

        const hashDiv = document.createElement('div');
        hashDiv.style.cssText = 'font-size: 9px; color: #666; font-family: "IBM Plex Mono", monospace; word-break: break-all;';
        hashDiv.textContent = s.hash || '';

        infoDiv.appendChild(dateDiv);
        infoDiv.appendChild(hashDiv);

        const actionsDiv = document.createElement('div');
        actionsDiv.style.cssText = 'display: flex; gap: 6px; flex-shrink: 0;';

        const openBtn = document.createElement('button');
        openBtn.className = 'btn btn-secondary';
        openBtn.style.cssText = 'font-size: 10px; padding: 4px 8px;';
        openBtn.textContent = 'Ouvrir';
        openBtn.onclick = () => loadWeb3Save(s.hash);

        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'btn btn-secondary';
        deleteBtn.style.cssText = 'font-size: 10px; padding: 4px 8px; background: #f44336; color: white;';
        deleteBtn.textContent = '×';
        deleteBtn.title = 'Supprimer';
        deleteBtn.onclick = () => {
            if (confirm(translate('confirmDeleteLocalSave'))) {
                const updated = loadWeb3Saves().filter(x => x.hash !== s.hash);
                saveWeb3Saves(updated);
                refreshWeb3SavesList();
            }
        };

        actionsDiv.appendChild(openBtn);
        actionsDiv.appendChild(deleteBtn);

        item.appendChild(infoDiv);
        item.appendChild(actionsDiv);

        listEl.appendChild(item);
    }
}

async function uploadToIPFS(apiKey, jsonData) {
    const projName = (window._spProjectName || '').trim();
    const fileName = projName ? projName.replace(/[\\/:*?"<>|]/g, '_') + '.json' : `superprint-project-${new Date().toISOString().slice(0,10)}.json`;
    const blob = new Blob([JSON.stringify(jsonData, null, 2)], { type: 'application/json' });
    const formData = new FormData();
    formData.append('file', blob, fileName);

    const res = await fetch('https://api.pinata.cloud/pinning/pinFileToIPFS', {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${apiKey}`,
        },
        body: formData,
    });

    if (!res.ok) {
        const t = await res.text().catch(() => '');
        if (res.status === 401) {
            throw new Error(`Authentification Pinata échouée. Assurez-vous d'utiliser un JWT (token commençant par "eyJ..."), pas une API Key classique. Créez-en un sur: https://app.pinata.cloud/developers/api-keys`);
        }
        throw new Error(`Upload IPFS échoué (${res.status}): ${t}`);
    }

    const json = await res.json();
    return json.IpfsHash || '';
}

async function loadWeb3Save(hash) {
    if (!hash || !String(hash).trim()) {
        alert(translate('alertIpfsInvalidHash'));
        return;
    }

    const statusEl = document.getElementById('web3UploadStatus');
    if (statusEl) statusEl.textContent = 'Chargement depuis IPFS...';

    try {
        const res = await fetch(`https://gateway.pinata.cloud/ipfs/${hash}`);
        if (!res.ok) {
            throw new Error(`Impossible de charger le fichier (${res.status})`);
        }

        const project = await res.json();

        // Load project data
        if (project.pages) {
            enableHighPerformance();
            
            pages = project.pages || [];
            pageFormat = project.pageFormat || { width: 210, height: 297 };
            margin = project.margin || 20;
            bleed = project.bleed || 3;
            textLinks = project.textLinks || {};
            if (project.projectName) window._spProjectName = project.projectName;
            masterPages = project.masterPages || {};
            pageMasterAssignments = project.pageMasterAssignments || {};
            pageNumberingSettings = project.pageNumberingSettings || {
                enabled: false, startAt: 1, position: 'bottom-center',
                fontFamily: 'Open Sans', fontSize: 10, fontColor: '#333333',
                prefix: '', suffix: '', style: 'decimal',
                marginBottom: 15, marginSide: 20
            };
            // FIX: Restaurer le viewMode sauvegardé ou forcer 'single'
            viewMode = project.viewMode || 'single';
            document.getElementById('singlePageMode').classList.toggle('active', viewMode === 'single');
            document.getElementById('spreadMode').classList.toggle('active', viewMode === 'spread');

            document.getElementById('pageWidth').value = pageFormat.width;
            document.getElementById('pageHeight').value = pageFormat.height;
            document.getElementById('margin').value = margin;
            document.getElementById('bleed').value = bleed;
            currentPageIndex = 0;
            renderAllPages();
            _spApplyColorMode(project.colorMode || 'rgb');
            _spRestoreGuides(project.guides);
            
            setTimeout(() => {
                disableHighPerformance();
                canvases.forEach(c => c && c.requestRenderAll());
                updatePageIndicator();
                saveState('Projet chargé depuis IPFS');
            }, 200);

            alert(translate('alertWeb3OpenSuccess'));
            closeWeb3Modal();
        } else {
            throw new Error('Format de fichier non reconnu.');
        }

        if (statusEl) statusEl.textContent = '';
    } catch (e) {
        alert(translatef('alertIpfsLoadError', e && e.message ? e.message : 'Unknown error'));
        if (statusEl) statusEl.textContent = '';
    }
}

// Initialize Web3 Modal
(function initWeb3Modal() {
    const modal = document.getElementById('web3Modal');
    const apiKeyInput = document.getElementById('web3ApiKey');
    const saveConfigBtn = document.getElementById('web3SaveConfig');
    const uploadBtn = document.getElementById('web3Upload');
    const statusEl = document.getElementById('web3UploadStatus');
    const sortFilter = document.getElementById('web3SortFilter');

    if (!modal) return;

    // Load settings on open
    window.openWeb3Modal = () => {
        const settings = loadWeb3Settings();
        if (apiKeyInput) apiKeyInput.value = settings.apiKey || '';
        refreshWeb3UploadButton();
        refreshWeb3SavesList();
        modal.style.display = 'flex';
    };

    window.closeWeb3Modal = () => {
        modal.style.display = 'none';
    };

    // Save config button
    if (saveConfigBtn) {
        saveConfigBtn.addEventListener('click', () => {
            const apiKey = (apiKeyInput?.value || '').trim();
            if (!apiKey) {
                alert(translate('alertEnterPinataKey'));
                return;
            }
            saveWeb3Settings({ apiKey });
            refreshWeb3UploadButton();
            alert(translate('alertConfigSaved'));
        });
    }

    // Upload button
    if (uploadBtn) {
        uploadBtn.addEventListener('click', async () => {
            const settings = loadWeb3Settings();
            const apiKey = String(settings.apiKey || '').trim();
            if (!apiKey) {
                alert(translate('alertConfigurePinata'));
                return;
            }

            uploadBtn.disabled = true;
            uploadBtn.textContent = 'Upload en cours...';
            if (statusEl) statusEl.textContent = 'Upload du fichier sur IPFS...';

            try {
                // Save all pages
                saveAllPages();
                
                const project = {
                    version: '2.0',
                    pages: pages,
                    pageFormat: pageFormat,
                    margin: margin,
                    bleed: bleed,
                    textLinks: textLinks,
                    viewMode: viewMode,
                    masterPages: masterPages,
                    pageMasterAssignments: pageMasterAssignments,
                    pageNumberingSettings: pageNumberingSettings
                };

                const hash = await uploadToIPFS(apiKey, project);
                if (!hash) {
                    throw new Error('Hash IPFS non reçu.');
                }

                // Save to history
                const saves = loadWeb3Saves();
                saves.push({
                    hash,
                    date: new Date().toLocaleString('fr-FR'),
                    timestamp: Date.now(),
                });
                saveWeb3Saves(saves);

                if (statusEl) {
                    statusEl.innerHTML = `<span style="color: #4caf50;">${translate('toastUploadSuccess')}</span><br><span style="font-size: 9px;">${translate('uploadHashLabel')}: ${hash}</span>`;
                }
                refreshWeb3SavesList();
            } catch (e) {
                alert(translatef('alertIpfsUploadError', e && e.message ? e.message : 'Unknown error'));
                if (statusEl) statusEl.textContent = '';
            } finally {
                uploadBtn.disabled = false;
                uploadBtn.textContent = 'Uploader sur IPFS';
                refreshWeb3UploadButton();
            }
        });
    }

    // Sort filter
    if (sortFilter) {
        sortFilter.addEventListener('change', refreshWeb3SavesList);
    }

    // Initialize
    refreshWeb3UploadButton();
})();

// ✨ CORRECTIF : Surveillance continue de la sélection de texte pour permettre l'édition des styles
// Ce polling vérifie toutes les 200ms si l'utilisateur a sélectionné du texte dans un bloc
// et met à jour le panneau typographique en conséquence
let textSelectionPollingInterval = null;
let lastTextSelectionState = null;

function startTextSelectionPolling() {
    // Nettoyer l'ancien interval s'il existe
    if (textSelectionPollingInterval) {
        clearInterval(textSelectionPollingInterval);
    }
    
    textSelectionPollingInterval = setInterval(() => {
        // 🔋 STABILITÉ (2026-06-05) : ne pas sonder le canvas quand l'onglet est en
        //   arrière-plan (cohérent avec les autres timers ; évite un drain CPU permanent).
        if (document.hidden) return;
        const activeCanvas = getActiveCanvas();
        if (!activeCanvas) return;
        
        const obj = activeCanvas.getActiveObject();
        if (!obj || (obj.type !== 'textbox' && obj.type !== 'text')) {
            // Pas de texte sélectionné, réinitialiser l'état
            if (lastTextSelectionState !== null) {
                lastTextSelectionState = null;
                updateTransformPanel();
            }
            return;
        }
        
        // Vérifier si du texte est sélectionné
        const hasSelection = obj.isEditing && 
                            obj.selectionStart != null && 
                            obj.selectionEnd != null && 
                            obj.selectionEnd > obj.selectionStart;
        
        // Créer une signature de l'état actuel
        const currentState = hasSelection ? 
            `${obj.selectionStart}-${obj.selectionEnd}` : 
            'no-selection';
        
        // Si l'état a changé, mettre à jour le panneau
        if (currentState !== lastTextSelectionState) {
            lastTextSelectionState = currentState;
            updateTransformPanel();
        }
    }, 500); // ⚡ PERF: Réduit de 200ms à 500ms pour économiser les cycles CPU
    
}

// Démarrer la surveillance au chargement
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(startTextSelectionPolling, 1000);
});

// ============================================================
// 💾 INDEXEDDB AUTO-SAVE / AUTO-RESTORE (Offline persistence)
// Sauvegarde automatique du projet en arrière-plan dans IndexedDB.
// Restaure automatiquement au rechargement de la page.
// ============================================================
(function setupIndexedDBPersistence() {
    const DB_NAME = 'SuperPrintDB';
    const DB_VERSION = 2; // ⬆ V2: ajout du store 'saveHistory' pour l'historique persistant
    const STORE_NAME = 'projects';
    const HISTORY_STORE = 'saveHistory'; // 💾 Historique des sauvegardes (Ctrl+S + auto)
    const PROJECT_KEY = 'autosave';
    const MAX_HISTORY_ENTRIES = 20; // Nombre max de snapshots persistants
    const AUTOSAVE_INTERVAL = 300000; // ⚡ PERF: 5min (le debounce 30s après saveState couvre les actions utilisateur; ce timer est le filet de sécurité pour les périodes d'inactivité)
    const SESSION_HISTORY_MIN_INTERVAL = 30000; // 🛡️ Session history max 1x / 30s (évite le blocage main-thread avec images)
    const PUSH_HISTORY_MAX_BYTES = 5 * 1024 * 1024; // 🛡️ 5 MB max par snapshot d'historique (images strippées au-delà)
    let _db = null;
    let _autosaveTimer = null;
    let _lastSaveHash = '';
    let _lastSessionHistorySave = 0; // 🛡️ Timestamp dernier saveSessionHistory réussi

    // Ouvrir / créer la base IndexedDB
    function openDB() {
        return new Promise((resolve, reject) => {
            if (_db) { resolve(_db); return; }
            const req = indexedDB.open(DB_NAME, DB_VERSION);
            req.onupgradeneeded = (e) => {
                const db = e.target.result;
                if (!db.objectStoreNames.contains(STORE_NAME)) {
                    db.createObjectStore(STORE_NAME);
                }
                // V2: Créer le store d'historique avec auto-increment
                if (!db.objectStoreNames.contains(HISTORY_STORE)) {
                    db.createObjectStore(HISTORY_STORE, { keyPath: 'id', autoIncrement: true });
                }
            };
            req.onsuccess = (e) => { _db = e.target.result; resolve(_db); };
            req.onerror = (e) => { console.warn('[AutoSave] IndexedDB error:', e); reject(e); };
        });
    }

    // Sauvegarder le projet dans IndexedDB
    async function autoSaveProject() {
        try {
            if (typeof _isRenderingAllPages !== 'undefined' && _isRenderingAllPages) return;
            if (typeof _isRestoringState !== 'undefined' && _isRestoringState) return;
            
            // ⚡ PERF: Ne pas re-sérialiser si rien n'a changé depuis le dernier save
            if (!window._spDirtyFlag) return;
            
            // ⚡ PERF: Éviter saveAllPages() si déjà fait récemment (< 10s)
            // saveState() appelle saveAllPages() — pas besoin de re-sérialiser si c'est frais
            const now = Date.now();
            const lastSAP = window._spLastSaveAllPagesTime || 0;
            if (typeof saveAllPages === 'function' && (now - lastSAP > 10000)) {
                try { saveAllPages(); window._spLastSaveAllPagesTime = now; } catch (_) {}
            }
            
            const project = {
                version: '2.0',
                pages: pages,
                pageFormat: pageFormat,
                margin: margin,
                bleed: bleed,
                textLinks: textLinks,
                viewMode: viewMode,
                colorMode: _spGetColorMode(),
                guides: _spCollectGuides(),
                masterPages: typeof masterPages !== 'undefined' ? masterPages : {},
                pageMasterAssignments: typeof pageMasterAssignments !== 'undefined' ? pageMasterAssignments : {},
                pageNumberingSettings: typeof pageNumberingSettings !== 'undefined' ? pageNumberingSettings : {},
                projectName: window._spProjectName || '',
                _autosaveTimestamp: Date.now()
            };
            
            // ⚡ PERF: Hash basé sur le contenu réel (pages.length + somme des tailles)
            // 💧 v1.7.92 : ajoute un hash FNV-1a 32-bit du contenu de chaque page
            //   pour éviter les collisions silencieuses (avant : égalité de longueur =
            //   même hash → autosave sautée → perte de données potentielle au crash).
            //   FNV-1a est très rapide (~5–10 ms par 100 KB) et très peu collisif.
            function _spFnv1a32(str) {
                let h = 0x811c9dc5;
                for (let i = 0, len = str.length; i < len; i++) {
                    h ^= str.charCodeAt(i);
                    h = Math.imul(h, 0x01000193);
                }
                return (h >>> 0).toString(36);
            }
            let cheapHash = (pages || []).length + '-';
            for (let i = 0; i < (pages || []).length; i++) {
                const _pg = pages[i];
                const _str = (typeof _pg.objects === 'string') ? _pg.objects : '';
                cheapHash += _str.length + ':' + _spFnv1a32(_str) + ',';
            }
            if (cheapHash === _lastSaveHash) { window._spDirtyFlag = false; return; }
            _lastSaveHash = cheapHash;
            
            const db = await openDB();
            const tx = db.transaction(STORE_NAME, 'readwrite');
            const store = tx.objectStore(STORE_NAME);
            store.put(project, PROJECT_KEY);
            
            await new Promise((resolve, reject) => {
                tx.oncomplete = () => { window._spDirtyFlag = false; resolve(); };
                tx.onerror = reject;
            });

            // 💾 Auto-save : NE PAS appeler pushSaveHistory ni saveSessionHistory ici.
            // Ces deux fonctions font un deep-clone complet de pages[] + history[] (avec images base64)
            // → blocage du main-thread sur gros projets. Ils sont appelés uniquement sur Ctrl+S et beforeunload.
        } catch (err) {
            console.warn('[AutoSave] Save error:', err);
        }
    }

    // Charger le projet depuis IndexedDB
    async function loadAutoSavedProject() {
        try {
            const db = await openDB();
            const tx = db.transaction(STORE_NAME, 'readonly');
            const store = tx.objectStore(STORE_NAME);
            const req = store.get(PROJECT_KEY);
            
            return new Promise((resolve, reject) => {
                req.onsuccess = () => resolve(req.result || null);
                req.onerror = () => resolve(null);
            });
        } catch (err) {
            console.warn('[AutoSave] Load error:', err);
            return null;
        }
    }

    // Supprimer la sauvegarde automatique (Nouveau projet)
    async function clearAutoSave() {
        try {
            const db = await openDB();
            const tx = db.transaction([STORE_NAME, HISTORY_STORE], 'readwrite');
            tx.objectStore(STORE_NAME).delete(PROJECT_KEY);
            // 🔄 Supprimer aussi le session history (stack undo/redo)
            tx.objectStore(STORE_NAME).delete(SESSION_HISTORY_KEY);
            // Vider aussi l'historique des sauvegardes
            tx.objectStore(HISTORY_STORE).clear();
            _lastSaveHash = '';
        } catch (err) {
            console.warn('[AutoSave] Clear error:', err);
        }
    }

    // ═══════════════════════════════════════════════════════════════
    // 💾 HISTORIQUE PERSISTANT DES SAUVEGARDES (Ctrl+S + Auto-save)
    // Stocke jusqu'à MAX_HISTORY_ENTRIES snapshots dans IndexedDB.
    // Restauré au rechargement → l'utilisateur retrouve son Ctrl+Z.
    // ═══════════════════════════════════════════════════════════════

    // Ajouter un snapshot à l'historique persistant
    // 🛡️ Remplace les sources base64 d'images par un marqueur léger dans un objet pages cloné.
    // Évite de stocker des centaines de MB de données image dans IndexedDB.
    function _stripImagesFromPages(pagesArr) {
        try {
            const stripped = _spClone(pagesArr);
            for (const pg of stripped) {
                const objs = typeof pg.objects === 'string' ? pg.objects : JSON.stringify(pg.objects || []);
                // Remplace les data-URL base64 (inline images) par un placeholder léger
                pg.objects = objs.replace(/"(data:image\/[^;]+;base64,[^"]{512,})"/g, '"__sp_img_stripped__"');
            }
            return stripped;
        } catch (_) { return pagesArr; }
    }

    async function pushSaveHistory(type) {
        try {
            const db = await openDB();

            // 🛡️ Construire le snapshot en strippant les images base64 > seuil
            // (les images restent dans le project autosave — ici on veut juste le squelette pour l'UI historique)
            const strippedPages = _stripImagesFromPages(pages);

            const entry = {
                type: type, // 'ctrl-s' | 'auto' | 'init'
                timestamp: Date.now(),
                timeLabel: new Date().toLocaleTimeString('fr-FR'),
                projectName: window._spProjectName || '',
                pages: strippedPages,
                pageFormat: { ...pageFormat },
                margin: margin,
                bleed: bleed,
                textLinks: _spClone(textLinks || {}),
                viewMode: viewMode,
                masterPages: _spClone(typeof masterPages !== 'undefined' ? masterPages : {}),
                pageMasterAssignments: _spClone(typeof pageMasterAssignments !== 'undefined' ? pageMasterAssignments : {}),
                pageNumberingSettings: _spClone(typeof pageNumberingSettings !== 'undefined' ? pageNumberingSettings : {}),
                pageCount: (pages || []).length
            };

            const tx = db.transaction(HISTORY_STORE, 'readwrite');
            const store = tx.objectStore(HISTORY_STORE);
            store.add(entry);

            await new Promise((resolve, reject) => {
                tx.oncomplete = resolve;
                tx.onerror = reject;
            });

            // Trimmer les vieilles entrées
            await trimSaveHistory();

        } catch (err) {
            console.warn('[SaveHistory] Push error:', err);
        }
    }

    // Supprimer les entrées les plus anciennes si > MAX_HISTORY_ENTRIES
    async function trimSaveHistory() {
        try {
            const db = await openDB();
            const tx = db.transaction(HISTORY_STORE, 'readwrite');
            const store = tx.objectStore(HISTORY_STORE);
            const countReq = store.count();

            countReq.onsuccess = () => {
                const total = countReq.result;
                if (total <= MAX_HISTORY_ENTRIES) return;

                const toDelete = total - MAX_HISTORY_ENTRIES;
                const cursorReq = store.openCursor();
                let deleted = 0;
                cursorReq.onsuccess = (e) => {
                    const cursor = e.target.result;
                    if (cursor && deleted < toDelete) {
                        cursor.delete();
                        deleted++;
                        cursor.continue();
                    }
                };
            };
        } catch (err) {
            console.warn('[SaveHistory] Trim error:', err);
        }
    }

    // Charger tout l'historique persistant depuis IndexedDB
    async function loadSaveHistory() {
        try {
            const db = await openDB();
            const tx = db.transaction(HISTORY_STORE, 'readonly');
            const store = tx.objectStore(HISTORY_STORE);
            const req = store.getAll();

            return new Promise((resolve) => {
                req.onsuccess = () => resolve(req.result || []);
                req.onerror = () => resolve([]);
            });
        } catch (err) {
            console.warn('[SaveHistory] Load error:', err);
            return [];
        }
    }

    // ═══════════════════════════════════════════════════════════════
    // 🔄 SESSION HISTORY — Persistance complète undo + redo
    // Sauvegarde history[] + historyStep dans IndexedDB.
    // Restauré au rechargement → Ctrl+Z ET Ctrl+Y fonctionnent.
    // ═══════════════════════════════════════════════════════════════
    const SESSION_HISTORY_KEY = 'sessionHistory';

    // Sauvegarder le stack undo/redo complet dans IndexedDB
    // 🛡️ Protégé par : cooldown 30s, guard images strippées, estimation taille < 20 MB
    // force=true : ignorer le cooldown (utilisé par Ctrl+S explicite)
    async function saveSessionHistory(force = false) {
        try {
            if (typeof _isRestoringState !== 'undefined' && _isRestoringState) return;
            if (!history || history.length === 0) return;

            // 🛡️ Cooldown : ne pas sauvegarder plus d'une fois toutes les 30s
            const now = Date.now();
            if (!force && now - _lastSessionHistorySave < SESSION_HISTORY_MIN_INTERVAL) return;

            // 🛡️ Construire le stack en strippant les images base64 des entrées de l'historique
            // (l'historique undo/redo n'a pas besoin de conserver les pixels des images,
            //  uniquement les métadonnées et coords — les images restent dans le projet autosave)
            const safeHistory = history.map(entry => {
                if (!entry) return entry;
                return {
                    ...entry,
                    pages: entry.pages ? _stripImagesFromPages(entry.pages) : entry.pages
                };
            });

            // 🛡️ Estimation rapide de la taille sérialisée avant d'aller en IndexedDB
            // (évite de bloquer sur un JSON.stringify géant)
            let estimatedSize = 0;
            for (const entry of safeHistory) {
                if (!entry || !entry.pages) continue;
                for (const pg of entry.pages) {
                    estimatedSize += (typeof pg.objects === 'string' ? pg.objects.length : 0);
                }
            }
            const SIZE_LIMIT = 20 * 1024 * 1024; // 20 MB
            if (estimatedSize > SIZE_LIMIT) {
                // Trop volumineux même strippé → ne sauvegarder que les 3 entrées les plus récentes
                const trimmed = safeHistory.slice(-3);
                console.warn('[SessionHistory] Stack trop volumineux (' + Math.round(estimatedSize/1024/1024) + ' MB) → seules les 3 dernières entrées sont persistées.');
                const db = await openDB();
                const tx = db.transaction(STORE_NAME, 'readwrite');
                tx.objectStore(STORE_NAME).put({ history: trimmed, historyStep: Math.min(historyStep, trimmed.length - 1), timestamp: now }, SESSION_HISTORY_KEY);
                await new Promise((r, j) => { tx.oncomplete = r; tx.onerror = j; });
                _lastSessionHistorySave = now;
                return;
            }

            const db = await openDB();
            const sessionData = {
                history: safeHistory,
                historyStep: historyStep,
                timestamp: now
            };

            const tx = db.transaction(STORE_NAME, 'readwrite');
            tx.objectStore(STORE_NAME).put(sessionData, SESSION_HISTORY_KEY);

            await new Promise((resolve, reject) => {
                tx.oncomplete = resolve;
                tx.onerror = reject;
            });
            _lastSessionHistorySave = now;
        } catch (err) {
            console.warn('[SessionHistory] Save error:', err);
        }
    }

    // Charger le stack undo/redo depuis IndexedDB
    async function loadSessionHistory() {
        try {
            const db = await openDB();
            const tx = db.transaction(STORE_NAME, 'readonly');
            const store = tx.objectStore(STORE_NAME);
            const req = store.get(SESSION_HISTORY_KEY);

            return new Promise((resolve) => {
                req.onsuccess = () => resolve(req.result || null);
                req.onerror = () => resolve(null);
            });
        } catch (err) {
            console.warn('[SessionHistory] Load error:', err);
            return null;
        }
    }

    // Démarrer l'auto-save périodique (non-bloquant avec requestIdleCallback)
    function startAutoSave() {
        if (_autosaveTimer) clearInterval(_autosaveTimer);
        _autosaveTimer = setInterval(() => {
            // Utiliser requestIdleCallback pour ne pas bloquer le thread principal
            if (typeof requestIdleCallback === 'function') {
                requestIdleCallback(() => { autoSaveProject(); }, { timeout: 5000 });
            } else {
                setTimeout(() => { autoSaveProject(); }, 50);
            }
        }, AUTOSAVE_INTERVAL);
    }

    // Exposer les fonctions globalement
    window._spAutoSave = autoSaveProject;
    window._spLoadAutoSave = loadAutoSavedProject;
    window._spClearAutoSave = clearAutoSave;
    window._spStartAutoSave = startAutoSave;
    window._spPushSaveHistory = pushSaveHistory;
    window._spLoadSaveHistory = loadSaveHistory;
    window._spSaveSessionHistory = (force) => saveSessionHistory(force);
    window._spLoadSessionHistory = loadSessionHistory;

    // Sauvegarder avant fermeture / rechargement
    window.addEventListener('beforeunload', () => {
        try {
            // ⚡ PERF: Ne re-sérialiser que si pas fait récemment (< 5s)
            const now = Date.now();
            const lastSAP = window._spLastSaveAllPagesTime || 0;
            if (typeof saveAllPages === 'function' && (now - lastSAP > 5000)) {
                saveAllPages();
                window._spLastSaveAllPagesTime = now;
            }
            window._spDirtyFlag = true;
            autoSaveProject();
            // 🔄 Persister le stack undo/redo complet (force=true : bypass cooldown au unload)
            saveSessionHistory(true);
        } catch (_) {}
    });

    // Sauvegarder aussi quand l'onglet perd le focus (mobile / changement d'app)
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') {
            try {
                // ⚡ PERF: Éviter re-sérialisation si déjà fait récemment
                const now = Date.now();
                const lastSAP = window._spLastSaveAllPagesTime || 0;
                if (typeof saveAllPages === 'function' && (now - lastSAP > 5000)) {
                    saveAllPages();
                    window._spLastSaveAllPagesTime = now;
                }
                window._spDirtyFlag = true;
                autoSaveProject();
                // 🔄 Persister le stack undo/redo (cooldown intégré dans saveSessionHistory — max 1×/30s)
                // 🛡️ Utiliser requestIdleCallback pour ne pas bloquer la transition de tab
                if (typeof requestIdleCallback === 'function') {
                    requestIdleCallback(() => { saveSessionHistory(); }, { timeout: 3000 });
                } else {
                    setTimeout(() => { saveSessionHistory(); }, 200);
                }
            } catch (_) {}
        }
    });
})();

