window.openNewProjectModal = function() {
    const modal = document.getElementById('newProjectModal');
    if (!modal) return;
    // Reset to defaults
    const nameInput = document.getElementById('npProjectName');
    if (nameInput) nameInput.value = '';
    document.querySelectorAll('.np-format-btn').forEach(b => b.classList.remove('active'));
    const a4Btn = document.querySelector('.np-format-btn[data-np-format="a4"]');
    if (a4Btn) a4Btn.classList.add('active');
    document.getElementById('npWidth').value = 210;
    document.getElementById('npHeight').value = 297;
    document.getElementById('npMargin').value = 20;
    document.getElementById('npBleed').value = 3;
    document.getElementById('npPageCount').value = 1;
    _npOrientation = 'portrait';
    const _npPortBtn = document.getElementById('npOrientPortrait');
    const _npLandBtn = document.getElementById('npOrientLandscape');
    if (_npPortBtn) _npPortBtn.classList.add('active');
    if (_npLandBtn) _npLandBtn.classList.remove('active');
    npUpdatePreview();
    // Update i18n labels
    if (typeof _npUpdateLabels === 'function') _npUpdateLabels();
    // Reset view mode toggle
    document.getElementById('npModeSingle').classList.add('active');
    document.getElementById('npModeSpread').classList.remove('active');
    window._npViewMode = 'single';
    // Reset to Basic tab + RGB color mode
    if (typeof npSwitchTab === 'function') npSwitchTab('basic');
    if (typeof npSetColorMode === 'function') npSetColorMode('rgb');
    // Render template asset strip
    if (typeof npRenderAssetStrip === 'function') npRenderAssetStrip();
    modal.style.display = 'flex';
    setTimeout(() => { if (nameInput) nameInput.focus(); }, 150);
};

// 🆕 v1.7.174 — Helpers pour l'onglet Advanced
window.npSetFormat = function(fmt, btn) {
    if (fmt === 'custom') {
        document.querySelectorAll('#npPanelAdvanced .np-format-btn').forEach(function(b){ b.classList.remove('active'); });
        if (btn) btn.classList.add('active');
        return;
    }
    var f = _npFormats[fmt];
    if (!f) return;
    document.getElementById('npWidth').value = f.w;
    document.getElementById('npHeight').value = f.h;
    document.querySelectorAll('#npPanelAdvanced .np-format-btn').forEach(function(b){ b.classList.remove('active'); });
    if (btn) btn.classList.add('active');
    npUpdatePreview();
};
window.npSwapDimensions = function() {
    var wEl = document.getElementById('npWidth');
    var hEl = document.getElementById('npHeight');
    var tmp = wEl.value;
    wEl.value = hEl.value;
    hEl.value = tmp;
    npSetFormat('custom');
    npUpdatePreview();
};
window.npSetCols = function(n, btn) {
    window._npCols = n;
    document.querySelectorAll('#npPanelAdvanced .np-format-btn').forEach(function(b){ if(b.textContent.length<=2) b.classList.remove('active'); });
    if (btn) btn.classList.add('active');
};
window.npSetMargin = function(val, btn) {
    document.getElementById('npMargin').value = val;
    document.querySelectorAll('#npPanelAdvanced .np-format-btn').forEach(function(b){ if(b.textContent.indexOf('troites')>0||b.textContent.indexOf('Normales')>0||b.textContent.indexOf('Larges')>0) b.classList.remove('active'); });
    if (btn) btn.classList.add('active');
};
